// renderAnswerDocFacetCoverage emits the "Required Answer Facets"
// section of the finalizer prompt. Source of truth: the compiled
// FacetCoverageContract on AnswerSurfacePlan (Phase 1). Phase 2 is
// prompt-only — no hard gate fires from this section; LLM may
// rebalance the answer based on the facets listed but is not rejected
// for missing them. Phase 4 will add validators.
//
// Returns "" when the contract is empty or nil so existing prompt
// shapes stay byte-identical.
// renderAnswerDocBlockContract renders the V2 block contract for the
// finalizer prompt (B6-T1, block_only_carrier.md §5.6). Returns "" when
// no semantic view can be compiled — V2 is the only carrier since B8.
//
// LLM-facing language only (R4 red line); no internal Go terminology.
// The two sub-sections are:
//
//	## Required Answer Blocks   — what kinds of blocks the answer
//	                              must include (Summary/Section/
//	                              OrderedList/Diagram/etc.) + min/max
//	                              counts + the family rationale.
//
// renderAnswerDocRetryState (R14-c5..c8, post_shape_residual_audit.md
// 2026-05-04) is the unified retry-state prompt section. Rendered
// at the TOP of BuildInitialInstruction when ctx.EmitStageRetryAttempt > 0
// AND ctx.Mutable.RetryState() carries content.
//
// Renders 4 sections in fixed order:
//
//  1. ## Hard Rule (top) — preserve every unchanged field byte-identical.
//  2. ## Required Changes — typed FieldPath + Repair text per violation,
//     grouped by repair phase; Soft skipped.
//  3. ## Active Violations — full set, by Severity + Layer, so the
//     LLM has cross-layer visibility (R13 fix).
//  4. ## Previous Emit — typed projection of prev emit (R6/R6.1 fix:
//     LLM sees what fields it already filled).
//
// Returns "" when no retry state to render (preserves byte-identical
// pre-R14 behaviour on fresh dispatches).
func renderAnswerDocRetryState(ctx *types.AgentContext) string {
	if ctx == nil || ctx.Mutable == nil {
		return ""
	}
	rs := ctx.Mutable.RetryState()
	if rs == nil || !rs.HasContent() {
		return ""
	}

	var b strings.Builder
	fmt.Fprintf(&b, "## Hard Rule (retry attempt %d)\n\n", rs.Attempt)
	if retryStateHasPreviousEmit(rs) {
		b.WriteString("Your last answer document was rejected, but a previous structured payload is available. If `emit_answer_document_patch` is available, prefer it. ")
		b.WriteString(types.AnswerDocumentPatchOperationTeaching)
		b.WriteString(" IMPORTANT: each `replace_blocks` entry is a FULL block replacement, not a field merge. Copy its previous title/text/columns/items/diagram and typed annotations, then change only the field named by Required Changes; when merely adding citation sidecars to a Markdown table, preserve the complete prior table in `text` and add the sidecar `items[]`. If patch is not available, re-emit `emit_answer_document` by **starting from your previous payload (shown in 'Previous Emit' below) and changing ONLY the field paths or global rewrite items listed in 'Required Changes' below**. Every other field — `blocks[].id`, `blocks[].kind`, `blocks[].title`, `blocks[].text`, `blocks[].columns[]`, `blocks[].facet_ids`, `blocks[].claim_uses[]`, `blocks[].surface_role`, `blocks[].items[]`, `blocks[].items[].cells[]`, `citations[]`, `exact_resolution` — MUST appear byte-identical to your Previous Emit. Do NOT regenerate from scratch. The validator will reject any retry that loses fields you already filled correctly.\n\n")
	} else {
		b.WriteString("Your previous attempt did not leave a usable structured answer document. Re-emit a complete `emit_answer_document` payload now. Do NOT use patch operations and do NOT refer to a Previous Emit. Build the full document from the already-provided evidence, support lanes, required answer blocks, and the required changes below. Do not reopen files or write free-form prose outside the tool call.\n\n")
	}

	// 2. Required Changes (phase partitioned, soft excluded).
	if changes := renderRetryRequiredChanges(rs); changes != "" {
		b.WriteString(changes)
	}

	// 3. Active Violations (full set, grouped by severity then layer).
	if active := renderRetryActiveViolations(rs); active != "" {
		b.WriteString(active)
	}

	// 4. Previous Emit (typed summary).
	if prev := renderRetryPrevEmit(rs); prev != "" {
		b.WriteString(prev)
	}

	// 5. P2 (2026-05-10) — Live coverage status. Computes the
	// structural-coverage gaps the post-emit validators are about
	// to check (block kind balance, facet anchoring depth) and
	// surfaces them so the LLM sees them BEFORE re-emitting.
	// Only fires on retry (rs.HasContent already gated above);
	// 0-impact on first dispatch.
	if status := renderLiveCoverageStatus(ctx, rs); status != "" {
		b.WriteString(status)
	}

	// 6. P3 (2026-05-10) — Mechanical Fix Actions. Same input as
	// renderRetryRequiredChanges but rendered as structured
	// Action+Target+Value triples for the 4 typed validator-driven
	// cluster kinds (block_coverage_missing / facet_uncovered /
	// principal_claim_use_missing / uncertainty_block_missing).
	// Reduces "LLM has to re-read prose to figure out the fix" to
	// "LLM applies each row mechanically". Subjective concerns
	// (semantic_quality_underfilled / etc.) continue rendering
	// through the prose path above (Required Changes); both
	// channels coexist.
	if mech := renderRetryStructuredFixList(rs); mech != "" {
		b.WriteString(mech)
	}
	return b.String()
}

func retryStateHasPreviousEmit(rs *types.RetryState) bool {
	if rs == nil {
		return false
	}
	return len(rs.PrevEmitJSON) > 0 || len(rs.PrevEmitSummary.BlockSummaries) > 0
}

// renderRetryStructuredFixList is the P3 surface — emits a
// structured Action+Target+Value list for the violation kinds the
// post-emit chain consistently raises. Validator-driven kinds with
// a known mechanical template render here; subjective LLM-reviewer
// concerns (semantic_quality_underfilled, richness regressions)
// fall through to the existing prose path.
//
// Output shape:
//
//	## Mechanical Fix Actions
//
//	Apply each action below mechanically; each entry names a single
//	emit_answer_document field path to set OR a single block to add.
//
//	1. Action: `add_block`
//	   - Target: `blocks[]`
//	   - kind: `ordered_list`
//	   - hint: <one-line user-vocab Why>
//
//	2. Action: `set_field`
//	   - Target: `blocks[id="b1"].claim_uses`
//	   - Value: `[{claim_form: "definition_fact"}]`
//	   - hint: <one-line user-vocab Why>
//
// Empty when no covered ViolKind is in rs.ActiveViolations (the
// section silently disappears for non-typed retry shapes).
//
// Red-line audit (R3/R4/R5/R6/R7/SST/CN+EN-only):
//   - R3 typed: each Action / Target / Value comes from the
//     ScoredViolation's typed Kind / FieldPath / BlockID
//   - R4 generic: action names + schema fields are universal;
//     no project / case names appear
//   - R5: structured retry hint, never writes answer body
//   - R6 no internal vocab: action names (add_block / set_field /
//     add_caveat_block) are abstract instructions, not Go types;
//     schema field paths (blocks[].kind / blocks[id].claim_uses)
//     are the LLM's emit vocabulary already — they appear in the
//     skill prompt and in the JSON schema's examples
//   - R7 actionable: each row is one mechanical edit; LLM can
//     apply without prose interpretation
//   - SST: shape mirrors the existing Required Changes section
//     (## heading, numbered list)
//   - CN+EN-only: prompt is English (consistent with the rest
//     of the finalizer skill prose)
func renderRetryStructuredFixList(rs *types.RetryState) string {
	if rs == nil || len(rs.ActiveViolations) == 0 {
		return ""
	}
	var rows []structuredFixRow
	for _, sv := range rs.ActiveViolations {
		row, ok := classifyViolationToStructuredFix(sv)
		if !ok {
			continue
		}
		rows = append(rows, row)
	}
	if len(rows) == 0 {
		return ""
	}
	var out strings.Builder
	out.WriteString("## Mechanical Fix Actions\n\n")
	out.WriteString("Apply each action below mechanically; each entry names a single `emit_answer_document` field path to set OR a single block to add. The Hint line is informational; it does not need interpretation.\n\n")
	for i, r := range rows {
		fmt.Fprintf(&out, "%d. Action: `%s`\n", i+1, r.Action)
		fmt.Fprintf(&out, "   - Target: `%s`\n", r.Target)
		for _, arg := range r.Args {
			fmt.Fprintf(&out, "   - %s: `%s`\n", arg.Name, arg.Value)
		}
		if r.Hint != "" {
			fmt.Fprintf(&out, "   - Hint: %s\n", r.Hint)
		}
		out.WriteString("\n")
	}
	return out.String()
}

// structuredFixRow is the typed surface a P3 row renders. Action
// is one of a small enum of mechanical operations the LLM can
// recognize; Target is a schema field path or `blocks[]`; Args are
// ordered operation-specific parameters; Hint
// is an optional one-line user-vocab "why" string.
type structuredFixRow struct {
	Action string
	Target string
	Args   []structuredFixArg
	Hint   string
}

type structuredFixArg struct {
	Name  string
	Value string
}

// classifyViolationToStructuredFix returns true with a typed row
// when the violation's Kind matches a covered validator-driven
// cluster shape. Unknown / subjective kinds return ok=false and the
// caller falls through to the prose renderer.
func classifyViolationToStructuredFix(sv types.ScoredViolation) (structuredFixRow, bool) {
	switch sv.Kind {
	case types.ViolBlockCoverageMissing:
		// Detail typically reads "required block kind=X appears
		// N times; the family contract requires at least M".
		// Extract the kind from the Detail tail (best-effort) so
		// the row's structured kind matches.
		row := structuredFixRow{
			Action: "add_block",
			Target: "blocks[]",
			Args: []structuredFixArg{
				{Name: "kind", Value: extractMissingBlockKind(sv)},
			},
			Hint: strings.TrimSpace(sv.Repair),
		}
		return row, true
	case types.ViolPrincipalClaimUseMissing:
		row := structuredFixRow{
			Action: "set_field",
			Target: principalClaimUseTarget(sv),
			Args: []structuredFixArg{
				{Name: "value", Value: "[{claim_form: <one of the contract's acceptable forms>}]"},
			},
			Hint: strings.TrimSpace(sv.Repair),
		}
		return row, true
	case types.ViolFacetUncovered:
		row := structuredFixRow{
			Action: "set_field",
			Target: "blocks[].facet_ids OR blocks[].claim_uses[].facet_id",
			Args: []structuredFixArg{
				{Name: "value", Value: extractFacetIDFromDetail(sv)},
			},
			Hint: strings.TrimSpace(sv.Repair),
		}
		return row, true
	case types.ViolUncertaintyBlockMissing:
		row := structuredFixRow{
			Action: "add_caveat_block",
			Target: "blocks[]",
			Args: []structuredFixArg{
				{Name: "kind", Value: "caveat"},
				{Name: "text", Value: "(disclose what was searched and what remained uncertain)"},
			},
			Hint: strings.TrimSpace(sv.Repair),
		}
		return row, true
	case types.ViolCurrentStatusVerdictMissing:
		row := structuredFixRow{
			Action: "set_field",
			Target: currentStatusVerdictTarget(sv),
			Args: []structuredFixArg{
				{Name: "value", Value: "still_present | fixed | not_enough_evidence"},
			},
			Hint: strings.TrimSpace(sv.Repair),
		}
		return row, true
	case types.ViolLaneBlockKindMismatch:
		row := structuredFixRow{
			Action: "set_field",
			Target: laneBlockKindTarget(sv),
			Args: []structuredFixArg{
				{Name: "value", Value: "(one of the block kinds named in the repair hint)"},
			},
			Hint: strings.TrimSpace(sv.Repair),
		}
		return row, true
	case types.ViolMissingRequestedRoleUndisclosed:
		row := structuredFixRow{
			Action: "set_field",
			Target: "missing_requested_roles[]",
			Args: []structuredFixArg{
				{Name: "value", Value: missingRequestedRolesValueHint(sv)},
			},
			Hint: strings.TrimSpace(sv.Repair),
		}
		return row, true
	}
	return structuredFixRow{}, false
}

// extractMissingBlockKind reads the typed FieldPath when present
// (carries `blocks[].kind=X`), otherwise scans Detail for the
// kind=<token> hint the post-emit validator embeds.
func extractMissingBlockKind(sv types.ScoredViolation) string {
	if sv.FieldPath != "" {
		// FieldPath looks like "blocks[].kind=X"
		if idx := strings.Index(sv.FieldPath, "kind="); idx >= 0 {
			return strings.TrimSpace(sv.FieldPath[idx+len("kind="):])
		}
	}
	// Fall back to Detail scan: look for "kind=X" first occurrence.
	if idx := strings.Index(sv.Detail, "kind="); idx >= 0 {
		tail := sv.Detail[idx+len("kind="):]
		end := strings.IndexAny(tail, " ;,)\n")
		if end < 0 {
			end = len(tail)
		}
		return strings.TrimSpace(tail[:end])
	}
	return "<missing block kind from validator detail>"
}

// principalClaimUseTarget builds the FieldPath for a
// principal-claim-use-missing violation. Falls back to a generic
// path when BlockID is empty.
func principalClaimUseTarget(sv types.ScoredViolation) string {
	if sv.BlockID == "" {
		return "blocks[].claim_uses"
	}
	return fmt.Sprintf("blocks[id=%q].claim_uses", sv.BlockID)
}

func currentStatusVerdictTarget(sv types.ScoredViolation) string {
	if sv.FieldPath != "" {
		return sv.FieldPath
	}
	if sv.BlockID != "" {
		return fmt.Sprintf("blocks[id=%q].current_status_verdict", sv.BlockID)
	}
	return "blocks[kind=decision].current_status_verdict OR add a decision block"
}

func laneBlockKindTarget(sv types.ScoredViolation) string {
	if sv.FieldPath != "" {
		return sv.FieldPath
	}
	if sv.BlockID != "" {
		return fmt.Sprintf("blocks[id=%q].kind", sv.BlockID)
	}
	return "blocks[].kind"
}

func missingRequestedRolesValueHint(sv types.ScoredViolation) string {
	repair := strings.TrimSpace(sv.Repair)
	if repair == "" {
		return "(copy the exact missing role set named by the active requirement)"
	}
	return repair
}

// extractFacetIDFromDetail reads the typed FieldPath when present
// (validator emits "facet:<kind>"), otherwise scans Detail for the
// quoted facet kind. Returns the kind or a placeholder.
func extractFacetIDFromDetail(sv types.ScoredViolation) string {
	// Detail typically contains: required facet "X" (essential) is not covered: ...
	if idx := strings.Index(sv.Detail, "facet "); idx >= 0 {
		tail := sv.Detail[idx+len("facet "):]
		// Look for the quoted name following "facet ".
		if start := strings.IndexByte(tail, '"'); start >= 0 {
			rest := tail[start+1:]
			if end := strings.IndexByte(rest, '"'); end > 0 {
				return strings.TrimSpace(rest[:end])
			}
		}
	}
	return "<missing facet kind from validator detail>"
}

// renderLiveCoverageStatus is the P2 surface — computes per-block-kind
// counts and per-facet declaration depth from the prior emit and
// surfaces them in user-vocab prose so the LLM sees the gaps BEFORE
// re-emitting. Fires on retry path only (caller already gated on
// rs.HasContent()).
//
// User-vocab translation table (R6):
//   - "DeclaredCount" → "declared on N blocks"
//   - "AnchoredCount" → "N of them grounded with evidence"
//   - "BlockRequirement.MinCount" → "required: at least N"
//   - "BlockRequirement.MaxCount" → "max: N"
//   - facet kind → AnswerFacetPublicLabel (already user-vocab)
//
// Empty when no view (single-shot test path) OR PrevEmitJSON
// undecodable; the section is opportunistic enrichment, never
// load-bearing.
//
// Red-line audit (R3/R4/R5/R6/R7/SST/CN+EN-only):
//   - R3 typed: every count comes from the typed BlockRequirement /
//     FacetRequirement / decoded prior emit doc
//   - R4 generic: templated; no project / case names
//   - R5 informational: section is read-only over the prior emit;
//     never writes answer body
//   - R6 no internal vocab: "Block kind balance" / "Aspect
//     coverage" / "grounded with evidence" are user-vocab
//     paraphrases of the internal AnchoredCount / DeclaredCount /
//     BlockRequirement metrics
//   - R7 actionable: each gap line tells the LLM exactly what to
//     change on retry; passing items are marked so the LLM
//     doesn't accidentally regress them
//   - SST: matches the surrounding renderAnswerDocRetryState
//     section structure (same `##` heading depth, same numbering
//     model)
//   - CN+EN-only: prompt is English (consistent with the
//     surrounding finalizer skill prose)
func renderLiveCoverageStatus(ctx *types.AgentContext, rs *types.RetryState) string {
	if rs == nil || len(rs.PrevEmitJSON) == 0 {
		return ""
	}
	view := types.BuildAnswerSemanticViewForAgentContext(ctx)
	if view == nil {
		return ""
	}
	var prevDoc types.AnswerDocumentV2
	if err := json.Unmarshal(rs.PrevEmitJSON, &prevDoc); err != nil {
		return ""
	}

	var blockLines []string
	if line := liveBlockKindBalance(&prevDoc, view); line != "" {
		blockLines = append(blockLines, line)
	}
	var facetLines []string
	if line := liveAspectCoverage(&prevDoc, view); line != "" {
		facetLines = append(facetLines, line)
	}
	if len(blockLines) == 0 && len(facetLines) == 0 {
		return ""
	}

	var out strings.Builder
	out.WriteString("## Coverage Gaps in Previous Emit (informational)\n\n")
	out.WriteString("Your previous emit had the following structural-coverage status. Items marked ⚠ are gaps the validator will reject again unless fixed; items marked ✓ are clean (preserve them as-is on retry).\n\n")
	for _, l := range blockLines {
		out.WriteString(l)
	}
	for _, l := range facetLines {
		out.WriteString(l)
	}
	return out.String()
}

// liveBlockKindBalance renders the per-required-block kind status
// line(s) — one bullet per RequiredBlock comparing prior emit
// count vs MinCount / MaxCount.
func liveBlockKindBalance(prev *types.AnswerDocumentV2, view *types.AnswerSemanticView) string {
	if prev == nil || view == nil || len(view.RequiredBlocks) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("**Block kind balance:**\n\n")
	any := false
	for _, req := range view.RequiredBlocks {
		if !req.Required {
			continue
		}
		got := types.CountAnswerBlocksForRequirement(prev.Blocks, req)
		kindLabel := req.AcceptedKindsLabel()
		if kindLabel == "" {
			kindLabel = string(req.Kind)
		}
		marker := "✓"
		var detail string
		if got < req.MinCount {
			marker = "⚠"
			detail = fmt.Sprintf("required at least %d", req.MinCount)
		} else if req.MaxCount > 0 && got > req.MaxCount {
			marker = "⚠"
			detail = fmt.Sprintf("over max %d", req.MaxCount)
		} else if req.MaxCount > 0 && req.MaxCount == req.MinCount {
			detail = fmt.Sprintf("required exactly %d", req.MinCount)
		} else {
			detail = fmt.Sprintf("required at least %d", req.MinCount)
		}
		fmt.Fprintf(&b, "  %s `%s` — emitted %d (%s)\n",
			marker, kindLabel, got, detail)
		any = true
	}
	if !any {
		return ""
	}
	b.WriteString("\n")
	return b.String()
}

// liveAspectCoverage renders the per-facet declaration depth line(s).
// Mirrors the post-emit countFacetCoverageDepth metric but renders
// in user-vocab prose. AnchoredCount = blocks whose payload also
// carries citation_ref >= 0 OR a claim_uses[] entry with non-empty
// EvidenceID/ClaimForm.
func liveAspectCoverage(prev *types.AnswerDocumentV2, view *types.AnswerSemanticView) string {
	if prev == nil || view == nil || view.FacetCoverage == nil {
		return ""
	}
	if len(view.FacetCoverage.Required) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("**Aspect coverage:**\n\n")
	any := false
	for _, req := range view.FacetCoverage.Required {
		if !req.RequiresHardDeclaration() {
			continue
		}
		kind := strings.TrimSpace(string(req.Kind))
		if kind == "" {
			continue
		}
		declared, anchored := liveCountFacetDepth(prev, kind)
		label := types.AnswerFacetPublicLabel(req.Kind)
		marker := "✓"
		var detail string
		switch {
		case declared == 0:
			marker = "⚠"
			detail = "not declared on any block — set block.facet_ids OR claim_uses[].facet_id"
		case anchored == 0:
			marker = "⚠"
			detail = fmt.Sprintf("declared on %d block(s) but %d grounded with evidence — attach the projected item evidence/citation carrier to one item, or add a claim_uses[] entry with claim_form/evidence_id",
				declared, anchored)
		case anchored < declared:
			marker = "⚠"
			detail = fmt.Sprintf("declared on %d block(s); %d grounded with evidence (the rest are label-only)",
				declared, anchored)
		default:
			detail = fmt.Sprintf("declared on %d block(s), all grounded with evidence",
				declared)
		}
		fmt.Fprintf(&b, "  %s %q — %s\n", marker, label, detail)
		any = true
	}
	if !any {
		return ""
	}
	b.WriteString("\n")
	return b.String()
}

// liveCountFacetDepth re-implements the post-emit countFacetCoverageDepth
// helper inline (the orchestrator-package original lives behind an
// agent-package import boundary). Only the load-bearing variant —
// block-level FacetIDs declarations + claim_uses[].FacetID — is
// rendered; the post-emit chain still runs the deeper
// blockHasAnchoredClaim / blockHasAnchoredItemSurface checks.
func liveCountFacetDepth(doc *types.AnswerDocumentV2, kind string) (declared, anchored int) {
	if doc == nil || kind == "" {
		return 0, 0
	}
	for _, b := range doc.Blocks {
		blockDeclares := false
		for _, fid := range b.FacetIDs {
			if strings.TrimSpace(fid) == kind {
				blockDeclares = true
				declared++
				break
			}
		}
		if blockDeclares {
			// Block-level declaration is "anchored" when ANY
			// claim_uses[] entry on this block names a ClaimForm
			// or EvidenceID OR any item carries a non-negative
			// citation_ref (matches the post-emit
			// blockHasAnchoredItemSurface lite path).
			anchoredHere := false
			for _, cu := range b.ClaimUses {
				if cu.ClaimForm != "" || cu.EvidenceID != "" {
					anchoredHere = true
					break
				}
			}
			if !anchoredHere {
				for _, item := range b.Items {
					if item.CitationRef >= 0 {
						anchoredHere = true
						break
					}
				}
			}
			if anchoredHere {
				anchored++
			}
		}
		// claim_uses[].facet_id channel — same kind on a claim_use
		// declares the facet; the per-claim_use's ClaimForm /
		// EvidenceID counts as anchored.
		for _, cu := range b.ClaimUses {
			if strings.TrimSpace(cu.FacetID) != kind {
				continue
			}
			declared++
			if cu.ClaimForm != "" || cu.EvidenceID != "" {
				anchored++
			}
		}
	}
	return declared, anchored
}

type retryRepairPhase string

const (
	retryRepairPhaseStructure   retryRepairPhase = "structure"
	retryRepairPhaseConsistency retryRepairPhase = "consistency"
	retryRepairPhaseCoverage    retryRepairPhase = "coverage"
	retryRepairPhaseRichness    retryRepairPhase = "richness"
)

// renderRetryRequiredChanges renders the typed FieldPath + Repair list
// for every violation with Severity >= Medium. Soft violations are
// listed in the Active Violations section but NOT in Required Changes.
//
// Repair work is partitioned by phase so a wrong-topic rewrite does
// not get bundled with enrichment requests. Within a phase, entries
// are still severity-sorted Critical -> High -> Medium.
func renderRetryRequiredChanges(rs *types.RetryState) string {
	if rs == nil || len(rs.ActiveViolations) == 0 {
		return ""
	}
	type phaseBucket struct {
		phase   retryRepairPhase
		entries []types.ScoredViolation
	}
	hasTopicMismatch := retryHasTopicMismatch(rs.ActiveViolations)
	buckets := []*phaseBucket{}
	for _, phase := range retryRepairPhaseOrder(hasTopicMismatch) {
		buckets = append(buckets, &phaseBucket{phase: phase})
	}
	for _, sv := range rs.ActiveViolations {
		if !retryRequiredChangeAllowed(sv, hasTopicMismatch) {
			continue
		}
		phase := retryRepairPhaseForViolation(sv)
		for _, b := range buckets {
			if b.phase == phase {
				b.entries = append(b.entries, sv)
				break
			}
		}
	}
	totalActionable := 0
	for _, b := range buckets {
		sort.SliceStable(b.entries, func(i, j int) bool {
			return retryRequiredSeverityRank(b.entries[i].Severity) < retryRequiredSeverityRank(b.entries[j].Severity)
		})
		totalActionable += len(b.entries)
	}
	if totalActionable == 0 {
		return ""
	}
	var out strings.Builder
	out.WriteString("## Required Changes\n\n")
	out.WriteString("Apply the first listed group before later groups. If the answer is on the wrong subject, fix that rewrite first; save enrichment-only additions for a later retry.\n\n")
	for _, b := range buckets {
		if len(b.entries) == 0 {
			continue
		}
		fmt.Fprintf(&out, "**%s**:\n\n", retryRepairPhaseTitle(b.phase))
		for _, sv := range b.entries {
			out.WriteString("- ")
			if sv.FieldPath != "" {
				fmt.Fprintf(&out, "field path `%s`", sv.FieldPath)
			} else {
				out.WriteString("global fix")
			}
			if sv.Severity != "" {
				fmt.Fprintf(&out, " [%s]", sv.Severity)
			}
			if sv.BlockID != "" && !strings.Contains(sv.FieldPath, sv.BlockID) {
				fmt.Fprintf(&out, " (block id=%q)", sv.BlockID)
			}
			repair := strings.TrimSpace(sv.Repair)
			if repair == "" {
				repair = strings.TrimSpace(sv.Detail)
			}
			if repair != "" {
				fmt.Fprintf(&out, " — %s", repair)
			}
			out.WriteString("\n")
		}
		out.WriteString("\n")
	}
	return out.String()
}

func retryHasTopicMismatch(vs []types.ScoredViolation) bool {
	for _, sv := range vs {
		if sv.Kind == types.ViolAnswerTopicMismatch && sv.Severity != types.SeveritySoft {
			return true
		}
	}
	return false
}

func retryRequiredChangeAllowed(sv types.ScoredViolation, hasTopicMismatch bool) bool {
	if sv.Severity == "" || sv.Severity == types.SeveritySoft {
		return false
	}
	if !hasTopicMismatch {
		return true
	}
	if sv.Kind == types.ViolAnswerTopicMismatch {
		return true
	}
	return sv.Severity == types.SeverityCritical
}

func retryRepairPhaseOrder(hasTopicMismatch bool) []retryRepairPhase {
	if hasTopicMismatch {
		return []retryRepairPhase{
			retryRepairPhaseCoverage,
			retryRepairPhaseStructure,
			retryRepairPhaseConsistency,
			retryRepairPhaseRichness,
		}
	}
	return []retryRepairPhase{
		retryRepairPhaseStructure,
		retryRepairPhaseConsistency,
		retryRepairPhaseCoverage,
		retryRepairPhaseRichness,
	}
}

func retryRepairPhaseForViolation(sv types.ScoredViolation) retryRepairPhase {
	// Registry is the single source (F2 migration completion): the
	// historical hand-written per-kind switch moved into
	// ViolKindSpec.RepairPhase / EffectiveRepairPhase, pinned by the
	// registry golden snapshot test.
	if spec, ok := types.ViolKindSpecFor(sv.Kind); ok {
		return retryRepairPhase(spec.EffectiveRepairPhase())
	}
	// Unregistered kinds: derive from the producer-stage label the
	// violation itself carries (same derivation the registry uses).
	switch sv.Layer {
	case "semantic_quality":
		return retryRepairPhaseCoverage
	case "v2_oracle":
		return retryRepairPhaseStructure
	case "evidence_pool":
		return retryRepairPhaseRichness
	}
	return retryRepairPhaseConsistency
}

func retryRepairPhaseTitle(phase retryRepairPhase) string {
	switch phase {
	case retryRepairPhaseStructure:
		return "Payload shape"
	case retryRepairPhaseConsistency:
		return "Grounding and consistency"
	case retryRepairPhaseCoverage:
		return "Requested topic and coverage"
	case retryRepairPhaseRichness:
		return "Supported enrichment"
	default:
		return "Required fix"
	}
}

func retryRequiredSeverityRank(sev types.Severity) int {
	switch sev {
	case types.SeverityCritical:
		return 0
	case types.SeverityHigh:
		return 1
	case types.SeverityMedium:
		return 2
	case types.SeveritySoft:
		return 3
	default:
		return 4
	}
}

// renderRetryActiveViolations renders the full violation set
// grouped by Severity+Layer. Includes Soft violations (telemetry
// only — LLM is informed but not required to fix). Cross-layer
// rendering ensures LLM sees scheduler / V2 oracle / contract.Check
// violations together (R13).
func renderRetryActiveViolations(rs *types.RetryState) string {
	if rs == nil || len(rs.ActiveViolations) == 0 {
		return ""
	}
	// Group: severity → layer → []entries
	bySeverity := map[types.Severity]map[string][]types.ScoredViolation{}
	for _, sv := range rs.ActiveViolations {
		layers := bySeverity[sv.Severity]
		if layers == nil {
			layers = map[string][]types.ScoredViolation{}
			bySeverity[sv.Severity] = layers
		}
		layers[sv.Layer] = append(layers[sv.Layer], sv)
	}
	var out strings.Builder
	out.WriteString("## Active Violations (typed, by severity + layer)\n\n")
	severityOrder := []types.Severity{
		types.SeverityCritical, types.SeverityHigh,
		types.SeverityMedium, types.SeveritySoft,
	}
	for _, sev := range severityOrder {
		layers := bySeverity[sev]
		if len(layers) == 0 {
			continue
		}
		fmt.Fprintf(&out, "**%s**:\n\n", strings.ToUpper(string(sev)))
		// Stable iteration: sort layers by name (deterministic prompt).
		layerNames := make([]string, 0, len(layers))
		for n := range layers {
			layerNames = append(layerNames, n)
		}
		// Simple sort without import; len is small.
		for i := 0; i < len(layerNames); i++ {
			for j := i + 1; j < len(layerNames); j++ {
				if layerNames[j] < layerNames[i] {
					layerNames[i], layerNames[j] = layerNames[j], layerNames[i]
				}
			}
		}
		for _, layer := range layerNames {
			for _, sv := range layers[layer] {
				fmt.Fprintf(&out, "- [%s · %s] %s", layer, sv.Kind, strings.TrimSpace(sv.Detail))
				if sv.Severity == types.SeveritySoft {
					out.WriteString(" *(telemetry only)*")
				}
				out.WriteString("\n")
			}
		}
		out.WriteString("\n")
	}
	return out.String()
}

// renderRetryPrevEmit renders the typed projection of the previous
// emit so the LLM sees what fields it already filled (R6/R6.1 fix).
//
// For each block, lists:
//   - id + kind + surface_role
//   - facet_ids verbatim (if non-empty)
//   - block-level claim_use presence + claim_form (if any)
//   - item count + items_with_citation (if any)
//   - text preview (head 400 + tail 200 truncation)
func renderRetryPrevEmit(rs *types.RetryState) string {
	if rs == nil || len(rs.PrevEmitSummary.BlockSummaries) == 0 {
		return ""
	}
	var out strings.Builder
	out.WriteString("## Previous Emit (preserve every field below byte-identical unless listed in Required Changes)\n\n")
	for _, bs := range rs.PrevEmitSummary.BlockSummaries {
		fmt.Fprintf(&out, "Block id=%q kind=%s", bs.ID, bs.Kind)
		if bs.SurfaceRole != "" {
			fmt.Fprintf(&out, " surface_role=%q", string(bs.SurfaceRole))
		}
		out.WriteString(":\n")
		if len(bs.FacetIDs) > 0 {
			fmt.Fprintf(&out, "  facet_ids: %s\n", renderQuotedList(bs.FacetIDs))
		}
		if bs.HasClaimUse {
			fmt.Fprintf(&out, "  claim_use: present (claim_form=%q)\n", string(bs.ClaimForm))
		} else {
			out.WriteString("  claim_use: ABSENT (verify whether contract requires it)\n")
		}
		if bs.HasItems {
			fmt.Fprintf(&out, "  items: %d total, %d with citation\n",
				bs.ItemCount, bs.ItemsWithCitation)
		}
		if bs.EdgeAnchoredClaimUses > 0 {
			fmt.Fprintf(&out, "  edge_anchors: %d entries (block-level edge_anchors[] array — preserve these on retry)\n",
				bs.EdgeAnchoredClaimUses)
		}
		if bs.TextPreview != "" {
			// Indent preview for readability.
			preview := strings.ReplaceAll(strings.TrimSpace(bs.TextPreview), "\n", " ")
			if len([]rune(preview)) > 200 {
				preview = string([]rune(preview)[:200]) + "…"
			}
			fmt.Fprintf(&out, "  text preview: %q\n", preview)
		}
		out.WriteString("\n")
	}
	if rs.PrevEmitSummary.CitationsCount > 0 {
		fmt.Fprintf(&out, "Citations: %d entries", rs.PrevEmitSummary.CitationsCount)
		if len(rs.PrevEmitSummary.CitationFiles) > 0 {
			fmt.Fprintf(&out, " (top files: %s)", strings.Join(rs.PrevEmitSummary.CitationFiles, ", "))
		}
		out.WriteString("\n\n")
	}
	if rs.PrevEmitSummary.HasExactResolution {
		out.WriteString("exact_resolution: present (preserve byte-identical)\n\n")
	}
	if len(rs.PrevEmitSummary.BlockCompanionLineages) > 0 {
		out.WriteString("Compatibility split companions (both are model-visible; if removing one, explicitly retain, replace, or remove the other in the same patch):\n")
		for _, lineage := range types.NormalizeAnswerBlockCompanionLineages(rs.PrevEmitSummary.BlockCompanionLineages) {
			fmt.Fprintf(&out, "  - visible=%q diagram=%q lineage=%s\n",
				lineage.VisibleBlockID, lineage.DiagramBlockID, lineage.Kind)
		}
		out.WriteString("\n")
	}
	return out.String()
}

// ## Facets each block must cover — which semantic surface each
//
//	block should ground (cross-ref to
//	the existing Required Answer Facets
//	section above).
func renderAnswerDocBlockContract(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	view := types.BuildAnswerSemanticViewForAgentContext(ctx)
	if view == nil {
		return ""
	}

	var b strings.Builder
	b.WriteString("## Required Answer Blocks\n\n")
	b.WriteString("Your answer should be composed from one or more BLOCKS. Each block has a kind " +
		"(summary / section / ordered_list / bullet_list / scalar / decision / table / diagram / caveat) " +
		"and counts toward the contract for this question's family. " +
		"Required blocks marked below MUST appear; optional blocks add richness when their facet matches your evidence.\n\n")
	if len(view.RequiredBlocks) > 0 {
		b.WriteString("**Required (must emit):**\n\n")
		for _, req := range view.RequiredBlocks {
			renderAnswerDocBlockRequirement(&b, req, view, true)
		}
		b.WriteString("\n")
	}
	if len(view.OptionalBlocks) > 0 {
		b.WriteString("**Optional (recommended when evidence supports):**\n\n")
		for _, req := range view.OptionalBlocks {
			renderAnswerDocBlockRequirement(&b, req, view, false)
		}
		b.WriteString("\n")
	}
	if view.DiagramPlan != nil && view.DiagramPlan.Required {
		fmt.Fprintf(&b, "**Diagram contract:** required (kind=%s); the diagram block must cover the family's structural relationships.\n\n",
			view.DiagramPlan.Kind)
	}
	if len(view.UncertaintyRules) > 0 {
		b.WriteString("**Uncertainty disclosures:** when the listed conditions hold, include a caveat block disclosing the boundary so the user knows what was searched and what was assumed.\n\n")
	}
	return b.String()
}

func renderAnswerDocBlockRequirement(b *strings.Builder, req types.BlockRequirement, view *types.AnswerSemanticView, _ bool) {
	countTag := ""
	switch {
	case req.MinCount == 0 && req.MaxCount == 1:
		countTag = "0..1"
	case req.MinCount == 1 && req.MaxCount == 1:
		countTag = "exactly 1"
	case req.MinCount > 0 && req.MaxCount == 0:
		countTag = fmt.Sprintf("%d+", req.MinCount)
	case req.MinCount == 0 && req.MaxCount == 0:
		countTag = "any number"
	default:
		countTag = fmt.Sprintf("%d-%d", req.MinCount, req.MaxCount)
	}
	kindLabel := req.AcceptedKindsLabel()
	if kindLabel == "" {
		kindLabel = string(req.Kind)
	}
	fmt.Fprintf(b, "- **%s** (%s)", kindLabel, countTag)
	rationale := strings.TrimSpace(req.Rationale)
	if rationale != "" {
		fmt.Fprintf(b, " — %s", rationale)
	}
	b.WriteString("\n")

	// R7 (post_shape_residual_audit.md, 2026-05-04): typed-set
	// fields verbatim — LLM was filling block.facet_ids /
	// block.claim_uses[].claim_form / block.surface_role using GUESS-WORK
	// because the prose only listed field NAMES, not the typed string
	// VALUES. Now we expose the values verbatim under each block
	// requirement so the LLM can copy them directly into the emit.
	if len(req.FacetIDs) > 0 {
		fmt.Fprintf(b, "  - `block.facet_ids` MUST include: %s (copy verbatim into the emit).\n",
			renderQuotedList(req.FacetIDs))
	}
	if len(req.AcceptableClaimForms) > 0 {
		forms := make([]string, 0, len(req.AcceptableClaimForms))
		for _, f := range req.AcceptableClaimForms {
			forms = append(forms, string(f))
		}
		if answerBlockRequirementHasTypedDecisionCarrier(req, view) {
			fmt.Fprintf(b, "  - The active typed decision verdict field is the carrier for this `decision` block; `block.claim_uses[]` is optional. If you add it, `claim_form` must be one of: %s (copy verbatim; do not guess).\n",
				renderQuotedList(forms))
		} else {
			fmt.Fprintf(b, "  - At least one `block.claim_uses[]` entry's `claim_form` MUST be one of: %s (copy verbatim).\n",
				renderQuotedList(forms))
		}
	}
	if req.SurfaceRoleHint != "" {
		fmt.Fprintf(b, "  - `block.surface_role` SHOULD be %q (copy verbatim).\n",
			string(req.SurfaceRoleHint))
	}
}

func answerBlockRequirementHasTypedDecisionCarrier(req types.BlockRequirement, view *types.AnswerSemanticView) bool {
	if req.Kind != types.BlockDecision || view == nil {
		return false
	}
	return (view.CurrentStatusDiagnostic != nil && view.CurrentStatusDiagnostic.Required) ||
		(view.ErrorGranularityProfile != nil && view.ErrorGranularityProfile.Active())
}

func renderAnswerDocExclusionPolicy(ctx *types.AgentContext) string {
	effectiveRoles := tool.EffectiveAnswerExclusionRolesForAgentContext(ctx)
	if len(effectiveRoles) == 0 {
		return ""
	}
	roles := make([]string, 0, len(effectiveRoles))
	for _, role := range effectiveRoles {
		roles = append(roles, string(role))
	}
	var b strings.Builder
	b.WriteString("## Typed Exclusion Policy\n\n")
	fmt.Fprintf(&b, "The current request excludes principal answer rows whose `candidate_role` is one of: %s.\n\n",
		renderQuotedList(roles))
	b.WriteString("- Do not put excluded-role candidates in principal list/table items.\n")
	b.WriteString("- When a principal list/table row represents a candidate member, set `items[].candidate_role` to the closest enum value so the validator can enforce this policy structurally.\n")
	b.WriteString("- It is OK to mention the excluded category or grounded excluded count as a scope boundary in summary/caveat prose. Do not name concrete excluded candidates anywhere in the visible answer unless the user explicitly asked for the excluded items themselves.\n\n")
	return b.String()
}

func renderAnswerDocRequestedCandidateRoles(view *types.AnswerSemanticView) string {
	if view == nil || len(view.RequiredCandidateRoles) == 0 {
		return ""
	}
	roles := make([]string, 0, len(view.RequiredCandidateRoles))
	for _, role := range view.RequiredCandidateRoles {
		if role == types.AnswerCandidateRoleUnknown {
			continue
		}
		roles = append(roles, string(role))
	}
	if len(roles) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Typed Answer Role Contract\n\n")
	fmt.Fprintf(&b, "The current request requires principal answer row role coverage for: %s.\n\n",
		renderQuotedList(roles))
	b.WriteString("- Put `items[].candidate_role` on the principal scalar/list/table item(s) that carry these requested answer roles.\n")
	b.WriteString("- `candidate_role` classifies the principal item represented by one row. Do not use a route, owner, value, or other related column as a second role for that row; keep such attributes in cells/text with their grounded citation.\n")
	b.WriteString("- For scalar answers whose literal is in `block.text`, add a one-element `items[]` entry with `candidate_role` and the supporting carrier exposed by the projected item schema; use stable evidence identity when available. The row can reuse the scalar literal as its label or keep a short role label.\n")
	b.WriteString("- Do not satisfy this contract with prose-only wording. The validator compares required role enums with `items[].candidate_role` enums.\n")
	b.WriteString("- Adjacent roles can stay as supporting context, but the principal answer must include the requested role enum(s) above.\n\n")
	return b.String()
}

// renderAnswerDocVisibleAnchorWhitelist (2026-05-17 T1 architectural
// fix) surfaces the per-dispatch authoritative slate of symbols the
// finalizer may cite as item labels, inline backtick references, or
// diagram edge endpoints. The slate is the pre-emit reflection of
// the post-emit hallucination oracles' decision surface — letting the
// model write against an explicit constraint space instead of
// inferring valid surfaces from scattered evidence-pool fragments
// (which routinely leads to the antagonistic-constraint retry
// pattern where fixing one oracle silently trips another).
//
// Empty-slate suppression: nil ctx, nil plan, nil view, or an empty
// VisibleAnchorWhitelist all yield "" so prompts without a populated
// support plan (single-shot tests, pre-AnalysisIR paths) keep their
// existing shape. Section header is the first content line so the
// section tracer reliably detects the section even when the slate is
// truncated past MaxVisibleAnchorWhitelistEntries.
//
// Rendering discipline:
//
//   - Required entries lead the section verbatim — the model sees
//     the must-surface set before any other anchor data.
//   - Groundable entries split into "high-confidence" and
//     "cite-with-caveat" sub-buckets by tier rank; the model can
//     pick the higher-confidence anchor when alternatives exist.
//   - SurfaceForms render as a parenthetical aside on entries that
//     carry alternative spellings, so the model knows the symbol
//     oracle accepts the equivalent forms.
//   - Truncation past MaxVisibleAnchorWhitelistEntries emits a note
//     that the guide is bounded but support-lane anchors remain
//     valid when copied verbatim from typed evidence.
func renderAnswerDocVisibleAnchorWhitelist(ctx *types.AgentContext) string {
	if ctx == nil {
		return ""
	}
	plan := answerSupportPlan(ctx)
	view := types.BuildAnswerSemanticViewForAgentContext(ctx)
	whitelist := types.BuildVisibleAnchorWhitelist(plan, view)
	if whitelist.IsEmpty() {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Preferred Visible Anchors (Pre-flight Guide)\n\n")
	b.WriteString("The symbols below are the strongest pre-flight anchors for `blocks[].items[].label`, inline backtick references in prose `text`, and diagram edge endpoints. This guide is not an exclusive list: anchors copied verbatim from Typed Answer Support Lanes, evidence endpoints, citations, or aggregate support_refs can also be valid. Prefer entries in this guide when they fit; when you use another supported anchor, copy the exact surface and cite the same evidence line.\n\n")
	b.WriteString("If the later Required Principal Member Set section lists a member that is absent from this guide, the principal member_set contract takes precedence: render that member exactly from the aggregate fact instead of treating this guide as a closed whitelist.\n\n")
	if len(whitelist.Required) > 0 {
		b.WriteString("### Required anchors (must surface in structured fields)\n\n")
		for _, e := range whitelist.Required {
			writeVisibleAnchorBullet(&b, e)
		}
		b.WriteString("\n")
	}
	if len(whitelist.Groundable) > 0 {
		highConfidence := whitelist.Groundable[:0:0]
		caveatTier := whitelist.Groundable[:0:0]
		for _, e := range whitelist.Groundable {
			if e.IsHighConfidenceTier() {
				highConfidence = append(highConfidence, e)
			} else {
				caveatTier = append(caveatTier, e)
			}
		}
		if len(highConfidence) > 0 {
			b.WriteString("### Preferred anchors — safe to cite\n\n")
			b.WriteString("These surfaces are citation-aligned evidence anchors. The trailing role tells what the cited line proves: `function` / `symbol` entries can be used as definition-style anchors, while `call_site`, `condition`, `return`, `assignment`, `initializer`, `import`, and `string_literal` entries should be cited only for that evidence role, not as the symbol's definition line.\n\n")
			for _, e := range highConfidence {
				writeVisibleAnchorBullet(&b, e)
			}
			b.WriteString("\n")
		}
		if len(caveatTier) > 0 {
			b.WriteString("### Supported anchors — cite with caveat\n\n")
			b.WriteString("These symbols resolved via approximate / recovery paths — snippet-fuzzy match, package-symbol fallback, or nearest-call/condition heuristic. They can be cited, but prose using them should acknowledge the approximation (mark uncertain phrases, or add a `caveat` block) so readers know the citation is best-effort.\n\n")
			for _, e := range caveatTier {
				writeVisibleAnchorBullet(&b, e)
			}
			b.WriteString("\n")
		}
	}
	totalRendered := len(whitelist.Required) + len(whitelist.Groundable)
	if totalRendered >= types.MaxVisibleAnchorWhitelistEntries {
		fmt.Fprintf(&b, "_Note: this guide is capped at %d entries; additional supported surfaces from longer support lanes are omitted for brevity. Anchors copied verbatim from Typed Answer Support Lanes, evidence endpoints, citations, or aggregate support_refs may still be valid when citation-aligned._\n\n",
			types.MaxVisibleAnchorWhitelistEntries)
	}
	b.WriteString("- Do NOT promote names from retry diagnostics, Evidence notes, raw tool output, or generic prose into authoritative code references. Any surface not listed in this guide must be copied verbatim from Typed Answer Support Lanes, evidence endpoints, citations, or aggregate support_refs and must be citation-aligned.\n\n")
	return b.String()
}

// writeVisibleAnchorBullet emits one whitelist entry as a markdown
// bullet. Kept on the per-entry layer so the four call sites (Required,
// high-confidence Groundable, caveat-tier Groundable, future buckets)
// share a single rendering style without duplicating the format string.
func writeVisibleAnchorBullet(b *strings.Builder, e types.VisibleAnchorEntry) {
	b.WriteString("- `")
	b.WriteString(e.Symbol)
	b.WriteString("`")
	if e.QualifiedSymbol != "" && e.QualifiedSymbol != e.Symbol {
		fmt.Fprintf(b, " (qualified: `%s`)", e.QualifiedSymbol)
	}
	if e.SourceFile != "" {
		if e.SourceLine > 0 {
			fmt.Fprintf(b, " — `%s:%d`", e.SourceFile, e.SourceLine)
		} else {
			fmt.Fprintf(b, " — `%s`", e.SourceFile)
		}
	}
	if e.Kind != "" && e.Kind != types.VisibleAnchorKindOther {
		fmt.Fprintf(b, " · %s", e.Kind)
	}
	if len(e.SurfaceForms) > 1 {
		// SurfaceForms always contains the primary symbol when non-
		// empty; print only when at least one alternate form exists.
		alts := make([]string, 0, len(e.SurfaceForms))
		for _, sf := range e.SurfaceForms {
			if sf == e.Symbol {
				continue
			}
			alts = append(alts, "`"+sf+"`")
		}
		if len(alts) > 0 {
			fmt.Fprintf(b, " · equivalent surface forms: %s", strings.Join(alts, ", "))
		}
	}
	b.WriteString("\n")
}

func renderAnswerDocRequiredMechanismAnchors(view *types.AnswerSemanticView) string {
	if view == nil || len(view.RequiredMechanismAnchors) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Typed Mechanism Anchor Contract\n\n")
	b.WriteString("The current mechanism answer must keep these exact endpoint anchors visible in structured carrier fields:\n\n")
	for _, anchor := range view.RequiredMechanismAnchors {
		if strings.TrimSpace(anchor.Text) == "" {
			continue
		}
		fmt.Fprintf(&b, "- `%s` (%s)\n", anchor.Text, answerDocContractTermKindLabel(anchor.Kind))
	}
	b.WriteString("\n")
	b.WriteString("- Satisfy this with `blocks[].items[].label`, a section/table block `title`, or typed diagram `edge_anchors` endpoints.\n")
	b.WriteString("- If the main explanation is prose-only, add a compact ordered_list or table of key anchors; each item label should be the exact anchor and carry the relevant projected evidence/citation selector when available.\n")
	b.WriteString("- Do not rely on prose-only mentions. The validator compares the typed anchor list above with structured AnswerDocument fields.\n\n")
	if boundary := view.CallChainEndpointBoundary; boundary != nil && boundary.Active() {
		b.WriteString("- This answer also has a typed no-directed-path endpoint boundary. Keep the requested sink visible as a separate supporting boundary item/block; do not append it as a hop in the principal directed ordered_list merely to satisfy this anchor contract.\n\n")
	}
	return b.String()
}

func renderAnswerDocCallChainTargetDiscovery(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	profile := ctx.AnalysisIR.RequestModel.CallChainEndpointProfile
	if !profile.DiscoverSinkActive() && !profile.DiscoverTerminalActive() && !profile.DiscoverPathActive() && !profile.RequiresRuntimeSelectionEvidence() {
		return ""
	}
	var b strings.Builder
	if profile.DiscoverSinkActive() {
		b.WriteString("## Call-chain runtime target discovery\n\n")
		fmt.Fprintf(&b, "- grounded source endpoint: `%s`\n", strings.TrimSpace(profile.Source))
		b.WriteString("- destination mode: `discover`; no preselected sink has answer authority\n")
		b.WriteString("- Select the reached implementation/class/handler yourself from grounded call, registration/binding, dispatch, and inheritance/implementation evidence. A pre-scan candidate, nearby definition, or same-name method is not enough.\n")
	} else if profile.DiscoverTerminalActive() {
		b.WriteString("## Call-chain conceptual terminal discovery\n\n")
		fmt.Fprintf(&b, "- grounded source endpoint: `%s`\n", strings.TrimSpace(profile.Source))
		b.WriteString("- destination mode: `discover_terminal`; the request supplied a conceptual destination, not a preselected code sink or a runtime-selection claim\n")
		b.WriteString("- Identify the terminal code endpoint from grounded static call edges and inspect its body before selecting the destination.\n")
	} else if profile.DiscoverPathActive() {
		b.WriteString("## Call-chain role-bound relation composition\n\n")
		b.WriteString("- endpoint mode: `discover_path`; the request supplied conceptual path boundaries, not preselected code endpoints\n")
		b.WriteString("- Select both endpoint identities and the relations that advance the requested boundary from grounded evidence. The typed rows below are composition aids only: they do not promote a parser candidate into an endpoint, required hop, or final conclusion.\n")
	} else {
		b.WriteString("## Runtime selection evidence\n\n")
		if profile.ExactActive() {
			fmt.Fprintf(&b, "- exact requested endpoints: `%s` -> `%s`\n", strings.TrimSpace(profile.Source), strings.TrimSpace(profile.Sink))
			b.WriteString("- Preserve the grounded selection/binding facts alongside the exact endpoint path; endpoint identity alone does not prove that mechanism.\n")
		} else {
			b.WriteString("- The request asks how an implementation, handler, backend, provider, or attempt-specific tool/path becomes available or selected; it does not declare a source-to-sink call-chain endpoint pair.\n")
			b.WriteString("- Preserve the grounded selection/availability fact and its connected operation or owner. Do not invent endpoint identities merely to make a continuous path.\n")
		}
	}
	b.WriteString("- " + types.CallChainObservedEffectBoundaryTeaching + "\n")
	b.WriteString("- Keep relation kinds honest: registration/binding is not a source-level call. When dispatch is dynamic, show the grounded static prefix and the typed binding/dispatch boundary separately; do not invent a direct invocation merely to make one continuous arrow.\n")
	b.WriteString("- Distinguish the selected runtime class from the class or mixin that owns an inherited method definition. State both when they differ, with their own grounded citations. The model owns the final destination conclusion; this section only preserves the evidence boundary.\n")
	b.WriteString("- A diagram is optional unless the Required Answer Blocks section explicitly requires one. If the dynamic boundary cannot be drawn without turning a binding, return, inheritance, or method-owner relation into a call arrow, omit the diagram and use a grounded ordered list, table, or prose section instead.\n")
	if capsule := renderAnswerDocRuntimeTargetRelationCapsule(ctx); capsule != "" {
		b.WriteString("\n")
		b.WriteString(capsule)
	}
	if candidates := renderAnswerDocDynamicSelectorResolutionCandidates(ctx, strings.TrimSpace(profile.Source)); candidates != "" {
		b.WriteString("\n\n")
		b.WriteString(candidates)
	}
	return strings.TrimRight(b.String(), "\n")
}

const answerDocRuntimeTargetRelationCapsuleLimit = 18

const (
	answerDocLocalFactOrderGroupLimit = 4
	answerDocLocalFactOrderRowLimit   = 8
)

type answerDocRuntimeTargetRelationRow struct {
	family string
	item   types.EvidenceItem
}

type answerDocLocalFactOrderGroup struct {
	source string
	owner  string
	items  []types.EvidenceItem
}

const (
	answerDocDynamicSelectorEvidenceLimit  = 512
	answerDocDynamicSelectorCandidateLimit = 4
)

// renderAnswerDocDynamicSelectorResolutionCandidates gives Finalizer a small,
// versioned, candidate-only composition of already-citable typed relations.
// It does not select the runtime target, invent a continuous call chain, draw a
// diagram, or rewrite an answer. Incomplete or ambiguous groups stay withheld.
func renderAnswerDocDynamicSelectorResolutionCandidates(ctx *types.AgentContext, entryIdentity string) string {
	pool := answerDocDynamicSelectorEvidencePool(ctx, answerDocDynamicSelectorEvidenceLimit, entryIdentity)
	compiled := types.CompileDynamicSelectorResolutionPaths(
		pool,
		entryIdentity,
	)
	// Keep compilation failures observable without putting internal rejection
	// enums into the model prompt or the reader-facing answer. These are typed
	// compiler outcomes, not conclusions: the log is diagnostic-only and does
	// not relax the fail-closed candidate contract.
	if len(compiled.Rejected) > 0 {
		reasonCounts := make(map[types.DynamicSelectorResolutionRejectionReason]int)
		for _, rejected := range compiled.Rejected {
			reasonCounts[rejected.Reason]++
		}
		reasons := make([]string, 0, len(reasonCounts))
		for reason, count := range reasonCounts {
			reasons = append(reasons, fmt.Sprintf("%s=%d", reason, count))
		}
		sort.Strings(reasons)
		logging.Debug("[finalizer/dynamic_selector] entry=%q candidates=%d rejected=%d reasons=%s",
			strings.TrimSpace(entryIdentity), len(compiled.Candidates), len(compiled.Rejected), strings.Join(reasons, ","))
	}
	if len(compiled.Candidates) == 0 {
		return ""
	}
	limit := len(compiled.Candidates)
	if limit > answerDocDynamicSelectorCandidateLimit {
		limit = answerDocDynamicSelectorCandidateLimit
	}
	var b strings.Builder
	b.WriteString("### Typed dynamic-selection candidates (soft context; model-owned)\n\n")
	b.WriteString("Each candidate below is an exact static-evidence composition, not proof of the runtime-selected implementation. Preserve every hop's stated relation; a selector-side binding may remain an assignment rather than a registration edge. Do not replace registration, argument flow, assignment, return, callback, or type relation with a direct call.\n\n")
	for i := 0; i < limit; i++ {
		path := compiled.Candidates[i]
		fmt.Fprintf(&b, "- candidate `%d`: entry=`%s`; selector_argument=`%s`; selector_literal=`%s`; registry_container=`%s`; lookup=`%s`; declared_candidate=`%s`\n",
			i+1,
			answerDocCallChainInline(path.EntryIdentity),
			answerDocCallChainInline(path.SelectorArgument),
			answerDocCallChainInline(path.SelectorLiteral),
			answerDocCallChainInline(path.ContainerIdentity),
			answerDocCallChainInline(path.LookupIdentity),
			answerDocCallChainInline(path.CandidateIdentity),
		)
		for _, hop := range path.Hops {
			if hop.Role == types.DynamicSelectorHopSelectorApplication {
				fmt.Fprintf(&b, "  - typed declaration selector application: `%s` applies literal `%s` to `%s` [%s]; represent this as a note/table fact, not a diagram edge.\n",
					answerDocCallChainInline(path.SelectorOwner),
					answerDocCallChainInline(path.SelectorLiteral),
					answerDocCallChainInline(path.CandidateIdentity),
					answerDocCallChainInline(hop.EvidenceID),
				)
				continue
			}
			fmt.Fprintf(&b, "  - relation_kind=`%s`: `%s` -> `%s` [%s]\n",
				hop.RelationKind,
				answerDocCallChainInline(hop.FromIdentity),
				answerDocCallChainInline(hop.ToIdentity),
				answerDocCallChainInline(hop.EvidenceID),
			)
		}
		for _, hop := range path.CallbackHops {
			if hop.Role == types.DynamicSelectorHopCallbackReceiverCall {
				fmt.Fprintf(&b, "  - optional callback receiver call, relation_kind=`%s`: `%s` -> `%s` [%s]; this proves the receiving API call, not execution of the transferred callback.\n",
					hop.RelationKind,
					answerDocCallChainInline(hop.FromIdentity),
					answerDocCallChainInline(hop.ToIdentity),
					answerDocCallChainInline(hop.EvidenceID),
				)
			} else {
				fmt.Fprintf(&b, "  - optional callback handoff, relation_kind=`%s`: `%s` -> `%s` [%s]; it proves transfer of a callable, not later execution.\n",
					hop.RelationKind,
					answerDocCallChainInline(hop.FromIdentity),
					answerDocCallChainInline(hop.ToIdentity),
					answerDocCallChainInline(hop.EvidenceID),
				)
			}
		}
		for _, hop := range path.TypeRoster {
			fmt.Fprintf(&b, "  - optional declared-type row, relation_kind=`%s`: `%s` -> `%s` [%s]; it does not prove runtime MRO or invocation.\n",
				hop.RelationKind,
				answerDocCallChainInline(hop.FromIdentity),
				answerDocCallChainInline(hop.ToIdentity),
				answerDocCallChainInline(hop.EvidenceID),
			)
		}
	}
	if len(compiled.Candidates) > limit {
		fmt.Fprintf(&b, "\n- `%d` additional complete candidates are omitted only from this bounded prompt view; do not claim uniqueness from the displayed subset.\n", len(compiled.Candidates)-limit)
	}
	if len(compiled.Rejected) > 0 {
		b.WriteString("\n- Additional selector groups were withheld because their typed path was incomplete or ambiguous; do not reconstruct them from source-display text or prose.\n")
	}
	b.WriteString("\n- Use these rows as evidence options. The model decides whether the candidate is relevant, whether separate runtime evidence proves that the argument equals the selector literal, which relations to explain or draw, the reader-facing business wording, and the final conclusion. Do not expose carrier role/status names in the reader-facing answer, and never add a synthetic `entry -> declared_candidate` call.\n")
	return strings.TrimRight(b.String(), "\n")
}

const answerDocDynamicSelectorCandidateRecipeLimit = 24

// renderAnswerDocDynamicSelectorRelationRecipes appends schema-native,
// copy-ready relation recipes for complete dynamic-selection candidates to
// the shared relation-authoring capsule. The selector compiler already proved
// each hop from citable typed evidence; this function changes only the
// authoring shape. It does not select a candidate, join the candidate to a
// runtime invocation, author reader wording, or require a diagram.
func renderAnswerDocDynamicSelectorRelationRecipes(b *strings.Builder, ctx *types.AgentContext) []types.DiagramEdgeAnchor {
	if b == nil || ctx == nil || ctx.AnalysisIR == nil ||
		ctx.AnalysisIR.RequestModel.CallChainEndpointProfile == nil {
		return nil
	}
	entry := strings.TrimSpace(ctx.AnalysisIR.RequestModel.CallChainEndpointProfile.Source)
	if entry == "" {
		return nil
	}
	pool := answerDocDynamicSelectorEvidencePool(ctx, answerDocDynamicSelectorEvidenceLimit, entry)
	compiled := types.CompileDynamicSelectorResolutionPaths(pool, entry)
	if len(compiled.Candidates) == 0 {
		return nil
	}

	var anchors []types.DiagramEdgeAnchor
	recipeCount := 0
	b.WriteString("- Dynamic-selection candidates also have schema-native relation recipes below. They are candidate-only permissions, not a runtime-selection conclusion or a requirement to draw every edge. Keep each selected recipe's exact node ids, endpoint identities, direction, relation kind, and source occurrence; add one model-authored business `visible_label` and use it byte-identically on the matching Mermaid edge. Do not connect separate candidate groups, collapse repeated source occurrences, or turn assignment, argument flow, return, callback, or type relation into `call`.\n")
	for candidateIndex, path := range compiled.Candidates {
		if recipeCount >= answerDocDynamicSelectorCandidateRecipeLimit {
			break
		}
		fmt.Fprintf(b, "- dynamic_candidate_relation_group[%d]: selector_literal=`%s`; declared_candidate=`%s`; status=`candidate_only`; choose this group only when the model's evidence-backed runtime/argument reasoning selects it.\n",
			candidateIndex+1, answerDocCallChainInline(path.SelectorLiteral), answerDocCallChainInline(path.CandidateIdentity))

		type recipeHop struct {
			hop  types.DynamicSelectorResolutionHop
			kind string
		}
		hops := make([]recipeHop, 0, len(path.Hops)+len(path.CallbackHops)+len(path.TypeRoster))
		for _, hop := range path.Hops {
			if hop.Role == types.DynamicSelectorHopSelectorApplication || !hop.RelationKind.IsValid() {
				continue
			}
			hops = append(hops, recipeHop{hop: hop, kind: "core"})
		}
		for _, hop := range path.CallbackHops {
			if hop.RelationKind.IsValid() {
				hops = append(hops, recipeHop{hop: hop, kind: "optional_" + string(hop.Role)})
			}
		}
		for _, hop := range path.TypeRoster {
			if hop.RelationKind.IsValid() {
				hops = append(hops, recipeHop{hop: hop, kind: "optional_type"})
			}
		}
		for hopIndex, row := range hops {
			if recipeCount >= answerDocDynamicSelectorCandidateRecipeLimit {
				break
			}
			from := strings.TrimSpace(row.hop.FromIdentity)
			to := strings.TrimSpace(row.hop.ToIdentity)
			if from == "" || to == "" || strings.ContainsAny(from+to, "\x00\r\n") {
				continue
			}
			fromNode := fmt.Sprintf("dc%dr%df", candidateIndex+1, hopIndex+1)
			toNode := fmt.Sprintf("dc%dr%dt", candidateIndex+1, hopIndex+1)
			anchor := types.DiagramEdgeAnchor{
				FromNode: fromNode, ToNode: toNode,
				FromIdentity: from, ToIdentity: to,
				RelationKind: row.hop.RelationKind,
			}
			payload, err := json.Marshal(anchor)
			if err != nil {
				continue
			}
			loc := ""
			for _, item := range pool {
				if strings.TrimSpace(item.ID) == strings.TrimSpace(row.hop.EvidenceID) {
					loc = item.DisplayLocation(true)
					break
				}
			}
			fmt.Fprintf(b, "  - dynamic_candidate_node_alias[%d.%d.from]=`%s` -> `%s`; dynamic_candidate_node_alias[%d.%d.to]=`%s` -> `%s`\n",
				candidateIndex+1, hopIndex+1, fromNode, answerDocCallChainInline(from),
				candidateIndex+1, hopIndex+1, toNode, answerDocCallChainInline(to))
			fmt.Fprintf(b, "  - dynamic_candidate_edge_recipe[%d.%d]=`%s -> %s`; role=`%s`; relation_kind=`%s`; evidence=`%s`; edge_anchor_json=`%s`",
				candidateIndex+1, hopIndex+1, fromNode, toNode, row.kind, row.hop.RelationKind,
				answerDocCallChainInline(row.hop.EvidenceID), payload)
			if loc != "" {
				fmt.Fprintf(b, " @ %s", loc)
			}
			b.WriteString("\n")
			anchors = append(anchors, anchor)
			recipeCount++
		}
		for _, hop := range path.Hops {
			if hop.Role == types.DynamicSelectorHopSelectorApplication {
				fmt.Fprintf(b, "  - dynamic_candidate_note_recipe[%d]: selector owner=`%s`; literal=`%s`; declared candidate=`%s`; evidence=`%s`; this is a declaration note/table fact and never an edge.\n",
					candidateIndex+1, answerDocCallChainInline(path.SelectorOwner), answerDocCallChainInline(path.SelectorLiteral),
					answerDocCallChainInline(path.CandidateIdentity), answerDocCallChainInline(hop.EvidenceID))
				break
			}
		}
	}
	if len(anchors) == 0 {
		return nil
	}
	if recipeCount >= answerDocDynamicSelectorCandidateRecipeLimit {
		b.WriteString("- Additional dynamic candidate relation recipes were omitted only from this bounded authoring view; do not infer uniqueness or absence from the displayed subset.\n")
	}
	return anchors
}

func answerDocDynamicSelectorEvidencePool(ctx *types.AgentContext, limit int, entryIdentity string) []types.EvidenceItem {
	if ctx == nil || limit <= 0 {
		return nil
	}
	entryIdentity = strings.TrimSpace(entryIdentity)
	isCore := func(item types.EvidenceItem) bool {
		if item.SelectorApplication != nil {
			return true
		}
		switch types.ClaimFormOf(item) {
		case types.ClaimRegistrationEdge, types.ClaimAssignmentFact, types.ClaimReturnFact,
			types.ClaimArgumentFlow, types.ClaimCallbackHandoff:
			return true
		default:
			return types.IsRepoMapTypeRelationEvidence(item)
		}
	}
	isCall := func(item types.EvidenceItem) bool {
		if types.ClaimFormOf(item) != types.ClaimCallEdge {
			return false
		}
		// Subject is the typed source endpoint of a call edge. OwnerSymbol is
		// only enclosing qualification and may legitimately be more qualified
		// than the requested entry (for example pipeline.runner.run_pipeline
		// versus run_pipeline). Keep the same endpoint priority as the selector
		// compiler so an exact call is not discarded before compilation.
		return entryIdentity == "" || types.AnswerCodeIdentitySurfacesEquivalent(
			firstNonEmptyAnswerDocString(item.Subject, item.OwnerSymbol), entryIdentity,
		)
	}
	seen := make(map[string]int, limit)
	out := make([]types.EvidenceItem, 0, extractorMinInt(len(ctx.EvidenceItems), limit))
	addGroup := func(items []types.EvidenceItem, accept func(types.EvidenceItem) bool, familyCount *int, familyLimit int) {
		for _, item := range items {
			if !accept(item) {
				continue
			}
			id := strings.TrimSpace(item.ID)
			if id == "" {
				id = types.StableEvidenceID(item)
				item.ID = id
			}
			if idx, ok := seen[id]; ok {
				out[idx] = types.MergeEvidenceItemByStableID(out[idx], item)
				continue
			}
			if len(out) >= limit || *familyCount >= familyLimit {
				continue
			}
			seen[id] = len(out)
			out = append(out, item)
			*familyCount = *familyCount + 1
		}
	}
	groups := [][]types.EvidenceItem{ctx.EvidenceItems}
	if ctx.Mutable != nil {
		if ta := ctx.Mutable.TurnAArtifacts(); ta != nil {
			groups = append(groups, ta.EvidenceItems)
		}
		groups = append(groups, ctx.Mutable.EmittedEvidence())
	}
	// Calls are normally the largest family. Reserve three quarters of this
	// bounded pool for the rarer selector/binding/value/type carriers so a
	// broad call inventory cannot starve the very rows needed to compile the
	// dynamic boundary. The remaining quarter carries entry/callback calls.
	coreLimit := limit - limit/4
	coreCount := 0
	for _, group := range groups {
		addGroup(group, isCore, &coreCount, coreLimit)
	}
	callCount := 0
	for _, group := range groups {
		addGroup(group, isCall, &callCount, limit-coreLimit)
	}
	return out
}

// renderAnswerDocLocalFactOrderCapsule exposes exact lexical order for
// accepted, same-owner source facts when a guard is present. It deliberately
// does not infer control-flow containment: source order can refute a reversed
// narration, but only a parser-authored control relation may prove which
// operation a condition guards. This is advisory model context, never an
// answer rewrite or emit-time gate.
func renderAnswerDocLocalFactOrderCapsule(ctx *types.AgentContext) string {
	supportScope := supportLaneScopeForContext(ctx, true)
	return renderAnswerDocLocalFactOrderCapsuleWithScope(ctx, supportScope)
}

func renderAnswerDocLocalFactOrderCapsuleWithScope(ctx *types.AgentContext, supportScope *supportLaneScope) string {
	pool := answerDocTypedEnrichmentEvidencePool(ctx, 256)
	if len(pool) == 0 {
		return ""
	}
	groupsBySource := make(map[string]map[string]*answerDocLocalFactOrderGroup)
	seen := make(map[string]struct{})
	for _, item := range pool {
		claim := types.ClaimFormOf(item)
		switch claim {
		case types.ClaimCallEdge, types.ClaimCallbackHandoff, types.ClaimArgumentFlow, types.ClaimGuardCondition, types.ClaimBranchEffect,
			types.ClaimAssignmentFact, types.ClaimReturnFact:
		default:
			continue
		}
		if !item.IsCitable() || item.LineStart <= 0 || strings.TrimSpace(item.Source) == "" ||
			types.RuntimeArtifactPathKind(item.Source) != "" || claim == types.ClaimExternalObservation {
			continue
		}
		owner := firstNonEmptyAnswerDocString(item.OwnerSymbol, item.Subject)
		if owner == "" {
			continue
		}
		if supportScope != nil && !supportScope.allowsLocalFact(owner, item) {
			continue
		}
		identity := answerDocEvidenceIdentity(item)
		if _, duplicate := seen[identity]; duplicate {
			continue
		}
		seen[identity] = struct{}{}
		sourceKey := strings.ToLower(strings.TrimSpace(item.Source))
		ownerKey := answerDocLocalFactOwnerKey(owner)
		groupsByOwner := groupsBySource[sourceKey]
		if groupsByOwner == nil {
			groupsByOwner = make(map[string]*answerDocLocalFactOrderGroup)
			groupsBySource[sourceKey] = groupsByOwner
		}
		group := groupsByOwner[ownerKey]
		if group == nil {
			group = &answerDocLocalFactOrderGroup{source: strings.TrimSpace(item.Source), owner: owner}
			groupsByOwner[ownerKey] = group
		}
		group.items = append(group.items, item)
	}

	// Sparse model-authored calls can carry only a callable leaf (`log`)
	// while parser/grounder facts carry a qualified identity (`Logger.log`).
	// Join those spellings only when the leaf has exactly one compatible
	// qualified owner in the same source. A short name shared by A.log and
	// B.log remains separate and lends neither owner an order/guard fact.
	for _, groupsByOwner := range groupsBySource {
		for ownerKey, group := range groupsByOwner {
			if answerDocLocalFactOwnerQualified(group.owner) {
				continue
			}
			matchKey := ""
			for candidateKey, candidate := range groupsByOwner {
				if candidateKey == ownerKey || !answerDocLocalFactOwnerQualified(candidate.owner) ||
					!answerDocDispatchIdentityCompatible(group.owner, candidate.owner) {
					continue
				}
				if matchKey != "" {
					matchKey = ""
					break
				}
				matchKey = candidateKey
			}
			if matchKey != "" {
				groupsByOwner[matchKey].items = append(groupsByOwner[matchKey].items, group.items...)
				delete(groupsByOwner, ownerKey)
			}
		}
	}

	groups := make([]answerDocLocalFactOrderGroup, 0)
	for _, groupsByOwner := range groupsBySource {
		for _, group := range groupsByOwner {
			hasGuard := false
			hasDifferentLine := false
			firstLine := 0
			for _, item := range group.items {
				if firstLine == 0 {
					firstLine = item.LineStart
				} else if item.LineStart != firstLine {
					hasDifferentLine = true
				}
				if types.ClaimFormOf(item) == types.ClaimGuardCondition {
					hasGuard = true
				}
			}
			if !hasGuard || !hasDifferentLine {
				continue
			}
			sort.SliceStable(group.items, func(i, j int) bool {
				if group.items[i].LineStart != group.items[j].LineStart {
					return group.items[i].LineStart < group.items[j].LineStart
				}
				return answerDocEvidenceIdentity(group.items[i]) < answerDocEvidenceIdentity(group.items[j])
			})
			groups = append(groups, *group)
		}
	}
	if len(groups) == 0 {
		return ""
	}
	sort.SliceStable(groups, func(i, j int) bool {
		if groups[i].source != groups[j].source {
			return groups[i].source < groups[j].source
		}
		return groups[i].owner < groups[j].owner
	})

	var b strings.Builder
	b.WriteString("## Typed same-owner lexical order (advisory)\n\n")
	b.WriteString("These rows preserve parser/grounder-accepted source order. They do not by themselves prove branch containment or causality.\n\n")
	for groupIndex, group := range groups {
		if groupIndex >= answerDocLocalFactOrderGroupLimit {
			break
		}
		fmt.Fprintf(&b, "- owner=`%s` source=`%s`\n",
			answerDocCallChainInline(group.owner), answerDocCallChainInline(group.source))
		for rowIndex, item := range group.items {
			if rowIndex >= answerDocLocalFactOrderRowLimit {
				break
			}
			fmt.Fprintf(&b, "  %d. line=`%d` claim_form=`%s` fact=`%s` [%s]\n",
				rowIndex+1,
				item.LineStart,
				types.ClaimFormOf(item),
				answerDocCallChainInline(answerDocLocalFactOrderDescription(item)),
				answerDocCallChainInline(answerDocEvidenceIdentity(item)),
			)
		}
	}
	b.WriteString("\n- Do not narrate a later guard as preceding an earlier operation. Attribute an operation to a guard only when a separate typed control-scope/containment relation proves that ownership; otherwise keep the guard and operation as separate facts and let the model state the remaining uncertainty.\n")
	return strings.TrimRight(b.String(), "\n")
}

func answerDocLocalFactOwnerKey(raw string) string {
	owner, operation := answerDocDispatchEndpointParts(raw)
	if owner != "" && operation != "" {
		return strings.ToLower(strings.TrimSpace(owner) + "." + strings.TrimSpace(operation))
	}
	return strings.ToLower(strings.TrimSpace(raw))
}

func answerDocLocalFactOwnerQualified(raw string) bool {
	owner, operation := answerDocDispatchEndpointParts(raw)
	return owner != "" && operation != ""
}

func answerDocLocalFactOrderDescription(item types.EvidenceItem) string {
	switch types.ClaimFormOf(item) {
	case types.ClaimCallEdge, types.ClaimCallbackHandoff, types.ClaimArgumentFlow:
		return firstNonEmptyAnswerDocString(item.OwnerSymbol, item.Subject) + " -> " + strings.TrimSpace(item.Object)
	case types.ClaimGuardCondition:
		return firstNonEmptyAnswerDocString(item.Condition, item.Object, item.AnchorSymbol, item.Subject)
	case types.ClaimBranchEffect:
		return strings.TrimSpace(item.Subject) + " -> " + strings.TrimSpace(item.Object)
	case types.ClaimAssignmentFact, types.ClaimReturnFact:
		return strings.TrimSpace(item.Subject) + " -> " + strings.TrimSpace(item.Object)
	default:
		return firstNonEmptyAnswerDocString(item.AnchorSymbol, item.Subject, item.Object)
	}
}

// renderAnswerDocRuntimeTargetRelationCapsule places the typed relation
// families needed for dynamic target discovery next to each other without
// collapsing them into a synthetic call path. Every row comes from a citable
// typed EvidenceItem; no model prose, investigation notes, or request keyword
// scan participates. The grouping is explanatory only — the model still owns
// target selection and the final conclusion.
func renderAnswerDocRuntimeTargetRelationCapsule(ctx *types.AgentContext) string {
	pool := answerDocTypedEnrichmentEvidencePool(ctx, 128)
	if len(pool) == 0 {
		return ""
	}
	registrations := make([]answerDocRuntimeTargetRelationRow, 0)
	decoratorApplications := make([]answerDocRuntimeTargetRelationRow, 0)
	structural := make([]answerDocRuntimeTargetRelationRow, 0)
	methodDefinitions := make([]answerDocRuntimeTargetRelationRow, 0)
	valueFlowCandidates := make([]answerDocRuntimeTargetRelationRow, 0)
	callbacks := make([]answerDocRuntimeTargetRelationRow, 0)
	cooperativeDelegations := make([]answerDocRuntimeTargetRelationRow, 0)
	calls := make([]answerDocRuntimeTargetRelationRow, 0)
	seen := make(map[string]struct{})
	for _, original := range pool {
		item := original
		// Registration evidence has an exact typed anchor symbol in older
		// sparse emits even when the optional subject field was omitted. Use
		// that typed carrier for capsule display only; never parse the summary
		// and never mutate the accepted evidence row.
		if item.Kind == types.EvidenceRegistration && strings.TrimSpace(item.Subject) == "" && strings.TrimSpace(item.Object) != "" {
			item.Subject = strings.TrimSpace(item.AnchorSymbol)
		}
		if !item.IsCitable() || strings.TrimSpace(item.Subject) == "" {
			continue
		}
		id := answerDocEvidenceIdentity(item)
		if _, duplicate := seen[id]; duplicate {
			continue
		}
		row := answerDocRuntimeTargetRelationRow{item: item}
		switch {
		case item.Producer == types.EvidenceProducerRepoMapDecoratorApplication &&
			item.Predicate == "decorator_selector_application" && strings.TrimSpace(item.Object) != "":
			row.family = "decorator_application"
			decoratorApplications = append(decoratorApplications, row)
			seen[id] = struct{}{}
			continue
		case types.ClaimFormOf(item) == types.ClaimDefinitionFact && !types.IsRepoMapTypeRelationEvidence(item):
			if owner, operation := answerDocDispatchEndpointParts(firstNonEmptyAnswerDocString(item.OwnerSymbol, item.Subject)); owner != "" && operation != "" {
				row.family = "method_definition"
				methodDefinitions = append(methodDefinitions, row)
				seen[id] = struct{}{}
			}
			continue
		case strings.TrimSpace(item.Object) == "":
			continue
		case types.ClaimFormOf(item) == types.ClaimRegistrationEdge:
			row.family = "registration_or_binding"
			registrations = append(registrations, row)
		case (item.Producer == types.EvidenceProducerRepoMapStructuralRelation ||
			item.Producer == types.EvidenceProducerRepoMapImplementerRelation) &&
			(item.Predicate == "inheritance" || item.Predicate == "embedding" || item.Predicate == "implements"):
			row.family = "declared_type_relation"
			structural = append(structural, row)
		case (item.Producer == "concrete_values" || item.Producer == "bridge_literal") &&
			(types.ClaimFormOf(item) == types.ClaimReturnFact || types.ClaimFormOf(item) == types.ClaimAssignmentFact):
			row.family = "value_or_factory_flow"
			valueFlowCandidates = append(valueFlowCandidates, row)
		case item.Producer == types.EvidenceProducerRepoMapCooperativeCall && types.ClaimFormOf(item) == types.ClaimCallEdge:
			row.family = "cooperative_delegation"
			cooperativeDelegations = append(cooperativeDelegations, row)
		case types.ClaimFormOf(item) == types.ClaimCallEdge:
			row.family = "static_call"
			calls = append(calls, row)
		case types.ClaimFormOf(item) == types.ClaimCallbackHandoff:
			row.family = "callback_handoff"
			callbacks = append(callbacks, row)
		default:
			continue
		}
		seen[id] = struct{}{}
	}
	// Concrete-value extraction is intentionally broad; unrelated method
	// returns from a candidate file must not consume the tiny dynamic-target
	// capsule budget. Keep a value/factory row only when one of its typed
	// endpoints is exactly connected to a static call or registration endpoint
	// (or the analyzer-declared source endpoint). This is graph connectivity,
	// not request/model prose similarity, and it does not create a new edge.
	connectedEndpointTails := make(map[string]struct{})
	addConnectedEndpoint := func(raw string) {
		tail := strings.ToLower(types.NormalizedSurfaceSymbolTail(strings.TrimSpace(raw)))
		if tail != "" {
			connectedEndpointTails[tail] = struct{}{}
		}
	}
	if ctx != nil && ctx.AnalysisIR != nil && ctx.AnalysisIR.RequestModel.CallChainEndpointProfile != nil {
		addConnectedEndpoint(ctx.AnalysisIR.RequestModel.CallChainEndpointProfile.Source)
	}
	for _, row := range calls {
		addConnectedEndpoint(row.item.Subject)
		addConnectedEndpoint(row.item.Object)
	}
	for _, row := range callbacks {
		addConnectedEndpoint(row.item.Subject)
		addConnectedEndpoint(row.item.Object)
	}
	for _, row := range registrations {
		addConnectedEndpoint(row.item.Subject)
		addConnectedEndpoint(row.item.Object)
	}
	connectedValueOwners := make([]string, 0, len(decoratorApplications)+len(registrations))
	for _, row := range registrations {
		connectedValueOwners = append(connectedValueOwners, strings.TrimSpace(row.item.Object))
	}
	for _, row := range decoratorApplications {
		addConnectedEndpoint(row.item.Subject)
		addConnectedEndpoint(row.item.Object)
		connectedValueOwners = append(connectedValueOwners, strings.TrimSpace(row.item.Object))
	}
	valueFlows := make([]answerDocRuntimeTargetRelationRow, 0, len(valueFlowCandidates))
	for _, row := range valueFlowCandidates {
		subjectTail := strings.ToLower(types.NormalizedSurfaceSymbolTail(strings.TrimSpace(row.item.Subject)))
		objectTail := strings.ToLower(types.NormalizedSurfaceSymbolTail(strings.TrimSpace(row.item.Object)))
		_, subjectConnected := connectedEndpointTails[subjectTail]
		_, objectConnected := connectedEndpointTails[objectTail]
		owner, _ := answerDocDispatchEndpointParts(row.item.Subject)
		ownerConnected := false
		for _, candidate := range connectedValueOwners {
			if answerDocDispatchIdentityCompatible(owner, candidate) {
				ownerConnected = true
				break
			}
		}
		if !subjectConnected && !objectConnected && !ownerConnected {
			continue
		}
		valueFlows = append(valueFlows, row)
	}
	// A relevance rank may reorder otherwise-equal evidence rows. Restore the
	// parser-authored declaration order for base/implements/embedding rosters;
	// this is typed source structure, not a model conclusion or prose heuristic.
	sort.SliceStable(structural, func(i, j int) bool {
		a, z := structural[i].item, structural[j].item
		if a.Source != z.Source {
			return a.Source < z.Source
		}
		if a.LineStart != z.LineStart {
			return a.LineStart < z.LineStart
		}
		if a.Subject != z.Subject {
			return a.Subject < z.Subject
		}
		if a.Predicate != z.Predicate {
			return a.Predicate < z.Predicate
		}
		if a.RelationOrdinal > 0 && z.RelationOrdinal > 0 && a.RelationOrdinal != z.RelationOrdinal {
			return a.RelationOrdinal < z.RelationOrdinal
		}
		return false
	})
	ordered := make([]answerDocRuntimeTargetRelationRow, 0, answerDocRuntimeTargetRelationCapsuleLimit)
	appendBounded := func(rows []answerDocRuntimeTargetRelationRow, familyCap int) {
		for i, row := range rows {
			if i >= familyCap || len(ordered) >= answerDocRuntimeTargetRelationCapsuleLimit {
				return
			}
			ordered = append(ordered, row)
		}
	}
	// Registration and type-declaration facts are normally much rarer than
	// call edges and are essential at the dynamic-dispatch boundary. Give
	// each a bounded protected slice, then use the remaining budget for the
	// already-ranked static prefix.
	appendBounded(registrations, 6)
	appendBounded(decoratorApplications, 6)
	appendBounded(structural, 8)
	appendBounded(valueFlows, 6)
	appendBounded(callbacks, 6)
	appendBounded(cooperativeDelegations, 6)
	appendBounded(calls, answerDocRuntimeTargetRelationCapsuleLimit)
	if len(ordered) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("### Typed relation capsule (bounded, no synthetic edges)\n\n")
	for _, row := range ordered {
		item := row.item
		predicate := answerDocCallChainInline(item.Predicate)
		if predicate == "" {
			predicate = row.family
		}
		location := answerDocCallChainInline(item.DisplayLocation(true))
		if location == "" {
			location = "location-unavailable"
		}
		fmt.Fprintf(&b, "- family=`%s` relation=`%s` subject=`%s` object=`%s` [%s] @ %s",
			row.family,
			predicate,
			answerDocCallChainInline(item.Subject),
			answerDocCallChainInline(item.Object),
			answerDocCallChainInline(answerDocEvidenceIdentity(item)),
			location)
		if row.family == "declared_type_relation" && item.RelationOrdinal > 0 {
			fmt.Fprintf(&b, " declared_order=`%d`", item.RelationOrdinal)
		}
		if form := answerDocReturnExpressionForm(item); form != "" {
			fmt.Fprintf(&b, " expression_form=`%s`", form)
		}
		b.WriteString("\n")
	}
	b.WriteString("\n- These rows can be composed in the explanation, but only `family=static_call` is a source-level invocation edge. A value/factory row proves only its typed return or assignment, and a declared-type row proves only the inherited/implemented owner relationship; neither alone proves that the registry selected that type at runtime. A callback-handoff row proves only that a receiving API was given a callable value, not that it later executed.\n")
	if compositions := renderAnswerDocRuntimeDispatchCompositions(registrations, structural, calls); compositions != "" {
		b.WriteString("\n")
		b.WriteString(compositions)
	}
	if compositions := renderAnswerDocCooperativeMethodRosters(registrations, structural, methodDefinitions, cooperativeDelegations); compositions != "" {
		b.WriteString("\n")
		b.WriteString(compositions)
	}
	if roleSeparation := renderAnswerDocSelectorValueRoleSeparation(decoratorApplications, valueFlows); roleSeparation != "" {
		b.WriteString("\n")
		b.WriteString(roleSeparation)
	}
	return strings.TrimRight(b.String(), "\n")
}

func renderAnswerDocSelectorValueRoleSeparation(
	decoratorApplications, valueFlows []answerDocRuntimeTargetRelationRow,
) string {
	type pair struct {
		application types.EvidenceItem
		value       types.EvidenceItem
	}
	var pairs []pair
	seen := make(map[string]struct{})
	for _, application := range decoratorApplications {
		target := strings.TrimSpace(application.item.Object)
		if target == "" {
			continue
		}
		for _, value := range valueFlows {
			if types.ClaimFormOf(value.item) != types.ClaimReturnFact {
				continue
			}
			owner, operation := answerDocDispatchEndpointParts(value.item.Subject)
			if owner == "" || operation == "" || !answerDocDispatchIdentityCompatible(owner, target) {
				continue
			}
			key := answerDocEvidenceIdentity(application.item) + "\x00" + answerDocEvidenceIdentity(value.item)
			if _, duplicate := seen[key]; duplicate {
				continue
			}
			seen[key] = struct{}{}
			pairs = append(pairs, pair{application: application.item, value: value.item})
		}
	}
	if len(pairs) == 0 {
		return ""
	}
	if len(pairs) > 8 {
		pairs = pairs[:8]
	}
	var b strings.Builder
	b.WriteString("### Typed selector/value roles (do not substitute)\n\n")
	b.WriteString("The same declaration owns these separately typed values. A decorator selector is not interchangeable with a method return value. Whether the selector is a registry key still depends on separate grounded evidence from the decorator implementation.\n\n")
	for _, entry := range pairs {
		fmt.Fprintf(&b, "- target=`%s`; decorator_application=`%s` [%s] @ %s; independent_method_return=`%s -> %s` [%s] @ %s\n",
			answerDocCallChainInline(entry.application.Object),
			answerDocCallChainInline(entry.application.Subject),
			answerDocCallChainInline(answerDocEvidenceIdentity(entry.application)),
			answerDocCallChainInline(entry.application.DisplayLocation(true)),
			answerDocCallChainInline(entry.value.Subject),
			answerDocCallChainInline(entry.value.Object),
			answerDocCallChainInline(answerDocEvidenceIdentity(entry.value)),
			answerDocCallChainInline(entry.value.DisplayLocation(true)))
	}
	b.WriteString("\n- Keep the two values in their typed roles when reasoning. Do not replace the selector with the return value, or the return value with the selector, merely because both belong to the same class/type. The model retains ownership of the final binding/dispatch conclusion.\n")
	return strings.TrimRight(b.String(), "\n")
}

const answerDocRuntimeDispatchCompositionLimit = 4

const answerDocCooperativeMethodRosterLimit = 4

// renderAnswerDocCooperativeMethodRosters composes parser-authored declared
// base order, citable method definitions and exact explicit-super calls. The
// roster remains candidate-only: direct base declaration order plus super
// syntax does not universally prove a language's full runtime MRO.
func renderAnswerDocCooperativeMethodRosters(
	registrations, structural, definitions, delegations []answerDocRuntimeTargetRelationRow,
) string {
	type rosterEntry struct {
		typeRelation types.EvidenceItem
		definition   types.EvidenceItem
		delegation   *types.EvidenceItem
		owner        string
		operation    string
	}
	type roster struct {
		candidate  string
		operation  string
		entries    []rosterEntry
		binding    *types.EvidenceItem
		delegators int
	}

	definitionByOwnerOperation := make(map[string]types.EvidenceItem)
	definitionOperationNames := make(map[string]string)
	for _, row := range definitions {
		owner, operation := answerDocDispatchEndpointParts(firstNonEmptyAnswerDocString(row.item.OwnerSymbol, row.item.Subject))
		if owner == "" || operation == "" {
			continue
		}
		key := strings.ToLower(owner) + "\x00" + strings.ToLower(operation)
		if _, exists := definitionByOwnerOperation[key]; !exists {
			definitionByOwnerOperation[key] = row.item
			definitionOperationNames[key] = operation
		}
	}
	delegationByOwnerOperation := make(map[string]types.EvidenceItem)
	for _, row := range delegations {
		owner, operation := answerDocDispatchEndpointParts(firstNonEmptyAnswerDocString(row.item.OwnerSymbol, row.item.Subject))
		if owner == "" || operation == "" {
			continue
		}
		key := strings.ToLower(owner) + "\x00" + strings.ToLower(operation)
		if _, exists := delegationByOwnerOperation[key]; !exists {
			delegationByOwnerOperation[key] = row.item
		}
	}
	lookupOwnerOperation := func(items map[string]types.EvidenceItem, owner, operationKey string) (types.EvidenceItem, bool) {
		for key, item := range items {
			parts := strings.SplitN(key, "\x00", 2)
			if len(parts) == 2 && parts[1] == operationKey && answerDocDispatchIdentityCompatible(parts[0], owner) {
				return item, true
			}
		}
		return types.EvidenceItem{}, false
	}

	structuralByCandidate := make(map[string][]types.EvidenceItem)
	var candidateOrder []string
	for _, row := range structural {
		candidate := strings.TrimSpace(row.item.Subject)
		if candidate == "" || strings.TrimSpace(row.item.Object) == "" || row.item.RelationOrdinal <= 0 {
			continue
		}
		key := strings.ToLower(candidate)
		if _, exists := structuralByCandidate[key]; !exists {
			candidateOrder = append(candidateOrder, key)
		}
		structuralByCandidate[key] = append(structuralByCandidate[key], row.item)
	}
	var rosters []roster
	for _, candidateKey := range candidateOrder {
		typeRows := structuralByCandidate[candidateKey]
		if len(typeRows) < 2 {
			continue
		}
		sort.SliceStable(typeRows, func(i, j int) bool { return typeRows[i].RelationOrdinal < typeRows[j].RelationOrdinal })
		operationCounts := make(map[string]int)
		operationNames := make(map[string]string)
		for _, typeRow := range typeRows {
			base := strings.TrimSpace(typeRow.Object)
			for key := range definitionByOwnerOperation {
				parts := strings.SplitN(key, "\x00", 2)
				if len(parts) != 2 || !answerDocDispatchIdentityCompatible(parts[0], base) {
					continue
				}
				operationCounts[parts[1]]++
				operationNames[parts[1]] = firstNonEmptyAnswerDocString(definitionOperationNames[key], parts[1])
			}
		}
		var operations []string
		for operation, count := range operationCounts {
			if count >= 2 {
				operations = append(operations, operation)
			}
		}
		sort.Strings(operations)
		for _, operationKey := range operations {
			candidate := roster{candidate: strings.TrimSpace(typeRows[0].Subject), operation: operationNames[operationKey]}
			for _, typeRow := range typeRows {
				base := strings.TrimSpace(typeRow.Object)
				definition, ok := lookupOwnerOperation(definitionByOwnerOperation, base, operationKey)
				if !ok {
					continue
				}
				entry := rosterEntry{typeRelation: typeRow, definition: definition, owner: base, operation: operationKey}
				if delegation, ok := lookupOwnerOperation(delegationByOwnerOperation, base, operationKey); ok {
					delegationCopy := delegation
					entry.delegation = &delegationCopy
					candidate.delegators++
				}
				candidate.entries = append(candidate.entries, entry)
			}
			if len(candidate.entries) < 2 {
				continue
			}
			for i := range registrations {
				if answerDocDispatchIdentityCompatible(registrations[i].item.Object, candidate.candidate) {
					binding := registrations[i].item
					candidate.binding = &binding
					break
				}
			}
			rosters = append(rosters, candidate)
			if len(rosters) >= answerDocCooperativeMethodRosterLimit {
				break
			}
		}
		if len(rosters) >= answerDocCooperativeMethodRosterLimit {
			break
		}
	}
	if len(rosters) == 0 {
		return ""
	}

	var b strings.Builder
	b.WriteString("### Typed cooperative-method rosters (candidate-only)\n\n")
	b.WriteString("Each roster preserves declared base order, independent method definitions, and any exact explicit-super calls. It does not turn the roster into direct owner-to-owner invocation edges or claim a fully resolved runtime MRO.\n\n")
	for i, candidate := range rosters {
		fmt.Fprintf(&b, "- candidate `%d`: declared_type=`%s`; operation=`%s`; runtime_mro_status=`unproven`",
			i+1, answerDocCallChainInline(candidate.candidate), answerDocCallChainInline(candidate.operation))
		if candidate.binding != nil {
			fmt.Fprintf(&b, "; binding_candidate=`%s -> %s` [%s] @ %s",
				answerDocCallChainInline(candidate.binding.Subject), answerDocCallChainInline(candidate.binding.Object),
				answerDocCallChainInline(answerDocEvidenceIdentity(*candidate.binding)), answerDocCallChainInline(candidate.binding.DisplayLocation(true)))
		}
		b.WriteString("\n")
		for _, entry := range candidate.entries {
			fmt.Fprintf(&b, "  %d. declared_owner=`%s`; type_relation=[%s] @ %s; method_definition=`%s.%s` [%s] @ %s",
				entry.typeRelation.RelationOrdinal,
				answerDocCallChainInline(entry.owner),
				answerDocCallChainInline(answerDocEvidenceIdentity(entry.typeRelation)),
				answerDocCallChainInline(entry.typeRelation.DisplayLocation(true)),
				answerDocCallChainInline(entry.owner),
				answerDocCallChainInline(entry.operation),
				answerDocCallChainInline(answerDocEvidenceIdentity(entry.definition)),
				answerDocCallChainInline(entry.definition.DisplayLocation(true)))
			if entry.delegation != nil {
				fmt.Fprintf(&b, "; cooperative_delegation=`%s -> %s` [%s] @ %s",
					answerDocCallChainInline(entry.delegation.Subject), answerDocCallChainInline(entry.delegation.Object),
					answerDocCallChainInline(answerDocEvidenceIdentity(*entry.delegation)), answerDocCallChainInline(entry.delegation.DisplayLocation(true)))
			}
			b.WriteString("\n")
		}
		fmt.Fprintf(&b, "  - typed_super_delegations=`%d/%d`; cooperative_path_status=`candidate_only`\n",
			candidate.delegators, maxInt(0, len(candidate.entries)-1))
	}
	b.WriteString("\n- Safe rendering: use `type_relation` edges for the declared-type roster and keep every proven `owner.operation -> super.operation` call as that exact call. Do not draw `BaseA.operation -> BaseB.operation` as a direct call unless a separate typed call edge names those exact owners. A sequence diagram may use a Note for candidate MRO order; an ordered list may describe the roster with `runtime_mro_status=unproven`. The model decides whether additional binding/runtime evidence proves the selected path.\n")
	return strings.TrimRight(b.String(), "\n")
}

// renderAnswerDocRuntimeDispatchCompositions joins only exact typed relation
// rows already present in the runtime-target capsule. The join is deliberately
// candidate-only: a static receiver call plus a declared subtype/implementer
// and a same-operation implementation body explains how dispatch *could* be
// represented, but it cannot prove which runtime value was selected. This is
// soft model context, never an answer rewrite or emit-time gate.
func renderAnswerDocRuntimeDispatchCompositions(
	registrations, structural, calls []answerDocRuntimeTargetRelationRow,
) string {
	type composition struct {
		staticCall         types.EvidenceItem
		typeRelation       types.EvidenceItem
		implementationCall types.EvidenceItem
		bindingCandidate   *types.EvidenceItem
	}
	var compositions []composition
	seen := make(map[string]struct{})
	for _, staticRow := range calls {
		staticOwner, operation := answerDocDispatchEndpointParts(staticRow.item.Object)
		if staticOwner == "" || operation == "" {
			continue
		}
		for _, typeRow := range structural {
			child := strings.TrimSpace(typeRow.item.Subject)
			base := strings.TrimSpace(typeRow.item.Object)
			if child == "" || base == "" || !answerDocDispatchIdentityCompatible(staticOwner, base) {
				continue
			}
			for _, implementationRow := range calls {
				implementationOwner, implementationOperation := answerDocDispatchEndpointParts(
					firstNonEmptyAnswerDocString(implementationRow.item.OwnerSymbol, implementationRow.item.Subject),
				)
				if implementationOwner == "" || implementationOperation == "" ||
					!strings.EqualFold(operation, implementationOperation) ||
					!answerDocDispatchIdentityCompatible(implementationOwner, child) {
					continue
				}
				key := strings.ToLower(strings.Join([]string{
					answerDocEvidenceIdentity(staticRow.item),
					answerDocEvidenceIdentity(typeRow.item),
					answerDocEvidenceIdentity(implementationRow.item),
				}, "\x00"))
				if _, duplicate := seen[key]; duplicate {
					continue
				}
				seen[key] = struct{}{}
				candidate := composition{
					staticCall:         staticRow.item,
					typeRelation:       typeRow.item,
					implementationCall: implementationRow.item,
				}
				for i := range registrations {
					if answerDocDispatchIdentityCompatible(registrations[i].item.Object, child) {
						binding := registrations[i].item
						candidate.bindingCandidate = &binding
						break
					}
				}
				compositions = append(compositions, candidate)
				if len(compositions) >= answerDocRuntimeDispatchCompositionLimit {
					break
				}
			}
			if len(compositions) >= answerDocRuntimeDispatchCompositionLimit {
				break
			}
		}
		if len(compositions) >= answerDocRuntimeDispatchCompositionLimit {
			break
		}
	}
	if len(compositions) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("### Typed dynamic-dispatch compositions (candidate-only)\n\n")
	b.WriteString("Each row below is a lossless composition of separate typed facts. It is a diagram/explanation recipe, not proof that the candidate implementation was selected at runtime.\n\n")
	for i, candidate := range compositions {
		fmt.Fprintf(&b, "- candidate `%d`: static_call=`%s -> %s` [%s] @ %s; type_relation=`%s -> %s` [%s] @ %s; implementation_body_call=`%s -> %s` [%s] @ %s",
			i+1,
			answerDocCallChainInline(firstNonEmptyAnswerDocString(candidate.staticCall.OwnerSymbol, candidate.staticCall.Subject)),
			answerDocCallChainInline(candidate.staticCall.Object),
			answerDocCallChainInline(answerDocEvidenceIdentity(candidate.staticCall)),
			answerDocCallChainInline(candidate.staticCall.DisplayLocation(true)),
			answerDocCallChainInline(candidate.typeRelation.Subject),
			answerDocCallChainInline(candidate.typeRelation.Object),
			answerDocCallChainInline(answerDocEvidenceIdentity(candidate.typeRelation)),
			answerDocCallChainInline(candidate.typeRelation.DisplayLocation(true)),
			answerDocCallChainInline(firstNonEmptyAnswerDocString(candidate.implementationCall.OwnerSymbol, candidate.implementationCall.Subject)),
			answerDocCallChainInline(candidate.implementationCall.Object),
			answerDocCallChainInline(answerDocEvidenceIdentity(candidate.implementationCall)),
			answerDocCallChainInline(candidate.implementationCall.DisplayLocation(true)),
		)
		if candidate.bindingCandidate != nil {
			fmt.Fprintf(&b, "; binding_candidate=`%s -> %s` [%s] @ %s",
				answerDocCallChainInline(candidate.bindingCandidate.Subject),
				answerDocCallChainInline(candidate.bindingCandidate.Object),
				answerDocCallChainInline(answerDocEvidenceIdentity(*candidate.bindingCandidate)),
				answerDocCallChainInline(candidate.bindingCandidate.DisplayLocation(true)),
			)
		}
		b.WriteString("; runtime_selection_status=`conditional`\n")
	}
	b.WriteString("\n- Safe diagram construction: keep `static_call` and `implementation_body_call` as separate call edges. In a sequence diagram, describe the base-to-candidate dispatch boundary with a `Note over` rather than a message arrow. In an architecture/call-DAG diagram, the subtype/implements edge may use `relation_kind=type_relation` and an exact binding may use `relation_kind=register`; neither may be recast as `call`. The model decides whether the binding and current request prove a selected runtime target.\n")
	return strings.TrimRight(b.String(), "\n")
}

func answerDocDispatchEndpointParts(raw string) (string, string) {
	identity := strings.TrimSpace(raw)
	if identity == "" {
		return "", ""
	}
	if idx := strings.Index(identity, "("); idx >= 0 {
		identity = identity[:idx]
	}
	for _, separator := range []string{"::", "->", "#", "/"} {
		identity = strings.ReplaceAll(identity, separator, ".")
	}
	identity = strings.Trim(identity, " .`*&")
	idx := strings.LastIndex(identity, ".")
	if idx <= 0 || idx+1 >= len(identity) {
		return "", ""
	}
	return strings.TrimSpace(identity[:idx]), strings.TrimSpace(identity[idx+1:])
}

func answerDocDispatchIdentityCompatible(left, right string) bool {
	left = strings.TrimSpace(left)
	right = strings.TrimSpace(right)
	if left == "" || right == "" {
		return false
	}
	return strings.EqualFold(left, right) ||
		types.CallChainEndpointCompatible(left, right) ||
		types.CallChainEndpointCompatible(right, left)
}

func firstNonEmptyAnswerDocString(values ...string) string {
	for _, value := range values {
		if value = strings.TrimSpace(value); value != "" {
			return value
		}
	}
	return ""
}

func renderAnswerDocCallChainEndpointBoundary(view *types.AnswerSemanticView, lang string) string {
	if view == nil || view.CallChainEndpointBoundary == nil || !view.CallChainEndpointBoundary.Active() {
		return ""
	}
	boundary := view.CallChainEndpointBoundary
	zh := strings.HasPrefix(strings.ToLower(strings.TrimSpace(lang)), "zh")
	var b strings.Builder
	b.WriteString("## Typed Call-Chain Endpoint Boundary\n\n")
	fmt.Fprintf(&b, "- source_endpoint=`%s`\n", answerDocCallChainInline(boundary.SourceEndpoint))
	fmt.Fprintf(&b, "- requested_sink=`%s`\n", answerDocCallChainInline(boundary.RequestedSink))
	if boundary.EvidenceCapsule == nil || boundary.EvidenceCapsule.Status != types.CallChainEndpointEvidenceDirectedPathPresent {
		if zh {
			b.WriteString("- 证据边界：当前已接纳的调用证据没有证明从起点到用户所问终点的有向调用路径。\n")
		} else {
			b.WriteString("- Evidence boundary: the accepted call evidence does not prove a directed call path from the source to the requested sink.\n")
		}
	}
	if capsule := boundary.EvidenceCapsule; capsule != nil {
		fmt.Fprintf(&b, "- %s\n", answerDocCallChainStatusReaderFact(capsule.Status, zh))
		if zh {
			fmt.Fprintf(&b, "- 当前证据胶囊包含 %d 条已落到源码的调用边。\n", capsule.EdgeCount)
		} else {
			fmt.Fprintf(&b, "- The current evidence capsule contains %d source-grounded call edges.\n", capsule.EdgeCount)
		}
		if capsule.SourceProof != "" {
			fmt.Fprintf(&b, "- %s\n", answerDocCallChainExistenceReaderFact("source", capsule.SourceProof, zh))
		}
		if capsule.RequestedSinkProof != "" {
			fmt.Fprintf(&b, "- %s\n", answerDocCallChainExistenceReaderFact("requested sink", capsule.RequestedSinkProof, zh))
		}
		if capsule.SourceProof == types.CallChainEndpointExistenceDefinitionOnly {
			if zh {
				b.WriteString("- 起点只有定义证据；当前胶囊没有给出与它相连的调用边。\n")
			} else {
				b.WriteString("- The source has definition evidence only; this capsule does not emit an incident call edge for it.\n")
			}
		}
		if capsule.RequestedSinkProof == types.CallChainEndpointExistenceDefinitionOnly {
			if zh {
				b.WriteString("- 用户所问终点只有定义证据；当前胶囊没有给出与它相连的调用边。\n")
			} else {
				b.WriteString("- The requested sink has definition evidence only; this capsule does not emit an incident call edge for it.\n")
			}
		}
		if capsule.SharedFrontier != "" {
			if zh {
				fmt.Fprintf(&b, "- 两侧路径共同到达的被调用函数是 `%s`。\n", answerDocCallChainInline(capsule.SharedFrontier))
			} else {
				fmt.Fprintf(&b, "- The callee reached independently from both sides is `%s`.\n", answerDocCallChainInline(capsule.SharedFrontier))
			}
		}
		if capsule.Status == types.CallChainEndpointEvidenceSharedCalleeBoundary && capsule.SharedFrontier != "" {
			fmt.Fprintf(&b, "- Exact directed topology: `%s -> ... -> %s <- ... <- %s`\n",
				answerDocCallChainInline(boundary.SourceEndpoint),
				answerDocCallChainInline(capsule.SharedFrontier),
				answerDocCallChainInline(boundary.RequestedSink))
		}
		b.WriteString("\n### Grounded endpoint evidence capsule\n\n")
		principalEdges := types.CallChainEndpointBoundaryPrincipalEdges(capsule)
		switch capsule.Status {
		case types.CallChainEndpointEvidenceDirectedPathPresent:
			renderAnswerDocCallChainEvidencePath(&b, answerDocCallChainPathLabel("source", zh), capsule.SourcePath)
		case types.CallChainEndpointEvidenceSharedCalleeBoundary:
			renderAnswerDocCallChainEvidencePath(&b, answerDocCallChainPathLabel("source", zh), capsule.SourcePath)
			renderAnswerDocCallChainEvidencePath(&b, answerDocCallChainPathLabel("sink", zh), capsule.SinkPath)
		case types.CallChainEndpointEvidenceReversePath:
			renderAnswerDocCallChainEvidencePath(&b, answerDocCallChainPathLabel("sink", zh), capsule.SinkPath)
		case types.CallChainEndpointEvidenceDisjointFrontiers:
			renderAnswerDocCallChainEvidencePath(&b, answerDocCallChainPathLabel("source frontier", zh), capsule.SourceFrontier)
			renderAnswerDocCallChainEvidencePath(&b, answerDocCallChainPathLabel("sink boundary", zh), capsule.RequestedBoundary)
		}
		if capsule.SourcePathOmitted > 0 {
			fmt.Fprintf(&b, "- %d middle source-side path edges are omitted from this bounded prompt capsule.\n", capsule.SourcePathOmitted)
		}
		if capsule.SinkPathOmitted > 0 {
			fmt.Fprintf(&b, "- %d middle requested-sink-side path edges are omitted from this bounded prompt capsule.\n", capsule.SinkPathOmitted)
		}
		if len(principalEdges) == 0 {
			b.WriteString("- No principal endpoint-boundary call edge is available. Other accepted call facts remain audit/support evidence only and are not intermediate hops for this exact endpoint question.\n")
		} else {
			b.WriteString("- A structured list/table block that declares `principal_path_edge` is reserved for the endpoint-boundary edges above. Put other grounded local calls in a separate supporting block without that facet; do not mix sibling calls into the principal endpoint carrier.\n")
		}
		b.WriteString("- The graph finding describes only resolution inside the grounded call-edge graph. Endpoint existence is separate evidence, and a definition-only endpoint may legitimately be absent from that graph.\n")
	}
	b.WriteString("\n")
	if boundary.EvidenceCapsule != nil && boundary.EvidenceCapsule.Status == types.CallChainEndpointEvidenceDirectedPathPresent {
		b.WriteString("The current grounded call-edge capsule contains a directed source-to-sink path and therefore conflicts with the retained no-directed-path boundary. Treat this as typed evidence-state inconsistency: synthesize from the cited path, do not present the stale boundary as established, and do not invent a replacement relation.\n\n")
		b.WriteString("- The model owns the conclusion; the system is only disclosing the conflicting typed carriers.\n\n")
		return b.String()
	}
	b.WriteString("The accepted investigation did not prove a directed source-to-sink call path. This is an endpoint boundary, not a reachable-chain member declaration.\n\n")
	b.WriteString("- Treat the capsule rows as grounded facts, not system-authored answer prose. Use them to synthesize the explanation and conclusion yourself.\n")
	b.WriteString("- Keep the nearest proven directed path from the typed call-edge rows above. Do not extend it to the requested sink through definition proximity, source order, or a prefix sibling.\n")
	b.WriteString("- An exact definition-site proof establishes that endpoint's existence. The absence of an incident call edge in this bounded capsule does not prove the endpoint is a leaf or has no callers/callees. Keep that local topology unproven unless an explicit typed call edge above establishes it.\n")
	b.WriteString("- Keep reverse or shared-callee typed calls as separate relationships in their real direction; never flip one to close the requested path.\n")
	if boundary.EvidenceCapsule != nil && boundary.EvidenceCapsule.Status == types.CallChainEndpointEvidenceSharedCalleeBoundary {
		b.WriteString("- Read the displayed topology literally: both arrowheads end at the same callee. Keep the two call facts separate; call edges alone do not prove parallel execution, convergence, a join, or a source-to-sink sequence. Never turn the two inward-pointing paths into a source-to-sink chain.\n")
	}
	b.WriteString("- Preserve the exact requested sink in a structured boundary/caveat/list item so the user's endpoint remains visible, but do not describe it as called by the reachable frontier.\n")
	b.WriteString("- Keep that requested-sink boundary in a separate supporting item/block, not as the last hop of the principal directed ordered_list. A definition-only boundary is visible context, not an extra path member.\n")
	b.WriteString("- The summary, principal member roster, and diagram must share this disposition. The model owns the conclusion; this typed context supplies the evidence boundary only.\n\n")
	return b.String()
}

// answerDocCallChainStatusReaderFact keeps machine topology enums inside the
// typed semantic view. The finalizer needs their exact meaning, not their wire
// spelling; omitting the raw token lowers copy pressure without changing any
// validator, relation direction, evidence edge, or model-owned conclusion.
func answerDocCallChainStatusReaderFact(status types.CallChainEndpointEvidenceStatus, zh bool) string {
	if zh {
		switch status {
		case types.CallChainEndpointEvidenceNoEdges:
			return "图形结论：没有可用于判断两个端点关系的已落地调用边。"
		case types.CallChainEndpointEvidenceEndpointUnresolved:
			return "图形结论：至少一个端点尚未在调用边图中唯一解析。"
		case types.CallChainEndpointEvidenceEndpointAmbiguous:
			return "图形结论：至少一个端点对应多个调用图节点，方向关系仍有歧义。"
		case types.CallChainEndpointEvidenceDirectedPathPresent:
			return "图形结论：已落地调用边构成从起点到用户所问终点的有向路径。"
		case types.CallChainEndpointEvidenceReversePath:
			return "图形结论：只证明了从用户所问终点指向起点的反向调用路径。"
		case types.CallChainEndpointEvidenceSharedCalleeBoundary:
			return "图形结论：起点与用户所问终点各自沿同一方向调用到同一个函数，但两侧都没有到达对方。"
		case types.CallChainEndpointEvidenceDisjointFrontiers:
			return "图形结论：两侧只形成彼此分离的已证调用前沿，没有连接成同一条路径。"
		default:
			return "图形结论：当前调用边证据不足以确定两个端点之间的有向关系。"
		}
	}
	switch status {
	case types.CallChainEndpointEvidenceNoEdges:
		return "Graph finding: no grounded call edge is available to determine the relation between the endpoints."
	case types.CallChainEndpointEvidenceEndpointUnresolved:
		return "Graph finding: at least one endpoint is not uniquely resolved in the call-edge graph."
	case types.CallChainEndpointEvidenceEndpointAmbiguous:
		return "Graph finding: at least one endpoint maps to multiple call-graph nodes, so the direction remains ambiguous."
	case types.CallChainEndpointEvidenceDirectedPathPresent:
		return "Graph finding: the grounded call edges form a directed path from the source to the requested sink."
	case types.CallChainEndpointEvidenceReversePath:
		return "Graph finding: only a reverse path from the requested sink toward the source is proved."
	case types.CallChainEndpointEvidenceSharedCalleeBoundary:
		return "Graph finding: the source and requested sink each follow same-direction calls to one common callee, but neither side reaches the other."
	case types.CallChainEndpointEvidenceDisjointFrontiers:
		return "Graph finding: the two sides have separate proved call frontiers and do not form one connected path."
	default:
		return "Graph finding: the current call-edge evidence does not determine a directed relation between the endpoints."
	}
}

func answerDocCallChainExistenceReaderFact(side string, proof types.CallChainEndpointExistenceProof, zh bool) string {
	if zh {
		label := "起点"
		if side != "source" {
			label = "用户所问终点"
		}
		switch proof {
		case types.CallChainEndpointExistenceCallEdge:
			return label + "存在性：已有落到源码的调用边直接引用这个端点。"
		case types.CallChainEndpointExistenceDefinitionOnly:
			return label + "存在性：只由精确定义位置证明，尚无与它相连的调用边。"
		default:
			return label + "存在性：当前证据尚不能唯一确认。"
		}
	}
	label := "Source"
	if side != "source" {
		label = "Requested-sink"
	}
	switch proof {
	case types.CallChainEndpointExistenceCallEdge:
		return label + " existence: a source-grounded call edge directly references this endpoint."
	case types.CallChainEndpointExistenceDefinitionOnly:
		return label + " existence: only an exact definition site proves it; no incident call edge is available."
	default:
		return label + " existence: the current evidence does not uniquely establish it."
	}
}

func answerDocCallChainPathLabel(kind string, zh bool) string {
	if zh {
		switch kind {
		case "source":
			return "起点侧已证路径"
		case "sink":
			return "终点侧已证路径"
		case "source frontier":
			return "起点侧已证前沿"
		default:
			return "终点侧已证边界"
		}
	}
	switch kind {
	case "source":
		return "Grounded source-side path"
	case "sink":
		return "Grounded requested-sink-side path"
	case "source frontier":
		return "Grounded source-side frontier"
	default:
		return "Grounded requested-sink-side boundary"
	}
}

func renderAnswerDocCallChainEvidencePath(b *strings.Builder, label string, edges []types.CallChainEvidenceEdge) {
	for _, edge := range edges {
		from := answerDocCallChainInline(edge.From)
		to := answerDocCallChainInline(edge.To)
		location := answerDocCallChainInline(edge.Source)
		if edge.LineStart > 0 {
			location = fmt.Sprintf("%s:%d", location, edge.LineStart)
			if edge.LineEnd > edge.LineStart {
				location += fmt.Sprintf("-%d", edge.LineEnd)
			}
		}
		identity := answerDocCallChainInline(edge.EvidenceID)
		if identity == "" {
			identity = "typed-call-edge"
		}
		fmt.Fprintf(b, "- %s: `%s` -> `%s` [%s] @ %s\n", label, from, to, identity, location)
	}
}

func answerDocCallChainInline(raw string) string {
	raw = strings.ReplaceAll(raw, "`", "'")
	return strings.Join(strings.Fields(raw), " ")
}

func renderAnswerDocErrorGranularityContract(view *types.AnswerSemanticView) string {
	if view == nil || view.ErrorGranularityProfile == nil || !view.ErrorGranularityProfile.Active() {
		return ""
	}
	values := make([]string, 0, len(types.AllErrorGranularityVerdicts()))
	for _, verdict := range types.AllErrorGranularityVerdicts() {
		values = append(values, string(verdict))
	}
	var b strings.Builder
	b.WriteString("## Typed Error Granularity Contract\n\n")
	b.WriteString("The current request requires a canonical failure-scope verdict.\n\n")
	allowedValues := values
	if len(view.ErrorGranularityProfile.RequestedVerdictOptions) > 0 {
		allowedValues = make([]string, 0, len(view.ErrorGranularityProfile.RequestedVerdictOptions)+1)
		for _, verdict := range view.ErrorGranularityProfile.RequestedVerdictOptions {
			allowedValues = append(allowedValues, string(verdict))
		}
		allowedValues = append(allowedValues, string(types.ErrorGranularityNotEnoughEvidence))
	}
	fmt.Fprintf(&b, "- Emit a principal `decision` block with `error_granularity_verdict` set to one of: %s.\n",
		renderQuotedList(allowedValues))
	if len(view.ErrorGranularityProfile.RequestedVerdictOptions) > 0 {
		b.WriteString("- The analyzer captured explicit requested verdict options for this question. Choose the most specific evidence-supported enum from those options; use `not_enough_evidence` only when the evidence cannot decide between them. Do not substitute a broader umbrella verdict that was not one of the requested options.\n")
	}
	b.WriteString("- Choose the enum from grounded evidence: `per_item_rejection` means the bad item or record is rejected while valid siblings continue; `whole_batch_failure` means one failure rejects the whole call or batch; `partial_success` means a mixed result is returned; `fail_fast` means processing stops at the first failure; `collect_errors` means errors are accumulated for reporting; `not_enough_evidence` means the evidence cannot decide.\n")
	b.WriteString("- Put the rationale and citations in the same decision block; do not satisfy this contract with prose-only wording.\n\n")
	b.WriteString("- For item-vs-batch or fail-fast judgments, cite both sides when available: the item-level handling branch (append/skip/continue/return for one record) and the batch-level gate (for example `len(built)==0`, rollback, or first-error return). Closure prose may summarize the verdict, but it is not a citation.\n\n")
	return b.String()
}

// renderQuotedList formats a slice of typed string values as a
// comma-separated list of double-quoted tokens so the LLM sees
// JSON-ready string values it can copy directly into the emit:
//
//	["enumeration_item", "uncertainty_boundary"]
//
// R7: LLM-facing typed-set field rendering — the verbatim form
// removes the "guess what string to put here" failure mode.
func renderQuotedList(values []string) string {
	if len(values) == 0 {
		return ""
	}
	out := make([]string, 0, len(values))
	for _, v := range values {
		v = strings.TrimSpace(v)
		if v == "" {
			continue
		}
		out = append(out, fmt.Sprintf("%q", v))
	}
	return "[" + strings.Join(out, ", ") + "]"
}

func renderAnswerDocFacetCoverage(ctx *types.AgentContext) string {
	plan := answerSurfacePlan(ctx)
	if plan == nil {
		return ""
	}
	// The semantic view applies typed family/runtime overrides after the
	// surface plan is compiled (for example demoting current_code_path when a
	// trace-only answer has no current-source lane). Rendering the original
	// plan here made the prompt teach a HARD facet that the block contract and
	// validator had already withdrawn. Read the same post-override carrier as
	// the validator so JSON teaching and execution cannot diverge.
	view := types.BuildAnswerSemanticViewForAgentContext(ctx)
	fc := plan.FacetCoverage
	if view != nil && view.FacetCoverage != nil {
		fc = view.FacetCoverage
	}
	if fc == nil {
		return ""
	}
	if len(fc.Required) == 0 && len(fc.Optional) == 0 {
		return ""
	}

	// R7 (post_shape_residual_audit.md, 2026-05-04): build a reverse
	// map of facet kind → block kind(s) so each facet line can name
	// the block where it should live. Reads view.RequiredBlocks /
	// OptionalBlocks (already in the prompt above) without
	// duplicating typed values.
	facetToBlocks := map[types.AnswerFacetKind][]types.AnswerBlockKind{}
	if view != nil {
		collect := func(blocks []types.BlockRequirement) {
			for _, blk := range blocks {
				for _, fid := range blk.FacetIDs {
					k := types.AnswerFacetKind(fid)
					facetToBlocks[k] = append(facetToBlocks[k], blk.AcceptedKinds()...)
				}
			}
		}
		collect(view.RequiredBlocks)
		collect(view.OptionalBlocks)
	}
	formatBlocks := func(kinds []types.AnswerBlockKind) string {
		if len(kinds) == 0 {
			return ""
		}
		seen := map[types.AnswerBlockKind]bool{}
		out := make([]string, 0, len(kinds))
		for _, k := range kinds {
			if seen[k] {
				continue
			}
			seen[k] = true
			out = append(out, fmt.Sprintf("`%s`", string(k)))
		}
		return strings.Join(out, ", ")
	}

	var b strings.Builder
	b.WriteString("## Required Answer Facets\n\n")
	b.WriteString("The user's question imposes the following coverage requirements on the rendered answer. " +
		"Each facet names a semantic surface the answer must touch; the parenthesised hint names the evidence shape that supports it. " +
		"Cover every HARD facet; SOFT facets are recommended when the answer already discusses their evidence; OPTIONAL facets add richness when they fit.\n\n")
	b.WriteString("To declare a facet on a block, set `block.facet_ids` (or `block.claim_uses[j].facet_id`) to the verbatim string shown after `facet_id:` on each line below — that exact string MUST appear in the emit. The rightmost hint (when present) names the block kind(s) that typically cover the facet so you know where to place it.\n\n")
	b.WriteString("Each line ends with `(evidence: N)` — N is the curated answer-grade evidence count when a typed support lane exists, otherwise the count of typed evidence items already bound to the facet. " +
		"For SOFT facets, N=0 means there is no typed evidence to surface, so do NOT invent claims for it. " +
		"For SOFT facets with N≥1, the line carries `(evidence available)`: cover it when the answer already discusses that evidence, but missing facet metadata alone is not an emit-time rejection. " +
		"For HARD facets, coverage is demanded regardless of N because the question pinned the facet as essential.\n\n")

	// Enumerate the facet_ids that the pre-emit oracle will hard-reject
	// if absent from any block. This is intentionally limited to
	// template-hard facets; evidence-sufficient SOFT facets are guidance,
	// not rewrite triggers.
	mustDeclare := make([]string, 0, len(fc.Required))
	mustDeclareSeen := map[types.AnswerFacetKind]bool{}
	for _, req := range fc.Required {
		if !req.RequiresHardDeclaration() {
			continue
		}
		if mustDeclareSeen[req.Kind] {
			continue
		}
		mustDeclareSeen[req.Kind] = true
		mustDeclare = append(mustDeclare, fmt.Sprintf("`%q`", string(req.Kind)))
	}
	if len(mustDeclare) > 0 {
		fmt.Fprintf(&b,
			"**Must declare (emit-time rejection if any are missing from every block's `facet_ids` and `claim_uses[].facet_id`):** %s.\n\n",
			strings.Join(mustDeclare, ", "),
		)
	}

	// G7 (2026-06-12 sweep): a HARD facet downgraded to SOFT used to
	// render indistinguishably from a born-SOFT facet — the model
	// never knew the question had pinned it. Surface the typed
	// downgrade signal (RichnessTelemetry kind=facet_softened) as an
	// advisory annotation; guidance only, the tier itself is
	// untouched (the downgrade decision is a noisy signal).
	softenedKinds := map[string]bool{}
	if ctx != nil && ctx.Mutable != nil {
		for _, sig := range ctx.Mutable.RichnessTelemetry() {
			if sig.Kind == "facet_softened" && sig.FacetKind != "" {
				softenedKinds[sig.FacetKind] = true
			}
		}
	}

	emit := func(req types.FacetRequirement) {
		label := types.AnswerFacetPublicLabel(req.Kind)
		var tag string
		switch req.Required {
		case types.FacetHardRequired:
			tag = "HARD"
		case types.FacetSoftRequired:
			tag = "SOFT"
		default:
			tag = "OPTIONAL"
		}
		fmt.Fprintf(&b, "- **%s**: %s.", tag, label)
		// R7: verbatim facet_id string the LLM must copy.
		fmt.Fprintf(&b, " `facet_id: %q`.", string(req.Kind))
		// Phase 5-E2: typed evidence count surfaces the gate input.
		fmt.Fprintf(&b, " (evidence: %d)", answerDocFacetPromptEvidenceCount(plan, req))
		// SOFT facets with typed evidence available get an explicit
		// availability marker, but they do not become emit-time hard
		// gates. This keeps metadata enrichment from overriding the
		// model's substantive answer.
		if req.Required == types.FacetSoftRequired && req.IsPromoted() {
			b.WriteString(" (evidence available)")
		}
		if req.Required == types.FacetSoftRequired && softenedKinds[string(req.Kind)] {
			b.WriteString(" (downgraded from HARD — the question pinned this facet but no matching evidence surfaced; if your evidence can carry it, cover it rather than skipping)")
		}
		if len(req.AcceptableForms) > 0 {
			forms := make([]string, 0, len(req.AcceptableForms))
			seen := map[string]bool{}
			for _, f := range req.AcceptableForms {
				name, ok := answerDocClaimFormLabels[f]
				if !ok || seen[name] {
					continue
				}
				seen[name] = true
				forms = append(forms, name)
			}
			if len(forms) > 0 {
				fmt.Fprintf(&b, " Acceptable evidence: %s.", strings.Join(forms, ", "))
			}
		}
		// R7: reverse lookup — which block kind(s) cover this facet.
		if owners, ok := facetToBlocks[req.Kind]; ok && len(owners) > 0 {
			fmt.Fprintf(&b, " Place on block kind: %s.", formatBlocks(owners))
		} else if fallback := types.BlockKindForFacetForPrompt(req.Kind); fallback != "" {
			fmt.Fprintf(&b, " Place on block kind: `%s`.", string(fallback))
		}
		if req.RequiresHardDeclaration() {
			b.WriteString(" → **MUST declare** via `block.facet_ids[]` or `claim_uses[].facet_id` (NOT prose); emit-time rejection if missing.")
		}
		b.WriteString("\n")
	}

	if len(fc.Required) > 0 {
		for _, req := range fc.Required {
			emit(req)
		}
	}
	if len(fc.Optional) > 0 {
		b.WriteString("\nOptional richness facets:\n")
		for _, req := range fc.Optional {
			emit(req)
		}
	}
	b.WriteString("\n")
	return b.String()
}

func answerDocFacetPromptEvidenceCount(plan *types.AnswerSurfacePlan, req types.FacetRequirement) int {
	raw := len(req.SourceCandidate)
	if raw == 0 {
		return 0
	}
	if plan == nil || plan.FacetCoverage == nil {
		return raw
	}
	allowed := make(map[string]bool, len(req.SourceCandidate))
	for _, id := range req.SourceCandidate {
		if id = strings.TrimSpace(id); id != "" {
			allowed[id] = true
		}
	}
	curated := 0
	for _, item := range types.PrincipalSupportEvidenceItemsForFacet(plan.FacetCoverage.Family, plan, req.Kind) {
		if allowed[strings.TrimSpace(item.ID)] {
			curated++
		}
	}
	if curated <= 0 {
		return raw
	}
	return curated
}

func renderAnswerDocDiagramContract(ctx *types.AgentContext, dc *types.DiagramContract) string {
	if dc == nil || !dc.Required {
		return ""
	}
	minimum := dc.Minimum
	if minimum <= 0 {
		minimum = 1
	}
	scope := dc.ScopeHint
	if scope == "" {
		scope = types.DiagramScopeOverall
	}

	var b strings.Builder
	b.WriteString("## Diagram Contract\n\n")
	b.WriteString("- Required: yes\n")
	fmt.Fprintf(&b, "- Minimum diagrams: %d\n", minimum)
	requiredKind := dc.RequiredKind
	if requiredKind == types.DiagramNone || !requiredKind.IsValid() {
		for _, kind := range dc.PreferredKinds {
			if kind != types.DiagramNone && kind.IsValid() {
				requiredKind = kind
				break
			}
		}
	}
	if requiredKind != types.DiagramNone && requiredKind.IsValid() {
		fmt.Fprintf(&b, "- Required kind: %s\n", requiredKind)
	}
	if len(dc.PreferredKinds) > 0 {
		kinds := make([]string, 0, len(dc.PreferredKinds))
		for _, kind := range dc.PreferredKinds {
			kinds = append(kinds, string(kind))
		}
		fmt.Fprintf(&b, "- Preferred kinds: %s\n", strings.Join(kinds, ", "))
	}
	fmt.Fprintf(&b, "- Scope: %s\n", scope)
	if len(dc.Reasons) > 0 {
		fmt.Fprintf(&b, "- Reasons: %s\n", strings.Join(dc.Reasons, ", "))
	}
	if len(dc.Participants) > 0 {
		b.WriteString("- Typed participant obligations:\n")
		for _, participant := range dc.Participants {
			identity := strings.TrimSpace(participant.Identity)
			if identity == "" || !participant.Role.IsValid() {
				continue
			}
			fmt.Fprintf(&b, "  - `%s`: `%s`\n", identity, participant.Role)
		}
		b.WriteString("- Participant obligations guide investigation and honest coverage; they are not source evidence and cannot mint an edge. `incident_required` needs a grounded incident relation or an explicit unproven disclosure. `context_only` must not be forced into a path.\n")
		if answerDocDiagramBoundaryRecipesApply(ctx) {
			boundaries, requestScopedSubsetIncomplete := answerDocDiagramUnprovenParticipantBoundaries(ctx, dc)
			if len(boundaries) > 0 {
				if requestScopedSubsetIncomplete {
					b.WriteString("- Typed unproven requested-relation recipes (a participant can retain this boundary even when an independently grounded local technical operation exists):\n")
					b.WriteString("- Whole-diagram scope recipe: on exactly one diagram block that presents the requested relation, set block-level `requested_relation_scope=partial_unproven`. This model-authored typed disclosure tells readers that the proved local segments do not yet establish one complete end-to-end requested relation. It adds no edge and does not replace your conclusion; do not repeat the raw enum in visible prose or labels.\n")
				} else {
					b.WriteString("- Typed uncovered-participant recipes (use a row only when that participant has no grounded visible incident relation):\n")
				}
				for recipeIndex, boundary := range boundaries {
					quotedIdentity := strconv.Quote(boundary.Participant)
					boundaryRow, _ := json.Marshal(boundary)
					fmt.Fprintf(&b, "  - boundary_recipe[%d]: participant_identity=%s; visible_disconnected_node_first_line_identity=%s; boundary_row=%s; edge_action=`none`\n",
						recipeIndex+1, quotedIdentity, quotedIdentity, boundaryRow)
				}
				b.WriteString("- For an unproven requested-relation recipe, choose any Mermaid-safe node ID, but make that standalone node's first label line exactly `visible_disconnected_node_first_line_identity`; copy `participant_identity` byte-for-byte into the block-level boundary row. Do not connect the node merely to satisfy coverage. An independently proved local operation may remain inside that participant's visible group with its exact technical endpoints; it does not close this boundary.\n")
			}
		}
	}
	b.WriteString("- This requirement is independent of question family: if it says `Required: yes`, the dispatch must contain at least one grounded fenced diagram via a principal `diagram` block (preferred) or a fenced block embedded in the `summary` block's text.\n")
	if requiredKind != types.DiagramNone && requiredKind.IsValid() {
		fmt.Fprintf(&b, "- The required kind is authoritative: set `diagram.kind=%s` and use the matching Mermaid body syntax for that semantic family.\n", requiredKind)
	}
	b.WriteString("- EDGE DECISION FIRST: choose the semantic relation before drawing the arrow. A stage/process/workflow order is `precedence/precedence_role`; a conditional trigger is `guard/guard_condition` (only enclosing callable -> condition); `control_flow/branch_effect` is exact parser-proved branch arm -> effect; `call/call_edge` is only a direct invocation backed by a same-direction typed call-site. A typed call proves invocation only: it does not by itself prove a read, write, mutation, returned value, or value transfer, so do not describe a getter as a write without a separate typed operation row. Other exact pairs are `callback/callback_handoff`, `argument_flow/argument_flow`, `import/import_edge`, `observe/external_observation`, `register/registration_edge`, `assignment/assignment_fact`, `data_flow/assignment_fact`, and `return/return_fact`; `contain` has no edge-level claim_form. argument_flow is an exact complete non-callable argument -> receiving API and proves no callee-side use. control_flow is typed-only and cannot be inferred from source words, adjacency, prose, or labels. Assignment is LHS -> RHS binding view, while data_flow is the same exact tuple in RHS -> LHS execution direction. These relations are not calls, and a flowchart arrow is not automatically a call.\n")
	b.WriteString("- USER-FACING DISPLAY LAYER: `relation_kind`, `claim_form`, recipe indexes, validator names, and words such as `precedence_role` are structured evidence metadata, not visible diagram copy. Keep Mermaid node IDs stable and preserve producer-supplied exact source/stage endpoint selectors in `edge_anchors`; use concise domain/business actions for visible node labels and edge messages, with the exact technical identity as a secondary label only when useful. In surrounding reader-facing prose, explain the semantic relationship in domain terms such as implements, calls, hands off, or precedes; do not explain literal Mermaid operator tokens or arrow glyphs, because the compatibility renderer may normalize an equivalent syntax family before display. A display alias never proves an endpoint or relation, and changing display wording must not change edge direction or typed authority. This guidance supplies no labels, nodes, or edges; you remain their author.\n")
	b.WriteString("- " + types.GroundedSourceDiagramRelationEvidenceContract + "\n")
	b.WriteString("- For architecture component nodes, use the canonical identity grounded by topology/stage binding, constructor/registration, interface implementation, or execution dispatch. A repair/validation/helper function that only contains the stage name is not itself the component boundary.\n")
	b.WriteString("- For architecture data-flow/carrier diagrams, an exact field/property ownership declaration grounds only the structural containment it states. You may render that ownership without an arrow by nesting the exact field/type node or subgroup inside the exact owner subgraph; this containment/grouping is not a call, transfer, execution order, or proof that any value moved. A typed incident_required owner that has no separately proved directed operation still keeps its `unproven` boundary for direct call/transfer coverage; the boundary does not negate the independently proved containment. Before drawing a transfer arrow, use grounded producer + merge/transfer + consumer evidence for that path. One merge function does not prove that every source field is stored in the destination; keep source-stated exclusions and separately consumed fields on their own handoff path or disclose them in prose. This ownership-versus-transfer split is language-neutral across fields, properties, members, slots, and equivalent carrier declarations.\n")
	b.WriteString("- Keep structured identity separate from display copy: an exact typed participant may be the stable Mermaid endpoint node ID while its visible label uses concise business language. The proved edge must terminate on that same node ID, and `edge_anchors.from_identity/to_identity` must retain the exact technical operation endpoints and direction. Do not draw the technical method as one endpoint and then invent a second method-to-component bridge; either use the exact participant node ID on the proved edge's corresponding endpoint side, or place the technical endpoint inside a visible group named for the exact participant. A disconnected node elsewhere cannot borrow that incidence.\n")
	b.WriteString("- PREFERRED form: a ` ```mermaid ` fenced block. For flow / architecture / call_dag families, default to `flowchart TD` and switch to LR / RL / BT only when that genuinely improves readability; vertical is preferred because code-bearing labels are often long. For `sequenceDiagram`, keep participant labels short and move detailed prose into messages / surrounding text because actors render horizontally. The renderer applies a deterministic-alignment pass to Mermaid bodies so the diagram looks clean across terminals / locales / CJK content. ASCII art (a bare ``` fence with `+ - | > <` connectors) is the FALLBACK ONLY when the supported Mermaid subset cannot express the shape.\n")
	b.WriteString("- Sequence operators `->>` / `-->>`, async `-)` / `--)`, and lost-message `-x` / `--x` (including Mermaid `+` / `-` activation suffixes) are all visible structured edges. Use async/lost forms only when the same typed relation and direction are grounded; they are not decoration or an escape from edge evidence. Only a dashed `-->>` reverse edge structurally paired with a grounded forward invocation is treated as a response rather than a second call.\n")
	b.WriteString("- Reuse grounded labels directly inside the fence. Do not rename, normalize, or abstract a cited file / symbol / path literal into a different label unless that alternate label is itself grounded in citations or log frames.\n")
	b.WriteString("- Avoid invented enumeration labels like `Level 1`, `Round 2`, or `Step 3` unless those exact labels appear in grounded evidence.\n\n")
	return b.String()
}

func answerDocDiagramBoundaryRecipesApply(ctx *types.AgentContext) bool {
	if ctx == nil || ctx.AnalysisIR == nil {
		return false
	}
	// The pre-emit participant coverage gate applies to every required
	// non-runtime-causal diagram family, not only AxisFlow. Source call-chain
	// analyzers legitimately use IntentTrace + AxisCall; withholding recipes
	// there made the initial prompt omit metadata that the same dispatch later
	// hard-required. Keep this predicate aligned with
	// DiagramParticipantCoverageMismatches instead of reinterpreting intent or
	// relation axis locally.
	return types.ResolveQuestionFamily(ctx.AnalysisIR.RequestModel) != types.QFRootCauseTrace
}

// answerDocDiagramUnprovenParticipantBoundaries is the single initial-prompt
// producer for the exact model-authored boundary rows that the pre-emit
// participant coverage gate may require. It consumes the analyzer's typed
// participant slate and the same source-relation projection as the gate; it
// reads no request/final prose and creates no edge or visible conclusion.
func answerDocDiagramUnprovenParticipantBoundaries(
	ctx *types.AgentContext,
	dc *types.DiagramContract,
) ([]types.DiagramParticipantBoundary, bool) {
	if !answerDocDiagramBoundaryRecipesApply(ctx) || dc == nil || !dc.Required || ctx == nil || ctx.AnalysisIR == nil {
		return nil, false
	}
	obligations := answerDocDiagramParticipantCoverageObligations(ctx, dc)
	if len(obligations) == 0 {
		return nil, false
	}
	evidence, edges, _, _ := answerDocCurrentSourceMechanismRelations(ctx)
	coverageRM := ctx.AnalysisIR.RequestModel
	coverageHint := types.DiagramHint{}
	if coverageRM.DiagramHint != nil {
		coverageHint = *coverageRM.DiagramHint
	}
	coverageHint.Participants = obligations
	coverageRM.DiagramHint = &coverageHint
	coverage := answerDocResolveFlowParticipantCoverage(
		coverageRM, edges, evidence, answerDocVerifiedReadModeStagePrecedenceForRequest(ctx),
	)
	boundaryParticipants := coverage.boundaryParticipants()
	boundaries := make([]types.DiagramParticipantBoundary, 0, len(boundaryParticipants))
	for _, participant := range boundaryParticipants {
		participant = strings.TrimSpace(participant)
		if participant == "" {
			continue
		}
		boundaries = append(boundaries, types.DiagramParticipantBoundary{
			Participant: participant,
			Status:      types.DiagramParticipantBoundaryUnproven,
		})
	}
	return boundaries, coverage.requestScopedSubsetIncomplete
}

// answerDocDiagramParticipantCoverageObligations keeps the prompt-side
// boundary carrier on the exact participant slate consumed by the hard
// coverage gate. The compiled AnswerSurfacePlan deliberately describes
// presentation shape and may omit DiagramContract.Participants; treating that
// omission as "no participant obligations" made the first-pass diagram omit
// the very block-level rows that the semantic-view gate later required.
//
// Prefer the compiled semantic-view obligations because they have already
// passed the analyzer provenance checks (including SourceQuote). The contract
// and request-model fallbacks keep narrow compatibility/unit contexts useful,
// but neither path reads request prose or creates a relation.
func answerDocDiagramParticipantCoverageObligations(
	ctx *types.AgentContext,
	dc *types.DiagramContract,
) []types.DiagramParticipantHint {
	if ctx == nil || ctx.AnalysisIR == nil {
		return nil
	}
	if view := types.BuildAnswerSemanticViewForAgentContext(ctx); view != nil &&
		view.DiagramPlan != nil && view.DiagramPlan.Required {
		return append([]types.DiagramParticipantHint(nil), view.DiagramParticipantObligations...)
	}
	if dc != nil && len(dc.Participants) > 0 {
		return append([]types.DiagramParticipantHint(nil), dc.Participants...)
	}
	if hint := ctx.AnalysisIR.RequestModel.DiagramHint; hint != nil {
		return append([]types.DiagramParticipantHint(nil), hint.Participants...)
	}
	return nil
}

func renderAnswerDocDiagramSeeds(ctx *types.AgentContext, dc *types.DiagramContract) string {
	if ctx == nil || dc == nil || !dc.Required {
		return ""
	}
	var b strings.Builder
	wrote := false
	appendSection := func(title, body string) {
		body = strings.TrimSpace(body)
		if body == "" {
			return
		}
		if !wrote {
			b.WriteString("## Diagram Seeds\n\n")
			// Reframed alongside the First-Pass reference: these
			// sections are GROUNDED FLOORS (everything listed is
			// already cited) the model can extend, not ceilings the
			// model must paste verbatim. The hard constraint stays
			// at the label-grounding level — file/path nodes inside
			// the fenced block must come from citations[] or Log
			// Triage frames — but the structure (number of nodes,
			// direction, branching) is the model's call.
			b.WriteString("These are grounded reference structures the diagram MAY draw from. Each section lists evidence-grounded nodes / labels you can use; you are encouraged to extend them with additional grounded nodes, change the direction, or introduce branching / fan-out where the mechanism warrants. Node membership alone does not prove adjacency, order, containment, or direction: an unconnected node set is intentional when no typed relation or ordered-flow carrier proves an edge. Add an edge only when the supplied typed relation / flow evidence supports it. The file/path grounding rule remains separate: file or path nodes inside the fenced block must come from citations[] or the Log Triage frames.\n\n")
			wrote = true
		}
		fmt.Fprintf(&b, "### %s\n\n%s\n\n", title, body)
	}

	appendSection("Grounded Labeling", renderAnswerDocDiagramLabelSeed())
	appendSection("Diagram Node Allowlist", renderAnswerDocDiagramFileLabelSeed(ctx))
	appendSection("Config Trace Precedence", renderAnswerDocDiagramConfigTraceSeed(ctx))
	appendSection("Log Triage", renderAnswerDocDiagramLogSeed(ctx.LogTriage))
	appendSection("Flow Findings", renderAnswerDocDiagramFlowSeed(ctx.FlowFindings, supportLaneScopeForContext(ctx, true)))
	appendSection("Principal Support Path", renderAnswerDocDiagramSupportSeed(ctx))
	appendSection("Exact Resolution Anchors", renderAnswerDocDiagramExactResolutionSeed(ctx))

	if !wrote {
		return ""
	}
	return b.String()
}

func renderAnswerDocFirstPassDiagramSkeleton(ctx *types.AgentContext) string {
	// A complete request-scoped spine is narrower than the generic grounded
	// support graph. Publishing both as peer "first-pass" floors makes a true
	// but out-of-scope sibling relation compete with the exact relation the
	// user asked to see. The mechanism authority already publishes the compact
	// principal recipe in this case, so withhold the generic skeleton and let
	// the model author the visible diagram from that typed spine. Supporting
	// relations remain available in the full advisory capsule and ledger.
	if answerDocMechanismHasCompleteRequestSpine(ctx) {
		return ""
	}
	// Prefer the validator-aligned typed topology carrier when one exists. The legacy
	// seed renderer publishes only Mermaid display labels; for a canonicalized
	// call graph those labels can intentionally be more qualified than the
	// underlying call-site endpoint (for example agent.buildAnalysisIR vs
	// buildAnalysisIR). Asking the model to copy that body without the sibling
	// from_identity/to_identity selectors teaches a draft that the strict
	// relation gate must later reject. The typed topology carrier is compiled from
	// the same typed relation projection as validation and keeps its Mermaid
	// node IDs, arrows, and edge_anchors together. This changes prompt evidence
	// only: the model still authors visible wording and the answer conclusion.
	reference := answerDocMechanismCopyReadyRepairPayload(ctx)
	validatorAligned := strings.TrimSpace(reference) != ""
	if !validatorAligned {
		reference = renderRetryDiagramSeedFenceForRepair(ctx, nil)
	}
	if strings.TrimSpace(reference) == "" {
		return ""
	}
	hasPrincipalMemberBoundary := false
	principalMemberCount := 0
	if ctx != nil && ctx.AnalysisIR != nil {
		principalMemberCount = len(types.PrincipalTypedRelationMemberNamesForRequest(
			answerDocStableAggregateFacts(ctx), &ctx.AnalysisIR.RequestModel,
		))
		hasPrincipalMemberBoundary = principalMemberCount > 0
	}
	var b strings.Builder
	b.WriteString("## First-Pass Diagram Reference\n\n")
	// Pre-2026-04-30 this section said "copy this fenced skeleton
	// verbatim ... you may delete unused nodes, but do not rename
	// the remaining ones." Combined with "explain any extra
	// semantics in prose around it", it forced any richer-than-
	// skeleton mechanism into prose and capped the diagram at the
	// seed shape. The reframing below presents the skeleton as a
	// GROUNDED FLOOR (every node here is already evidence-grounded)
	// rather than a CEILING: the model is explicitly authorised to
	// add nodes, change `flowchart TD` to LR / RL / BT when needed, introduce branches /
	// fan-out, or switch to `sequenceDiagram` — the only hard rule
	// being that every label remains grounded in citations[] or
	// Log Triage frames.
	if hasPrincipalMemberBoundary {
		fmt.Fprintf(&b, "Below is a grounded authoring reference restricted to the completion-verified principal typed-relation member set (%d member(s)). It is the exact same-relation membership boundary as the principal table/list, not a broader source-roster floor. You still author all visible wording and may choose a faithful subset only when the answer contract permits it:\n\n", principalMemberCount)
		b.WriteString("- Do not add another principal member connected by the same declared-type relation merely because a broader grounded/source-scope relation exists elsewhere. Keep such relations as explicitly bounded support/audit context outside this principal diagram.\n")
	} else {
		b.WriteString("Below is a grounded starting reference — every node listed here is already corroborated by evidence in this dispatch, and some scenarios may supply prevalidated role labels whose supporting anchors are listed elsewhere in the prompt. Use it as a FLOOR, not a ceiling:\n\n")
		b.WriteString("- You SHOULD extend it with additional grounded nodes when the investigation supports a richer mechanism (e.g. more call-chain hops, branch points, fan-out, error paths).\n")
	}
	if dc := answerDocDiagramContract(ctx); dc != nil && dc.RequiredKind != types.DiagramNone && dc.RequiredKind.IsValid() {
		fmt.Fprintf(&b, "- Required semantic kind for this dispatch: `%s`; keep `diagram.kind` and the Mermaid syntax aligned with that kind.\n", dc.RequiredKind)
	} else {
		b.WriteString("- You MAY change the direction (`flowchart TD` ↔ `LR` / `RL` / `BT`), introduce subgraph-like clusters as flat nodes, or switch to `sequenceDiagram` if actor-to-actor better fits the mechanism — none of these are forbidden.\n")
	}
	b.WriteString("- You MAY add branches / fan-out / multi-source / multi-sink shapes; the linear chain in the reference is just the safest default skeleton, not a structural requirement.\n")
	b.WriteString("- Preserve an edge from the reference only when it is actually present there. A node-only reference deliberately asserts no relationship: never connect nodes merely because they are listed next to each other or appear in collection order.\n")
	if validatorAligned {
		b.WriteString("- This reference includes validator-aligned topology and `edge_anchors_json` identity fields, but it is intentionally NOT an acceptance-ready answer: directed template edges carry the literal syntax-safe placeholder `AUTHOR_BUSINESS_ACTION` and anchors have no `visible_label`. If you retain an edge, keep its node IDs, direction, and matching anchor object together, then replace the placeholder with one concise domain/business action and copy that exact wording into both the Mermaid edge/message and the anchor `visible_label`. Do not emit the template unchanged or substitute the display label for `from_identity` / `to_identity`.\n")
	}
	b.WriteString("- HARD RULE: every node label must remain grounded in citations[] or Log Triage frames. Renaming an existing node, abstracting it, or inventing a node without grounded backing is rejected by the diagram-grounding gate.\n\n")
	b.WriteString(reference)
	b.WriteString("\n\n")
	return b.String()
}

func renderAnswerDocDiagramLabelSeed() string {
	return strings.TrimSpace(
		"Label each node with grounded names you already have: cited repo files, cited symbols, log-frame functions, or path literals that appear in cited line text.\n" +
			"- If the evidence names one spelling, keep that spelling in the diagram instead of renaming it to a nearby alias.\n" +
			"- If you need an alternate label, only use it when that exact label appears in citations or log frames.\n" +
			"- Do not synthesize bare line-number aliases such as `L877`, `Line 42`, or similar citation-derived shorthand unless the cited text itself contains that exact token.\n" +
			"- Supporting anchor locations belong OUTSIDE the fence. Do not append `(<file>:<line>)`, `<br/>(<file>)`, or similar support-location suffixes to a node label unless that exact combined label is itself grounded.\n" +
			"- Prefer direct grounded names over abstract buckets such as `Level 1` / `Round 2` / `Step 3`.\n" +
			"- Inside a fenced diagram, keep file/path node labels to the prompt's `Diagram Node Allowlist` unless the same exact label is also grounded by citations[] or Log Triage frames in this tool call.",
	)
}

func renderAnswerDocDiagramFileLabelSeed(ctx *types.AgentContext) string {
	labels := collectAnswerDocDiagramFileLabels(ctx)
	if len(labels) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("If your fenced diagram names file or path nodes, keep them to this exact grounded allowlist unless the same exact alternate label is independently grounded in this dispatch:\n")
	for _, label := range labels {
		fmt.Fprintf(&b, "- `%s`\n", label)
	}
	b.WriteString("Do not shorten, strip suffixes, normalize example/demo filenames into runtime-looking aliases, or rewrite one grounded label into a nearby spelling unless that exact alternate label is independently grounded.")
	return strings.TrimSpace(b.String())
}

func collectAnswerDocDiagramFileLabels(ctx *types.AgentContext) []string {
	if ctx == nil {
		return nil
	}
	seen := make(map[string]bool)
	var labels []string
	appendLabel := func(label string) {
		label = strings.TrimSpace(strings.ReplaceAll(label, `\`, `/`))
		if label == "" || seen[label] {
			return
		}
		seen[label] = true
		labels = append(labels, label)
	}
	if ctx.LogTriage != nil {
		for _, err := range ctx.LogTriage.Errors {
			for _, frame := range err.Frames {
				appendLabel(frame.File)
			}
		}
		for _, file := range ctx.LogTriage.ResolvedFiles {
			appendLabel(file)
		}
	}
	for _, anchor := range collectConfigTraceDiagramAnchors(ctx) {
		appendLabel(anchor.Source)
	}
	for _, entry := range collectDiagramSupportEntries(ctx, 0) {
		source := strings.TrimSpace(entry.Source)
		if source == "" {
			source, _ = supportLaneScopeParseLocation(entry.Location)
		}
		appendLabel(source)
	}
	for _, ev := range ctx.EvidenceItems {
		if ev.DiagramRole == "" {
			continue
		}
		if types.DiagramEvidenceEligible(ev) {
			appendLabel(ev.Source)
		}
	}
	if len(labels) == 0 {
		return nil
	}
	sort.Strings(labels)
	if len(labels) > 10 {
		labels = labels[:10]
	}
	return labels
}

func renderAnswerDocDiagramLogSeed(bundle *types.LogBundle) string {
	if bundle == nil || len(bundle.Errors) == 0 {
		return ""
	}
	resolved := make([]types.LogFrame, 0, 8)
	for _, err := range bundle.Errors {
		for _, frame := range err.Frames {
			if frame.File == "" || frame.Line <= 0 {
				continue
			}
			resolved = append(resolved, frame)
			if len(resolved) >= 8 {
				break
			}
		}
		if len(resolved) >= 8 {
			break
		}
	}
	if len(resolved) < 2 {
		return ""
	}
	// Use the canonical Mermaid renderer so the seed shape agrees
	// with the skill's Mermaid-preferred contract. Pre-2026-04-30
	// this renderer hand-built a bare ``` fence with `innermost
	// failure: …` / `  -> caller:` ASCII prose, which trained the
	// model to copy ASCII verbatim despite the prompt-level Mermaid
	// preference.
	bundleSubset := &types.LogBundle{
		Errors: []types.LogError{{Frames: resolved}},
	}
	fence := types.RenderLogDiagramFence(bundleSubset)
	if fence == "" {
		return ""
	}
	return "When you draw a call-chain / sequence diagram, start from these resolved frames (extend with additional grounded callers if your investigation supports a richer chain):\n\n" + fence
}

func renderRequiredLogTriageTypes(bundle *types.LogBundle) string {
	typeNames := types.LogBundleErrorTypes(bundle)
	if len(typeNames) == 0 {
		return ""
	}
	return "For this dispatch, the exact structured log error type(s) you must mention literally in `summary` are: `" + strings.Join(typeNames, "`, `") + "`."
}

func renderRequiredLogTriageMessages(ctx *types.AgentContext) string {
	messages := requiredLogErrorMessagesForAgentContext(ctx)
	if len(messages) == 0 {
		return ""
	}
	return "Because the typed request profile marks this as a diagnostic / root-cause artifact question, preserve these structured log error message(s) verbatim in `summary` or body: `" + strings.Join(messages, "`, `") + "`."
}

func requiredLogErrorMessagesForAgentContext(ctx *types.AgentContext) []string {
	if ctx == nil || ctx.LogTriage == nil || ctx.AnalysisIR == nil {
		return nil
	}
	if !ctx.AnalysisIR.RequestModel.RequiresDiagnosticArtifactMessageSurface() {
		return nil
	}
	return requiredLogErrorMessages(ctx.LogTriage)
}

func requiredLogErrorMessages(bundle *types.LogBundle) []string {
	messages := types.LogBundleErrorMessages(bundle)
	if len(messages) > 4 {
		messages = messages[:4]
	}
	return messages
}

func renderAnswerDocDiagramFlowSeed(findings []types.FlowFindingDigest, supportScope *supportLaneScope) string {
	if len(findings) == 0 {
		return ""
	}
	var b strings.Builder
	emitted := 0
	for i, ff := range findings {
		if i >= answerDocMaxFlowEnrichmentScan || emitted >= 3 {
			break
		}
		if supportScope != nil && !supportScope.allowsFlowFinding(ff) {
			continue
		}
		parts := make([]string, 0, 3)
		if len(ff.Path) > 0 {
			parts = append(parts, "path="+strings.Join(ff.Path, " -> "))
		}
		if len(ff.Hops) > 0 {
			parts = append(parts, "hops="+strings.Join(ff.Hops, " -> "))
		}
		if len(ff.Conditions) > 0 {
			parts = append(parts, "conditions="+strings.Join(ff.Conditions, "; "))
		}
		if len(parts) == 0 {
			continue
		}
		fmt.Fprintf(&b, "- %s\n", strings.Join(parts, " | "))
		emitted++
	}
	return strings.TrimSpace(b.String())
}

func renderAnswerDocDiagramSupportSeed(ctx *types.AgentContext) string {
	if ctx == nil {
		return ""
	}
	entries := collectDiagramSupportEntries(ctx, answerDocDiagramSupportSeedLimit)
	if len(entries) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("Use these typed support-lane entries as the principal diagram floor. They come from the same answer-support lanes used by validation, so they should outrank background answer-chain artifacts:\n")
	for _, entry := range entries {
		display := diagramSupportEntrySurface(entry)
		if display == "" {
			continue
		}
		if loc := strings.TrimSpace(entry.Location); loc != "" {
			fmt.Fprintf(&b, "- %s (`%s`)\n", display, loc)
			continue
		}
		fmt.Fprintf(&b, "- %s\n", display)
	}
	return strings.TrimSpace(b.String())
}

const answerDocDiagramSupportSeedLimit = 12

func collectDiagramSupportEntries(ctx *types.AgentContext, limit int) []types.AnswerSupportEntry {
	if ctx == nil {
		return nil
	}
	plan := answerSupportPlan(ctx)
	if plan == nil {
		return nil
	}
	seen := make(map[string]bool)
	var out []types.AnswerSupportEntry
	for _, lane := range plan.Lanes {
		if !answerSupportLaneAllowsDiagram(lane) {
			continue
		}
		for _, entry := range lane.Entries {
			display := diagramSupportEntrySurface(entry)
			if display == "" {
				continue
			}
			key := strings.ToLower(display) + "\x00" + strings.ToLower(strings.TrimSpace(entry.Location))
			if seen[key] {
				continue
			}
			seen[key] = true
			out = append(out, entry)
			if limit > 0 && len(out) >= limit {
				return out
			}
		}
	}
	return out
}

func answerSupportLaneAllowsDiagram(lane types.AnswerSupportLane) bool {
	for _, kind := range lane.AllowedBlocks {
		if strings.TrimSpace(kind) == string(types.BlockDiagram) {
			return true
		}
	}
	return false
}

func diagramSupportEntrySurface(entry types.AnswerSupportEntry) string {
	if entry.AnchorKind == types.AnchorCall || entry.AnchorKind == types.AnchorCallback {
		if subject := strings.TrimSpace(entry.Subject); subject != "" {
			if object := strings.TrimSpace(entry.Object); object != "" {
				return subject + " -> " + object
			}
		}
	}
	return firstNonEmptyString(
		strings.TrimSpace(entry.AnchorSymbol),
		strings.TrimSpace(entry.Subject),
		strings.TrimSpace(entry.Object),
		strings.TrimSpace(entry.Text),
	)
}

func renderAnswerDocDiagramExactResolutionSeed(ctx *types.AgentContext) string {
	contract := answerDocExactResolutionContract(ctx)
	if ctx == nil || contract == nil {
		return ""
	}
	seeds := collectExactResolutionSeeds(ctx, contract)
	if len(seeds) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("For exact-target questions, keep the requested target separate from nearby context unless you have explicit alias proof. If you draw related context, prefer these grounded labels as node names:\n")
	for _, seed := range seeds {
		fmt.Fprintf(&b, "- %s\n", seed.Text)
	}
	return strings.TrimSpace(b.String())
}

type configTraceDiagramAnchor = types.ConfigTraceDiagramAnchor

func renderAnswerDocDiagramConfigTraceSeed(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil || ctx.AnalysisIR.RequestModel.Scenario != types.ScenarioConfigTrace {
		return ""
	}
	anchors := collectConfigTraceDiagramAnchors(ctx)
	if len(anchors) < 2 {
		return ""
	}
	rolesPresent := make(map[string]bool, len(anchors))
	for _, anchor := range anchors {
		rolesPresent[anchor.Role] = true
	}
	var b strings.Builder
	// Render the precedence chain as a Mermaid flowchart via the
	// canonical renderer so the seed shape agrees with the skill's
	// Mermaid-preferred contract. Pre-2026-04-30 this hand-built a
	// bare ``` fence with `node\n  ->\n` ASCII shape that taught
	// the model to copy ASCII whenever a config-trace question fired.
	b.WriteString("For config-precedence questions, prefer the validated role-labeled precedence chain below. The chain is ordered from highest precedence at the top to lowest precedence at the bottom. Each node label is a compiled role abstraction backed by grounded evidence in this dispatch; the supporting file:line anchors are listed immediately after the fence. Treat it as a grounded FLOOR — keep any role label you retain verbatim, but you MAY add additional grounded precedence layers when your investigation supports a richer chain (still subject to the citation-grade rules below).\n\n")
	b.WriteString(types.RenderConfigTraceDiagramFence(anchors))
	b.WriteByte('\n')
	for _, anchor := range anchors {
		support := types.ConfigTraceDiagramAnchorSupportLabel(anchor)
		if support == "" {
			continue
		}
		fmt.Fprintf(&b, "- `%s` [%s] → `%s`\n", anchor.Label, anchor.Role, support)
	}
	b.WriteByte('\n')
	b.WriteString("The support locations listed above stay outside the fence. Keep the node labels themselves bare role labels / compound role labels / grounded file-path labels; do not append `:line`, `(<file>:<line>)`, or `<br/>` support text to the label body unless that exact combined label is itself grounded.\n")
	b.WriteString("Precedence semantics live in prose, not in invented node names: `override` = highest-precedence operator-supplied layer (CLI flag / env override / SDK setter / RPC override — all the same tier), `config` = grounded repo/user config-file layer (YAML/JSON/TOML/INI/etc.), `default` = code-default fallback. `runtime` is the binding / merge code path between those layers, not a standalone user-config tier.\n")
	if missing := missingConfigTraceDiagramRoles(rolesPresent); len(missing) > 0 {
		fmt.Fprintf(&b, "Current grounded evidence does NOT include anchor(s) for these precedence role(s): %s. Do not add fenced-diagram nodes for missing roles unless you first cite a real repo anchor for them; if you need to explain those semantics, keep them in prose as general precedence rules rather than grounded nodes in this dispatch.\n", strings.Join(missing, ", "))
	}
	// Two-channel structural rule. The downstream validator
	// (validateSummaryConfigTraceFenceLabels) accepts ANY label that
	// fits one of the channels below, regardless of the specific
	// word the LLM picks. Examples like `CLI` / `RPC` / `UI` are
	// teaching aids — the validator does NOT keyword-match on them;
	// it runs the structural channel checks. So the rule
	// generalises to any vocabulary the user happens to reach for.
	fmt.Fprintf(&b, "Every node label inside this fenced diagram must satisfy ONE of three structural grounding channels (the validator runs them in order and accepts the first match):\n")
	fmt.Fprintf(&b, "  1. Use a role label EXACTLY as listed in the supporting-anchor block above: `%s`, `%s`, `%s`, or `%s`. The role marker is the binding.\n",
		types.ConfigTraceDiagramRoleNodeLabel(types.EvidenceDiagramRoleOverride),
		types.ConfigTraceDiagramRoleNodeLabel(types.EvidenceDiagramRoleConfig),
		types.ConfigTraceDiagramRoleNodeLabel(types.EvidenceDiagramRoleRuntime),
		types.ConfigTraceDiagramRoleNodeLabel(types.EvidenceDiagramRoleDefault))
	fmt.Fprintf(&b, "  2. Write a compound `<content> (<role-marker>)` label whose parenthetical is one of `override` / `config` / `runtime` / `default` (or their long forms). The role-marker carries the binding; the content phrase is the human-readable surface.\n")
	fmt.Fprintf(&b, "  3. Use a concrete file path or symbol that appears in `citations[]`.\n")
	fmt.Fprintf(&b, "Any label that fits NONE of the three channels (a one-word concept like `CLI` / `RPC` / `UI` without a role marker, a numbered band such as `band 1`, an architectural archetype) is rejected. Drop those nodes from the fence and explain the concept in prose instead — do not invent a new bucket name.\n")
	return strings.TrimSpace(b.String())
}

func missingConfigTraceDiagramRoles(present map[string]bool) []string {
	if len(present) == 0 {
		return nil
	}
	order := []types.EvidenceDiagramRole{
		types.EvidenceDiagramRoleOverride,
		types.EvidenceDiagramRoleConfig,
		types.EvidenceDiagramRoleRuntime,
		types.EvidenceDiagramRoleDefault,
	}
	var missing []string
	for _, role := range order {
		key := string(role)
		if key == "" || present[key] {
			continue
		}
		missing = append(missing, key)
	}
	return missing
}

func collectConfigTraceDiagramAnchors(ctx *types.AgentContext) []configTraceDiagramAnchor {
	if plan := answerSurfacePlan(ctx); plan != nil {
		out := make([]configTraceDiagramAnchor, 0, len(plan.ConfigTraceDiagramAnchors))
		for _, anchor := range plan.ConfigTraceDiagramAnchors {
			out = append(out, configTraceDiagramAnchor(anchor))
		}
		return out
	}
	if ctx == nil || ctx.AnalysisIR == nil {
		return nil
	}
	stableAbsent := ctx.Mutable != nil && strings.EqualFold(strings.TrimSpace(ctx.Mutable.InvestigationResultKind()), "absence")
	anchors := types.CollectConfigTraceDiagramAnchors(
		ctx.AnalysisIR.RequestModel.Scenario,
		stableAbsent,
		ctx.AnalysisIR.AnswerContract.ExactResolution,
		answerDocExactContextRequiredFiles(ctx),
		ctx.EvidenceItems,
	)
	out := make([]configTraceDiagramAnchor, 0, len(anchors))
	for _, anchor := range anchors {
		out = append(out, configTraceDiagramAnchor(anchor))
	}
	return out
}

func answerDocExactContextRequiredFiles(ctx *types.AgentContext) []string {
	if ctx == nil || ctx.Mutable == nil {
		return nil
	}
	return ctx.Mutable.ExactContextRequiredFiles()
}

func firstNonEmptyString(items ...string) string {
	for _, item := range items {
		item = strings.TrimSpace(item)
		if item != "" {
			return item
		}
	}
	return ""
}

func renderAnswerDocExactResolutionContract(ctx *types.AgentContext) string {
	if ctx == nil || ctx.Mutable == nil {
		return ""
	}
	contract := answerDocExactResolutionContract(ctx)
	if contract == nil || len(contract.Targets) == 0 {
		return ""
	}
	label := strings.TrimSpace(contract.TargetLabel)
	if label == "" {
		label = "target"
	}
	pending := types.ExactResolutionPendingTargets(contract, ctx.UnverifiedAnalyzerFindings)
	justification := strings.TrimSpace(sanitizeExactResolutionAbsenceJustification(ctx, contract, ctx.Mutable.StableAbsenceJustification()))
	stateAbsent := contract.AllowAbsence &&
		ctx.Mutable.StableInvestigationResultKind() == "absence" &&
		justification != "" &&
		len(pending) > 0
	plan := answerSurfacePlan(ctx)

	var b strings.Builder
	b.WriteString("## Exact Resolution Contract\n\n")
	fmt.Fprintf(&b, "- Requested exact %s: %s\n", label, backtickJoin(contract.Targets))
	b.WriteString("- Set `exact_resolution.status` explicitly: `exact_match`, `alias_match`, or `absent`.\n")
	b.WriteString("- Resolve the requested exact target directly. Do not answer with a nearby item unless you have explicit alias / synonym / parser-mapping proof.\n")
	b.WriteString("- The system renders the exact-resolution lead deterministically from `exact_resolution`; use `summary` for grounded explanation / nearby context, not for ambiguous substitute wording.\n")
	if contract.AllowAbsence {
		b.WriteString("- Absence-only is acceptable if the investigation shows the exact target is absent. In that case set `exact_resolution.status=\"absent\"`.\n")
	}
	if contract.AliasRequiresProof {
		b.WriteString("- Any alias / equivalent / substitute claim requires `exact_resolution.status=\"alias_match\"` plus `exact_resolution.anchor`, and explicit grounded proof. Never rely on lexical similarity or \"closest match\" reasoning.\n")
	}
	if hint := strings.TrimSpace(contract.RelatedContextScopeHint); hint != "" {
		fmt.Fprintf(&b, "- If you add related context, keep it within the %s, ground it, and set `exact_resolution.context_mode=\"grounded_context_only\"`.\n", hint)
	} else {
		b.WriteString("- If you add related context, keep it grounded and clearly separate it from the exact target resolution by using `exact_resolution.context_mode=\"grounded_context_only\"`.\n")
	}
	b.WriteString("- If you cite nearby grounded context beyond the primary exact-proof sources, you MUST set `exact_resolution.context_mode=\"grounded_context_only\"`. Leave `context_mode=\"none\"` only when the answer stays on the exact target proof itself.\n")
	b.WriteString("- Surface-allowed nearby context is not automatically citation-grade. When the prompt separates citation-grade anchors from prose-only anchors, only the citation-grade set may appear in `citations[]` or fenced diagrams; prose-only anchors must stay uncited in `summary`.\n")
	if stateAbsent {
		b.WriteString("- Investigation state: the exact target is currently absent in the repo / branch under inspection.\n")
		fmt.Fprintf(&b, "- Absence justification: %s\n", justification)
		b.WriteString("- Emit `exact_resolution.status=\"absent\"`; the renderer will insert the exact-absence lead before `summary`.\n")
		b.WriteString("- Locked exact-resolution output: if you keep any nearby grounded context, the safest valid object is `{\"status\":\"absent\",\"context_mode\":\"grounded_context_only\"}`. Do not switch to `exact_match` or `alias_match` unless a newly cited grounded anchor explicitly proves the target or an explicit mapping.\n")
		b.WriteString("- Do not speculate about hypothetical parser / runtime behavior (ignored, warning, error, fallback, etc.) unless a grounded repo anchor explicitly proves that behavior.\n")
		b.WriteString("- When `context_mode=\"grounded_context_only\"`, treat `summary` as the follow-on grounded-context block only. Do not write a second absence paragraph there: the renderer already supplies the exact target lead.\n")
		b.WriteString("- Keep the exact target name in the renderer-generated lead only. `summary` and diagrams should talk about grounded nearby anchors, not keep reusing the absent target as if it had a runtime path.\n")
		b.WriteString("- Keep nearby context at the abstraction already grounded by the evidence. A cited struct / function / type name does NOT license an invented field inventory, member count, default-value table, or exhaustive list unless a cited line or structured evidence item explicitly enumerates those members.\n")
		b.WriteString("- Do not add a separate paragraph about the effect of supplying the absent target unless the user explicitly asked for that behavior and a cited anchor proves it.\n")
		if types.ExactResolutionTargetIsConfigKey(contract) {
			b.WriteString("- Because the exact config key is absent, do NOT emit a principal scalar block with a synthetic literal such as `(missing)` / `(不存在)`. Prefer a summary-led explanation so the answer can lead with the exact absence before any nearby grounded context.\n")
		}
		if ctx.AnalysisIR != nil && ctx.AnalysisIR.RequestModel.Scenario == types.ScenarioConfigTrace {
			b.WriteString("- Because the exact config key is absent, do NOT emit a principal scalar block with a synthetic literal such as `(missing)` / `(不存在)`. Prefer a summary-led explanation so the answer can lead with the exact absence and then explain any grounded same-family precedence chain as related context only.\n")
			b.WriteString("- For config-trace related context, grounded same-scope anchors may appear in `summary` even when they do not carry a validated diagram role. But fenced diagrams and diagram citations are stricter: only anchors with a validated `diagram_role_hint` (`default`, `config`, `runtime`, or `override`) may become diagram nodes.\n")
			b.WriteString("- When a requested precedence layer has no grounded binding, say that layer absence explicitly (for example, `no config-file key matches this target` or `no CLI flag binds this key`) instead of vague placeholders like `N/A` / `不适用`.\n")
			b.WriteString("- For config-precedence answers, only create a separate numbered step when that layer has its own grounded repo anchor. If a layer is absent or only inferred from the exact-absence state, keep it in `summary` or leave that step uncited instead of borrowing a nearby config-file / struct citation.\n")
			b.WriteString("- In an ordered-list block, every source-backed step must mention at least one identifier that appears on its selected evidence line or nearby corroboration window. This applies to stable evidence IDs and to a schema-permitted legacy citation index. If the step summarizes a whole struct/range/absence conclusion rather than one corroborated line, leave that step unsupported and keep the precise line-backed facts in neighboring steps.\n")
			b.WriteString("- A repo-wide search result, aggregate absence conclusion, or test-only proof step usually has no single corroborating production line. In `step_list`, keep those steps uncited unless one cited line literally states the same claim.\n")
			if roles := types.JoinEvidenceDiagramRoles(contract.RequestedContextRoles); roles != "" {
				fmt.Fprintf(&b, "- The user explicitly asked to cover these nearby precedence roles when you keep follow-on context: `%s`. Do not collapse the answer to only one surviving layer when grounded anchors for the other requested roles are still available in this dispatch.\n", roles)
			}
		}
	}
	if plan != nil && plan.PreferredExactResolution != nil {
		fmt.Fprintf(&b, "- Preferred exact_resolution object for this dispatch: `{\"status\":\"%s\",\"context_mode\":\"%s\"}`.\n",
			plan.PreferredExactResolution.Status, plan.PreferredExactResolution.ContextMode)
	}
	if plan != nil && plan.SummarySurfaceMode == types.AnswerSummarySurfaceFollowOnGroundedContext {
		b.WriteString("- Summary surface mode: follow-on grounded context only. The renderer already prints the exact-target absence lead, so `summary` should start directly on the grounded nearby context/mechanism and must not restate the exact target.\n")
	}
	if plan != nil && plan.SummarySurfaceMode == types.AnswerSummarySurfaceDriftBoundedRootCause {
		b.WriteString("- Summary surface mode: drift-bounded root cause. The renderer will prepend the log-source-drift lead, but it will keep your grounded `summary`. Use `summary` for the concise present-tense cause/mechanism sentence (and the compiled call-chain fence when helpful). Do not assert a more specific historical failure cause than the current cited code proves.\n")
		// B8-T1 part 3: the original step_list-only nudge is now
		// covered by the V2 block contract's BlockOrderedList
		// requirement on QFCallChain / QFRootCauseTrace families.
		// The general drift-bounded surface guidance still
		// applies to all shapes.
		b.WriteString("- For ordered-step or call-chain answers, keep every step directly citation-backed instead of adding uncited root-cause hypotheses.\n")
	}
	if ctx.AnalysisIR != nil &&
		ctx.AnalysisIR.RequestModel.Scenario == types.ScenarioConfigTrace &&
		contract.TargetKind == types.SubjectConfigKey {
		b.WriteString("- When you mention a precedence layer that lacks a grounded binding for the requested target, say that layer absence explicitly (for example `no config-file key matches this target` or `no CLI flag binds this key`) instead of vague placeholders like `N/A` / `不适用`.\n")
	}
	b.WriteString("\n")
	citationGradeRendered := false
	if citationGrade := renderAnswerDocCitationGradeExactContextAnchors(ctx, contract); citationGrade != "" {
		citationGradeRendered = true
		b.WriteString(citationGrade)
	}
	if primary := renderAnswerDocPrimaryExactProofCitationSeeds(ctx, contract); primary != "" {
		b.WriteString(primary)
	}
	if policy := renderAnswerDocNearbyContextCitationPolicy(ctx, contract); policy != "" {
		b.WriteString(policy)
	}
	if allowed := renderAnswerDocAllowedExactContextAnchors(ctx, contract, citationGradeRendered); allowed != "" {
		b.WriteString(allowed)
	}
	if proseOnly := renderAnswerDocProseOnlyExactContextAnchors(ctx, contract); proseOnly != "" {
		b.WriteString(proseOnly)
	}
	if diagram := renderAnswerDocDiagramGradeExactContextAnchors(ctx, contract); diagram != "" {
		b.WriteString(diagram)
	}
	if candidates := renderAnswerDocRelatedContextCitationCandidates(ctx, contract); candidates != "" {
		b.WriteString(candidates)
	}
	if missing := renderAnswerDocConfigTraceMissingLayerWording(ctx, contract); missing != "" {
		b.WriteString(missing)
	}
	if forbidden := renderAnswerDocForbiddenExactContextAnchors(ctx, contract); forbidden != "" {
		b.WriteString(forbidden)
	}
	if seeds := renderAnswerDocExactResolutionSeeds(ctx, contract); seeds != "" {
		b.WriteString(seeds)
	}
	return b.String()
}

func renderAnswerDocConfigTraceMissingLayerWording(ctx *types.AgentContext, contract *types.ExactResolutionContract) string {
	if ctx == nil || ctx.AnalysisIR == nil || contract == nil {
		return ""
	}
	if ctx.AnalysisIR.RequestModel.Scenario != types.ScenarioConfigTrace || contract.TargetKind != types.SubjectConfigKey {
		return ""
	}
	missing := types.ConfigTraceMissingRequestedDiagramRoles(contract, answerDocExactContextRequiredFiles(ctx), ctx.EvidenceItems)
	if len(missing) == 0 {
		return ""
	}
	labelByRole := types.ConfigTraceRequestedRoleLabels(ctx.AnalysisIR.RequestModel, contract)
	var lines []string
	lines = append(lines, "- Populate document-level `missing_requested_roles[]` with the missing requested layers below; the renderer will materialise the explicit missing-layer prose from this typed field.")
	for _, role := range missing {
		label := strings.TrimSpace(labelByRole[role])
		switch role {
		case types.EvidenceDiagramRoleConfig:
			if label == "" {
				label = "config-file"
			}
			lines = append(lines,
				fmt.Sprintf("- For the missing `%s` layer, prefer explicit absence wording such as `%s 层没有匹配该键` or `no %s key matches this target`.", role, label, label))
		case types.EvidenceDiagramRoleOverride:
			if strings.EqualFold(strings.TrimSpace(label), "cli") {
				lines = append(lines,
					"- For the missing `override` layer when the user names it as `CLI`, prefer explicit absence wording such as `CLI 层未绑定该键` or `no CLI flag binds this key`.")
				continue
			}
			if label == "" {
				label = "override"
			}
			lines = append(lines,
				fmt.Sprintf("- For the missing `%s` layer, prefer explicit absence wording such as `%s 层未绑定该键` or `no %s binding exists for this target`.", role, label, label))
		case types.EvidenceDiagramRoleDefault:
			if label == "" {
				label = "code default"
			}
			lines = append(lines,
				fmt.Sprintf("- For the missing `%s` layer, prefer explicit absence wording such as `%s 层没有为该精确键提供绑定` or `no %s binding exists for this exact key`.", role, label, label))
		case types.EvidenceDiagramRoleRuntime:
			if label == "" {
				label = "runtime"
			}
			lines = append(lines,
				fmt.Sprintf("- For the missing `%s` layer, prefer explicit absence wording such as `%s 层未提供该键的运行时绑定` or `no %s binding exists for this target`.", role, label, label))
		}
	}
	if len(lines) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Explicit Missing-Layer Wording\n\n")
	for _, line := range lines {
		b.WriteString(line)
		b.WriteString("\n")
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocAcceptedClosure(ctx *types.AgentContext) string {
	plan := answerSurfacePlan(ctx)
	if plan == nil {
		return ""
	}
	if strings.TrimSpace(plan.StableInvestigationReason) == "" &&
		strings.TrimSpace(plan.StableAbsenceJustification) == "" &&
		len(plan.StableValidationBoundaryNotes) == 0 {
		return ""
	}
	sourceInventoryAccepted := answerDocSourceInventorySuppressesStaleDisplayDebt(ctx)
	var b strings.Builder
	b.WriteString("## Accepted Closure Status\n\n")
	b.WriteString("- A prior exploration window already reached a stable closure for this dispatch.\n")
	if plan.StableAbsent {
		b.WriteString("- The stable state currently remains an accepted bounded absence / no-hit result for the exact target under the explored scope.\n")
	}
	if strings.TrimSpace(plan.StableInvestigationResultKind) != "" {
		renderAcceptedInvestigationDisposition(&b, ctx, plan.StableInvestigationResultKind)
	}
	if reason := strings.TrimSpace(plan.StableInvestigationReason); reason != "" {
		if runtimeObservationOnlyForAnswerDoc(ctx) {
			b.WriteString("- model-authored closure reason omitted from this authority section because the typed observed-artifact lane is authoritative for direct runtime facts. Any preserved runtime narrative appears only as advisory synthesis below, not as caller-side provenance or current-source proof.\n")
		} else if suppressUnstructuredClosureReasonForTypedMechanism(ctx) {
			b.WriteString("- model-authored closure reason omitted from this authority section because grounded current-source facts and typed flow carriers are authoritative for mechanism roles and relations. Unstructured exploration synthesis cannot upgrade a local definition, branch, assignment, or payload field into a runtime identity, pairing key, call edge, or ordered path.\n")
		} else if suppressUnstructuredClosureReasonForPrincipalMemberSets(ctx, plan.StableAggregateFacts) {
			reason = sanitizeAggregateExcludedCandidatesForPrompt(ctx, reason, plan.StableAggregateFacts)
			fmt.Fprintf(&b, "- model-authored closure set-level summary (advisory only; typed `aggregate_facts.member_set` rows/counts below remain the authoritative member carrier if any number or member identity conflicts): %s\n", truncateAnswerDocPromptText(reason, 700))
		} else {
			reason = sanitizeAggregateExcludedCandidatesForPrompt(ctx, reason, plan.StableAggregateFacts)
			fmt.Fprintf(&b, "- model-authored closure reason: %s\n", truncateAnswerDocPromptText(reason, 900))
		}
	}
	if justification := strings.TrimSpace(plan.StableAbsenceJustification); justification != "" {
		fmt.Fprintf(&b, "- absence justification: %s\n", truncateAnswerDocPromptText(justification, 500))
	}
	if len(plan.StableValidationBoundaryNotes) > 0 {
		if sourceInventoryAccepted {
			b.WriteString("- post-closure validation audit notes (not user-visible caveats for the accepted source-inventory universe):\n")
		} else {
			b.WriteString("- post-closure validation boundaries:\n")
		}
		for i, note := range plan.StableValidationBoundaryNotes {
			trimmed := strings.TrimSpace(note)
			if trimmed == "" {
				continue
			}
			fmt.Fprintf(&b, "  %d. %s\n", i+1, truncateAnswerDocPromptText(trimmed, 700))
		}
	}
	b.WriteString("- Treat this closure as a structured exploration handoff, not as a citation and not as system-written answer text.\n")
	b.WriteString("- Preserve resolved counts, listed members, excluded categories/counts, scope boundaries, and verdicts from the closure only when the same value is carried by structured aggregate facts, typed support lanes, current citations, or raw tool outputs below. If unstructured closure prose conflicts with typed member obligations, principal support lanes, or structured aggregate facts, prefer the typed/structured handoff.\n")
	if sourceInventoryAccepted {
		b.WriteString("- Source-inventory authority has accepted the requested/exact universe. Do not convert stale broad-lens budget, pagination, or post-closure audit notes into a user-visible caveat; answer from the Principal Enumeration Rows and source-inventory authority handoff unless another precise hard gap is present.\n")
	} else {
		b.WriteString("- When post-closure validation boundaries say the supported candidate set remains broad, unresolved, or under-constrained, converge the answer by prioritizing/grouping the supported facts and disclose the boundary in summary/caveat text. Do not invent missing precision solely to satisfy a validation criterion.\n")
	}
	b.WriteString("- Rebuild the user-visible prose yourself inside `emit_answer_document`; do not invent facts beyond the closure/evidence boundary.\n\n")
	return b.String()
}

// renderAcceptedInvestigationDisposition keeps the internal completion enum
// from teaching the answer model that an accepted closure proved every
// requested relation.  The exact machine state remains unchanged; only the
// prompt projection is clarified when a producer-owned typed caveat says a
// substantive boundary survived bounded convergence.
func renderAcceptedInvestigationDisposition(b *strings.Builder, ctx *types.AgentContext, resultKind string) {
	if b == nil {
		return
	}
	resultKind = strings.TrimSpace(resultKind)
	if resultKind == "" {
		return
	}
	if strings.EqualFold(resultKind, "resolved") && acceptedClosureHasTypedUnresolvedBoundary(ctx) {
		b.WriteString("- accepted closure: the collected evidence is sufficient to write an evidence-bounded answer, while one or more structured evidence boundaries remain unproven. Do not interpret closure as proof that every requested relation, participant, source, or optional detail was established; preserve the specific boundary guidance below.\n")
		return
	}
	fmt.Fprintf(b, "- result_kind: `%s`\n", resultKind)
}

func acceptedClosureHasTypedUnresolvedBoundary(ctx *types.AgentContext) bool {
	if ctx == nil || ctx.Mutable == nil || ctx.Mutable.EvidenceClosure() == nil {
		return false
	}
	for _, caveat := range ctx.Mutable.EvidenceClosure().CompletionCaveats() {
		// completion_form is landing-shape debt, not evidence/coverage debt.
		// It must not by itself downgrade the semantic closure description.
		if caveat.Lane != "" && caveat.Lane != types.DowngradeLaneCompletionForm {
			return true
		}
	}
	return false
}

// suppressUnstructuredClosureReasonForTypedMechanism keeps stage-local prose
// from becoming a second mechanism authority after grounded source facts have
// landed. The explorer is still free to synthesize a conclusion, and the
// finalizer still owns the user-visible answer; this only prevents an
// unstructured completion reason from overriding the typed evidence/flow
// carriers while the answer is being composed.
//
// The predicate intentionally reads only the structured request profile and
// typed evidence/flow fields. It does not inspect the user's prose, an
// evidence Summary, or model-authored answer text.
func suppressUnstructuredClosureReasonForTypedMechanism(ctx *types.AgentContext) bool {
	if ctx == nil || ctx.AnalysisIR == nil ||
		!answerDocMechanismRelationAuthorityApplies(ctx.AnalysisIR.RequestModel) {
		return false
	}
	for _, item := range answerDocTypedEnrichmentEvidencePool(ctx, answerDocMaxEnrichmentCandidateFacts) {
		if answerDocGroundedCurrentSourceMechanismFact(item) {
			return true
		}
	}
	return len(answerDocSupportedMechanismFlowPathsForContext(ctx)) > 0
}

func renderAnswerDocUnifiedIntentContract(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	contract := types.CompileAnswerIntentContract(ctx.AnalysisIR.RequestModel, &ctx.AnalysisIR.AnswerContract)
	if len(contract.Origins) == 0 && len(contract.RequestedOutputs) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Evidence Origin / Requested Output Boundary\n\n")
	b.WriteString("- Evidence origins describe where a fact came from. They are not answer shapes by themselves.\n")
	b.WriteString("- Requested outputs describe what the user-facing answer must preserve. Do not collapse a richer requested output to a scalar merely because one evidence origin supplies a commit id, count, path, or literal.\n")
	b.WriteString("- Use this section as orientation only. It is not an extra hard gate and does not replace the block requirements, typed support lanes, citations, or aggregate facts below.\n")
	if len(contract.Origins) > 0 {
		fmt.Fprintf(&b, "- evidence origins: %s\n", renderAnswerIntentOrigins(contract.Origins))
	}
	if len(contract.RequestedOutputs) > 0 {
		fmt.Fprintf(&b, "- requested outputs: %s\n", renderAnswerIntentOutputs(contract.RequestedOutputs))
	}
	if contract.HasOrigin(types.AnswerEvidenceOriginVCSMetadata) &&
		!contract.HasOutput(types.AnswerRequestedOutputScalar) &&
		!contract.HasOutput(types.AnswerRequestedOutputCount) {
		b.WriteString("- Repository-history evidence is provenance for the answer, not a request to emit a `scalar` block. Preserve feature summaries, comparisons, diagrams, diagnostics, or mechanism explanations when those outputs are listed.\n")
	}
	if contract.HasOrigin(types.AnswerEvidenceOriginVCSDiff) &&
		contract.HasOrigin(types.AnswerEvidenceOriginCurrentSource) {
		b.WriteString("- Keep historical diff facts and current-checkout source facts in separate lanes: old symbols / old lines from a diff prove historical change, while current-source claims still need current-source evidence.\n")
	}
	if contract.HasOrigin(types.AnswerEvidenceOriginRuntimeArtifact) &&
		!contract.HasOrigin(types.AnswerEvidenceOriginCurrentSource) {
		b.WriteString("- Runtime artifact facts may answer what was observed without current-repo citations. Do not invent current-source file:line citations unless a separate current-source lane is present and grounded.\n")
	}
	if contract.HasOrigin(types.AnswerEvidenceOriginCommandMeasurement) {
		b.WriteString("- Command measurement facts can support exact counts or scalar measurements without pretending the value lives at a source `file:line`.\n")
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocClaimBindings(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	facts := answerDocStableAggregateFacts(ctx)
	bindings := types.CompileAnswerClaimBindings(facts, &ctx.AnalysisIR.RequestModel, &ctx.AnalysisIR.AnswerContract)
	if len(bindings) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Claim Binding / Gate Policy Handoff\n\n")
	b.WriteString("- The following claim bindings are compiled from typed `aggregate_facts`, runtime artifacts, evidence origins, and requested outputs. They are the shared interpretation for answer-writing and review lanes.\n")
	b.WriteString("- Do not translate non-`current_source` bindings into current-source file:line requirements. Use each binding's origin-specific support shape.\n")
	b.WriteString("- A `current_source` binding can create source-line citation pressure only when it carries exact source support; otherwise treat it as repairable context and use grounded evidence rows / ledger records for citations.\n")
	b.WriteString("- `authority_ceiling` caps how strongly a binding may be turned into a current-source or causal claim. `historical` runtime/VCS bindings may state what was observed or changed, but they do not prove the current checkout's root cause unless a separate exact `current_source` binding supports that claim.\n")
	b.WriteString("- `hard` means the principal claim itself must be exact; `repairable` / `soft` defects should be locally repaired or disclosed in a localized supplement rather than forcing a broad rewrite.\n")
	ledger := answerDocObservationLedger(ctx)
	visibleLedgerRecords, _ := answerDocFinalizerObservationRecords(ctx, ledger.Records)
	visibleLedgerIDs := make(map[string]bool, len(visibleLedgerRecords))
	for _, record := range visibleLedgerRecords {
		if id := strings.TrimSpace(record.ID); id != "" {
			visibleLedgerIDs[id] = true
		}
	}
	visibleBindings := make([]types.AnswerClaimBinding, 0, len(bindings))
	for _, binding := range bindings {
		if answerDocClaimBindingSupersededPreTriageNavigation(binding, ledger, visibleLedgerIDs) {
			continue
		}
		visibleBindings = append(visibleBindings, binding)
	}
	bindings = visibleBindings
	if len(bindings) == 0 {
		return ""
	}
	limit := len(bindings)
	if limit > 12 {
		limit = 12
	}
	for i := 0; i < limit; i++ {
		binding := bindings[i]
		source := fmt.Sprintf("aggregate_facts[%d] kind=`%s` role=`%s`", binding.AggregateIndex, binding.AggregateKind, binding.AggregateRole)
		if binding.AggregateIndex < 0 {
			source = fmt.Sprintf("source=`%s`", binding.Source)
		}
		ledgerIDs := answerDocClaimBindingLedgerRecordIDs(binding, ledger)
		ledgerPart := ""
		if len(ledgerIDs) > 0 {
			ledgerPart = fmt.Sprintf("; ledger_records=%s", strings.Join(ledgerIDs, ","))
		}
		exactSourcePart := ""
		if binding.Origin == types.AnswerEvidenceOriginCurrentSource {
			exactSourcePart = fmt.Sprintf("; exact_source_support=%t", types.AnswerClaimBindingHasExactCurrentSourceSupport(binding))
		}
		authorityPart := ""
		if authority := types.AnswerClaimBindingAuthorityCeiling(binding); authority != "" {
			authorityPart = fmt.Sprintf("; authority_ceiling=`%s`", authority)
		}
		driftPart := ""
		if binding.DriftReason != "" {
			driftPart = fmt.Sprintf("; drift_reason=`%s`", binding.DriftReason)
		}
		fmt.Fprintf(&b,
			"- `%s`: origin=`%s`; policy=`%s`; outputs=%s; %s; target=%q; support_refs=%d%s%s%s%s\n",
			binding.ClaimID,
			binding.Origin,
			binding.GroundingPolicy,
			renderAnswerIntentOutputs(binding.RequestedOutputs),
			source,
			binding.TargetRef,
			len(binding.SupportRefs),
			exactSourcePart,
			authorityPart,
			driftPart,
			ledgerPart,
		)
	}
	if len(bindings) > limit {
		fmt.Fprintf(&b, "- ... %d additional binding(s) omitted from prompt for brevity; use aggregate_facts below as the complete ledger.\n", len(bindings)-limit)
	}
	b.WriteString("\n")
	return b.String()
}

// answerDocClaimBindingSupersededPreTriageNavigation keeps the claim-binding
// view aligned with the Finalizer's observation view. A model-extracted perf
// observation or stall remains a display-only navigation binding when no
// deterministic query covers its capture. Once the exact same typed ledger
// record is hidden by same-capture deterministic-query precedence, its
// model-authored subject must not leak back into the causal material through
// this parallel binding surface. Matching uses only source enum,
// authority/policy enums, compiler-owned record IDs, and exact typed
// ClaimKey/Subject equality; no request or answer prose is inspected.
func answerDocClaimBindingSupersededPreTriageNavigation(
	binding types.AnswerClaimBinding,
	ledger types.ObservationLedger,
	visibleLedgerIDs map[string]bool,
) bool {
	if strings.TrimSpace(binding.Source) != "perf_trace" ||
		binding.GroundingPolicy != types.ClaimGroundingDisplayOnly ||
		binding.AuthorityCeiling != types.AuthorityIllustrative {
		return false
	}
	target := strings.TrimSpace(binding.TargetRef)
	if target == "" {
		return false
	}
	matched := false
	for _, record := range ledger.Records {
		recordID := strings.TrimSpace(record.ID)
		if record.Origin != types.AnswerEvidenceOriginRuntimeArtifact ||
			(!strings.HasPrefix(recordID, "perf:observation:") &&
				!strings.HasPrefix(recordID, "perf:stall:")) ||
			(!strings.EqualFold(strings.TrimSpace(record.ClaimKey), target) &&
				!strings.EqualFold(strings.TrimSpace(record.Subject), target)) {
			continue
		}
		matched = true
		if visibleLedgerIDs[recordID] {
			return false
		}
	}
	return matched
}

func answerDocClaimBindingLedgerRecordIDs(binding types.AnswerClaimBinding, ledger types.ObservationLedger) []string {
	if len(ledger.Records) == 0 {
		return nil
	}
	if binding.AggregateIndex >= 0 {
		want := fmt.Sprintf("aggregate:%d#%s", binding.AggregateIndex, binding.Origin)
		for _, record := range ledger.Records {
			if record.ID == want {
				return []string{want}
			}
		}
		return nil
	}
	var prefix string
	switch strings.TrimSpace(binding.Source) {
	case "log_triage":
		prefix = "log:"
	case "perf_trace":
		prefix = "perf:"
	default:
		return nil
	}
	target := strings.TrimSpace(binding.TargetRef)
	out := make([]string, 0, 3)
	for _, record := range ledger.Records {
		if len(out) >= 3 {
			break
		}
		if record.Origin != binding.Origin || !strings.HasPrefix(record.ID, prefix) {
			continue
		}
		if target != "" &&
			!strings.EqualFold(strings.TrimSpace(record.ClaimKey), target) &&
			!strings.EqualFold(strings.TrimSpace(record.Subject), target) {
			continue
		}
		out = append(out, record.ID)
	}
	if len(out) > 0 {
		return out
	}
	for _, record := range ledger.Records {
		if len(out) >= 3 {
			break
		}
		if record.Origin == binding.Origin && strings.HasPrefix(record.ID, prefix) {
			out = append(out, record.ID)
		}
	}
	return out
}

// answerDocObservationLedgerPromptLimit references the unified
// observation-view budget source (Batch E2) so the answer-writing prompt
// render cannot drift from the checkpoint/extract observation views.
const answerDocObservationLedgerPromptLimit = types.ObservationPromptRecordLimit
const answerDocMixedRuntimeSourceObservationLedgerPromptLimit = 10

func renderAnswerDocObservationLedger(ctx *types.AgentContext) string {
	ledger := answerDocObservationLedger(ctx)
	if ledger.Empty() {
		return ""
	}
	promptLedgerRecords, supersededPreTriageNarratives := answerDocFinalizerObservationRecords(ctx, ledger.Records)
	promptLedgerRecords, outsideSelectedWindowRecords := answerDocSelectedWindowObservationRecords(ctx, promptLedgerRecords)
	promptLedger := ledger
	promptLedger.Records = promptLedgerRecords
	records := answerDocObservationPromptRecords(ctx, promptLedgerRecords, answerDocObservationLedgerPromptLimit)
	if len(records) == 0 {
		return ""
	}
	records = answerDocObservationRecordsWithoutReaderAuthorityDuplicates(ctx, promptLedger, records)
	if len(records) == 0 && answerDocLogPeerRelationUnproven(ctx) {
		// The dedicated reader-ready peer-error section below republishes the
		// complete per-occurrence messages and ordered frames in natural
		// language. Keep machine relation keys in the lossless audit ledger,
		// not in the answer-writing prompt where they can leak into prose.
		return ""
	}
	var b strings.Builder
	b.WriteString("## Observation Ledger\n\n")
	b.WriteString("- This is a compact typed view of accepted observations from exploration: current source evidence, structured aggregate facts, VCS/diff or command tool banners, runtime artifacts, cross-repo index rows, external documents, web pages, MCP resources, and connector resources.\n")
	b.WriteString("- It is read-only context for answer writing. Do not turn non-`current_source` observations into source `file:line` citation requirements; use them as their own origin-specific support and disclose boundaries when needed.\n")
	b.WriteString("- Prefer these origin/role/policy fields over raw tool-output shape when deciding whether a fact is principal, repairable, support-only, negative, or citation-bearing.\n\n")
	b.WriteString("- When naming how a runtime/trace fact was obtained, use the row's `producer` exactly: say `trace_query` only for rows whose producer is `trace_query`; for `perf_trace` / `log_triage` rows say they came from attached trace/log preprocessing or runtime artifact observations.\n\n")
	b.WriteString("- Copy path-like, date-like, URL-like, commit-like, row/line/span, and connector/resource ID literals only from exact typed detail, raw payload, or row-set references. Do not expand abbreviated display strings such as git `--stat` paths containing `...`; if exact detail is unavailable, describe the scope without inventing the literal.\n\n")
	if supersededPreTriageNarratives > 0 {
		fmt.Fprintf(&b, "- Same-artifact deterministic runtime queries supersede %d pre-triage free-form navigation observation(s) in this answer-writing view. Their audit records remain in the full ledger; measured perf frame/jank/stall rows and deterministic observations remain available.\n\n", supersededPreTriageNarratives)
	}
	if outsideSelectedWindowRecords > 0 {
		fmt.Fprintf(&b, "- The user-selected explicit trace window is the principal answer scope. %d deterministic query observation(s) whose own typed query windows extend outside it are omitted from this answer-writing view; they remain in the full ledger, causal projection inputs, report appendix, and audit trail as other-window context. Fully contained drilldown rows remain available.\n\n", outsideSelectedWindowRecords)
	}
	if authority := renderAnswerDocRuntimeSourceAuthority(ctx, promptLedger); authority != "" {
		b.WriteString(authority)
	}
	if authority := renderAnswerDocVCSSelectionAuthority(ctx); authority != "" {
		b.WriteString(authority)
	}
	if authority := renderAnswerDocVCSChangedPathAuthority(promptLedger); authority != "" {
		b.WriteString(authority)
	}
	if authority := renderAnswerDocHistoricalCurrentSourceAuthority(promptLedger); authority != "" {
		b.WriteString(authority)
	}
	if relation := renderAnswerDocRuntimeArtifactPairRelationAuthority(promptLedger); relation != "" {
		b.WriteString(relation)
	}
	if coverage := renderAnswerDocTraceObservationCoverage(promptLedger); coverage != "" {
		b.WriteString(coverage)
	}
	if authority := renderAnswerDocTraceValueOccurrenceAuthority(ctx, promptLedger); authority != "" {
		b.WriteString(authority)
	}
	if authority := renderAnswerDocBoundedRuntimeFactAuthority(ctx, promptLedger); authority != "" {
		b.WriteString(authority)
	}
	if authority := renderAnswerDocTraceBlockingWallClockAuthority(ctx, promptLedger); authority != "" {
		b.WriteString(authority)
	}
	if authority := renderAnswerDocTraceIPCRequestCensusAuthority(ctx, promptLedger); authority != "" {
		b.WriteString(authority)
	}
	if authority := renderAnswerDocTraceTargetStateScopeAuthority(promptLedger, extractAnswerDocLang(ctx)); authority != "" {
		b.WriteString(authority)
	}
	if authority := renderAnswerDocTraceRankAuthority(promptLedger, extractAnswerDocLang(ctx)); authority != "" {
		b.WriteString(authority)
	}
	if authority := renderAnswerDocTraceWakeupCensusAuthority(promptLedger, extractAnswerDocLang(ctx)); authority != "" {
		b.WriteString(authority)
	}
	if len(records) > 0 && len(promptLedger.Records) > len(records) {
		renderedIDs := make(map[string]bool, len(records))
		for _, record := range records {
			renderedIDs[strings.TrimSpace(record.ID)] = true
		}
		fmt.Fprintf(&b, "*(showing %d prioritized record(s) of %d total", len(records), len(promptLedger.Records))
		if dropped := types.SummarizeDroppedObservationRecords(promptLedger.Records, renderedIDs); dropped != "" {
			fmt.Fprintf(&b, "; dropped: %s", dropped)
		}
		b.WriteString(")*\n\n")
	}
	if len(records) == 0 {
		if strings.HasPrefix(strings.ToLower(strings.TrimSpace(extractAnswerDocLang(ctx))), "zh") {
			b.WriteString("- 完整的调度器标记等待清单将在下方专用读者事实区只发布一次；原始机器记录仍保留在审计账本和校验器中。\n")
		} else {
			b.WriteString("- Complete scheduler-marked target-wait rows are intentionally published once in the dedicated reader-ready section below; their lossless machine records remain in the audit ledger and validators.\n")
		}
	}
	for _, record := range records {
		fmt.Fprintf(&b,
			"- `%s`: origin=`%s`; producer=`%s`; source=`%s`; role=`%s`; policy=`%s`",
			record.ID,
			record.Origin,
			record.Producer,
			record.Source,
			record.Role,
			record.GroundingPolicy,
		)
		if record.ProvenanceLane.IsValid() {
			fmt.Fprintf(&b, "; lane=`%s`", record.ProvenanceLane)
		}
		if record.ClaimAuthority.IsValid() {
			fmt.Fprintf(&b, "; claim_authority=`%s`", record.ClaimAuthority)
		}
		if span := strings.TrimSpace(record.Span); span != "" {
			fmt.Fprintf(&b, "; span=%s", span)
		}
		if claim := strings.TrimSpace(record.Claim); claim != "" {
			fmt.Fprintf(&b, "; claim=%q", claim)
		}
		if record.Negative {
			b.WriteString("; negative=true")
		}
		if record.ResultCount != nil {
			fmt.Fprintf(&b, "; result_count=%d", *record.ResultCount)
		}
		if value := strings.TrimSpace(record.Value); value != "" {
			fmt.Fprintf(&b, "; value=%q", value)
		}
		if summary := strings.TrimSpace(record.Summary); summary != "" {
			fmt.Fprintf(&b, "; summary=%q", summary)
		}
		if excerpt := strings.TrimSpace(record.Excerpt); excerpt != "" {
			fmt.Fprintf(&b, "; excerpt=%q", excerpt)
		}
		if len(record.Notes) > 0 {
			if notes := renderAnswerDocObservationNotes(record.Notes, len(record.Notes)); notes != "" {
				fmt.Fprintf(&b, "; notes=%s", notes)
			}
		}
		if record.SupportRefCount > 0 {
			fmt.Fprintf(&b, "; support_refs=%d", record.SupportRefCount)
		}
		b.WriteString("\n")
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocVCSSelectionAuthority(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil || ctx.Mutable == nil {
		return ""
	}
	profile := ctx.AnalysisIR.RequestModel.HistorySelectionProfile
	if profile == nil || !profile.Active() {
		return ""
	}
	var results []types.ToolResult
	if ta := ctx.Mutable.TurnAArtifacts(); ta != nil {
		results = append(results, ta.ToolResults...)
	}
	results = append(results, ctx.Mutable.DispatchToolResults()...)
	authority, ok := types.BuildVCSHistorySelectionAuthority(&ctx.AnalysisIR.RequestModel, results)
	var b strings.Builder
	b.WriteString("### Typed VCS Principal Selection\n\n")
	if !ok {
		fmt.Fprintf(&b, "- request selection=`%s`; item_kind=`%s`; status=`unproven` — no compatible typed ordered VCS result is available. Do not silently substitute a subjectively important history row; preserve the selection boundary and state what evidence is missing.\n\n", profile.Mode, profile.ItemKind)
		return b.String()
	}
	fmt.Fprintf(&b, "- selection=`%s`; item_kind=`%s`; query_order=`%s`; query_limit=%d; complete=%t; reason=`%s`\n",
		authority.Mode, authority.ItemKind, authority.QueryOrder, authority.QueryLimit, authority.Complete, authority.Reason)
	for i, commit := range authority.SelectedCommits {
		fmt.Fprintf(&b, "  - principal_ordinal=%d; commit=`%s`\n", i+1, strings.TrimSpace(commit))
	}
	b.WriteString("- Treat exactly these selected row(s) as the principal history target. Later rows from a wider query are context only. Do not replace the selected row based on commit subject, patch size, changed-file role, or a judgment that another row is more substantive. Current-source explanation must follow the selected target; if current-source evidence for it is incomplete, disclose that boundary instead of changing targets.\n\n")
	return b.String()
}

func renderAnswerDocVCSChangedPathAuthority(ledger types.ObservationLedger) string {
	var records []types.ObservationRecord
	for _, record := range ledger.Records {
		if record.Origin != types.AnswerEvidenceOriginVCSDiff ||
			record.Predicate != "changed_paths" || record.Enumeration == nil {
			continue
		}
		recordCopy := record
		records = append(records, recordCopy)
	}
	if len(records) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("### Typed VCS Changed-Path Authority\n\n")
	b.WriteString("The paths below come from tool-computed `git show --name-only` rosters, not abbreviated `--stat` display text. When the answer states a changed-file count or list for one of these commits, preserve this total and every emitted path exactly. Keep current implementation relevance as a separate current-source claim; it must not silently replace the historical changed-path roster.\n")
	for _, record := range records {
		boundary := record.Enumeration
		complete := boundary.TotalKnown && boundary.Emitted == boundary.Total && boundary.Reason == "complete"
		fmt.Fprintf(&b, "- commit=`%s`; emitted=%d; ", strings.TrimSpace(record.Subject), boundary.Emitted)
		if boundary.TotalKnown {
			fmt.Fprintf(&b, "total=%d; complete=%t", boundary.Total, complete)
		} else {
			b.WriteString("total=unknown; complete=false")
		}
		if boundary.Reason != "" {
			fmt.Fprintf(&b, "; reason=`%s`", boundary.Reason)
		}
		b.WriteString("\n")
		for _, changedPath := range record.SurfaceTerms {
			if changedPath = strings.TrimSpace(changedPath); changedPath != "" {
				fmt.Fprintf(&b, "  - `%s`\n", changedPath)
			}
		}
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocHistoricalCurrentSourceAuthority(ledger types.ObservationLedger) string {
	authority := types.BuildHistoricalCurrentSourceAuthority(ledger)
	if !authority.Active {
		return ""
	}
	var b strings.Builder
	b.WriteString("### Historical Observation / Current Checkout Boundary\n\n")
	fmt.Fprintf(&b, "- historical_transition=`%s`; reason=`%s`; historical_origins=", authority.TransitionStatus, authority.Reason)
	for i, origin := range authority.HistoricalOrigins {
		if i > 0 {
			b.WriteString(",")
		}
		fmt.Fprintf(&b, "`%s`", origin)
	}
	b.WriteString("\n")
	b.WriteString("- Historical observations/diffs and current-checkout facts are independently valid lanes. `unproven` means no typed revision mapping or behavioural transition witness connects them: do not claim the historical incident was fixed, introduced, preserved, or caused by the current checkout. You may still describe what the historical lane changed/observed and what the current source independently does.\n")
	b.WriteString("- The exact current-source bindings below are the only verified current locations in this boundary. A historical path match means only that the path appears in the typed changed-path roster; it does not prove symbol identity or behavioural continuity. If a historical symbol has no exact current binding below, keep its current location/status unproven instead of assigning it to a nearby cited helper.\n")
	for _, def := range authority.CurrentDefinitions {
		symbol := strings.TrimSpace(def.Symbol)
		if symbol == "" {
			symbol = "(unnamed exact source span)"
		}
		fmt.Fprintf(&b, "  - symbol=`%s`; current_path=`%s`; current_lines=%d-%d; historical_path_match=%t\n",
			symbol, def.Path, def.LineStart, def.LineEnd, def.HistoricalPathMatch)
	}
	if authority.CurrentDefinitionsCapped {
		fmt.Fprintf(&b, "  - current_definition_roster_capped=true; emitted=%d; total=%d — omitted definitions are not absent, but they are not exact location authority in this prompt view.\n", len(authority.CurrentDefinitions), authority.CurrentDefinitionTotal)
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocTargetWaitOccurrenceAuthority(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	ledger := answerDocObservationLedger(ctx)
	authorities := types.BuildTargetWaitOccurrenceAuthorities(ledger, &ctx.AnalysisIR.RequestModel)
	if len(authorities) == 0 {
		return ""
	}
	zh := strings.HasPrefix(strings.ToLower(strings.TrimSpace(extractAnswerDocLang(ctx))), "zh")
	var b strings.Builder
	if zh {
		b.WriteString("## 目标线程的调度器标记等待清单\n\n")
		b.WriteString("- 这些完整清单由运行时引擎按目标线程和所选窗口配对，只包含不可中断等待、明确的 IO 等待，以及阻塞原因明确标记为 IO 等待的可中断睡眠。普通可中断睡眠和由其他机制证明的等待或阻塞不在本清单内。\n")
		b.WriteString("- 清单为零只表示该目标与窗口内没有匹配上述窄口径的区间；不能据此声称没有睡眠、等待、阻塞或 IO 活动。另行发布的线程状态总量、IO 完成闭环和依赖证据仍然有效。\n")
		b.WriteString("- 如果正文列举清单中的任一项，必须保留同一清单的全部项目及其原始起止时间和持续时间；不得用相邻调度事件重建区间，也不得把阻塞原因记录的时间戳当作区间起点。字段名和机器状态码只用于内部校验，不要写入面向客户的正文。\n\n")
	} else {
		b.WriteString("## Scheduler-marked waits for the target thread\n\n")
		b.WriteString("- These complete lists are paired by the runtime engine for the target thread and selected window. They include uninterruptible waits, explicit IO waits, and interruptible sleep only when its blocked-reason evidence explicitly marks IO wait. Ordinary interruptible sleep and waits or blocking proved by other mechanisms are outside this list.\n")
		b.WriteString("- A zero list means only that no interval matched this narrow classifier for the target and window. It does not prove there was no sleep, waiting, blocking, or IO activity. Separately published thread-state totals, completion-closed IO evidence, and dependency evidence remain valid.\n")
		b.WriteString("- If the answer enumerates any item, preserve every item in the same list with its original start, end, and duration. Do not rebuild intervals from adjacent scheduler events or use a blocked-reason timestamp as an interval start. Field names and machine status codes are validation metadata and must not appear in customer-facing prose.\n\n")
	}
	for _, authority := range authorities {
		if zh {
			fmt.Fprintf(&b, "- %s：清单完整覆盖所选窗口；共 %d 次，合计 %.3f 毫秒。\n",
				authority.Subject, authority.Count, authority.SumMS)
		} else {
			fmt.Fprintf(&b, "- %s: the list completely covers the selected window; %d occurrence(s), totaling %.3f ms.\n",
				authority.Subject, authority.Count, authority.SumMS)
		}
		for _, row := range authority.Rows {
			state := traceFinalReaderStateLabel(row.State, zh)
			if state == "" {
				state = row.State
			}
			iowait := "unknown"
			if zh {
				iowait = "未知"
			}
			switch row.IOWait {
			case "1":
				if zh {
					iowait = "是"
				} else {
					iowait = "yes"
				}
			case "0":
				if zh {
					iowait = "否"
				} else {
					iowait = "no"
				}
			}
			if zh {
				fmt.Fprintf(&b, "  - 第 %d 次：%s；%.6f–%.6f 秒；持续 %.3f 毫秒；调度器 IO 等待标记：%s；内核记录函数：%s。\n",
					row.Ordinal, state, row.StartTs, row.EndTs, row.DurationM, iowait, row.Caller)
			} else {
				fmt.Fprintf(&b, "  - Occurrence %d: %s; %.6f–%.6f seconds; duration %.3f ms; scheduler IO-wait marker: %s; recorded kernel function: %s.\n",
					row.Ordinal, state, row.StartTs, row.EndTs, row.DurationM, iowait, row.Caller)
			}
		}
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocTraceObservationCoverage(ledger types.ObservationLedger) string {
	coverage := types.BuildTraceObservationCoverage(ledger)
	if !coverage.Active {
		return ""
	}
	var b strings.Builder
	b.WriteString("### Trace Observation Coverage\n\n")
	b.WriteString("- This typed coverage view is a soft handoff for trace/log answer writing. It summarizes which deterministic `trace_query` dimensions are already on the ledger; missing dimensions are follow-up suggestions only, not completion blockers.\n")
	fmt.Fprintf(&b, "- trace_query_calls=%d; trace_observations=%d", coverage.QueryCount, coverage.TotalRecords)
	if len(coverage.Windows) > 0 {
		fmt.Fprintf(&b, "; windows=`%s`", strings.Join(coverage.Windows, "`, `"))
	}
	if len(coverage.SourceRefs) > 0 {
		fmt.Fprintf(&b, "; sources=`%s`", strings.Join(coverage.SourceRefs, "`, `"))
	}
	b.WriteByte('\n')
	if len(coverage.Dimensions) > 0 {
		parts := make([]string, 0, len(coverage.Dimensions))
		for _, dim := range coverage.Dimensions {
			item := fmt.Sprintf("%s:%d", dim.Dimension, dim.Count)
			if dim.OnChainCount > 0 || dim.AdjacentCount > 0 || dim.BackgroundCount > 0 {
				item += fmt.Sprintf("(on=%d adjacent=%d background=%d)", dim.OnChainCount, dim.AdjacentCount, dim.BackgroundCount)
			}
			parts = append(parts, item)
		}
		fmt.Fprintf(&b, "- dimensions: %s\n", strings.Join(parts, ", "))
	}
	if len(coverage.SoftMissingDimensions) > 0 {
		fmt.Fprintf(&b, "- soft_followup_candidates: `%s` (do not reopen exploration solely for these if the answer is otherwise sufficient; disclose as caveat or use bounded trace_query follow-up when budget allows)\n", strings.Join(coverage.SoftMissingDimensions, "`, `"))
	}
	if len(coverage.ShardAggregates) > 0 {
		b.WriteString("- shard_aggregates: bounded shard summaries below are soft parent-window handoff, not completion blockers.\n")
		for i, agg := range coverage.ShardAggregates {
			if i >= 4 {
				break
			}
			fmt.Fprintf(&b, "  - shard[%d] subject=`%s`; object=`%s`; chain_relevance=`%s`; shards=%d",
				i+1, agg.Subject, agg.Object, agg.ChainRelevance, agg.ShardCount)
			writeAnswerDocTraceShardAmount(&b, agg.AdditivityStatus, agg.TotalImpactMS, agg.MaxShardImpactMS)
			if agg.Window != "" {
				fmt.Fprintf(&b, "; window=%s", agg.Window)
			}
			if len(agg.ExampleWindows) > 0 {
				fmt.Fprintf(&b, "; example_windows=`%s`", strings.Join(agg.ExampleWindows, "`, `"))
			}
			if len(agg.SupportRefs) > 0 {
				fmt.Fprintf(&b, "; support_refs=`%s`", strings.Join(agg.SupportRefs, "`, `"))
			}
			b.WriteByte('\n')
		}
	}
	if len(coverage.ShardStateAggregates) > 0 {
		b.WriteString("- state_shard_aggregates: bounded state/window-stats shard summaries below are soft parent-window handoff, not completion blockers.\n")
		for i, agg := range coverage.ShardStateAggregates {
			if i >= 4 {
				break
			}
			fmt.Fprintf(&b, "  - state_shard[%d] dimension=`%s`; subject=`%s`; object=`%s`; shards=%d; significant_shards=%d",
				i+1, agg.Dimension, agg.Subject, agg.Object, agg.ShardCount, agg.SignificantShardCount)
			writeAnswerDocTraceShardAmount(&b, agg.AdditivityStatus, agg.TotalImpactMS, agg.MaxShardImpactMS)
			if agg.DrilldownSource != "" {
				fmt.Fprintf(&b, "; source=`%s`", agg.DrilldownSource)
			}
			if len(agg.RecommendedViews) > 0 {
				fmt.Fprintf(&b, "; recommended_views=`%s`", strings.Join(agg.RecommendedViews, "`, `"))
			}
			if agg.ChainRequired || agg.RecursiveDrilldown {
				fmt.Fprintf(&b, "; chain_required=%t; recursive=%t", agg.ChainRequired, agg.RecursiveDrilldown)
			}
			if agg.Window != "" {
				fmt.Fprintf(&b, "; window=%s", agg.Window)
			}
			if len(agg.ExampleWindows) > 0 {
				fmt.Fprintf(&b, "; example_windows=`%s`", strings.Join(agg.ExampleWindows, "`, `"))
			}
			if len(agg.SupportRefs) > 0 {
				fmt.Fprintf(&b, "; support_refs=`%s`", strings.Join(agg.SupportRefs, "`, `"))
			}
			b.WriteByte('\n')
		}
	}
	shownTopObservations := 0
	for i, obs := range coverage.TopObservations {
		if i >= types.TraceCoverageTopObservationPromptLimit {
			break
		}
		shownTopObservations++
		fmt.Fprintf(&b, "- top[%d] dimension=`%s`; id=`%s`", i+1, obs.Dimension, obs.ID)
		if obs.ChainRelevance != "" {
			fmt.Fprintf(&b, "; chain_relevance=`%s`", obs.ChainRelevance)
		}
		if obs.Window != "" {
			fmt.Fprintf(&b, "; window=%s", obs.Window)
		}
		if obs.Filter != "" {
			fmt.Fprintf(&b, "; filter=%q", obs.Filter)
		}
		if obs.Value != "" {
			fmt.Fprintf(&b, "; value=%q", obs.Value)
		}
		if obs.DrilldownSource != "" {
			fmt.Fprintf(&b, "; drilldown_source=`%s`", obs.DrilldownSource)
		}
		if len(obs.RecommendedViews) > 0 {
			fmt.Fprintf(&b, "; recommended_views=`%s`", strings.Join(obs.RecommendedViews, "`, `"))
		}
		if obs.Dimension == types.TraceObservationDimensionStateDrilldown {
			fmt.Fprintf(&b, "; chain_required=%t; recursive=%t", obs.ChainRequired, obs.RecursiveDrilldown)
		} else {
			if obs.ChainRequired {
				b.WriteString("; chain_required=true")
			}
			if obs.RecursiveDrilldown {
				b.WriteString("; recursive=true")
			}
		}
		if obs.Summary != "" {
			fmt.Fprintf(&b, "; summary=%q", obs.Summary)
		}
		if obs.Span != "" {
			fmt.Fprintf(&b, "; span=%s", obs.Span)
		}
		if len(obs.SupportRefs) > 0 {
			fmt.Fprintf(&b, "; support_refs=`%s`", strings.Join(obs.SupportRefs, "`, `"))
		}
		b.WriteByte('\n')
	}
	if coverage.TotalRecords > shownTopObservations {
		fmt.Fprintf(&b, "- (top view truncated: %d more trace observation(s) beyond the %d shown are not rendered here; the full set remains available in the raw trace_query records and the observation ledger)\n",
			coverage.TotalRecords-shownTopObservations, shownTopObservations)
	}
	b.WriteByte('\n')
	return b.String()
}

func writeAnswerDocTraceShardAmount(b *strings.Builder, status string, totalMS, maxMS float64) {
	if b == nil {
		return
	}
	if status == types.TraceObservationShardAdditivityOverlappingWindows {
		fmt.Fprintf(b, "; total_impact=`unavailable`; max_shard=%.3fms; cross_shard_additivity=`forbidden_overlapping_windows`", maxMS)
		return
	}
	fmt.Fprintf(b, "; total_impact=%.3fms; max_shard=%.3fms; cross_shard_additivity=`disjoint_windows`", totalMS, maxMS)
}

func renderAnswerDocTraceTargetStateScopeAuthority(ledger types.ObservationLedger, lang string) string {
	authorities := types.BuildTraceTargetStateScopeAuthoritiesFromLedger(ledger)
	if len(authorities) == 0 {
		return ""
	}
	zh := strings.HasPrefix(strings.ToLower(strings.TrimSpace(lang)), "zh")
	var b strings.Builder
	if zh {
		b.WriteString("### 目标线程状态统计口径\n\n")
		b.WriteString("- 下面是单个目标线程在所选窗口内的墙钟状态分区，只描述该线程。目标线程的运行或可运行占比不能直接代表整机 CPU 利用率、空闲算力或饱和程度；此类结论必须另有逐 CPU、核簇、进程域或系统级证据。\n")
		b.WriteString("- 保留这里发布的毫秒值与窗口精度，不要从四舍五入的叙述或相邻窗口重新计算。状态只说明线程把时间花在哪一种调度状态，不自动说明等待机制。可中断睡眠本身不证明主动让出、空闲、抢占、IO、锁或其他等待；已经可运行但尚未获调度的时间属于调度延迟。\n")
		b.WriteString("- 其中的 IO 等待采用调度器标记的窄口径：不可中断等待、明确 IO 等待，以及阻塞原因标记为 IO 等待的可中断睡眠。零值只表示没有匹配该窄口径，不能证明磁盘、文件系统、设备或其他 IO 活动/阻塞不存在。由 IO 发起到完成闭合的目标线程等待是另一把尺；若未单独发布，应表述为未评估而不是零。\n")
	} else {
		b.WriteString("### Target-thread scheduler-state accounting\n\n")
		b.WriteString("- The rows below partition wall-clock time for one target thread in the selected window. They describe only that thread. Its running or runnable share does not establish system-wide CPU utilization, idle capacity, or saturation; those conclusions require separate per-CPU, core-class, process-domain, or system evidence.\n")
		b.WriteString("- Preserve the published millisecond values and window precision; do not reconstruct them from rounded prose or a neighboring window. A scheduler state says where the target spent time, not why. Interruptible sleep alone does not prove yielding, idleness, preemption, IO, a lock, or another wait mechanism; ready-but-unscheduled time is scheduling latency.\n")
		b.WriteString("- IO wait here uses the narrow scheduler-marked definition: uninterruptible wait, explicit IO wait, and interruptible sleep whose blocked-reason evidence marks IO wait. Zero means no match for that narrow definition; it does not prove the absence of disk, filesystem, device, or other IO activity/blocking. Target blocking closed by IO issue-to-completion evidence is a separate ruler; when it is not separately published, it is unassessed rather than zero.\n")
	}
	for i, authority := range authorities {
		if i >= 4 {
			if zh {
				fmt.Fprintf(&b, "- 另有 %d 个目标线程状态统计未在本紧凑视图展开。\n", len(authorities)-i)
			} else {
				fmt.Fprintf(&b, "- %d additional target-thread state account(s) are omitted from this compact view.\n", len(authorities)-i)
			}
			break
		}
		label := authority.ArtifactLabel
		if label == "" {
			label = fmt.Sprintf("partition-%d", i+1)
		}
		coverage := traceFinalReaderCoverageLabel(authority.CoverageStatus, zh)
		if zh {
			fmt.Fprintf(&b,
				"- 工件 %s；目标线程 %s；窗口 %.6f–%.6f 秒；运行 %.3f 毫秒，可运行但尚未获调度 %.3f 毫秒，可中断睡眠 %.3f 毫秒，不可中断等待 %.3f 毫秒，其中调度器标记的 IO 等待 %.3f 毫秒、带 IO 等待标记的可中断睡眠 %.3f 毫秒；合计 %.3f 毫秒；%s；未归账 %.3f 毫秒。\n",
				label, authority.Subject, authority.WindowStartTs, authority.WindowEndTs,
				authority.RunningMS, authority.RunnableMS, authority.SleepMS, authority.DStateMS,
				authority.IOWaitMS, authority.SleepIOWaitMS, authority.TotalMS, coverage, authority.UnaccountedMS)
		} else {
			fmt.Fprintf(&b,
				"- Artifact %s; target thread %s; window %.6f–%.6f seconds; running %.3f ms, runnable but not yet scheduled %.3f ms, interruptible sleep %.3f ms, uninterruptible wait %.3f ms, including %.3f ms marked by the scheduler as IO wait and %.3f ms of interruptible sleep carrying an IO-wait marker; total %.3f ms; %s; %.3f ms unaccounted.\n",
				label, authority.Subject, authority.WindowStartTs, authority.WindowEndTs,
				authority.RunningMS, authority.RunnableMS, authority.SleepMS, authority.DStateMS,
				authority.IOWaitMS, authority.SleepIOWaitMS, authority.TotalMS, coverage, authority.UnaccountedMS)
		}
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocTraceValueOccurrenceAuthority(ctx *types.AgentContext, ledger types.ObservationLedger) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	authorities := types.BuildTraceValueOccurrenceAuthorities(ledger, &ctx.AnalysisIR.RequestModel)
	if len(authorities) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("### Trace Value-Owner Temporal Authority\n\n")
	b.WriteString("- Each exact row below binds a measured value to the occurrence interval owned by the same deterministic trace observation. If a command aggregate, transaction phase, neighboring event, or narrative note gives a different timestamp, it cannot replace this value-owner interval.\n")
	b.WriteString("- This authority changes no query, projection, rank, wakeup chain, supplementation, or measured value. `ambiguous_multiple_occurrences` means no single interval may be selected by arrival order.\n")
	for _, authority := range authorities {
		fmt.Fprintf(&b,
			"- artifact=`%s`; subject=`%s`; type=`%s`; value=%.3fms; temporal_status=`%s`; occurrence_count=%d",
			authority.ArtifactLabel,
			authority.Subject,
			authority.Type,
			authority.ValueMS,
			authority.Status,
			authority.OccurrenceN,
		)
		if authority.Status == "exact" {
			fmt.Fprintf(&b, "; value_owner_occurrence=`%.6f..%.6f`", authority.StartTs, authority.EndTs)
		} else {
			b.WriteString("; value_owner_occurrence=`unavailable`")
		}
		if len(authority.RecordIDs) > 0 {
			fmt.Fprintf(&b, "; source_records=`%s`", strings.Join(authority.RecordIDs, "`,`"))
		}
		b.WriteByte('\n')
	}
	b.WriteString("\n")
	return b.String()
}

// renderAnswerDocBoundedRuntimeFactAuthority gives a finite runtime question
// a compact, lossless view of the exact typed families selected by the
// analyzer.  It reads the full accepted ledger rather than the generic 10/32
// row prompt budget, so a long same-target CPU/state roster cannot hide an IO
// pair, its coverage row, or a separately requested pressure caliber.  This is
// evidence handoff only: it neither edits the answer nor elects a root cause.
func renderAnswerDocBoundedRuntimeFactAuthority(ctx *types.AgentContext, ledger types.ObservationLedger) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	rm := &ctx.AnalysisIR.RequestModel
	profile := rm.RuntimeQuestionProfile
	if profile == nil || !profile.CarriesBoundedFactFamilies() {
		return ""
	}
	groups := make(map[types.RuntimeQuestionFactFamily][]types.ObservationRecord)
	for _, record := range ledger.Records {
		if record.Origin != types.AnswerEvidenceOriginRuntimeArtifact ||
			!types.RuntimeObservationProducerIsDeterministicQuery(record.Producer) ||
			record.GroundingPolicy != types.ClaimGroundingHard {
			continue
		}
		for _, family := range types.RuntimeObservationRecordFactFamilies(record) {
			if profile.RequestsFactFamily(family) {
				groups[family] = append(groups[family], record)
			}
		}
	}
	if len(groups) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("### Requested Runtime Fact Authority\n\n")
	b.WriteString("- These rows are the exact finite fact families requested for this answer. They bypass only the generic prompt display budget; they do not widen the question into root-cause ranking, alter a Trace causal projection, or decide the model-owned conclusion.\n")
	b.WriteString("- Keep measurement rulers separate. One block request's issue-to-complete residence is elapsed wall clock for that request, but it is not target-thread blocking time. A completion-closed issuer-blocked interval is target blocking wall clock even when the scheduler state is interruptible `S`. Only an explicitly typed closure permits that attribution. Cross-request `request·ms` and composite pressure scores are non-wall-clock/non-additive.\n")
	b.WriteString("- `selected_window_context` rows describe the selected window but are not attributed to the named target unless the row itself has `owner_scope=target_owned`. Use context rows only as comparison/background evidence. The raw rows below are audit metadata, not reader-facing vocabulary: translate their meaning into natural language and do not copy family/status/caliber enums into the visible answer.\n")
	if bridge := renderAnswerDocIOMeasurementRelationBridge(ctx, ledger, groups[types.RuntimeQuestionFactIOLatency]); bridge != "" {
		b.WriteString(bridge)
	}
	seenFamily := map[types.RuntimeQuestionFactFamily]bool{}
	for _, family := range profile.FactFamilies {
		if seenFamily[family] || len(groups[family]) == 0 {
			continue
		}
		seenFamily[family] = true
		rows := answerDocBoundedRuntimeFactAuthorityRows(groups[family], family, rm)
		fmt.Fprintf(&b, "- requested_family=`%s`; exact_rows=%d; rendered_rows=%d\n", family, len(groups[family]), len(rows))
		if family == types.RuntimeQuestionFactIOLatency {
			targetRows := 0
			for _, record := range rows {
				if types.ObservationRecordMatchesUserRuntimeTarget(record, rm) &&
					strings.EqualFold(strings.TrimSpace(record.Predicate), "io_latency") &&
					traceQueryObservationSupplementNoteValue(record, types.TraceNoteKeyIORequestResidenceCaliber) != "" {
					targetRows++
				}
			}
			fmt.Fprintf(&b, "  - target_owned_request_rows_rendered=`%d`; this is a bounded witness count, not a target request total unless a target-scoped complete census explicitly says so. A selected-window/global `io_latency_coverage` row's emitted/total/overflow values MUST NOT be attributed to the named target.\n", targetRows)
		}
		for _, row := range rows {
			fmt.Fprintf(&b, "  - %s\n", answerDocBoundedRuntimeFactAuthorityRow(row, rm))
		}
	}
	b.WriteByte('\n')
	return b.String()
}

// renderAnswerDocIOMeasurementRelationBridge places the exact IO rulers next
// to one another before their audit rows.  The underlying producers publish
// several individually precise views whose wire names overlap in ordinary
// language ("wait", "latency", "duration").  Leaving those views in distant
// prompt sections caused models to negate a proven completion-closed S wait
// with a zero D/io-wait roster, or to call a single request's elapsed duration
// non-wall-clock because a different cross-request aggregate was non-additive.
//
// This bridge only restates typed ledger facts and set relationships. It does
// not edit answer_document, choose a cause, rank a candidate, or inspect user
// or model prose.
func renderAnswerDocIOMeasurementRelationBridge(
	ctx *types.AgentContext,
	ledger types.ObservationLedger,
	ioRecords []types.ObservationRecord,
) string {
	if ctx == nil || ctx.AnalysisIR == nil || len(ioRecords) == 0 {
		return ""
	}
	rm := &ctx.AnalysisIR.RequestModel
	profile := rm.RuntimeQuestionProfile
	if profile == nil || !profile.RequestsFactFamily(types.RuntimeQuestionFactIOLatency) {
		return ""
	}

	rows := answerDocBoundedRuntimeFactAuthorityRows(ioRecords, types.RuntimeQuestionFactIOLatency, rm)
	requestWitnesses := 0
	requestMaxMS := 0.0
	for _, record := range rows {
		if !types.ObservationRecordMatchesUserRuntimeTarget(record, rm) ||
			!strings.EqualFold(strings.TrimSpace(record.Predicate), "io_latency") ||
			traceQueryObservationSupplementNoteValue(record, types.TraceNoteKeyIORequestResidenceCaliber) == "" {
			continue
		}
		value, err := strconv.ParseFloat(strings.TrimSpace(traceQueryObservationSupplementNoteValue(record, types.TraceNoteKeyIORequestResidence)), 64)
		if err != nil || value < 0 {
			continue
		}
		requestWitnesses++
		if value > requestMaxMS {
			requestMaxMS = value
		}
	}

	var completionClosed *types.TraceBlockingWallClockAuthority
	for _, authority := range types.BuildTraceBlockingWallClockAuthorities(ledger, rm) {
		if authority.Type != "block_io_completion_closed_issuer_wait" {
			continue
		}
		copy := authority
		completionClosed = &copy
		break
	}

	var schedulerWait *types.TargetWaitOccurrenceAuthority
	for _, authority := range types.BuildTargetWaitOccurrenceAuthorities(ledger, rm) {
		copy := authority
		schedulerWait = &copy
		break
	}

	var coverage *types.ObservationRecord
	for i := range ioRecords {
		if strings.EqualFold(strings.TrimSpace(ioRecords[i].Predicate), "io_latency_coverage") {
			coverage = &ioRecords[i]
			break
		}
	}

	if requestWitnesses == 0 && completionClosed == nil && schedulerWait == nil && coverage == nil {
		return ""
	}
	var b strings.Builder
	b.WriteString("  - IO measurement relation bridge (reader-facing meanings; use these meanings instead of wire enums):\n")
	if requestWitnesses > 0 {
		fmt.Fprintf(&b,
			"    - Single-request device elapsed time: %d target-owned request witness(es), largest visible %.3fms. Every issue-to-complete value IS elapsed wall clock for that one request; it is NOT target-thread blocking time, and it MUST NOT be labelled non-wall-clock.\n",
			requestWitnesses, requestMaxMS,
		)
	}
	if completionClosed != nil {
		coverageMeaning := "the interval union is complete for this typed set"
		if completionClosed.CoverageStatus != "complete" {
			coverageMeaning = "only the observed interval union is proven, so this is a lower bound"
		}
		stateMeaning := "with their scheduler states preserved on the audit rows"
		for _, occurrence := range completionClosed.Occurrences {
			if strings.Contains(occurrence.Flags, "state=s_sleep") {
				stateMeaning = "including interruptible S-state waits"
				break
			}
		}
		fmt.Fprintf(&b,
			"    - Target completion-closed blocking time: %d proven interval(s), union=%.3fms, %s; this IS target-thread blocking wall clock; %s.\n",
			len(completionClosed.Occurrences), completionClosed.ObservedMS, stateMeaning, coverageMeaning,
		)
	}
	if schedulerWait != nil {
		fmt.Fprintf(&b,
			"    - Scheduler-marked IO-wait roster: %d occurrence(s), sum=%.3fms. This roster covers D/io_wait intervals plus S intervals only when blocked_reason carries iowait=1. A zero here does NOT include or refute separately proven completion-closed waits above.\n",
			schedulerWait.Count, schedulerWait.SumMS,
		)
	}
	if coverage != nil {
		emitted := traceQueryObservationSupplementNoteValue(*coverage, types.TraceNoteKeyIOCoverageEmitted)
		total := traceQueryObservationSupplementNoteValue(*coverage, types.TraceNoteKeyTotal)
		overflow := traceQueryObservationSupplementNoteValue(*coverage, types.TraceNoteKeyIOOverflowPairs)
		overflowMS := traceQueryObservationSupplementNoteValue(*coverage, types.TraceNoteKeyIOOverflowRequestMS)
		fmt.Fprintf(&b,
			"    - Global selected-window block-request coverage: emitted=%s, total=%s, hidden=%s. The hidden-request duration sum is %s request·ms; this aggregate IS non-wall-clock and non-additive, is not a target request count, and cannot be added to either wall-clock ruler above.\n",
			firstNonEmptyAnswerDocString(emitted, "unknown"),
			firstNonEmptyAnswerDocString(total, "unknown"),
			firstNonEmptyAnswerDocString(overflow, "unknown"),
			firstNonEmptyAnswerDocString(overflowMS, "unknown"),
		)
	}
	b.WriteString("    - Selected-window storage/inode/pressure rows are background unless their own row is target-owned; per-slice maxima are elapsed-duration statistics, not target blocking totals, and overlapping slices are not additive.\n")
	return b.String()
}

func answerDocBoundedRuntimeFactAuthorityRows(records []types.ObservationRecord, family types.RuntimeQuestionFactFamily, rm *types.RequestModel) []types.ObservationRecord {
	const familyCap = 10
	// Requested-family ranking is typed and stable. It keeps target-owned
	// values ahead of context rows while ResultCount set/coverage records stay
	// visible near their leaf rows.
	prioritized := types.PrioritizeObservationRecords(records, rm, nil, len(records))
	selected := make([]types.ObservationRecord, 0, familyCap)
	seenPhysical := make(map[string]bool, familyCap)
	add := func(record types.ObservationRecord) {
		if len(selected) >= familyCap {
			return
		}
		key := answerDocBoundedRuntimeFactPhysicalKey(record)
		if seenPhysical[key] {
			return
		}
		seenPhysical[key] = true
		selected = append(selected, record)
	}
	// For IO latency, reserve the coverage/caliber rows before filling exact
	// pairs. Eight target pairs must not hide the total/overflow boundary or a
	// separately requested storage/inode layer.
	if family == types.RuntimeQuestionFactIOLatency {
		for _, predicate := range []string{"io_latency_coverage", "storage_latency_by_layer", "block_io_by_inode"} {
			for _, record := range prioritized {
				if strings.EqualFold(strings.TrimSpace(record.Predicate), predicate) {
					add(record)
					break
				}
			}
		}
	}
	for _, record := range prioritized {
		add(record)
	}
	return selected
}

// answerDocBoundedRuntimeFactPhysicalKey removes duplicate typed witnesses
// produced when the explorer asks the same deterministic view more than once.
// A block request's producer-owned endpoint identity is stable across tool
// calls, while record.ID intentionally contains the per-call result id.  Do
// not use fuzzy text or proximity: an incomplete identity falls back to the
// exact record id and remains separately visible.
func answerDocBoundedRuntimeFactPhysicalKey(record types.ObservationRecord) string {
	if strings.EqualFold(strings.TrimSpace(record.Predicate), "io_latency") {
		artifact := strings.TrimSpace(record.SourceRef.ArtifactID)
		if artifact == "" {
			artifact = types.RuntimeArtifactCaptureIdentityPath(record.SourceRef)
		}
		parts := []string{
			artifact,
			traceQueryObservationSupplementNoteValue(record, types.TraceNoteKeyIOEndpointFamily),
			traceQueryObservationSupplementNoteValue(record, types.TraceNoteKeyDev),
			traceQueryObservationSupplementNoteValue(record, types.TraceNoteKeyIOSector),
			traceQueryObservationSupplementNoteValue(record, types.TraceNoteKeyIOLength),
			traceQueryObservationSupplementNoteValue(record, types.TraceNoteKeyIOIssueTS),
			traceQueryObservationSupplementNoteValue(record, types.TraceNoteKeyIOCompleteTS),
			traceQueryObservationSupplementNoteValue(record, types.TraceNoteKeyIOIssueThread),
		}
		complete := true
		for _, part := range parts {
			complete = complete && part != ""
		}
		if complete {
			return "io_request\x00" + strings.Join(parts, "\x00")
		}
	}
	return "record\x00" + strings.TrimSpace(record.ID)
}

func answerDocBoundedRuntimeFactAuthorityRow(record types.ObservationRecord, rm *types.RequestModel) string {
	ownerScope := "selected_window_context"
	if types.ObservationRecordMatchesUserRuntimeTarget(record, rm) {
		ownerScope = "target_owned"
	}
	predicate := strings.TrimSpace(record.Predicate)
	parts := []string{
		fmt.Sprintf("id=`%s`", strings.TrimSpace(record.ID)),
		fmt.Sprintf("owner_scope=`%s`", ownerScope),
		fmt.Sprintf("subject=`%s`", strings.TrimSpace(record.Subject)),
		fmt.Sprintf("predicate=`%s`", predicate),
	}
	if object := strings.TrimSpace(record.Object); object != "" {
		parts = append(parts, fmt.Sprintf("object=`%s`", object))
	}
	if value := strings.TrimSpace(record.Value); value != "" {
		parts = append(parts, fmt.Sprintf("value=`%s%s`", value, strings.TrimSpace(record.Unit)))
	}
	if record.Span.EndTs > record.Span.StartTs {
		parts = append(parts, fmt.Sprintf("interval=`%.6f..%.6f`", record.Span.StartTs, record.Span.EndTs))
	}
	appendNote := func(label, key string) {
		if value := traceQueryObservationSupplementNoteValue(record, key); value != "" {
			parts = append(parts, fmt.Sprintf("%s=`%s`", label, value))
		}
	}
	if strings.EqualFold(predicate, "io_latency") {
		appendNote("request_residence", types.TraceNoteKeyIORequestResidence)
		appendNote("request_residence_caliber", types.TraceNoteKeyIORequestResidenceCaliber)
		appendNote("request_clock_scope", types.TraceNoteKeyIORequestResidenceClock)
		appendNote("completion_woke_issuer", types.TraceNoteKeyIOCompletionWokeIssuer)
		appendNote("complete_thread", types.TraceNoteKeyIOCompleteThread)
		appendNote("issuer_blocked_state", types.TraceNoteKeyIOIssuerBlockedState)
		appendNote("issuer_blocked_start", types.TraceNoteKeyIOIssuerBlockedStart)
		appendNote("issuer_blocked_end", types.TraceNoteKeyIOIssuerBlockedEnd)
		appendNote("issuer_blocked", types.TraceNoteKeyIOIssuerBlocked)
		appendNote("issuer_blocked_caliber", types.TraceNoteKeyIOCausalWaitCaliber)
		appendNote("issuer_blocked_clock_scope", types.TraceNoteKeyIOTargetBlockingClock)
		parts = append(parts, "cross_ruler_addition=`forbidden`")
	} else if strings.EqualFold(predicate, "io_latency_coverage") {
		appendNote("emitted", types.TraceNoteKeyIOCoverageEmitted)
		appendNote("total", types.TraceNoteKeyTotal)
		appendNote("coverage_status", types.TraceNoteKeyIOCoverageStatus)
		appendNote("overflow_pairs", types.TraceNoteKeyIOOverflowPairs)
		appendNote("overflow_request_ms", types.TraceNoteKeyIOOverflowRequestMS)
		appendNote("overflow_sum_caliber", types.TraceNoteKeyIOOverflowSumCaliber)
	} else {
		for _, key := range []string{
			types.TraceNoteKeyDev, types.TraceNoteKeyInode,
			types.TraceNoteKeyIOPressureSignal, types.TraceNoteKeyIOPressureEvidenceQuality,
			types.TraceNoteKeyIOPressureScoreCaliber,
		} {
			appendNote(key, key)
		}
	}
	return strings.Join(parts, "; ")
}

func renderAnswerDocTraceBlockingWallClockAuthority(ctx *types.AgentContext, ledger types.ObservationLedger) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	authorities := types.BuildTraceBlockingWallClockAuthorities(ledger, &ctx.AnalysisIR.RequestModel)
	if len(authorities) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("### Trace Target Blocking Wall-Clock Authority\n\n")
	b.WriteString("- Only the typed target-owned intervals below are proven blocking wall clock. A synchronous request count, transaction/reply latency, peer execution interval, or model aggregate is a different measurement and must not be added unless it owns one of these blocking intervals.\n")
	b.WriteString("- An interruptible `S` scheduler state is compatible with a proven blocking occurrence. Zero `D-state`/uninterruptible time cannot refute a listed `S`-state wait or prove that no counterpart wait occurred.\n")
	b.WriteString("- `coverage_status=complete` permits an exhaustive total for that type/window. `lower_bound_capacity_truncated` permits only a proven observed lower bound; do not say total/all/only. Overlapping occurrence intervals are unioned, never double-counted.\n")
	for _, authority := range authorities {
		fmt.Fprintf(&b,
			"- artifact=`%s`; selected_window=`%s`; subject=`%s`; blocking_type=`%s`; proven_blocking_wall_clock=%.3fms; blocking_occurrences_present=`%t`; occurrence_count=%d; coverage_status=`%s`\n",
			authority.ArtifactLabel,
			authority.SelectedWindow,
			authority.Subject,
			authority.Type,
			authority.ObservedMS,
			len(authority.Occurrences) > 0,
			len(authority.Occurrences),
			authority.CoverageStatus,
		)
		for index, occurrence := range authority.Occurrences {
			fmt.Fprintf(&b,
				"  - occurrence=%d; interval=`%.6f..%.6f`; duration=%.3fms",
				index+1,
				occurrence.StartTs,
				occurrence.EndTs,
				occurrence.DurationMS,
			)
			if occurrence.Peer != "" {
				fmt.Fprintf(&b, "; peer=`%s`", occurrence.Peer)
			}
			if occurrence.Flags != "" {
				fmt.Fprintf(&b, "; flags=`%s`", occurrence.Flags)
			}
			if len(occurrence.RecordIDs) > 0 {
				fmt.Fprintf(&b, "; source_records=`%s`", strings.Join(occurrence.RecordIDs, "`,`"))
			}
			b.WriteByte('\n')
		}
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocTraceIPCRequestCensusAuthority(ctx *types.AgentContext, ledger types.ObservationLedger) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	authorities := types.BuildTraceIPCRequestCensusAuthorities(ledger, &ctx.AnalysisIR.RequestModel)
	if len(authorities) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("### Trace IPC Request Census Authority\n\n")
	b.WriteString("- IPC request counts and target blocking-occurrence counts are separate typed calibers. `sync_request=N` counts synchronous request rows; it does not mean N requests produced a proven target blocking interval. Blocking wall clock and its occurrence count come only from `Trace Target Blocking Wall-Clock Authority`.\n")
	b.WriteString("- Native transaction fields below belong to the exact IPC send row. Keep transaction id, flags, code, peer, send time, and matched-receive time together; never copy those fields from a neighboring IPC row or blocking interval.\n")
	b.WriteString("- `coverage_status=complete` permits exhaustive request-count wording. Every other status is incomplete/lower-bound for at least one count or roster dimension and forbids total/all/only wording.\n")
	for _, authority := range authorities {
		fmt.Fprintf(&b,
			"- artifact=`%s`; selected_window=`%s`; subject=`%s`; requests=%d; sync_request=%d; oneway_request=%d; unknown=%d; coverage_status=`%s`\n",
			authority.ArtifactLabel,
			authority.SelectedWindow,
			authority.Subject,
			authority.TotalRequests,
			authority.SyncRequests,
			authority.OnewayRequests,
			authority.UnknownRequests,
			authority.CoverageStatus,
		)
		for _, request := range authority.SyncRoster {
			fmt.Fprintf(&b,
				"  - transaction=%d; semantics=`sync_request`; peer=`%s`; send=`%.6f`; matched_receive=`%.6f`; transport_latency=%.3fms",
				request.TransactionID,
				request.Peer,
				request.SendTs,
				request.ReceiveTs,
				(request.ReceiveTs-request.SendTs)*1000,
			)
			if request.FlagsKnown {
				fmt.Fprintf(&b, "; flags=`%s`", request.Flags)
			} else {
				b.WriteString("; flags=`unavailable`")
			}
			if request.CodeKnown {
				fmt.Fprintf(&b, "; code=`%s`", request.Code)
			} else {
				b.WriteString("; code=`unavailable`")
			}
			if request.ReceiverSource != "" {
				fmt.Fprintf(&b, "; receiver_source=`%s`", request.ReceiverSource)
			}
			if request.RecordID != "" {
				fmt.Fprintf(&b, "; source_record=`%s`", request.RecordID)
			}
			b.WriteByte('\n')
		}
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocTraceRankAuthority(ledger types.ObservationLedger, lang string) string {
	set := types.CompileTraceCausalProjectionSet(ledger)
	authorities := types.BuildTraceRankRosterAuthorities(set)
	if len(authorities) == 0 {
		return ""
	}
	zh := strings.HasPrefix(strings.ToLower(strings.TrimSpace(lang)), "zh")
	var b strings.Builder
	written := 0
	for _, authority := range authorities {
		if len(authority.Seats) == 0 {
			continue
		}
		if written == 0 {
			if zh {
				b.WriteString("### 面向答案的 Trace 排名与算力供给口径\n\n")
				b.WriteString("- 这是由结构化证据生成的写作参考；不改变根因排名、因果投影、自动补采或任何测量值，结论仍由模型给出。\n")
				b.WriteString("- 下方清单是第 N 位名次的唯一依据。没有出现在清单中的测量分量、背景项、目标症状、数据缺口或已并入项没有独立名次；不得按时长或其他表格中的位置补排名。原因名称已经使用面向读者的单源词表，正文不得改抄原始类型、层级、通道或修向枚举。\n")
			} else {
				b.WriteString("### Reader-ready Trace ranking and compute-supply basis\n\n")
				b.WriteString("- This is a structured-evidence writing reference. It does not change the root ranking, causal projection, automatic supplementation, or any measured value; the model still owns the conclusion.\n")
				b.WriteString("- The list below is the only authority for Rank N ordinals. A measured component, background item, target symptom, data gap, or absorbed item absent from it has no independent rank. Do not infer one from duration or another table's position. Cause names already use the single-source reader lexicon; never copy raw type, tier, channel, or repair-bucket enums into visible prose.\n")
			}
		}
		written++
		top := authority.Seats[0]
		label := strings.TrimSpace(authority.ArtifactLabel)
		if label == "" {
			if zh {
				label = fmt.Sprintf("第 %d 份 trace", written)
			} else {
				label = fmt.Sprintf("trace %d", written)
			}
		}
		topCause := answerDocTraceRankReaderCauseLabel(top.Type, zh)
		boardScope := answerDocTraceRankReaderBoardScope(authority.BoardChannel, zh)
		if zh {
			fmt.Fprintf(&b, "- 排名清单 %d；trace：%s；排序范围：%s；清单%s；第一位：#%d %s，%s，按现有规则可消除影响 %.3fms",
				written, label, boardScope, answerDocTraceRankReaderCoverage(authority.Complete, zh), top.Rank,
				strings.TrimSpace(top.Subject), topCause, top.EffectiveImpactMS)
			if authority.BoardTarget != "" {
				fmt.Fprintf(&b, "；分析目标：%s", authority.BoardTarget)
			}
		} else {
			fmt.Fprintf(&b, "- ranking list %d; trace: %s; ranking scope: %s; roster %s; first: #%d %s, %s, %.3fms eliminable under existing rules",
				written, label, boardScope, answerDocTraceRankReaderCoverage(authority.Complete, zh), top.Rank,
				strings.TrimSpace(top.Subject), topCause, top.EffectiveImpactMS)
			if authority.BoardTarget != "" {
				fmt.Fprintf(&b, "; analysis target: %s", authority.BoardTarget)
			}
		}
		if authority.WindowEndTs > authority.WindowStartTs {
			if zh {
				fmt.Fprintf(&b, "；窗口：%.6f..%.6f 秒", authority.WindowStartTs, authority.WindowEndTs)
			} else {
				fmt.Fprintf(&b, "; window: %.6f..%.6f seconds", authority.WindowStartTs, authority.WindowEndTs)
			}
		}
		if zh {
			b.WriteString("。同一排序范围内可比较各行的可消除影响，但各行可能在时间、线程或因果片段上重叠，不得相加；不同排序范围的名次也不得互相比较。只有证据在一条合并行内明确发布的合计才可作为该行总量。\n")
		} else {
			b.WriteString(". Eliminable impacts are comparable only within this ranking scope, but rows may overlap in time, thread, or causal segments and must not be added. Ranks from different scopes are not comparable. Only a total explicitly published within one merged evidence row is additive as that row's total.\n")
		}
		if !authority.Complete {
			if zh {
				b.WriteString("  - 当前清单不完整或存在名次歧义；保留已经发布的名次，不补造缺失项，也不要声称已经覆盖全部原因。\n")
			} else {
				b.WriteString("  - The current roster is incomplete or rank-ambiguous. Preserve published ranks, invent no missing entries, and do not claim complete cause coverage.\n")
			}
		}
		if zh {
			b.WriteString("  - 按名次排列的原因清单：\n")
		} else {
			b.WriteString("  - Causes in rank order:\n")
		}
		for _, seat := range authority.Seats {
			cause := answerDocTraceRankReaderCauseLabel(seat.Type, zh)
			if zh {
				fmt.Fprintf(&b, "    - #%d %s：%s；按现有规则可消除影响 %.3fms\n",
					seat.Rank, seat.Subject, cause, seat.EffectiveImpactMS)
			} else {
				fmt.Fprintf(&b, "    - #%d %s: %s; %.3fms eliminable under existing rules\n",
					seat.Rank, seat.Subject, cause, seat.EffectiveImpactMS)
			}
		}
		if supply, ok := answerDocTraceRankAuthorityTopSupplySeat(authority.Seats); ok {
			primary := authority.Complete && supply.Rank == top.Rank
			cause := answerDocTraceRankReaderCauseLabel(supply.Type, zh)
			if zh {
				relation := "次要候选"
				if primary {
					relation = "第一位"
				}
				fmt.Fprintf(&b, "  - 算力供给补充：#%d %s 的“%s”计入 %.3fms，当前为%s。这说明存在已测算力供给提升空间，但不单独证明热限频、调频策略限制或绑错核；若其他方向领先，只能说算力供给不是首要方向，不能说它不存在或已被排除。\n",
					supply.Rank, strings.TrimSpace(supply.Subject), cause, supply.EffectiveImpactMS, relation)
			} else {
				relation := "a secondary candidate"
				if primary {
					relation = "ranked first"
				}
				fmt.Fprintf(&b, "  - Compute-supply note: #%d %s has %.3fms under “%s” and is %s. This measures compute-delivery headroom but does not by itself prove thermal throttling, governor limiting, or wrong-core placement. If another direction leads, say compute supply is not primary, never that it is absent or ruled out.\n",
					supply.Rank, strings.TrimSpace(supply.Subject), supply.EffectiveImpactMS, cause, relation)
			}
		}
	}
	if written == 0 {
		return ""
	}
	b.WriteString("\n")
	return b.String()
}

func answerDocTraceRankReaderCauseLabel(raw string, zh bool) string {
	if label := strings.TrimSpace(tool.TraceRootCauseTypeDisplayLabel(raw, zh)); label != "" {
		return label
	}
	if zh {
		return "未分类的已测原因"
	}
	return "unclassified measured cause"
}

func answerDocTraceRankReaderBoardScope(raw string, zh bool) string {
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "on_chain":
		if zh {
			return "唤醒/依赖链上"
		}
		return "on the wakeup/dependency chain"
	case "adjacent":
		if zh {
			return "邻近区域（仅支撑额外排查，不属于链上主因）"
		}
		return "adjacent context (follow-up support only, not an on-chain primary cause)"
	case "background":
		if zh {
			return "背景信息（仅支撑额外排查，不属于链上主因）"
		}
		return "background context (follow-up support only, not an on-chain primary cause)"
	default:
		if zh {
			return "独立排序范围"
		}
		return "an independent ranking scope"
	}
}

func answerDocTraceRankReaderCoverage(complete bool, zh bool) string {
	if zh {
		if complete {
			return "完整"
		}
		return "不完整或存在名次歧义"
	}
	if complete {
		return "complete"
	}
	return "incomplete or rank-ambiguous"
}

func renderAnswerDocTraceWakeupCensusAuthority(ledger types.ObservationLedger, lang string) string {
	authorities := types.BuildTraceTargetWakeupCensusAuthorities(ledger)
	if len(authorities) == 0 {
		return ""
	}
	zh := strings.HasPrefix(strings.ToLower(strings.TrimSpace(lang)), "zh")
	terminator := ".\n"
	if zh {
		terminator = "。\n"
	}
	var b strings.Builder
	if zh {
		b.WriteString("### 面向答案的目标线程唤醒统计\n\n")
		b.WriteString("- 以下统计只转述已解析的唤醒记录，不改变唤醒链、根因排序、因果投影、自动补采或任何测量值。\n")
		b.WriteString("- 方向均为“唤醒方 → 目标线程”。状态计数描述唤醒发生前目标线程离开的状态，而不是唤醒后进入的状态。唤醒只使目标线程变为可运行；何时真正切入 CPU、是否随后被抢占或再次睡眠，需要独立且完整的调度切换证据。\n")
	} else {
		b.WriteString("### Reader-ready target-thread wakeup counts\n\n")
		b.WriteString("- These counts restate parsed wakeup records only; they do not change wakeup-chain construction, root ranking, causal projection, automatic supplementation, or any measured value.\n")
		b.WriteString("- Every direction is waker → target. State counts describe the state the target left when the wakeup occurred, not a state entered afterward. A wakeup only makes the target runnable; switch-in, execution, preemption, or a later sleep requires separate complete scheduler-transition evidence.\n")
	}
	for i, authority := range authorities {
		if i >= 4 {
			if zh {
				fmt.Fprintf(&b, "- 另有 %d 组目标线程统计未在此紧凑视图中展开。\n", len(authorities)-i)
			} else {
				fmt.Fprintf(&b, "- %d additional target count set(s) are omitted from this compact view.\n", len(authorities)-i)
			}
			break
		}
		coverage := "complete"
		if zh {
			coverage = "覆盖完整"
		}
		if !authority.Complete {
			coverage = "coverage is internally inconsistent"
			if zh {
				coverage = "统计内部不一致，不能宣称完整"
			}
		}
		if zh {
			fmt.Fprintf(&b, "- 目标线程 %s；窗口 %s；共记录 %d 次唤醒（%s）",
				authority.Target, authority.Window, authority.TotalCount, coverage)
		} else {
			fmt.Fprintf(&b, "- Target %s; window %s; %d wakeup(s) recorded (%s)",
				authority.Target, authority.Window, authority.TotalCount, coverage)
		}
		if authority.SplitAvailable {
			if zh {
				fmt.Fprintf(&b, "；唤醒发生前离开的状态：睡眠 %d 次、D/IO 等待 %d 次、其他或未分类 %d 次",
					authority.SleepExitCount, authority.DExitCount, authority.OtherExitCount)
			} else {
				fmt.Fprintf(&b, "; state left before wakeup: sleep %d, D/IO wait %d, other or unclassified %d",
					authority.SleepExitCount, authority.DExitCount, authority.OtherExitCount)
			}
		}
		b.WriteString(terminator)
		for j, pair := range authority.Pairs {
			if j >= 8 {
				if zh {
					fmt.Fprintf(&b, "  - 另有 %d 个唤醒方未在此紧凑视图中展开。\n", len(authority.Pairs)-j)
				} else {
					fmt.Fprintf(&b, "  - %d additional waker pair(s) are omitted from this compact view.\n", len(authority.Pairs)-j)
				}
				break
			}
			if zh {
				fmt.Fprintf(&b, "  - 唤醒方 %s → 目标线程：%d 次", pair.Waker, pair.Count)
			} else {
				fmt.Fprintf(&b, "  - Waker %s → target: %d time(s)", pair.Waker, pair.Count)
			}
			if pair.SplitAvailable {
				if zh {
					fmt.Fprintf(&b, "；此前目标线程离开睡眠 %d 次、D/IO 等待 %d 次、其他或未分类 %d 次",
						pair.SleepExitCount, pair.DExitCount, pair.OtherExitCount)
				} else {
					fmt.Fprintf(&b, "; target state left beforehand: sleep %d, D/IO wait %d, other or unclassified %d",
						pair.SleepExitCount, pair.DExitCount, pair.OtherExitCount)
				}
			}
			if pair.FirstTimestamp != "" || pair.LastTimestamp != "" {
				if zh {
					fmt.Fprintf(&b, "；首次 %s 秒，末次 %s 秒", pair.FirstTimestamp, pair.LastTimestamp)
				} else {
					fmt.Fprintf(&b, "; first at %s seconds, last at %s seconds", pair.FirstTimestamp, pair.LastTimestamp)
				}
			}
			b.WriteString(terminator)
		}
	}
	b.WriteString("\n")
	return b.String()
}

func answerDocTraceRankAuthorityTopSupplySeat(seats []types.TraceRankRosterSeat) (types.TraceRankRosterSeat, bool) {
	var best types.TraceRankRosterSeat
	found := false
	for _, seat := range seats {
		if strings.TrimSpace(seat.FixDirection) != "frequency_thermal" {
			continue
		}
		if !found || seat.Rank < best.Rank ||
			(seat.Rank == best.Rank && seat.EffectiveImpactMS > best.EffectiveImpactMS) {
			best, found = seat, true
		}
	}
	return best, found
}

func renderAnswerDocRuntimeSourceAuthority(ctx *types.AgentContext, ledger types.ObservationLedger) string {
	authority := types.BuildRuntimeSourceAnswerAuthoritySnapshotForAgentContext(ctx, ledger)
	if !authority.Active {
		return ""
	}
	var b strings.Builder
	b.WriteString("### Runtime Source Authority\n\n")
	b.WriteString("- This typed authority summarizes runtime/log/trace proof and current-source proof obligations for this answer. It is answer-writing handoff guidance only; do not treat it as a new reason to reopen exploration or invent citations.\n")
	fmt.Fprintf(&b, "- current_source_lane=`%s`; requirement_precision=`%s`; current_source_required=%t; current_source_satisfied=%t\n",
		authority.CurrentSourceLane,
		runtimeSourceRequirementPromptValue(authority.CurrentSourceRequirement),
		authority.CurrentSourceRequired,
		authority.CurrentSourceSatisfied,
	)
	fmt.Fprintf(&b, "- runtime_observations=%d; deterministic_runtime_queries=%d; current_source_records=%d; exact_current_source_support=%d\n",
		authority.RuntimeObservationCount,
		authority.DeterministicRuntimeQueryCount,
		authority.CurrentSourceRecordCount,
		authority.ExactCurrentSourceSupportCount,
	)
	fmt.Fprintf(&b, "- proof_state: combined_ready=%t; runtime_only_with_caveat=%t; hard_block=%t; caveat_only=%t\n",
		authority.CanCompleteWithCombinedProof,
		authority.CanUseRuntimeOnlyWithCaveat,
		authority.CanHardBlockCompletion,
		authority.CanDowngradeToCaveat,
	)
	if authority.RuntimeCitationPolicy != "" {
		fmt.Fprintf(&b, "- runtime_citation_policy=`%s`\n", authority.RuntimeCitationPolicy)
	}
	if len(authority.ReasonCodes) > 0 {
		parts := make([]string, 0, len(authority.ReasonCodes))
		for _, code := range authority.ReasonCodes {
			if strings.TrimSpace(string(code)) != "" {
				parts = append(parts, string(code))
			}
		}
		if len(parts) > 0 {
			fmt.Fprintf(&b, "- authority_reason_codes: `%s`\n", strings.Join(parts, "`, `"))
		}
	}
	switch {
	case authority.CanHardBlockCompletion:
		b.WriteString("- guidance: a precise current-source obligation is still missing; if the final answer proceeds, disclose that source-proof boundary instead of presenting runtime rows as source citations.\n")
	case authority.CanDowngradeToCaveat:
		b.WriteString("- guidance: the missing current-source obligation is soft. Preserve runtime observations as answer-grade support and disclose the source boundary as a caveat when relevant; do not broaden the answer slate solely to satisfy this soft lane.\n")
	case authority.CanCompleteWithCombinedProof && authority.CurrentSourceSatisfied:
		b.WriteString("- guidance: runtime and current-source proof are both present; preserve both origins and keep their citations/provenance separate.\n")
	case authority.RuntimeOnlySufficient || authority.CanUseRuntimeOnlyWithCaveat:
		b.WriteString("- guidance: runtime evidence is sufficient for the runtime artifact claim; keep source citations out unless current-source records are present.\n")
	}
	b.WriteString("\n")
	return b.String()
}

func runtimeSourceRequirementPromptValue(v types.RuntimeSourceRequirementPrecision) string {
	if strings.TrimSpace(string(v)) == "" {
		return "none"
	}
	return string(v)
}

func renderAnswerDocToolHandoffCarriers(ctx *types.AgentContext) string {
	if ctx == nil || ctx.Mutable == nil {
		return ""
	}
	ta := ctx.Mutable.TurnAArtifacts()
	if ta == nil || len(ta.HandoffCarriers) == 0 {
		return ""
	}
	carriers := answerDocToolHandoffCarriersForFinalizer(ctx, ta.HandoffCarriers)
	if len(carriers) == 0 {
		return ""
	}
	observationDetails := answerDocToolHandoffObservationDetails(ctx, carriers)
	if answerDocRuntimeSourceAuthorityUsesCompactToolHandoff(ctx) {
		return renderTypedToolHandoffCarriers("## Typed Repair And Evidence Handoff", carriers, toolHandoffRenderOptions{
			MaxCarriers:        4,
			MaxRefs:            6,
			ObservationDetails: observationDetails,
		})
	}
	return renderTypedToolHandoffCarriers("## Typed Repair And Evidence Handoff", carriers, toolHandoffRenderOptions{
		ObservationDetails: observationDetails,
	})
}

func answerDocToolHandoffObservationDetails(ctx *types.AgentContext, carriers []types.ToolHandoffCarrier) map[string]types.ObservationPromptRecord {
	wanted := make(map[string]struct{})
	for _, carrier := range carriers {
		for _, ref := range carrier.ObservationRefs {
			if id := strings.TrimSpace(ref.ID); id != "" {
				wanted[id] = struct{}{}
			}
		}
	}
	if len(wanted) == 0 {
		return nil
	}
	ledger := answerDocObservationLedger(ctx)
	var rm *types.RequestModel
	var contract *types.AnswerContract
	if ctx != nil && ctx.AnalysisIR != nil {
		rm = &ctx.AnalysisIR.RequestModel
		contract = &ctx.AnalysisIR.AnswerContract
	}
	out := make(map[string]types.ObservationPromptRecord)
	for _, record := range ledger.Records {
		id := strings.TrimSpace(record.ID)
		if _, ok := wanted[id]; !ok || !observationRecordHasTargetWaitOccurrencePrompt(record) {
			continue
		}
		opts := types.DefaultObservationPromptProjectionOptions(1)
		// R12 caps the roster at eight rows; meta + sum + eight rows closes
		// this family at ten notes. Preserve each already-bounded row whole.
		opts.NoteLimit = 10
		opts.PrincipalNoteLimit = 10
		opts.OriginSpecificSupportingNoteLimit = 10
		opts.OriginSpecificPrincipalNoteLimit = 10
		opts.NoteMaxLen = 512
		projected := types.ProjectObservationPromptRecords([]types.ObservationRecord{record}, rm, contract, opts)
		if len(projected) == 1 && len(targetWaitOccurrenceHandoffNotes(projected[0].Notes)) > 0 {
			out[id] = projected[0]
		}
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

func observationRecordHasTargetWaitOccurrencePrompt(record types.ObservationRecord) bool {
	prefix := types.TraceNoteKeyTargetWaitOccurrencePrompt + "="
	for _, note := range record.RichNotes {
		if strings.HasPrefix(strings.TrimSpace(note), prefix) {
			return true
		}
	}
	return false
}

func answerDocRuntimeSourceAuthorityUsesCompactToolHandoff(ctx *types.AgentContext) bool {
	return answerDocRuntimeSourceAuthorityUsesCompactObservationPrompt(ctx, types.ObservationLedger{})
}

func answerDocToolHandoffCarriersForFinalizer(ctx *types.AgentContext, carriers []types.ToolHandoffCarrier) []types.ToolHandoffCarrier {
	carriers = types.NormalizeToolHandoffCarriers(carriers)
	if len(carriers) == 0 {
		return carriers
	}
	// The accepted-evidence handoff is an authority surface, not a navigation
	// dump. Keep only evidence whose typed grounding state has actually reached
	// grounded or recovered. Empty/ungrounded rows remain in the lossless Turn A
	// artifacts and evidence ledger for diagnostics and downstream hard gates,
	// but exposing them beside accepted rows invites the finalizer to promote a
	// merely similar repo-map candidate into the answer. This projection reads
	// only the typed grounding enum; it never scans request or answer prose.
	projected := make([]types.ToolHandoffCarrier, 0, len(carriers))
	for _, carrier := range carriers {
		originalRefCount := len(carrier.AcceptedEvidence)
		refs := make([]types.AcceptedEvidenceRef, 0, originalRefCount)
		for _, ref := range carrier.AcceptedEvidence {
			if ref.GroundingStatus == types.GroundingGrounded ||
				ref.GroundingStatus == types.GroundingRecovered {
				refs = append(refs, ref)
			}
		}
		carrier.AcceptedEvidence = refs
		if originalRefCount > 0 && len(refs) == 0 &&
			len(carrier.ObservationRefs) == 0 && carrier.Repair == nil &&
			carrier.Refinement == nil && carrier.PlanRepairPack == nil &&
			carrier.SupportedJSON == nil {
			continue
		}
		projected = append(projected, carrier)
	}
	carriers = types.NormalizeToolHandoffCarriers(projected)
	if len(carriers) == 0 {
		return carriers
	}
	// Keep handoff observation refs on the same explicit-window projection as
	// the Observation Ledger prompt. The carrier remains intact for repair,
	// supported-JSON, and accepted-evidence duties; only refs whose producer-
	// owned selected_window crosses the user's typed explicit window leave the
	// Finalizer prompt. Full tool results and the audit ledger are unchanged.
	if ctx != nil && ctx.AnalysisIR != nil && ctx.AnalysisIR.RequestModel.RuntimeArtifactScopeProfile != nil {
		ledger := answerDocObservationLedger(ctx)
		projected, omitted := answerDocSelectedWindowObservationRecords(ctx, ledger.Records)
		if omitted > 0 {
			allowed := make(map[string]bool, len(projected))
			known := make(map[string]bool, len(ledger.Records))
			for _, record := range ledger.Records {
				known[strings.TrimSpace(record.ID)] = true
			}
			for _, record := range projected {
				allowed[strings.TrimSpace(record.ID)] = true
			}
			for i := range carriers {
				refs := make([]types.ToolObservationRef, 0, len(carriers[i].ObservationRefs))
				for _, ref := range carriers[i].ObservationRefs {
					id := strings.TrimSpace(ref.ID)
					if known[id] && !allowed[id] {
						continue
					}
					refs = append(refs, ref)
				}
				carriers[i].ObservationRefs = refs
			}
			carriers = types.NormalizeToolHandoffCarriers(carriers)
		}
	}
	if ctx != nil && ctx.AnalysisIR != nil && ctx.AnalysisIR.RequestModel.RuntimeQuestionProfile != nil &&
		ctx.AnalysisIR.RequestModel.RuntimeQuestionProfile.SuppressesRootCauseRankingPrompt() {
		projected := make([]types.ToolHandoffCarrier, 0, len(carriers))
		for _, carrier := range carriers {
			originalRefCount := len(carrier.ObservationRefs)
			refs := make([]types.ToolObservationRef, 0, len(carrier.ObservationRefs))
			for _, ref := range carrier.ObservationRefs {
				record := types.ObservationRecord{ID: ref.ID, ClaimKey: ref.ClaimKey}
				if !answerDocObservationRecordIsCausalRankingPromptRow(record) {
					refs = append(refs, ref)
				}
			}
			carrier.ObservationRefs = refs
			// A refinement-only carrier for a discarded broad causal view is
			// not actionable in finalization and only re-advertises that view.
			if originalRefCount > 0 && len(refs) == 0 && len(carrier.AcceptedEvidence) == 0 &&
				carrier.Repair == nil && carrier.SupportedJSON == nil {
				continue
			}
			projected = append(projected, carrier)
		}
		carriers = types.NormalizeToolHandoffCarriers(projected)
	}
	// A complete target-wait roster is rendered once by the dedicated
	// reader-facing authority. Drop only its duplicate observation refs from
	// the model prompt; typed carriers and the lossless ledger remain intact for
	// validation and diagnostics.
	if ctx != nil && ctx.AnalysisIR != nil {
		shadowed := answerDocReaderAuthorityShadowedObservationIDs(ctx, answerDocObservationLedger(ctx))
		if len(shadowed) > 0 {
			projected := make([]types.ToolHandoffCarrier, 0, len(carriers))
			for _, carrier := range carriers {
				originalRefCount := len(carrier.ObservationRefs)
				refs := make([]types.ToolObservationRef, 0, originalRefCount)
				for _, ref := range carrier.ObservationRefs {
					if shadowed[strings.TrimSpace(ref.ID)] {
						continue
					}
					refs = append(refs, ref)
				}
				carrier.ObservationRefs = refs
				if originalRefCount > 0 && len(refs) == 0 && len(carrier.AcceptedEvidence) == 0 &&
					carrier.Repair == nil && carrier.SupportedJSON == nil {
					continue
				}
				projected = append(projected, carrier)
			}
			carriers = types.NormalizeToolHandoffCarriers(projected)
		}
	}
	if len(carriers) == 0 || !answerDocSourceInventorySuppressesStaleDisplayDebt(ctx) {
		return carriers
	}
	out := make([]types.ToolHandoffCarrier, 0, len(carriers))
	for _, carrier := range carriers {
		carrier = types.StripSourceInventoryStaleDisplayDebtFromToolHandoffCarrier(carrier)
		if !carrier.Empty() {
			out = append(out, carrier)
		}
	}
	return types.NormalizeToolHandoffCarriers(out)
}

func renderAnswerDocSourceInventoryHandoff(ctx *types.AgentContext) string {
	observation := answerDocSourceInventoryObservation(ctx)
	if !observation.IsActive() {
		return ""
	}
	snapshot := answerDocSourceInventoryAuthoritySnapshot(ctx, observation)
	view := types.BuildSourceInventoryAnswerAuthorityView(snapshot)
	var b strings.Builder
	b.WriteString("## Repo Lens Candidate Universe Handoff\n\n")
	b.WriteString("- This section comes from `repo_map(view=\"source_inventory\")` / source-inventory observations. It verifies navigation facts such as scopes, files, candidate members, attributes, languages, support refs, and `count == len(members)`.\n")
	b.WriteString("- It is not final answer text. Use it to avoid losing the candidate universe or rereading the same scope. " + types.SourceInventoryMechanicalFactBoundary + " Preserve it as the answer slate only when accepted aggregate facts, evidence, or the model's own extraction already selected the same answer axis.\n")
	b.WriteString("- If accepted principal `aggregate_facts.member_set` rows below match this universe, their members/counts are the model-selected slate. If they do not match or are absent, treat this as advisory navigation and disclose ambiguity instead of auto-filling a table.\n")
	if view.Active {
		fmt.Fprintf(&b, "- authority: block_completion=%t caveat_only=%t needs_followup=%t mechanical_landing=%t\n",
			view.CanBlockCompletion, view.CanOnlyCaveat, view.NeedsFollowup, view.CanEnterMechanicalLanding)
		if len(view.ReasonCodes) > 0 {
			fmt.Fprintf(&b, "- authority_reason_codes: `%s`\n", strings.Join(view.ReasonCodes, "`, `"))
		}
	}
	if len(observation.Scopes) > 0 {
		fmt.Fprintf(&b, "- scopes: `%s`\n", strings.Join(observation.Scopes, "`, `"))
	}
	if len(observation.Provenance) > 0 {
		fmt.Fprintf(&b, "- provenance: `%s`\n", strings.Join(observation.Provenance, "`, `"))
	}
	if view.PrincipalTotal > 0 {
		renderAnswerDocSourceInventoryAuthorityView(&b, view)
		return b.String()
	}
	const maxRows = 24
	emitted := 0
	totalRows := 0
	for _, set := range observation.Sets {
		totalRows += len(set.Members)
		if len(set.Members) == 0 {
			continue
		}
		fmt.Fprintf(&b, "- role `%s` (%s): count=%d len(members)=%d complete=%t\n",
			set.Role, types.SourceInventoryAdvisoryRoleLabel(set.Role), set.Count, len(set.Members), set.Complete)
		for _, member := range set.Members {
			if emitted >= maxRows {
				continue
			}
			name := strings.TrimSpace(member.Name)
			if name == "" {
				continue
			}
			fmt.Fprintf(&b, "  - member=`%s`", name)
			if file := strings.TrimSpace(member.File); file != "" {
				if member.Line > 0 {
					fmt.Fprintf(&b, " @ `%s:%d`", file, member.Line)
				} else {
					fmt.Fprintf(&b, " @ `%s`", file)
				}
			}
			if lang := strings.TrimSpace(member.Language); lang != "" {
				fmt.Fprintf(&b, ", language=%s", lang)
			}
			if state := strings.TrimSpace(string(member.CoverageState)); state != "" {
				fmt.Fprintf(&b, ", coverage_state=%s", state)
			}
			if attrs := renderAnswerDocSourceInventoryRowAttributes(member.Attributes); attrs != "" {
				fmt.Fprintf(&b, ", attributes=%s", attrs)
			}
			b.WriteString("\n")
			emitted++
		}
	}
	if totalRows > emitted {
		fmt.Fprintf(&b, "- showing %d of %d member row(s); use the count invariants above, accepted aggregate facts, or a narrower `source_inventory` page rather than widening blindly.\n", emitted, totalRows)
	}
	b.WriteString("\n")
	return b.String()
}

func answerDocSourceInventoryAuthoritySnapshot(ctx *types.AgentContext, observation types.SourceInventoryObservation) types.SourceInventoryAuthoritySnapshot {
	if ctx == nil || ctx.AnalysisIR == nil {
		return types.SourceInventoryAuthoritySnapshot{PrincipalRowSet: types.BuildSourceInventoryPrincipalRowSet(types.SourceInventoryPrincipalRowSetInput{
			Observation:      observation,
			MaxPrincipalRows: 36,
			MaxSupportRows:   8,
			MaxAuditRows:     4,
		})}
	}
	var existing []types.AnswerAggregateFact
	var required []string
	if ctx.Mutable != nil {
		existing = ctx.Mutable.StableInvestigationAggregateFacts()
	}
	required = ctx.AnalysisIR.EvidencePlan.RequiredFiles
	busCtx := &types.BusContext{
		RepoRoot:   ctx.RepoRoot,
		Mutable:    ctx.Mutable,
		AnalysisIR: ctx.AnalysisIR,
		MultiGraph: ctx.MultiGraph,
	}
	snapshot := types.BuildSourceInventoryAuthoritySnapshot(types.SourceInventoryAuthoritySnapshotInput{
		Observation:               observation,
		RequestModel:              ctx.AnalysisIR.RequestModel,
		ExistingAggregateFacts:    existing,
		AcceptedExactUniverse:     tool.SourceInventoryAcceptedClosureCoversExactUniverse(busCtx, existing),
		AcceptedRequestedUniverse: tool.SourceInventoryAcceptedClosureCoversRequestedUniverse(busCtx, existing),
		RequiredFiles:             required,
		MaxPrincipalRows:          36,
		MaxSupportRows:            8,
		MaxAuditRows:              4,
	})
	return types.NormalizeSourceInventoryAuthoritySnapshot(snapshot)
}

func answerDocSourceInventorySuppressesStaleDisplayDebt(ctx *types.AgentContext) bool {
	observation := answerDocSourceInventoryObservation(ctx)
	if !observation.IsActive() {
		return false
	}
	return types.SourceInventoryAuthoritySuppressesStaleDisplayDebt(answerDocSourceInventoryAuthoritySnapshot(ctx, observation))
}

func renderAnswerDocSourceInventoryAuthorityView(b *strings.Builder, view types.SourceInventoryAnswerAuthorityView) {
	if b == nil || view.PrincipalTotal <= 0 {
		return
	}
	if len(view.PrincipalRoles) > 0 {
		roles := make([]string, 0, len(view.PrincipalRoles))
		for _, role := range view.PrincipalRoles {
			roles = append(roles, string(role))
		}
		fmt.Fprintf(b, "- principal_roles: `%s`\n", strings.Join(roles, "`, `"))
	}
	if view.PrincipalScope != "" {
		fmt.Fprintf(b, "- principal_scope: `%s`", view.PrincipalScope)
		if view.RepoWidePrincipal {
			b.WriteString(" (repo-wide typed inventory)")
		}
		b.WriteByte('\n')
	}
	if len(view.SourceClasses) > 0 {
		parts := make([]string, 0, len(view.SourceClasses))
		for _, class := range view.SourceClasses {
			parts = append(parts, fmt.Sprintf("%s:%d", class.Role, class.Count))
		}
		fmt.Fprintf(b, "- source_classes: %s\n", strings.Join(parts, ", "))
	}
	if view.RequestedUniverse.Active {
		renderAnswerDocSourceInventoryRequestedUniverse(b, view.RequestedUniverse)
	}
	fmt.Fprintf(b, "- row_lanes: principal=%d", view.PrincipalTotal)
	if view.PrincipalHiddenCount > 0 {
		fmt.Fprintf(b, " (+%d hidden)", view.PrincipalHiddenCount)
	}
	fmt.Fprintf(b, ", support=%d", view.SupportTotal)
	if view.SupportHiddenCount > 0 {
		fmt.Fprintf(b, " (+%d hidden)", view.SupportHiddenCount)
	}
	fmt.Fprintf(b, ", audit=%d", view.AuditTotal)
	if view.AuditHiddenCount > 0 {
		fmt.Fprintf(b, " (+%d hidden)", view.AuditHiddenCount)
	}
	b.WriteString("\n\n")
	b.WriteString("### Principal candidate rows\n\n")
	b.WriteString("These rows are selected from the full typed observation before prompt row limits, balanced by role/source-class/language family. Treat them as the candidate universe handoff, not as final prose.\n\n")
	renderAnswerDocSourceInventoryRows(b, view.PrincipalRows, false)
	if view.PrincipalHiddenCount > 0 {
		fmt.Fprintf(b, "- ... %d additional principal row(s) are preserved in the typed observation but omitted from this bounded prompt view.\n", view.PrincipalHiddenCount)
	}
	b.WriteString("\n")
	if view.SupportTotal > 0 {
		b.WriteString("### Support/navigation rows\n\n")
		b.WriteString("These rows are outside the principal scope or lack direct source location; use them for navigation or qualification only, not as replacement answer members.\n\n")
		renderAnswerDocSourceInventoryRows(b, view.SupportRows, true)
		if view.SupportHiddenCount > 0 {
			fmt.Fprintf(b, "- ... %d additional support row(s) omitted from this bounded prompt view.\n", view.SupportHiddenCount)
		}
		b.WriteString("\n")
	}
	if view.AuditTotal > 0 {
		b.WriteString("### Audit-only rows\n\n")
		b.WriteString("These rows are non-principal roles under the current typed source-inventory profile. Keep them out of the answer slate unless another typed carrier makes them principal.\n\n")
		renderAnswerDocSourceInventoryRows(b, view.AuditRows, true)
		if view.AuditHiddenCount > 0 {
			fmt.Fprintf(b, "- ... %d additional audit row(s) omitted from this bounded prompt view.\n", view.AuditHiddenCount)
		}
		b.WriteString("\n")
	}
}

func renderAnswerDocSourceInventoryRequestedUniverse(b *strings.Builder, universe types.SourceInventoryRequestedUniverseView) {
	if b == nil || !universe.Active {
		return
	}
	var parts []string
	if len(universe.Languages) > 0 {
		parts = append(parts, "languages=`"+strings.Join(universe.Languages, "`, `")+"`")
	}
	if len(universe.SourceClasses) > 0 {
		classes := make([]string, 0, len(universe.SourceClasses))
		for _, class := range universe.SourceClasses {
			classes = append(classes, string(class))
		}
		parts = append(parts, "source_classes=`"+strings.Join(classes, "`, `")+"`")
	}
	if len(universe.SurfaceFamilies) > 0 {
		parts = append(parts, "surface_families=`"+strings.Join(universe.SurfaceFamilies, "`, `")+"`")
	}
	if len(parts) > 0 {
		fmt.Fprintf(b, "- requested_universe: %s\n", strings.Join(parts, "; "))
	}
	if universe.InventoryOutOfUniverseRowsSuppressed > 0 {
		fmt.Fprintf(b, "- inventory_out_of_universe_rows_suppressed: %d", universe.InventoryOutOfUniverseRowsSuppressed)
		if len(universe.ReasonCodes) > 0 {
			fmt.Fprintf(b, " (`%s`)", strings.Join(universe.ReasonCodes, "`, `"))
		}
		b.WriteByte('\n')
	}
}

func renderAnswerDocSourceInventoryRows(b *strings.Builder, rows []types.SourceInventoryRow, includeReason bool) {
	for _, row := range rows {
		member := row.Member
		name := strings.TrimSpace(member.Name)
		if name == "" {
			name = strings.TrimSpace(member.Key)
		}
		if name == "" {
			continue
		}
		fmt.Fprintf(b, "- member=`%s`, role=%s", name, row.Role)
		if row.SourceClass != "" {
			fmt.Fprintf(b, ", source_class=%s", row.SourceClass)
		}
		if lang := strings.TrimSpace(row.Language); lang != "" {
			fmt.Fprintf(b, ", language=%s", lang)
		}
		if family := strings.TrimSpace(row.SurfaceFamily); family != "" {
			fmt.Fprintf(b, ", surface_family=`%s`", family)
		}
		if file := strings.TrimSpace(member.File); file != "" {
			if member.Line > 0 {
				fmt.Fprintf(b, ", location=`%s:%d`", file, member.Line)
			} else {
				fmt.Fprintf(b, ", location=`%s`", file)
			}
		}
		if state := strings.TrimSpace(string(member.CoverageState)); state != "" {
			fmt.Fprintf(b, ", coverage_state=%s", state)
		}
		if attrs := renderAnswerDocSourceInventoryRowAttributes(member.Attributes); attrs != "" {
			fmt.Fprintf(b, ", attributes=%s", attrs)
		}
		if includeReason && strings.TrimSpace(row.ReasonCode) != "" {
			fmt.Fprintf(b, ", lane=%s reason=%s", row.Lane, row.ReasonCode)
		}
		b.WriteByte('\n')
	}
}

func renderAnswerDocSourceInventoryRowAttributes(attrs []types.SourceInventoryObservationAttribute) string {
	const maxAttrs = 4
	if len(attrs) == 0 {
		return ""
	}
	parts := make([]string, 0, len(attrs))
	for _, attr := range attrs {
		name := strings.TrimSpace(attr.Name)
		if name == "" {
			name = strings.TrimSpace(attr.Key)
		}
		if name == "" {
			continue
		}
		role := strings.TrimSpace(string(attr.Role))
		if role == "" {
			role = "attribute"
		}
		item := role + ":" + name
		if loc := answerDocSourceInventoryAttributeLocation(attr); loc != "" {
			item += " @ " + loc
		}
		if attr.Ambiguity != "" {
			item += " ambiguity=" + strings.TrimSpace(attr.Ambiguity)
		}
		parts = append(parts, "`"+strings.ReplaceAll(item, "`", "'")+"`")
		if len(parts) >= maxAttrs {
			break
		}
	}
	if len(parts) == 0 {
		return ""
	}
	if hidden := len(attrs) - len(parts); hidden > 0 {
		parts = append(parts, fmt.Sprintf("+%d more", hidden))
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func answerDocSourceInventoryAttributeLocation(attr types.SourceInventoryObservationAttribute) string {
	if _, loc, ok := types.ParseAnswerSupportRefMemberLocation(attr.SupportRef); ok {
		file := strings.TrimSpace(strings.ReplaceAll(loc.File, `\`, `/`))
		if file != "" && loc.LineStart > 0 {
			return fmt.Sprintf("%s:%d", file, loc.LineStart)
		}
	}
	file := strings.TrimSpace(strings.ReplaceAll(attr.File, `\`, `/`))
	if file == "" || attr.Line <= 0 {
		return ""
	}
	return fmt.Sprintf("%s:%d", file, attr.Line)
}

func answerDocSourceInventoryObservation(ctx *types.AgentContext) types.SourceInventoryObservation {
	if ctx == nil || ctx.Mutable == nil {
		return types.SourceInventoryObservation{}
	}
	observation := ctx.Mutable.SourceInventoryObservation()
	if ta := ctx.Mutable.TurnAArtifacts(); ta != nil {
		observation = types.MergeSourceInventoryObservation(observation, ta.SourceInventoryObservation)
		if !observation.IsActive() && ta.SourceInventoryAdvisory.IsActive() {
			observation = types.SourceInventoryObservationFromAdvisory(ta.SourceInventoryAdvisory)
		}
	}
	return observation
}

func answerDocObservationLedger(ctx *types.AgentContext) types.ObservationLedger {
	if ctx == nil {
		return types.ObservationLedger{}
	}
	input := types.ObservationLedgerInputFromAgentContext(ctx, 64)
	input.AggregateFacts = answerDocStableAggregateFacts(ctx)
	input.RowSetWriter = answerDocObservationRowSetWriter(ctx)
	return types.CompileObservationLedger(input)
}

func answerDocObservationPromptRecords(ctx *types.AgentContext, records []types.ObservationRecord, limit int) []types.ObservationPromptRecord {
	var rm *types.RequestModel
	var contract *types.AnswerContract
	if ctx != nil && ctx.AnalysisIR != nil {
		rm = &ctx.AnalysisIR.RequestModel
		contract = &ctx.AnalysisIR.AnswerContract
	}
	records, _ = answerDocFinalizerObservationRecords(ctx, records)
	records, _ = answerDocSelectedWindowObservationRecords(ctx, records)
	ledger := types.ObservationLedger{Records: records}
	return types.ProjectObservationPromptRecords(records, rm, contract, answerDocObservationPromptProjectionOptions(ctx, ledger, limit))
}

// answerDocObservationRecordsWithoutReaderAuthorityDuplicates removes only
// prompt rows whose complete values are already republished by the dedicated
// target-wait reader authority. The lossless ObservationLedger, tool result,
// audit payload, causal projection, and answer-side consistency checker retain
// the original rows. Keeping one natural-language prompt surface prevents
// repeated trace queries from teaching the answer model a compatibility
// predicate or machine status value as customer vocabulary.
func answerDocObservationRecordsWithoutReaderAuthorityDuplicates(
	ctx *types.AgentContext,
	ledger types.ObservationLedger,
	records []types.ObservationPromptRecord,
) []types.ObservationPromptRecord {
	shadowed := answerDocReaderAuthorityShadowedObservationIDs(ctx, ledger)
	peerReaderAuthority := answerDocLogPeerRelationUnproven(ctx)
	if (len(shadowed) == 0 && !peerReaderAuthority) || len(records) == 0 {
		return records
	}
	out := make([]types.ObservationPromptRecord, 0, len(records))
	for _, record := range records {
		if shadowed[strings.TrimSpace(record.ID)] {
			continue
		}
		if peerReaderAuthority && (strings.HasPrefix(strings.TrimSpace(record.ID), "log:error:") || strings.TrimSpace(record.ID) == "log:cross_error_relation") {
			continue
		}
		out = append(out, record)
	}
	return out
}

func answerDocReaderAuthorityShadowedObservationIDs(ctx *types.AgentContext, ledger types.ObservationLedger) map[string]bool {
	if ctx == nil || ctx.AnalysisIR == nil || len(ledger.Records) == 0 {
		return nil
	}
	authorities := types.BuildTargetWaitOccurrenceAuthorities(ledger, &ctx.AnalysisIR.RequestModel)
	if len(authorities) == 0 {
		return nil
	}
	subjects := make(map[string]bool, len(authorities))
	for _, authority := range authorities {
		if subject := strings.ToLower(strings.TrimSpace(authority.Subject)); subject != "" {
			subjects[subject] = true
		}
	}
	shadowed := make(map[string]bool)
	for _, record := range ledger.Records {
		predicate := strings.ToLower(strings.TrimSpace(record.Predicate))
		if predicate != "target_window_wait_occurrences" && predicate != "target_window_wait_occurrence" {
			continue
		}
		if subjects[strings.ToLower(strings.TrimSpace(record.Subject))] {
			if id := strings.TrimSpace(record.ID); id != "" {
				shadowed[id] = true
			}
		}
	}
	return shadowed
}

// answerDocSelectedWindowObservationRecords keeps deterministic trace-query
// rows whose own typed selected_window is fully contained by the user's
// explicit requested window on the Finalizer prompt surface. Wider, later, or
// otherwise crossing query windows remain losslessly available in the full
// observation ledger, causal projection, report appendix, and audit output;
// they are removed only from the principal answer-writing pool so a broad
// drilldown cannot masquerade as selected-window evidence. Records without a
// typed selected_window fail open, as do non-runtime/non-deterministic rows.
// No request text, model narrative, or final prose is inspected.
func answerDocSelectedWindowObservationRecords(ctx *types.AgentContext, records []types.ObservationRecord) ([]types.ObservationRecord, int) {
	if ctx == nil || (ctx.AgentName != types.AgentFinalizer && ctx.Stage != types.StageFinalize) ||
		ctx.AnalysisIR == nil || ctx.AnalysisIR.RequestModel.RuntimeArtifactScopeProfile == nil || len(records) == 0 {
		return records, 0
	}
	requestedStart, requestedEnd, ok := ctx.AnalysisIR.RequestModel.RuntimeArtifactScopeProfile.ExplicitTimeWindow()
	if !ok {
		return records, 0
	}
	out := make([]types.ObservationRecord, 0, len(records))
	omitted := 0
	for _, record := range records {
		if record.Origin != types.AnswerEvidenceOriginRuntimeArtifact ||
			!types.RuntimeObservationProducerIsDeterministicQuery(record.Producer) {
			out = append(out, record)
			continue
		}
		start, end, present := types.TraceCausalProjectionSelectedWindowNote(record.RichNotes)
		if !present {
			out = append(out, record)
			continue
		}
		if !types.TraceCausalProjectionPrincipalValueWindowContains(
			requestedStart, requestedEnd, start, end,
		) {
			omitted++
			continue
		}
		out = append(out, record)
	}
	if omitted == 0 {
		return records, 0
	}
	return out, omitted
}

// answerDocFinalizerObservationRecords removes model-extracted
// PerfObservation and PerfStall candidate rows whose physical capture is also
// covered by a deterministic runtime query. The full ledger remains lossless
// for audit. Selection is structural: producer-owned authority, compiler-owned
// row ID, and typed capture identity; neither user/model prose nor observation
// summaries participate. Validator-owned stall rows remain available.
func answerDocFinalizerObservationRecords(ctx *types.AgentContext, records []types.ObservationRecord) ([]types.ObservationRecord, int) {
	if ctx == nil || (ctx.AgentName != types.AgentFinalizer && ctx.Stage != types.StageFinalize) || len(records) == 0 {
		return records, 0
	}
	records = answerDocScopeProjectedObservationRecords(ctx, records)
	perf := answerDocObservationLedgerPerfBundle(ctx)
	if perf == nil || (len(perf.Observations) == 0 && len(perf.Stalls) == 0) {
		return records, 0
	}
	preTriageIDs := make(map[string]bool)
	for i, observation := range perf.Observations {
		if observation.IsNavigationOnly() {
			preTriageIDs[fmt.Sprintf("perf:observation:%d", i)] = true
		}
	}
	for i, stall := range perf.Stalls {
		if stall.IsNavigationOnly() {
			preTriageIDs[fmt.Sprintf("perf:stall:%d", i)] = true
		}
	}
	if len(preTriageIDs) == 0 {
		return records, 0
	}
	deterministic := make([]types.ObservationRecord, 0)
	for _, record := range records {
		if record.Origin == types.AnswerEvidenceOriginRuntimeArtifact &&
			types.RuntimeObservationProducerIsDeterministicQuery(record.Producer) {
			deterministic = append(deterministic, record)
		}
	}
	if len(deterministic) == 0 {
		return records, 0
	}
	out := make([]types.ObservationRecord, 0, len(records))
	omitted := 0
	allowAttachedTraceIDJoin := answerDocHasSingleAttachedTraceIdentity(ctx)
	for _, record := range records {
		if preTriageIDs[strings.TrimSpace(record.ID)] &&
			answerDocRecordHasSameCaptureQuery(record, deterministic, allowAttachedTraceIDJoin) {
			omitted++
			continue
		}
		out = append(out, record)
	}
	if omitted == 0 {
		return records, 0
	}
	return out, omitted
}

// answerDocScopeProjectedObservationRecords removes prompt-only rows that the
// analyzer's typed finite scope does not authorize. The full ObservationLedger
// remains unchanged for audit, deterministic projection, and causal-diagnosis
// runs. A bounded named-target question keeps target-owned rows, exact evidence
// boundaries, and explicitly requested global fact families; unrelated runtime
// subjects cannot crowd or contaminate the final synthesis. This projection
// consumes no request or model/final prose.
func answerDocScopeProjectedObservationRecords(ctx *types.AgentContext, records []types.ObservationRecord) []types.ObservationRecord {
	if ctx == nil || ctx.AnalysisIR == nil || ctx.AnalysisIR.RequestModel.RuntimeQuestionProfile == nil {
		return records
	}
	rm := &ctx.AnalysisIR.RequestModel
	profile := rm.RuntimeQuestionProfile
	if !profile.SuppressesRootCauseRankingPrompt() {
		return records
	}
	projectNamedTarget := profile.CarriesBoundedFactFamilies() && answerDocHasUserRuntimeTarget(rm)
	out := make([]types.ObservationRecord, 0, len(records))
	for _, record := range records {
		if answerDocObservationRecordIsCausalRankingPromptRow(record) {
			continue
		}
		if projectNamedTarget && !answerDocBoundedRuntimeObservationPromptRecordAllowed(record, rm, profile) {
			continue
		}
		out = append(out, record)
	}
	return out
}

func answerDocHasUserRuntimeTarget(rm *types.RequestModel) bool {
	if rm == nil {
		return false
	}
	for _, target := range rm.RuntimeTargets {
		if types.RuntimeTargetIsExplorationCursorSource(target.Source) {
			continue
		}
		if (target.PID > 0 && target.PID <= types.RuntimeTargetMaxPID) || strings.TrimSpace(target.Thread) != "" {
			return true
		}
	}
	return false
}

// answerDocBoundedRuntimeObservationPromptRecordAllowed is deliberately a
// small typed projector, not a truth filter. Non-runtime rows stay available;
// evidence-boundary rows remain visible; causal diagnosis never calls it.
func answerDocBoundedRuntimeObservationPromptRecordAllowed(
	record types.ObservationRecord,
	rm *types.RequestModel,
	profile *types.RuntimeQuestionProfile,
) bool {
	if record.Origin != types.AnswerEvidenceOriginRuntimeArtifact ||
		!types.RuntimeObservationProducerIsDeterministicQuery(record.Producer) {
		return true
	}
	predicate := strings.ToLower(strings.TrimSpace(record.Predicate))
	if types.TraceObservationIsEvidenceBoundary(record) || answerDocBoundedRuntimeTargetDiagnosticPredicate(predicate) {
		return true
	}
	if types.ObservationRecordMatchesUserRuntimeTarget(record, rm) {
		// Target ownership alone does not authorize an IO-latency card for an
		// unrelated finite state/relation lookup. The dedicated typed family is
		// the only narrow-lane authority; causal diagnosis bypasses this
		// projector entirely.
		if answerDocBoundedRuntimeIOLatencyPredicate(predicate) {
			return profile.RequestsFactFamily(types.RuntimeQuestionFactIOLatency)
		}
		// A count/duration request does not authorize a kernel caller census.
		// The profile's existing two-axis contract owns this exceptional row.
		return predicate != "blocked_reason_census" || profile.RequestsBlockedReasonCensus()
	}
	return answerDocBoundedRuntimeGlobalFactPredicateAllowed(predicate, profile)
}

func answerDocBoundedRuntimeIOLatencyPredicate(predicate string) bool {
	switch predicate {
	case "io_latency", "io_latency_coverage", "storage_latency_by_layer", "block_io_by_inode":
		return true
	default:
		return false
	}
}

func answerDocBoundedRuntimeTargetDiagnosticPredicate(predicate string) bool {
	switch predicate {
	case "frame_target_resolution", "thread_incarnation_suppression", "thread_selector_exact_name_mismatch", "trace_gap", "missing_wakeup":
		return true
	default:
		return false
	}
}

func answerDocBoundedRuntimeGlobalFactPredicateAllowed(predicate string, profile *types.RuntimeQuestionProfile) bool {
	if profile.RequestsFactFamily(types.RuntimeQuestionFactOtherObservedValue) {
		return true
	}
	if profile.RequestsFactFamily(types.RuntimeQuestionFactFrequencyResidency) {
		switch predicate {
		case "cpu_frequency_limit", "frequency_tier_census":
			return true
		}
	}
	if profile.RequestsFactFamily(types.RuntimeQuestionFactIOLatency) && answerDocBoundedRuntimeIOLatencyPredicate(predicate) {
		return true
	}
	if profile.RequestsFactFamily(types.RuntimeQuestionFactResourcePressure) {
		switch predicate {
		case "background_pressure", "compute_supply_balance", "io_pressure", "runnable_occupancy":
			return true
		}
	}
	return false
}

func answerDocObservationRecordIsCausalRankingPromptRow(record types.ObservationRecord) bool {
	id := strings.ToLower(strings.TrimSpace(record.ID))
	if strings.Contains(id, "#root_cause_rank:") ||
		strings.Contains(id, "#trace_query:root_cause_rank:") ||
		strings.Contains(id, "#root_evidence:") {
		return true
	}
	claim := strings.ToLower(strings.TrimSpace(record.ClaimKey))
	return strings.HasPrefix(claim, "root_cause_")
}

func answerDocObservationLedgerPerfBundle(ctx *types.AgentContext) *types.PerfBundle {
	if ctx == nil {
		return nil
	}
	if ctx.AnalysisIR != nil && ctx.AnalysisIR.RequestModel.PerfTrace != nil {
		return ctx.AnalysisIR.RequestModel.PerfTrace
	}
	if ctx.Mutable != nil {
		return ctx.Mutable.PerfTrace()
	}
	return nil
}

func answerDocRecordHasSameCaptureQuery(
	record types.ObservationRecord,
	deterministic []types.ObservationRecord,
	allowAttachedTraceIDJoin bool,
) bool {
	wantPath := strings.TrimSpace(types.RuntimeArtifactCaptureIdentityPath(record.SourceRef))
	wantID := strings.TrimSpace(record.SourceRef.ArtifactID)
	for _, query := range deterministic {
		queryPath := strings.TrimSpace(types.RuntimeArtifactCaptureIdentityPath(query.SourceRef))
		if wantPath != "" && queryPath != "" && wantPath == queryPath {
			return true
		}
		queryID := strings.TrimSpace(query.SourceRef.ArtifactID)
		if allowAttachedTraceIDJoin &&
			strings.EqualFold(wantID, "attached_trace") &&
			strings.EqualFold(queryID, "attached_trace") {
			return true
		}
		if wantPath == "" && queryPath == "" && answerDocExplicitRuntimeArtifactID(wantID) && wantID == queryID {
			return true
		}
	}
	return false
}

// answerDocHasSingleAttachedTraceIdentity authorizes the reserved
// artifact_id=attached_trace join only when run-entry typed state proves there
// is one attached trace. Inline attachments have no addressable source path,
// while trace_query legitimately reads their reserved materialized blob; the
// shared typed ID is therefore the only stable physical-capture identity.
// Multiple attached traces fail closed so the generic ID cannot collapse two
// captures. Raw attachment bytes and user/model prose are never inspected.
func answerDocHasSingleAttachedTraceIdentity(ctx *types.AgentContext) bool {
	if ctx == nil {
		return false
	}
	profile := types.NormalizeRuntimeArtifactPreflightProfile(ctx.RuntimeArtifactPreflight)
	if len(profile.Artifacts) > 0 {
		count := 0
		for _, artifact := range profile.Artifacts {
			if strings.EqualFold(strings.TrimSpace(artifact.Carrier), "attachment") &&
				artifact.RuntimeArtifactKind() == "trace" {
				count++
			}
		}
		return count == 1
	}
	return strings.TrimSpace(ctx.AttachedHitrace) != "" ||
		strings.TrimSpace(ctx.AttachedHitraceSource) != ""
}

func answerDocExplicitRuntimeArtifactID(id string) bool {
	switch strings.ToLower(strings.TrimSpace(id)) {
	case "", "attached_trace", "trace_query", "runtime_artifact":
		return false
	default:
		return true
	}
}

func answerDocObservationPromptProjectionOptions(ctx *types.AgentContext, ledger types.ObservationLedger, limit int) types.ObservationPromptProjectionOptions {
	if limit <= 0 {
		limit = answerDocObservationLedgerPromptLimit
	}
	opts := types.DefaultObservationPromptProjectionOptions(limit)
	if !answerDocRuntimeSourceAuthorityUsesCompactObservationPrompt(ctx, ledger) {
		return opts
	}
	if opts.Limit > answerDocMixedRuntimeSourceObservationLedgerPromptLimit {
		opts.Limit = answerDocMixedRuntimeSourceObservationLedgerPromptLimit
	}
	opts.SourceMaxLen = 72
	opts.ValueMaxLen = 96
	opts.SummaryMaxLen = 128
	opts.NoteMaxLen = 120
	opts.ExcerptMaxLen = 96
	opts.PrincipalExcerptMaxLen = 160
	opts.NoteLimit = 1
	opts.PrincipalNoteLimit = 2
	opts.StrongCurrentSourceNoteLimit = 2
	opts.OriginSpecificSupportingNoteLimit = 3
	opts.OriginSpecificPrincipalNoteLimit = 3
	return opts
}

func answerDocRuntimeSourceAuthorityUsesCompactObservationPrompt(ctx *types.AgentContext, ledger types.ObservationLedger) bool {
	authority := types.BuildRuntimeSourceAnswerAuthoritySnapshotForAgentContext(ctx, ledger)
	if !authority.Active {
		return false
	}
	runtimeCarrier := authority.HasRuntimeCarrier()
	if !runtimeCarrier {
		return false
	}
	if !answerDocRuntimeSourceRequestCarrierActive(ctx, authority) {
		return false
	}
	return authority.HasRuntimeSourceHandoffSurface()
}

func answerDocRuntimeSourceRequestCarrierActive(ctx *types.AgentContext, authority types.RuntimeSourceAnswerAuthoritySnapshot) bool {
	return types.RuntimeSourceAuthorityRequestCarrierActiveForAgentContext(ctx, authority)
}

func answerDocObservationRowSetWriter(ctx *types.AgentContext) types.ObservationRowSetWriter {
	if ctx == nil || strings.TrimSpace(ctx.WorkDir) == "" {
		return nil
	}
	return func(name, content string) string {
		return tool.StoreBlobArtifact(ctx.WorkDir, "answer_observation_row_set", name, content)
	}
}

func renderAnswerDocObservationNotes(notes []string, limit int) string {
	if limit <= 0 || len(notes) == 0 {
		return ""
	}
	parts := make([]string, 0, limit)
	seen := make(map[string]struct{}, limit)
	for _, note := range notes {
		note = truncateAnswerDocPromptText(note, 160)
		if note == "" {
			continue
		}
		if _, ok := seen[note]; ok {
			continue
		}
		seen[note] = struct{}{}
		parts = append(parts, fmt.Sprintf("%q", note))
		if len(parts) >= limit {
			break
		}
	}
	if len(parts) == 0 {
		return ""
	}
	if len(notes) > len(parts) {
		parts = append(parts, fmt.Sprintf("... +%d", len(notes)-len(parts)))
	}
	return strings.Join(parts, ", ")
}

func renderAnswerIntentOrigins(origins []types.AnswerEvidenceOrigin) string {
	if len(origins) == 0 {
		return "(none)"
	}
	parts := make([]string, 0, len(origins))
	for _, origin := range origins {
		if origin == types.AnswerEvidenceOriginUnknown {
			continue
		}
		parts = append(parts, "`"+string(origin)+"`")
	}
	if len(parts) == 0 {
		return "(none)"
	}
	return strings.Join(parts, ", ")
}

func renderAnswerIntentOutputs(outputs []types.AnswerRequestedOutput) string {
	if len(outputs) == 0 {
		return "(none)"
	}
	parts := make([]string, 0, len(outputs))
	for _, output := range outputs {
		if output == types.AnswerRequestedOutputUnknown {
			continue
		}
		parts = append(parts, "`"+string(output)+"`")
	}
	if len(parts) == 0 {
		return "(none)"
	}
	return strings.Join(parts, ", ")
}

func renderAnswerDocRequestedAnswerDimensions(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	view := types.BuildAnswerSemanticViewForAgentContext(ctx)
	var dimensions []types.RequestedAnswerDimension
	if view != nil {
		dimensions = view.Presentation.RequestedDimensions
	}
	runtimeWorkRelationRequested := answerDocTypedRuntimeWorkRelationRequested(ctx)
	if len(dimensions) == 0 && !runtimeWorkRelationRequested {
		return ""
	}
	lang := extractAnswerDocLang(ctx)
	callChainMemberRoster := view != nil && view.Family == types.QFCallChain && answerDocHasRequiredDimensionRole(dimensions, types.RequestedAnswerDimensionMemberSet)
	sourceInventoryMemberRoster := answerDocRequestedMemberSetUsesExactSourceInventoryRows(ctx)
	var b strings.Builder
	if lang == "zh" {
		b.WriteString("## 用户要求的答案维度\n\n")
		b.WriteString("- 当前问题显式要求最终答案保留下面这些可见维度。请把它们自然地呈现为小标题、表格列、列表标签或紧凑段落标签。\n")
		b.WriteString("- 下列冒号后的文字就是面向用户的标签；不要在可见答案中追加系统内部角色或枚举名。\n")
		b.WriteString("- 如果答案按多个主体逐项展开（例如逐提交、逐日志事件、逐 trace span、逐组件、逐文件），每个主体下面都应尽量显式保留这些维度标签；某一维没有证据时，在该主体下说明边界，不要补编。\n")
		b.WriteString("- 这些维度是展示契约，不是新的证据来源；不要为没有证据支撑的维度编造内容，证据不足时在边界说明中说清楚。\n")
		b.WriteString("- 每一行都是独立的可见输出面；即使共用证据，图也不能吞掉用户另行要求的清单、表格或解释。按“第 N 维”的顺序安排这些输出面；如果图在清单之前，先给图，再在图后给清单。\n")
		if callChainMemberRoster {
			b.WriteString("- 本轮的成员清单与调用链端点边是两个独立的 typed 责任。普通关键函数/成员清单块只设置 `facet_ids:[\"member_set\"]`，不要同时设置 `principal_path_edge`、directed `claim_uses` 或 `edge_anchors`；精确端点边另用独立块承载。只有清单的每一行本身就是一条精确端点边时才能合并。请在第一稿就分块，不要等校验修补。\n")
		}
		b.WriteString("- 保留模型已经写好的内容；不要为了套表格而删除、替换或压扁更丰富的说明。\n\n")
	} else {
		b.WriteString("## User-Requested Answer Dimensions\n\n")
		b.WriteString("- The current request explicitly asks the final answer to preserve the visible dimensions below. Render them naturally as headings, table columns, list labels, or compact paragraph labels.\n")
		b.WriteString("- The text after each colon is the user-facing label. Do not append internal system roles or enum names to the visible answer.\n")
		b.WriteString("- When the answer is organized by multiple subjects (for example per commit, log event, trace span, component, or file), preserve these dimension labels under each subject where possible; if a dimension lacks evidence, state that boundary under that subject instead of inventing content.\n")
		b.WriteString("- These dimensions are presentation guidance, not new evidence origins. Do not invent unsupported content; disclose missing evidence in a boundary note or caveat.\n")
		b.WriteString("- Every row is an independent visible output surface. Even when surfaces share evidence, a diagram must not absorb a separately requested list, table, or explanation. Follow Dimension N as visible output order; when the diagram precedes a roster, render the roster after the diagram.\n")
		if callChainMemberRoster {
			b.WriteString("- The requested member roster and the call-chain endpoint edges are two independent typed responsibilities. An ordinary key-function/member roster block uses only `facet_ids:[\"member_set\"]`; do not also attach `principal_path_edge`, directed `claim_uses`, or `edge_anchors`. Put the exact endpoint edges in a separate block. Merge them only when every roster row is itself one exact endpoint edge. Separate these blocks in the first draft instead of relying on repair.\n")
		}
		b.WriteString("- Preserve model-authored content; do not delete, replace, or flatten richer explanation just to fit a table.\n\n")
	}
	hasRuntimeWorkRelationDimension := false
	for _, dim := range dimensions {
		if dim.Required && dim.Role == types.RequestedAnswerDimensionRuntimeWorkRelation {
			hasRuntimeWorkRelationDimension = true
		}
		label := strings.TrimSpace(dim.Label)
		if label == "" {
			continue
		}
		if lang == "zh" {
			fmt.Fprintf(&b, "- 第 %d 维：%s", dim.Index, label)
		} else {
			fmt.Fprintf(&b, "- Dimension %d: %s", dim.Index, label)
		}
		if dim.SourceQuote != "" && dim.SourceQuote != label {
			fmt.Fprintf(&b, " — source quote: %q", dim.SourceQuote)
		}
		b.WriteString("\n")
		if dim.Required && dim.Role == types.RequestedAnswerDimensionMemberSet {
			if lang == "zh" {
				if sourceInventoryMemberRoster {
					b.WriteString("  - 当前清单由 `Principal Enumeration Rows` 的精确结构承担：每个模型成文主块保留 `facet_ids:[\"enumeration_item\"]`，每个可见结构化行保留精确 `source_inventory_row_id`；仅当一个块刻意只承载单一家族时才保留对应 `source_inventory_family`，混合/全局块应省略。精确行身份已经承担成员集，不要再添加重复的 `member_set` 标记。逐行字段可直接放在列表 `items[].label/text`，也可使用 `columns[]` + 可见 `items[].cells[]`；不要为了字段展示复制第二份清单，也不要使用 Markdown 表加隐藏 sidecar。\n")
				} else {
					b.WriteString("  - 在真正承载这组成员的可见列表/表格块上设置隐藏元数据 `facet_ids:[\"member_set\"]`；不要把 `member_set` 写进可见标题或正文，也不要把别的关系/边界清单标成这组成员。\n")
				}
				if answerDocumentRelationMemberSetRequestsVisibleLocations(ctx) {
					b.WriteString("  - 当前 typed 证据为每个成员提供了精确源码位置；在同一个成员块中，把各自路径或 file:line 放进该成员自己的可见行/单元格。引用只负责证明，不能代替用户要求看到的文件位置。\n")
				}
			} else {
				if sourceInventoryMemberRoster {
					b.WriteString("  - This roster is structurally owned by the exact `Principal Enumeration Rows`: keep `facet_ids:[\"enumeration_item\"]` on each model-authored principal block and the exact `source_inventory_row_id` on every visible structured row; keep `source_inventory_family` only when one block intentionally carries exactly one family, and omit it for a mixed/global block. Exact row identity already owns the member set; do not add a duplicate `member_set` marker. Row-local fields may stay in list `items[].label/text`, or use `columns[]` plus visible `items[].cells[]`; do not duplicate the roster merely to display fields, and do not use a Markdown table with hidden sidecars.\n")
				} else {
					b.WriteString("  - On the visible list/table block that actually carries this roster, set hidden metadata `facet_ids:[\"member_set\"]`. Do not print `member_set` in the visible title/body, and do not tag a different relation/boundary list as this roster.\n")
				}
				if answerDocumentRelationMemberSetRequestsVisibleLocations(ctx) {
					b.WriteString("  - Exact typed source locations are available for every member. In the same roster block, put each path or file:line in that member's own visible row/cell. A citation proves the row but does not replace the requested visible location.\n")
				}
			}
		}
		if dim.Required && dim.Role == types.RequestedAnswerDimensionRelationPath {
			if answerDocRequestedRelationPathUsesRuntimeObservation(ctx) {
				if lang == "zh" {
					b.WriteString("  - 在模型成文、可见的主路径块上设置隐藏 ownership 标记 `facet_ids:[\"relation_path\",\"observed_artifact_fact\"]`，并用 `claim_uses:[{\"claim_form\":\"external_observation\",\"facet_id\":\"observed_artifact_fact\"}]` 保留运行时观测权威；展示已有 typed 唤醒/依赖方向，不要补 `principal_path_edge` 或把运行时关系伪写成源码 `call` 锚。\n")
				} else {
					b.WriteString("  - On the model-authored visible principal runtime-path block, set the hidden ownership marker `facet_ids:[\"relation_path\",\"observed_artifact_fact\"]` and preserve runtime-observation authority with `claim_uses:[{\"claim_form\":\"external_observation\",\"facet_id\":\"observed_artifact_fact\"}]`. Show only the existing typed wakeup/dependency direction; do not add `principal_path_edge` or masquerade a runtime relation as a source-code `call` anchor.\n")
				}
			} else if lang == "zh" {
				b.WriteString("  - 让承载这条源码关系路径的模型成文主块保留可见有向步骤，并设置 `surface_role:\"principal\"` 与 `facet_ids:[\"principal_path_edge\"]`；每条边仍需现有 typed claim/anchor 证据，不能从成员名推造关系。\n")
			} else {
				b.WriteString("  - Keep visible directed steps in the model-authored principal source-relation block and set `surface_role:\"principal\"` with `facet_ids:[\"principal_path_edge\"]`. Every edge still needs existing typed claim/anchor evidence; never invent a relation from member names.\n")
			}
		}
		if dim.Required && dim.Role == types.RequestedAnswerDimensionRuntimeWorkRelation {
			if lang == "zh" {
				b.WriteString("  - 在模型成文、可见的主结论块上设置隐藏 ownership 标记 `facet_ids:[\"runtime_work_relation\",\"observed_artifact_fact\"]`，并用 `claim_uses:[{\"claim_form\":\"external_observation\",\"facet_id\":\"observed_artifact_fact\"}]` 保留运行时证据权威。回答必须由模型命名 typed 工作/span、报告其测得时长，并说明它与目标之间已证的关系凭证和未证边界；例如只有 host→target 唤醒锚时，不得把它扩写成“该工作完成导致唤醒”。系统不会替模型选择有关、无关或证据不足的结论。\n")
			} else {
				b.WriteString("  - On the model-authored visible principal conclusion block, set the hidden ownership marker `facet_ids:[\"runtime_work_relation\",\"observed_artifact_fact\"]` and preserve runtime-evidence authority with `claim_uses:[{\"claim_form\":\"external_observation\",\"facet_id\":\"observed_artifact_fact\"}]`. The model must name the typed work/span, report its measured duration, and explain the proved relation credential and unproved boundary to the target; for example, a host-to-target wake anchor alone must not be expanded into a claim that completion of the work caused the wakeup. The system does not choose a related, unrelated, or insufficient-evidence conclusion for the model.\n")
			}
		}
		if dim.Required && dim.Role == types.RequestedAnswerDimensionDiagram {
			if lang == "zh" {
				b.WriteString("  - 在这个维度的位置呈现请求的图；图只承载有证据的关系，不替代相邻维度要求的清单、表格或文字解释。\n")
			} else {
				b.WriteString("  - Render the requested visual at this dimension's position. The diagram carries only grounded relations and does not replace a sibling roster, table, or prose explanation.\n")
			}
		}
		if dim.Required && dim.Role == types.RequestedAnswerDimensionSourceLocation {
			if lang == "zh" {
				b.WriteString("  - 对逐成员源码答案，把每个成员已验证的源码路径或 file:line 放在该成员自己的可见行/单元格中；引用只负责证明，不能代替用户要求看到的文件位置。\n")
			} else {
				b.WriteString("  - For per-member source answers, put each member's verified source path or file:line in that member's own visible row/cell. A citation proves the row but does not replace the requested visible location.\n")
			}
		}
		if dim.Required && dim.Role == types.RequestedAnswerDimensionSourceAttribute {
			if lang == "zh" {
				b.WriteString("  - 对逐成员源码答案，把每个成员已验证的 package/module/namespace 属性放在该成员自己的可见行/单元格中；不要用文件路径代替语言作用域。\n")
			} else {
				b.WriteString("  - For per-member source answers, put each verified package/module/namespace attribute in that member's own visible row/cell; a file path does not substitute for the language scope.\n")
			}
		}
	}
	if runtimeWorkRelationRequested && !hasRuntimeWorkRelationDimension {
		if lang == "zh" {
			b.WriteString("- 本轮 typed 运行时问题另行声明了一个运行时工作/span/operation 与目标关系子问；它是语义回答义务，不要求复制为另一条展示维度。请在模型成文、可见的主结论块上设置隐藏 ownership 标记 `facet_ids:[\"runtime_work_relation\",\"observed_artifact_fact\"]` 与 `claim_uses:[{\"claim_form\":\"external_observation\",\"facet_id\":\"observed_artifact_fact\"}]`，由模型命名 typed 工作、报告测得时长，并说明已证关系凭证和未证边界。不要让系统替模型选择有关、无关或证据不足的结论。\n")
		} else {
			b.WriteString("- The typed runtime profile independently declares a runtime work/span/operation-to-target semantic subquestion; this is an answer obligation and need not be duplicated as another presentation-dimension row. In a model-authored visible principal conclusion block, set the hidden ownership marker `facet_ids:[\"runtime_work_relation\",\"observed_artifact_fact\"]` with `claim_uses:[{\"claim_form\":\"external_observation\",\"facet_id\":\"observed_artifact_fact\"}]`. The model must name the typed work, report measured duration, and explain the proved relation credential and unproved boundary. Do not let the system choose a related, unrelated, or insufficient-evidence conclusion.\n")
		}
	}
	b.WriteString("\n")
	return b.String()
}

// answerDocTypedRuntimeWorkRelationRequested reads only analyzer-emitted typed
// request carriers.  The dedicated RuntimeQuestionProfile flag is the
// canonical semantic obligation; the legacy requested-dimension role remains
// a backward-compatible presentation carrier.  No request, reasoning, answer,
// or Mermaid text participates in this decision.
func answerDocTypedRuntimeWorkRelationRequested(ctx *types.AgentContext) bool {
	if ctx == nil || ctx.AnalysisIR == nil {
		return false
	}
	rm := &ctx.AnalysisIR.RequestModel
	if rm.RuntimeQuestionProfile != nil && rm.RuntimeQuestionProfile.RequestsRuntimeWorkRelation() {
		return true
	}
	if rm.RequestedAnswerDimensions == nil || !rm.RequestedAnswerDimensions.Active() {
		return false
	}
	return answerDocHasRequiredDimensionRole(
		rm.RequestedAnswerDimensions.Dimensions,
		types.RequestedAnswerDimensionRuntimeWorkRelation,
	)
}

// answerDocRequestedMemberSetUsesExactSourceInventoryRows selects the one
// typed roster lane whose family plus exact row ids already carries membership
// ownership. It reads only the schema-validated source-inventory profile; raw
// request text, dimension labels, answer prose, and model reasoning are absent.
func answerDocRequestedMemberSetUsesExactSourceInventoryRows(ctx *types.AgentContext) bool {
	if ctx == nil || ctx.AnalysisIR == nil ||
		ctx.AnalysisIR.RequestModel.SourceInventoryProfile == nil ||
		!ctx.AnalysisIR.RequestModel.SourceInventoryProfile.Active() {
		return false
	}
	for _, set := range answerDocPrincipalEnumerationSets(ctx, answerSurfacePlan(ctx)) {
		for _, row := range set.Rows {
			if strings.TrimSpace(row.RowID) != "" &&
				strings.TrimSpace(types.SourceInventorySurfaceFamilyKey(row.SurfaceTerms)) != "" {
				return true
			}
		}
	}
	return false
}

func renderAnswerDocRequestedDimensionEvidenceOwnership(ctx *types.AgentContext) string {
	if ctx == nil || ctx.Mutable == nil {
		return ""
	}
	view := types.BuildAnswerSemanticViewForAgentContext(ctx)
	if view == nil || len(view.Presentation.RequestedDimensions) == 0 {
		return ""
	}
	byIndex := map[int][]types.EvidenceItem{}
	for _, item := range ctx.Mutable.EmittedEvidence() {
		if item.GroundingStatus != types.GroundingGrounded && item.GroundingStatus != types.GroundingRecovered {
			continue
		}
		for _, index := range item.RequestedDimensionIndices {
			byIndex[index] = append(byIndex[index], item)
		}
	}
	if len(byIndex) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Requested Dimension Evidence Ownership\n\n")
	b.WriteString("The model selected these grounded evidence rows for independent requested dimensions. Use only a row listed under that dimension to support its mechanism; sibling evidence does not cross-satisfy it. This map does not author the conclusion.\n\n")
	for _, dim := range view.Presentation.RequestedDimensions {
		items := byIndex[dim.Index]
		if len(items) == 0 {
			continue
		}
		fmt.Fprintf(&b, "- Dimension %d:\n", dim.Index)
		for _, item := range items {
			location := strings.TrimSpace(item.Source)
			if item.LineStart > 0 {
				location = fmt.Sprintf("%s:%d", location, item.LineStart)
			}
			fmt.Fprintf(&b, "  - [%s] kind=%s anchor=%s subject=%q object=%q\n", location, item.Kind, item.AnchorKind, item.Subject, item.Object)
		}
	}
	return b.String()
}

func answerDocHasRequiredDimensionRole(dimensions []types.RequestedAnswerDimension, role types.RequestedAnswerDimensionRole) bool {
	for _, dimension := range dimensions {
		if dimension.Required && dimension.Role == role {
			return true
		}
	}
	return false
}

func renderAnswerDocCurrentSourceExplanationProfile(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	profile := ctx.AnalysisIR.RequestModel.CurrentSourceExplanationProfile
	if profile == nil || !profile.Active() {
		return ""
	}
	authority := types.BuildRuntimeSourceAnswerAuthoritySnapshotForAgentContext(ctx, types.ObservationLedger{})
	if authority.Active &&
		!authority.CurrentSourceRequired &&
		authority.RuntimeOnlySufficient &&
		authority.CurrentSourceRecordCount == 0 {
		return ""
	}
	lang := extractAnswerDocLang(ctx)
	var b strings.Builder
	if lang == "zh" {
		b.WriteString("## 当前源码解释请求\n\n")
		switch {
		case answerDocCurrentSourceProfileShouldUseBothLanes(authority):
			b.WriteString("- 共享 runtime/source authority 表明 current-source 义务是精确的，或已经有当前源码证据落地。请同时使用外部观察 lane 和 current-source lane；不要把外部观察伪装成源码 `file:line`，也不要因为外部观察存在就省略已落地的当前源码解释。\n")
		case answerDocCurrentSourceProfileShouldUseSoftCaveat(authority):
			b.WriteString("- 共享 runtime/source authority 将 current-source 义务判为 soft/caveat-only。保留外部观察作为答案级证据；只有在已落地当前源码证据时才写源码机制，否则用边界说明收敛，不要为了这个 soft lane 扩宽答案或补造源码引用。\n")
		default:
			b.WriteString("- 当前问题打开了 current-source 解释 lane。优先使用已落地的当前源码证据；如果没有足够源码证据，请把它作为证据边界说明，而不是把外部观察伪装成源码 `file:line`。\n")
		}
		b.WriteString("- 如果已读的当前源码证据里有精确符号、函数、配置键、错误类型或字面量锚点，请把这些锚点自然写进正文解释；不要只把它们留在文末引用列表。若外部观察无法追到完整当前源码调用链，请明确边界，只解释已由源码证明的相邻机制。\n")
		b.WriteString("- 多条源码事实不会自动组成一条顺序流水线。由不同 guard/profile 选择的解析路径应写成 alternative/dispatch 分支；wrapper/public entry 只证明委托，不能替代被调函数中真正执行 correlation key、栈/队列、reset、malformed/order 或 fail policy 的操作证据。只有引用 gutter 中实际可见的操作才能进入机制结论，未读分支保留为边界。\n")
		b.WriteString("- typed handoff 中 `claim_form=definition_fact` / `source_shape_authority=definition_site_only` 只证明该定义入口存在，不证明模型摘要所述的函数体操作。aggregate fact、completion reason 和 evidence summary 是模型整理层，不能提高源码权限；函数体行为必须来自实际可见 gutter，或 call/guard/assignment/return 等对应的结构化 operation anchor。\n")
		b.WriteString("- 对需要源码引用、但不属于 `Principal Enumeration Rows` 的结构化条目，请把对应 handoff 行的 `evidence=` ID 原样放入条目的 `evidence_ids`，并省略手工引用序号；当前 schema 暴露该字段时，提交 `citation_ref/citation_refs` 却不提交 `evidence_ids` 会被拒绝。无证或综合说明应同时省略 ID 和引用序号。`Principal Enumeration Rows` 中的概念成员和源码清单行统一只使用其精确 `source_inventory_row_id`，不要同时提交 `evidence_ids`。系统只把模型选中的 ID 映射为引用，不选择条目，也不代写结论。\n")
		b.WriteString("- 这是证据 lane 指引，不是系统补表许可；保留模型已经写好的丰富说明，证据不足时用边界说明而不是编造。\n\n")
	} else {
		b.WriteString("## Current-Source Explanation Request\n\n")
		switch {
		case answerDocCurrentSourceProfileShouldUseBothLanes(authority):
			b.WriteString("- The shared runtime/source authority says the current-source obligation is precise, or current-source evidence has already landed. Use both the external observation lane and the current-source lane; do not pretend external observations are source `file:line` proof, and do not omit landed current-source explanation just because an external observation exists.\n")
		case answerDocCurrentSourceProfileShouldUseSoftCaveat(authority):
			b.WriteString("- The shared runtime/source authority classifies the current-source obligation as soft/caveat-only. Preserve external observations as answer-grade support; use current-source mechanism detail only when current-source evidence has landed, otherwise converge with a source-boundary note instead of broadening the answer or inventing source citations for this soft lane.\n")
		default:
			b.WriteString("- The current request opens a current-source explanation lane. Prefer landed current-source evidence; when source proof is insufficient, disclose that evidence boundary instead of pretending external observations are source `file:line` proof.\n")
		}
		b.WriteString("- When already-read current-source evidence provides exact symbols, functions, config keys, error types, or literal anchors, weave those anchors into the visible explanation instead of leaving them only in the bibliography. If the external observation cannot be traced to a complete current-source call chain, state that boundary while explaining only adjacent mechanisms proven by source evidence.\n")
		b.WriteString("- Multiple grounded source facts do not automatically form one ordered pipeline. Present parser paths selected by different guards/profiles as alternative or dispatch branches. A wrapper/public entry proves delegation only; it cannot substitute for the callee operation that implements a correlation key, stack/queue, reset, malformed/order handling, or failure policy. Put an operation in the mechanism conclusion only when it is visible in the cited gutter, and keep unread branches as a boundary.\n")
		b.WriteString("- In the typed handoff, `claim_form=definition_fact` / `source_shape_authority=definition_site_only` proves only that the definition entry exists; it does not prove function-body operations described by a model summary. Aggregate facts, completion reasons, and evidence summaries are model distillation and cannot raise source authority. Body behavior requires a visible source gutter or the matching structured call/guard/assignment/return operation anchor.\n")
		b.WriteString("- For a structured item outside `Principal Enumeration Rows` that needs a source citation, copy the supporting accepted rows' `evidence=` IDs into item `evidence_ids` and omit manual citation indexes. When the current schema exposes this field, submitting `citation_ref/citation_refs` without `evidence_ids` is rejected. Omit both IDs and citation indexes for unsupported or synthesized items. Conceptual members and source-inventory rows listed under `Principal Enumeration Rows` use only their exact `source_inventory_row_id`; never submit both owners. The system maps only the selected IDs to citations; it does not choose the item or write its conclusion.\n")
		b.WriteString("- This is evidence-lane guidance, not permission for system table replacement. Preserve model-authored explanation; disclose unsupported parts in a boundary note instead of inventing facts.\n\n")
	}
	if len(profile.Modes) > 0 {
		parts := make([]string, 0, len(profile.Modes))
		for _, mode := range profile.Modes {
			if mode == "" {
				continue
			}
			parts = append(parts, "`"+string(mode)+"`")
		}
		if len(parts) > 0 {
			if lang == "zh" {
				fmt.Fprintf(&b, "- 模式：%s\n", strings.Join(parts, ", "))
			} else {
				fmt.Fprintf(&b, "- Modes: %s\n", strings.Join(parts, ", "))
			}
		}
	}
	if len(profile.SourceQuotes) > 0 {
		if lang == "zh" {
			b.WriteString("- 用户原文锚点：")
		} else {
			b.WriteString("- Source quotes: ")
		}
		quoted := make([]string, 0, len(profile.SourceQuotes))
		for _, quote := range profile.SourceQuotes {
			trimmed := strings.TrimSpace(quote)
			if trimmed != "" {
				quoted = append(quoted, fmt.Sprintf("%q", trimmed))
			}
		}
		b.WriteString(strings.Join(quoted, ", "))
		b.WriteString("\n")
	}
	if len(profile.TargetTerms) > 0 {
		if lang == "zh" {
			b.WriteString("- 搜索/排序提示词：")
		} else {
			b.WriteString("- Search/ranking terms: ")
		}
		b.WriteString(strings.Join(profile.TargetTerms, ", "))
		b.WriteString("\n")
	}
	b.WriteString("\n")
	return b.String()
}

func answerDocCurrentSourceProfileShouldUseBothLanes(authority types.RuntimeSourceAnswerAuthoritySnapshot) bool {
	return authority.KeepsCurrentSourceLaneLoadBearing() ||
		authority.CurrentSourceRecordCount > 0 ||
		authority.ExactCurrentSourceSupportCount > 0
}

func answerDocCurrentSourceProfileShouldUseSoftCaveat(authority types.RuntimeSourceAnswerAuthoritySnapshot) bool {
	if !authority.Active {
		return false
	}
	if answerDocCurrentSourceProfileShouldUseBothLanes(authority) {
		return false
	}
	return authority.AllowsRuntimeEvidenceWithoutCurrentSource() ||
		(authority.CurrentSourceRequirement == types.RuntimeSourceRequirementSoft &&
			authority.NeedsCurrentSourceEvidence)
}

func renderAnswerDocInvestigationNarrativeHandoff(ctx *types.AgentContext) string {
	if ctx == nil || ctx.Mutable == nil {
		return ""
	}
	if ctx.AnalysisIR != nil && types.CompileCallChainEndpointBoundary(
		ctx.AnalysisIR.RequestModel, ctx.Mutable.PrincipalSpanWaiver()) != nil {
		// Prior/superseded closure notes are unstructured model synthesis.
		// Once the model declares a typed no-directed-path boundary, replaying
		// those notes beside the exact endpoint disposition can reintroduce a
		// fabricated path. The notes remain in TurnAArtifacts for audit; the
		// finalizer receives grounded call triples and the typed boundary.
		return ""
	}
	if answerDocLogPeerRelationUnproven(ctx) {
		// A peer-only LogBundle already carries every answer-grade occurrence,
		// frame and message plus the precise cross-relation boundary. Replaying
		// model-authored investigation prose beside it creates a second, noisier
		// relation authority. Keep those notes in TurnAArtifacts for audit and
		// give the finalizer only the typed bundle/ledger and the tail boundary.
		return ""
	}
	if runtimeObservationOnlyForAnswerDoc(ctx) && answerDocHasDirectRuntimeObservation(ctx) &&
		(answerDocHasDeterministicRuntimeQueryObservation(ctx) || answerDocHasUnsupportedRuntimeModelSynthesis(ctx)) {
		// Producer-owned runtime rows already provide the answer-grade artifact
		// facts. Replaying an earlier model-authored investigation narrative
		// beside them creates a second authority that can promote caller-side
		// provenance, upstream construction, or stale trace windows without an
		// independent witness.
		// Keep the notes in TurnAArtifacts for audit; the Finalizer receives the
		// typed ledger/projection and reader-ready decision cards instead. The
		// decision is typed producer authority only; no narrative is scanned.
		return ""
	}
	ta := ctx.Mutable.TurnAArtifacts()
	var raw []string
	if ta != nil {
		raw = append([]string(nil), ta.InvestigationNotes...)
	}
	if runtimeObservationOnlyForAnswerDoc(ctx) {
		if !answerDocHasDeterministicRuntimeQueryObservation(ctx) {
			reason := ""
			if ta != nil {
				reason = strings.TrimSpace(ta.AcceptedClosureReason)
			}
			if reason == "" {
				reason = strings.TrimSpace(ctx.Mutable.StableInvestigationCompleteReason())
			}
			if reason != "" {
				raw = append(raw, "Accepted runtime closure reason (advisory only; direct artifact facts remain authoritative): "+reason)
			}
		}
	}
	if len(raw) == 0 {
		return ""
	}
	notes := recentSanitizedInvestigationNarrativeNotes(raw)
	if len(notes) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Investigation Narrative Handoff\n\n")
	b.WriteString("- These are bounded, model-authored exploration notes from the accepted investigation window. They are advisory synthesis only: not citations, not source code, not a hard gate, and not a replacement for typed support lanes.\n")
	b.WriteString("- Use them to preserve scope boundaries, negative-search conclusions, cross-bucket / cross-repository distinctions, and investigator caveats that would otherwise be lost when the structured evidence is one-sided.\n")
	b.WriteString("- If these notes conflict with typed support lanes, structured aggregate facts, current citations, or tool outputs, prefer the typed/structured evidence and disclose the boundary instead of silently dropping a user-requested side.\n\n")
	if len(raw) > len(notes) {
		fmt.Fprintf(&b, "*(showing the %d most recent usable note(s) of %d total)*\n\n", len(notes), len(raw))
	}
	for i, note := range notes {
		fmt.Fprintf(&b, "**Note %d:**\n%s\n\n", i+1, note)
	}
	return b.String()
}

func answerDocHasDeterministicRuntimeQueryObservation(ctx *types.AgentContext) bool {
	if ctx == nil {
		return false
	}
	input := types.ObservationLedgerInputFromAgentContext(ctx, 64)
	ledger := types.CompileObservationLedger(input)
	// Single source of truth: the ledger chokepoint base-normalizes the
	// producer id, so run-suffixed ids (trace_query:run2) are recognized.
	// An inline exact-match here previously diverged from the two other
	// channels and missed those ids.
	return ledger.HasDeterministicRuntimeQueryObservation()
}

func answerDocHasDirectRuntimeObservation(ctx *types.AgentContext) bool {
	if ctx == nil {
		return false
	}
	input := types.ObservationLedgerInputFromAgentContext(ctx, 64)
	input.AggregateFacts = answerDocStableAggregateFacts(ctx)
	return types.CompileObservationLedger(input).HasDirectRuntimeObservation()
}

func answerDocHasUnsupportedRuntimeModelSynthesis(ctx *types.AgentContext) bool {
	if ctx == nil || ctx.Mutable == nil || ctx.AnalysisIR == nil {
		return false
	}
	facts := append([]types.AnswerAggregateFact(nil), ctx.Mutable.StableInvestigationAggregateFacts()...)
	if ta := ctx.Mutable.TurnAArtifacts(); ta != nil {
		facts = append(facts, ta.AcceptedAggregateFacts...)
	}
	input := types.ObservationLedgerInputFromAgentContext(ctx, 64)
	input.AggregateFacts = facts
	ledger := types.CompileObservationLedger(input)
	_, withheld := types.ProjectDirectRuntimeAggregateFacts(facts, &ctx.AnalysisIR.RequestModel, ledger)
	return withheld
}

func recentSanitizedInvestigationNarrativeNotes(raw []string) []string {
	if len(raw) == 0 {
		return nil
	}
	start := len(raw) - answerDocMaxInvestigationNarrativeNotes
	if start < 0 {
		start = 0
	}
	out := make([]string, 0, len(raw)-start)
	for _, note := range raw[start:] {
		clean := sanitizePriorDraftForSummary(note)
		clean = truncateAnswerDocPromptText(clean, answerDocMaxInvestigationNarrativeNoteBytes)
		clean = strings.TrimSpace(clean)
		if clean == "" {
			continue
		}
		out = append(out, clean)
	}
	return out
}

// renderAnswerDocPrincipalMemberSetContract surfaces the strong-contract
// must-verbatim list of principal member_set members so the LLM sees the
// exact strings the pre-emit oracle
// (preCheckAggregateMemberSetCoverage at
// internal/tool/answer_document_pre_emit_check.go:1264) will check for.
//
// Why this exists (P1A, 2026-05-17):
// The existing `renderAnswerDocAggregateFacts` already prints every fact
// with its members in an audit-style listing, but its prose reads as
// "preserve when applicable" guidance — the LLM treats decorated members
// like `gate.Run (9 checks)` or `assertExternalDirectoryEffect (路径边界)`
// as paraphrasable display strings and rewrites them to `gate.Run /
// gate.RunWith` or strips the parenthetical. The oracle then rejects the
// emit because the verbatim member is missing from the visible answer.
// This section reframes the same data as a hard pre-emit contract,
// matching the wording of the oracle reject so the LLM gets the same
// instruction on the success path and the failure path.
//
// This is the T1-style symmetric fix for member sets (visible_anchor_whitelist
// did the same for grounded anchors). Mirrors the
// AggregateMemberSetIsScalarCountSupport filter so we do not demand
// verbatim members for scalar-count questions where the count IS the
// answer.
func renderAnswerDocPrincipalMemberSetContract(ctx *types.AgentContext) string {
	plan := answerSurfacePlan(ctx)
	if plan == nil || len(plan.StableAggregateFacts) == 0 {
		return ""
	}
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	rm := ctx.AnalysisIR.RequestModel
	allRefs := types.PrincipalAggregateMemberSetFactRefsForRequest(plan.StableAggregateFacts, &rm)
	if len(allRefs) == 0 {
		return ""
	}
	sets := answerDocPrincipalEnumerationSets(ctx, plan)
	refs, advisoryRefs := answerDocPartitionPrincipalMemberSetRefs(allRefs, &rm, sets)
	if len(refs) == 0 {
		return renderAnswerDocAdvisoryPrincipalMemberSets(advisoryRefs)
	}
	if len(sets) > 0 {
		return renderAnswerDocPrincipalMemberSetContractFromEnumerationRows(ctx, refs, sets) +
			renderAnswerDocAdvisoryPrincipalMemberSets(advisoryRefs)
	}

	type renderedFact struct {
		label   string
		members []string
	}
	rendered := make([]renderedFact, 0, len(refs))
	totalMembers := 0
	for _, ref := range refs {
		fact := ref.Fact
		if types.AggregateMemberSetIsScalarCountSupport(&rm, fact) {
			continue
		}
		members := answerDocDistinctPrincipalMembers(fact.Members)
		if len(members) == 0 {
			continue
		}
		rendered = append(rendered, renderedFact{
			label:   strings.TrimSpace(fact.Label),
			members: members,
		})
		totalMembers += len(members)
	}
	if len(rendered) == 0 {
		return ""
	}

	var b strings.Builder
	b.WriteString("## Required Principal Member Set\n\n")
	b.WriteString("The investigator handed off the following principal `member_set` aggregate fact(s) via `emit_investigation_complete.aggregate_facts`. ")
	if types.RequiresExhaustiveEnumerationMemberSetHandoff(rm) || types.RequiresRelationMemberSetHandoff(rm) {
		b.WriteString("**Every member listed below MUST appear verbatim — including any decorator in parentheses (e.g. `(9 checks)`, `(路径边界)`), arrow (e.g. ` → `), or separator (e.g. `::`, `/`) — as a structured item in a principal `section`, `ordered_list`, `bullet_list`, or `table`. Prefer one titled block per principal set when multiple sets are present.** ")
		b.WriteString("For a `section`, put member rows in `items[]`; prose-only mentions inside `summary` or block `text` may enrich the answer, but they are not the principal member carrier for this typed exhaustive/member-set request.\n\n")
	} else {
		b.WriteString("**Every member listed below MUST appear verbatim — including any decorator in parentheses (e.g. `(9 checks)`, `(路径边界)`), arrow (e.g. ` → `), or separator (e.g. `::`, `/`) — in some `blocks[].items[].label`, `blocks[].items[].text`, `blocks[].items[].cells[]`, or `blocks[].text` of the emitted answer document.** ")
	}
	if types.RequiresSourceOperationSiteMemberSetHandoff(rm) {
		b.WriteString("This request's member_set is a source operation-site set: render it as the principal write/call/registration/entry-point list or table before broad mechanism prose. Use member-specific support refs for the operation-site citation; constants, literal target paths, config keys, or registry names are row details and must not replace the citation for the function/call/write site itself. ")
	}
	b.WriteString("The pre-emit oracle rejects the call (with field `blocks[].items[].label/text/cells OR blocks[].text`) if any member is missing, paraphrased, abbreviated, or has its decorator stripped. Mirror each string byte-for-byte; do NOT rewrite the wording.\n\n")
	b.WriteString("Concretely: a member rendered as `gate.Run (9 checks)` is NOT satisfied by `gate.Run` alone, `gate.Run / gate.RunWith`, or `gate.Run 函数`. The full string `gate.Run (9 checks)` must appear together inside one block's label/text/cells/items.\n\n")
	b.WriteString("Upstream contract for decorator-shape members: for each member rendered as `code_identifier (qualifier)` (e.g. `Orchestrator (4-stage pipeline)`, `assertExternalDirectoryEffect (路径边界)`), the investigator was required to attach `support_refs[i] = file:line` per member on `emit_investigation_complete` — empty `support_refs` on a decorated `member_set` is rejected at that boundary because the decorator changes the surface so the framework cannot auto-resolve the member against an evidence anchor named by the bare leading identifier alone. When matching support is available on the bus, carry it through the exact projected row/evidence selector so the visible decorator remains bound to that source without manual pool arithmetic.\n\n")

	for _, rf := range rendered {
		if rf.label != "" {
			fmt.Fprintf(&b, "- principal set %q (%d member(s)):\n", rf.label, len(rf.members))
		} else {
			fmt.Fprintf(&b, "- principal set (%d member(s)):\n", len(rf.members))
		}
		for _, member := range rf.members {
			fmt.Fprintf(&b, "  - `%s`\n", member)
		}
	}
	b.WriteString("\n")
	b.WriteString(renderAnswerDocAdvisoryPrincipalMemberSets(advisoryRefs))
	return b.String()
}

func answerDocDistinctPrincipalMembers(raw []string) []string {
	members := make([]string, 0, len(raw))
	seen := map[string]bool{}
	for _, member := range raw {
		trimmed := strings.TrimSpace(member)
		if trimmed == "" {
			continue
		}
		// Principal member surfaces are source identities, not search tokens.
		// Case-sensitive languages may legitimately publish two distinct
		// symbols whose only spelling difference is case (for example an
		// unexported helper and its exported wrapper in Go). The pre-emit
		// contract is verbatim, so a case-folded dedup here silently shrinks the
		// model-authored typed set and later forces a contradictory supplement.
		// Preserve exact post-trim spelling. A producer that explicitly owns a
		// case-insensitive identity domain must normalize its typed carrier
		// before it reaches this language-neutral renderer.
		if seen[trimmed] {
			continue
		}
		seen[trimmed] = true
		members = append(members, trimmed)
	}
	return members
}

func answerDocPartitionPrincipalMemberSetRefs(refs []types.AnswerAggregateFactRef, rm *types.RequestModel, sets []types.EnumerationDisplaySet) (authoritative, advisory []types.AnswerAggregateFactRef) {
	setAuthority := make(map[int]bool, len(sets))
	for _, set := range sets {
		setAuthority[set.FactIndex] = true
	}
	for _, ref := range refs {
		if setAuthority[ref.Index] || types.AnswerAggregateFactAuthorizesPrincipalContract(ref.Fact, rm) {
			authoritative = append(authoritative, ref)
		} else {
			advisory = append(advisory, ref)
		}
	}
	return authoritative, advisory
}

func renderAnswerDocAdvisoryPrincipalMemberSets(refs []types.AnswerAggregateFactRef) string {
	if len(refs) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Advisory Model-Inferred Member Sets\n\n")
	b.WriteString("- These structured sets were retained from exploration but carry only `system_inference` / illustrative authority. They are investigation candidates, not a required answer roster, not proof of relation or order, and not permission to join independently grounded components.\n")
	b.WriteString("- Use, qualify, revise, or omit them according to the grounded evidence and the typed component/flow boundary. A `role=principal_answer` value here records the investigation's proposed slate; it does not create a MUST-render or hard-validation contract.\n")
	for _, ref := range refs {
		label := strings.TrimSpace(ref.Fact.Label)
		if label == "" {
			label = fmt.Sprintf("aggregate_facts[%d]", ref.Index)
		}
		fmt.Fprintf(&b, "- advisory set %q (%d candidate member(s))", label, len(ref.Fact.Members))
		if members := renderAggregateStringList(ref.Fact.Members, 24); members != "" {
			fmt.Fprintf(&b, ": %s", members)
		}
		b.WriteString("\n")
	}
	b.WriteString("\n")
	return b.String()
}

const answerDocMaxRelationSurfaceRows = 10
const answerDocMaxTypedRelationRoleRows = 24

type answerDocRelationSurfaceRow struct {
	role              string
	label             string
	loc               string
	surface           string
	authorityBoundary string
	score             int
	index             int
}

func renderAnswerDocTypedRelationSourceRoleHandoff(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil || len(ctx.TypedRelationHints) == 0 {
		return ""
	}
	rm := ctx.AnalysisIR.RequestModel
	principalMembers := types.PrincipalTypedRelationMemberNamesForRequest(
		answerDocStableAggregateFacts(ctx), &rm,
	)
	hasPrincipalMemberBoundary := len(principalMembers) > 0
	type row struct {
		relation types.TypedRelationKind
		source   string
		member   types.TypedRelationMember
	}
	var rows []row
	principal, auxiliary, unknown := 0, 0, 0
	for _, hint := range ctx.TypedRelationHints {
		for _, raw := range hint.Members {
			member := types.ProjectTypedRelationMemberScopeLane(raw, rm)
			switch member.ScopeLane {
			case types.TypedRelationMemberLanePrincipal:
				principal++
			case types.TypedRelationMemberLaneAuxiliary:
				auxiliary++
			default:
				unknown++
			}
			rows = append(rows, row{
				relation: hint.Relation,
				source:   strings.TrimSpace(hint.SourceName),
				member:   member,
			})
		}
	}
	if len(rows) == 0 {
		return ""
	}
	sort.SliceStable(rows, func(i, j int) bool {
		if rows[i].member.ScopeLane != rows[j].member.ScopeLane {
			return rows[i].member.ScopeLane == types.TypedRelationMemberLanePrincipal
		}
		if rows[i].relation != rows[j].relation {
			return rows[i].relation < rows[j].relation
		}
		if rows[i].source != rows[j].source {
			return rows[i].source < rows[j].source
		}
		if rows[i].member.Name != rows[j].member.Name {
			return rows[i].member.Name < rows[j].member.Name
		}
		return rows[i].member.File < rows[j].member.File
	})

	var b strings.Builder
	b.WriteString("## Typed Relation Source-Role Projection (Advisory)\n\n")
	fmt.Fprintf(&b, "- complete_relation_roster=%d; principal=%d; auxiliary=%d; unknown=%d.\n", len(rows), principal, auxiliary, unknown)
	b.WriteString("- This projection reads only typed relation members, deterministic path roles, and analyzer-emitted `SourceScopeProfile`; it does not scan the raw request or answer prose.\n")
	if hasPrincipalMemberBoundary {
		fmt.Fprintf(&b, "- exact_principal_member_boundary=`completion_verified_typed_relation_member_set`; principal_member_count=%d. This exact set is the sole membership authority for the principal relation table and sibling principal diagram. Source-scope lanes below remain audit/support metadata and cannot add another principal member; broader structural relations may remain in a separately labelled support view.\n", len(principalMembers))
	} else {
		b.WriteString("- For the principal relation table/diagram/member_set, use lane=`principal`. Preserve lane=`auxiliary` as an explicitly labelled support/audit roster unless the typed scope opts that source role into principal. Disclose lane=`unknown` and verify it; never silently promote or delete it.\n")
	}
	b.WriteString("- The complete structural roster and the principal answer set are intentionally different surfaces. Auxiliary membership proves the structural edge exists, but does not by itself authorize a row as a principal production answer.\n")
	b.WriteString("- Lookup direction and display direction are distinct for declared type relations. For `implements`, `extends`, and `overrides`, `source` is the queried contract/supertype and `member` is the implementing/subtype/overriding declaration; a visible `type_relation` edge and its anchor therefore run `member -> source`. The recipes below are advisory authoring aids; the exact provider and hard validator independently verify every model-authored edge.\n")
	for i, row := range rows {
		if i >= answerDocMaxTypedRelationRoleRows {
			fmt.Fprintf(&b, "- (%d additional typed relation role row(s) omitted only from this compact prompt view; the complete roster remains upstream)\n", len(rows)-i)
			break
		}
		role := string(row.member.SourceRole)
		if role == "" {
			role = "unknown"
		}
		lane := string(row.member.ScopeLane)
		if lane == "" {
			lane = "unknown"
		}
		fmt.Fprintf(&b, "- lane=`%s` source_role=`%s` relation=`%s` source=`%s` member=`%s`",
			lane, role, row.relation, row.source, row.member.Name)
		if hasPrincipalMemberBoundary {
			membership := "support_only"
			if types.PrincipalTypedRelationMemberMatches(row.member.Name, principalMembers) {
				membership = "principal"
			}
			fmt.Fprintf(&b, " answer_membership=`%s`", membership)
		}
		if row.member.File != "" {
			fmt.Fprintf(&b, " @ %s", row.member.File)
			if row.member.Line > 0 {
				fmt.Fprintf(&b, ":%d", row.member.Line)
			}
		}
		b.WriteString("\n")
	}

	// Emit a composable alias/body/anchor recipe for the principal declared-type
	// rows. The lookup carrier is keyed by the contract, but Mermaid and the
	// strict validator use subtype/implementer -> supertype/contract direction.
	// This is language-neutral and reads only the closed relation enum plus the
	// typed member/source identities above. It neither requires a diagram nor
	// installs one in the answer.
	type aliasRow struct {
		key      string
		alias    string
		identity string
	}
	type recipeRow struct {
		index      int
		relation   types.TypedRelationKind
		fromAlias  string
		toAlias    string
		fromLabel  string
		toLabel    string
		anchorJSON string
	}
	aliases := make([]aliasRow, 0, len(rows)+1)
	aliasFor := func(key, identity string) string {
		for _, candidate := range aliases {
			if candidate.key == key {
				return candidate.alias
			}
		}
		alias := fmt.Sprintf("tr%d", len(aliases)+1)
		aliases = append(aliases, aliasRow{key: key, alias: alias, identity: identity})
		return alias
	}
	recipes := make([]recipeRow, 0, len(rows))
	for _, row := range rows {
		if row.member.ScopeLane != types.TypedRelationMemberLanePrincipal ||
			(hasPrincipalMemberBoundary && !types.PrincipalTypedRelationMemberMatches(row.member.Name, principalMembers)) ||
			!answerDocTypedRelationUsesMemberToSourceDisplay(row.relation) ||
			row.member.Name == "" || row.source == "" {
			continue
		}
		fromAlias := aliasFor("member\x00"+row.member.Name+"\x00"+row.member.File, row.member.Name)
		toAlias := aliasFor("source\x00"+row.source, row.source)
		anchor := types.DiagramEdgeAnchor{
			FromNode:     fromAlias,
			ToNode:       toAlias,
			FromIdentity: row.member.Name,
			ToIdentity:   row.source,
			RelationKind: types.DiagramRelTypeRelation,
		}
		payload, err := json.Marshal(anchor)
		if err != nil {
			continue
		}
		recipes = append(recipes, recipeRow{
			index: len(recipes) + 1, relation: row.relation,
			fromAlias: fromAlias, toAlias: toAlias,
			fromLabel: row.member.Name, toLabel: row.source,
			anchorJSON: string(payload),
		})
		if len(recipes) >= answerDocMaxTypedRelationRoleRows {
			break
		}
	}
	if len(recipes) > 0 {
		b.WriteString("- declared_type_relation_authoring=`available`; copy the selected recipe's body edge and matching anchor together; keep aliases local to the same diagram block.\n")
		for _, recipe := range recipes {
			fromLabel, _ := json.Marshal(recipe.fromLabel)
			toLabel, _ := json.Marshal(recipe.toLabel)
			body := fmt.Sprintf("%s[%s] -->|%s| %s[%s]", recipe.fromAlias, fromLabel, recipe.relation, recipe.toAlias, toLabel)
			bodyJSON, _ := json.Marshal(body)
			// encoding/json HTML-escapes `>` by default. That is valid JSON but
			// turns the most important copy-ready Mermaid token into `--\u003e`.
			// Restore the three JSON-safe characters so the model sees the native
			// edge spelling while the surrounding string stays valid JSON.
			bodyJSON = []byte(strings.NewReplacer(`\u003c`, "<", `\u003e`, ">", `\u0026`, "&").Replace(string(bodyJSON)))
			fmt.Fprintf(&b, "- type_relation_recipe[%d]: direction=`member_to_source`; relation=`%s`; body_json=%s; edge_anchor_json=`%s`\n",
				recipe.index, recipe.relation, bodyJSON, recipe.anchorJSON)
		}
	}
	b.WriteString("\n")
	return b.String()
}

func answerDocTypedRelationUsesMemberToSourceDisplay(relation types.TypedRelationKind) bool {
	switch relation {
	case types.TypedRelationImplements, types.TypedRelationExtends, types.TypedRelationOverrides:
		return true
	default:
		return false
	}
}

func renderAnswerDocRelationSurfaceHandoff(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	rm := ctx.AnalysisIR.RequestModel
	rows := selectAnswerDocRelationSurfaceRows(ctx, answerDocMaxRelationSurfaceRows)
	if len(rows) == 0 {
		return ""
	}
	facts := answerDocStableAggregateFacts(ctx)
	relationRefs := types.PrincipalRelationMemberSetFactRefsForRequest(facts, &rm)
	// Relation-looking member labels and exact per-member coordinates do not
	// prove the set's direction, order, membership, or cross-component bridge.
	// Reuse the same principal-contract authority as every other finalizer and
	// validator consumer so this advisory handoff cannot call a soft model
	// inference "required" after the structured aggregate section rejected that
	// upgrade.
	relationRefs, _ = answerDocPartitionPrincipalMemberSetRefs(relationRefs, &rm, nil)
	if !answerDocShouldRenderRelationSurfaceHandoff(rm, rows, relationRefs) {
		return ""
	}

	var b strings.Builder
	b.WriteString("## Relation Role Handoff (Advisory)\n\n")
	b.WriteString("- The rows below come only from structured exploration carriers: accepted `EvidenceItem` fields and typed relation surfaces. They do not parse raw user text or free-form investigation prose.\n")
	b.WriteString("- Advisory boundary: these rows can help preserve relation roles during answer-writing, but they are not a system-authored final answer set. Do not invent principal members from them.\n")
	b.WriteString("- Role priority: evidence-authorized principal relation `member_set` facts are the answer-member carrier; advisory model-inferred sets remain candidates only. Principal enumeration rows / support lanes add richer notes and citations; role=`qualifying_gate` rows constrain which members qualify; role=`registration_or_binding` and role=`registry_identity_chain` rows prove population or identity; dispatcher/runtime/tool-registration/helper rows explain support flow and must not replace qualifying members.\n")
	if len(relationRefs) > 0 {
		b.WriteString("- A principal relation `member_set` is already present above. That required member set is the answer-member carrier; use these rows only for per-member explanation, boundaries, and citations.\n")
	} else if types.PrincipalMemberSetRequiresTypedRelationAuthority(rm) {
		b.WriteString("- No evidence-authorized principal relation `member_set` is active. A model-authored set becomes the answer-member carrier only after the completion layer attaches exact typed-relation authority; until then keep it advisory, preserve component boundaries, and do not substitute dispatcher/helper rows or individually true nodes as a proved path.\n")
	} else {
		b.WriteString("- No hard principal relation `member_set` is active for this dispatch. Keep the direct answer aligned with the user's requested relation, and separate qualifying members from dispatchers, registries, helpers, runtimes, or other supporting roles.\n")
	}
	b.WriteString("- If a global registry, tool catalog, dispatcher, or runtime row appears together with a qualifying gate or identity chain, treat the global row as support context. Do not infer that every broad interface implementer or every registered helper qualifies unless a principal member_set or same-member grounded row says so.\n")
	b.WriteString("- If a row conflicts with citations, aggregate facts, source-inventory counts, or required principal members, prefer the typed/structured contract and state the boundary rather than silently dropping a user-requested side.\n\n")

	for _, row := range rows {
		fmt.Fprintf(&b, "- role=`%s`", row.role)
		if row.label != "" {
			fmt.Fprintf(&b, " `%s`", row.label)
		}
		if row.loc != "" {
			fmt.Fprintf(&b, " @ %s", row.loc)
		}
		if row.authorityBoundary != "" {
			fmt.Fprintf(&b, "; %s", row.authorityBoundary)
		}
		if row.surface != "" {
			fmt.Fprintf(&b, ": %s", row.surface)
		}
		b.WriteString("\n")
	}
	b.WriteString("\n")
	return b.String()
}

type answerDocMechanismRelationEdge struct {
	from       string
	to         string
	anchorFrom string
	anchorTo   string
	relation   types.DiagramRelationKind
	loc        string
	// requestSpine marks a relation selected by a request-scoped typed
	// authority provider, rather than a merely relevant grounded sibling. It
	// is presentation planning metadata only: it cannot mint an edge, bridge
	// components, or change validation authority. The first producer is the
	// checkout-verified read-mode stage sequence.
	requestSpine bool
	// requestScoped marks a relation selected by the request-scoped provider
	// even when that provider covers only a strict subset of the requested
	// incident participants. Keeping this separate from requestSpine prevents
	// a true stage-order segment from being advertised as a complete carrier or
	// data-flow answer. It remains presentation metadata only.
	requestScoped bool
	// sourceItem is the existing citable model-selected operation behind this
	// recipe. It is retained only for participant/type identity projection; it
	// never changes the edge relation or endpoints.
	sourceItem types.EvidenceItem
}

// answerDocMechanismUnaryAnnotation carries a citable typed fact whose
// semantics attach to one exact participant instead of relating two
// endpoints. It is deliberately separate from answerDocMechanismRelationEdge:
// a branch condition must never acquire a synthetic object, self-loop, or
// edge anchor merely so a visual can mention it.
type answerDocMechanismUnaryAnnotation struct {
	participant string
	relation    types.DiagramRelationKind
	detail      string
	loc         string
}

type answerDocMechanismUnaryAnnotationRow struct {
	annotation  answerDocMechanismUnaryAnnotation
	participant string
}

type answerDocMechanismAliasRow struct {
	identity string
	alias    string
}

type answerDocMechanismRecipeRow struct {
	edge   answerDocMechanismRelationEdge
	from   string
	to     string
	anchor string
	typed  types.DiagramEdgeAnchor
}

type answerDocMechanismAuthoringReceipts struct {
	relationAnchors        []types.DiagramEdgeAnchor
	semanticHandoffAnchors []types.DiagramEdgeAnchor
}

type answerDocMechanismRelationTopology struct {
	uniqueEdges       int
	nodes             int
	weakComponents    int
	maxOutDegree      int
	maxInDegree       int
	fanOutPresent     bool
	fanInPresent      bool
	disconnected      bool
	singleLinearGraph bool
}

func renderAnswerDocMechanismRelationAuthority(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil || !answerDocMechanismRelationAuthorityApplies(ctx.AnalysisIR.RequestModel) {
		return ""
	}
	evidence, allEdges, acceptedFacts, callsiteFacts := answerDocCurrentSourceMechanismRelations(ctx)
	edges := answerDocMechanismEndpointBoundaryEdges(ctx, allEdges)
	unaryAnnotations := answerDocMechanismUnaryAnnotations(evidence)
	semanticHandoffs := answerDocRegisteredExportHandoffsForContext(ctx)
	if acceptedFacts == 0 {
		return ""
	}
	typedPaths := answerDocSupportedMechanismFlowPathsForContext(ctx)
	status := "unproven"
	switch {
	case len(typedPaths) > 0:
		status = "typed_flow_paths_present"
	case len(edges) > 0:
		status = "listed_edges_only"
	}

	var b strings.Builder
	b.WriteString("## Current-Source Mechanism Relation Authority\n\n")
	fmt.Fprintf(&b,
		"- accepted_grounded_source_facts=%d; grounded_callsite_facts=%d; explicit_typed_directed_relations=%d; typed_unary_annotations=%d; ordered_path_authority=`%s`.\n",
		acceptedFacts, callsiteFacts, len(edges), len(unaryAnnotations), status)
	if len(edges) < len(allEdges) {
		fmt.Fprintf(&b, "- principal_relation_scope=`typed_endpoint_boundary`; supporting_directed_relations_outside_boundary=`%d`. The omitted relations remain grounded support facts, but they are not principal intermediate hops or principal diagram edges for this exact endpoint answer.\n", len(allEdges)-len(edges))
	}
	renderAnswerDocFlowParticipantCoverageGuidance(&b, ctx, edges, evidence)
	participantCoverage := answerDocResolveFlowParticipantCoverage(
		ctx.AnalysisIR.RequestModel,
		edges,
		evidence,
		answerDocVerifiedReadModeStagePrecedenceForRequest(ctx),
	)
	if topology, ok := answerDocMechanismRelationGraphTopology(edges); ok {
		fmt.Fprintf(&b,
			"- typed_relation_graph: unique_endpoint_relations=%d; nodes=%d; weak_components=%d; max_out_degree=%d; max_in_degree=%d; fan_out_present=%t; fan_in_present=%t; disconnected_present=%t; single_linear_relation_graph=%t.\n",
			topology.uniqueEdges, topology.nodes, topology.weakComponents,
			topology.maxOutDegree, topology.maxInDegree, topology.fanOutPresent,
			topology.fanInPresent, topology.disconnected, topology.singleLinearGraph)
		if !topology.singleLinearGraph {
			b.WriteString("- The relation inventory is not one linear hop chain. Do not turn its relation count into a hop count or list sibling fan-out/fan-in edges as consecutive intermediates. If `typed_flow_path[...]` records are present, only those records authorize their own ordered subset; otherwise keep the listed directed edges as a graph/boundary.\n")
		}
		b.WriteString("- These topology fields describe only the shape of grounded directed relations. `fan_out_present` means one node has multiple outgoing typed relations; `weak_components` and `disconnected_present` describe graph connectivity. None of them proves concurrent/parallel execution, temporal order, a join, or runtime convergence. State those semantics only when separate typed control-flow, concurrency, or runtime evidence establishes them.\n")
	}
	b.WriteString("- A grounded definition, enum constant, classifier branch, return, or assignment proves that local fact only. Several true nodes do not by themselves prove call order, data flow, or a complete mechanism chain.\n")
	b.WriteString("- Only the explicit typed relations and supported typed flow paths listed below carry their stated authority. Unlisted adjacency remains unproven. Describe other grounded nodes as independent mechanism facts; do not join them into a path merely because the answer contract asks for `principal_path_edge`.\n")
	b.WriteString("- The relation recipes are advisory, source-derived authoring aids. They do not choose the answer, require a diagram, or create a synthetic bridge. If you draw one, reuse its node aliases in the diagram body and copy its native JSON anchor unchanged; omit unsupported bridges instead of changing their relation kind to `call`.\n")
	b.WriteString("- When a user-facing component or participant is broader than a typed callable endpoint, preserve both layers: place the exact endpoint node inside that component's Mermaid subgraph/group, draw the copied typed relation only between the exact endpoint nodes, and use the component group/label only for responsibility. Do not retarget the relation to an abstract component node, and do not delete an already-typed relation merely to simplify the diagram. This layered form is language-neutral.\n")
	if len(edges) == 0 {
		b.WriteString("- No citable typed directed relation is available. `principal_path_edge` may carry an uncertainty boundary or independent fact list, but it must not claim an ordered/complete current-source chain.\n")
		if ctx.Mutable != nil &&
			ctx.Mutable.EvidenceClosure().HasCompletionCaveat(types.DowngradeLaneFlowOperationCarrier) {
			b.WriteString("- relation_surface_exit=`typed_unproven_node_only`: the bounded operation-evidence supplement already converged without a citable directed relation. Keep the explicitly requested diagram as a model-authored node/group inventory with zero structural arrows, and explain the unproven relation boundary in your own answer prose. Do not omit the requested diagram and do not invent an edge. The node-only exit changes presentation satisfiability only; it does not prove a relation or write the answer for you.\n")
		}
	}
	if len(edges) > 0 || len(unaryAnnotations) > 0 {
		receipts := renderAnswerDocMechanismRelationAuthoringCapsule(
			&b,
			edges,
			unaryAnnotations,
			semanticHandoffs,
			answerDocMechanismCopyReadyRelationLimit(ctx),
			answerDocMechanismCopyReadyDiagramKind(ctx, edges, semanticHandoffs),
			answerDocMechanismRequestedDiagramKind(ctx, edges),
			participantCoverage.requestScopedRelationComplete,
		)
		// A complete dynamic-selection candidate may carry precise non-call
		// hops that the general grounded-mechanism inventory intentionally does
		// not infer (indexed assignment, argument flow, factory return, declared
		// type). Publish those already-compiled hops in the same recipe section
		// and receipt so initial authoring and retry repair consume one contract.
		// This remains candidate-only and never selects or connects a runtime
		// implementation on the model's behalf.
		receipts.relationAnchors = append(receipts.relationAnchors,
			renderAnswerDocDynamicSelectorRelationRecipes(&b, ctx)...)
		if ctx.Mutable != nil {
			ctx.Mutable.SetFinalizerTypedRelationRecipeAnchors(receipts.relationAnchors)
			ctx.Mutable.SetFinalizerTypedRelationSemanticHandoffAnchors(receipts.semanticHandoffAnchors)
		}
		if dc := answerDocDiagramContract(ctx); dc != nil {
			if boundaries, _ := answerDocDiagramUnprovenParticipantBoundaries(ctx, dc); len(boundaries) > 0 {
				// A participant boundary is a required block sibling, but it is not
				// a request to copy every grounded relation recipe into the visible
				// diagram. Keep the exact boundary rows copy-ready while leaving edge
				// selection with the model. The prior combined carrier bundled the
				// full relation-authority inventory with these rows and contradicted
				// the bounded per-participant guidance above: a model following the
				// atomic-copy command had to render every local helper relation.
				// This carrier still creates no visible edge, node, wording, layout,
				// or conclusion and reads no request/model/answer prose.
				renderAnswerDocDiagramParticipantBoundaryCarrier(&b, boundaries)
			}
		}
	}
	for i, path := range typedPaths {
		if i >= 4 {
			fmt.Fprintf(&b, "- (%d additional typed path(s) omitted from this compact authority view)\n", len(typedPaths)-i)
			break
		}
		fmt.Fprintf(&b, "- typed_flow_path[%d]=`%s`\n", i+1, strings.Join(path, " -> "))
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocDiagramParticipantBoundaryCarrier(
	b *strings.Builder,
	boundaries []types.DiagramParticipantBoundary,
) {
	if b == nil || len(boundaries) == 0 {
		return
	}
	payload, err := json.Marshal(boundaries)
	if err != nil {
		return
	}
	fmt.Fprintf(b, "- diagram_participant_boundaries_json=`%s`; copy this exact array into the `participant_boundaries` sibling field of the one model-authored diagram that presents the requested relation. Select `edge_anchors` only for the typed candidate/recipe edges you actually choose to draw; do not copy the full relation-authority inventory merely because these boundary rows are required. The boundary rows constrain only the still-unproved requested relation, while independently selected proved arrows keep their own exact anchors. Do not display this JSON, boundary status, or validator vocabulary in reader-facing prose.\n", payload)
}

// answerDocMechanismEndpointBoundaryEdges narrows the copy-ready relation
// carrier to the exact typed endpoint boundary after a no-directed-path
// closure. Broad source evidence remains available elsewhere, but it must not
// become a system-suggested principal path merely because it shares the source
// caller. The predicate is schema/edge based and language-neutral.
func answerDocMechanismEndpointBoundaryEdges(ctx *types.AgentContext, edges []answerDocMechanismRelationEdge) []answerDocMechanismRelationEdge {
	view := types.BuildAnswerSemanticViewForAgentContext(ctx)
	if view == nil || view.CallChainEndpointBoundary == nil ||
		view.CallChainEndpointBoundary.EvidenceCapsule == nil ||
		view.CallChainEndpointBoundary.Disposition != types.CallChainEndpointNoDirectedPath ||
		view.CallChainEndpointBoundary.EvidenceCapsule.Status == types.CallChainEndpointEvidenceDirectedPathPresent {
		return edges
	}
	allowed := types.CallChainEndpointBoundaryPrincipalEdges(view.CallChainEndpointBoundary.EvidenceCapsule)
	out := make([]answerDocMechanismRelationEdge, 0, len(allowed))
	for _, edge := range edges {
		if edge.relation != types.DiagramRelCall {
			continue
		}
		for _, boundaryEdge := range allowed {
			if types.AnswerCodeIdentitySurfacesEquivalent(edge.from, boundaryEdge.From) &&
				types.AnswerCodeIdentitySurfacesEquivalent(edge.to, boundaryEdge.To) {
				out = append(out, edge)
				break
			}
		}
	}
	return out
}

// answerDocCurrentSourceMechanismRelations is the single producer for the
// finalizer's typed relation edges and participant coverage. Diagram boundary
// recipes and Current-Source Authority must consume this same projection so a
// participant cannot be called both incident and uncovered in one prompt.
func answerDocCurrentSourceMechanismRelations(ctx *types.AgentContext) ([]types.EvidenceItem, []answerDocMechanismRelationEdge, int, int) {
	if ctx == nil || ctx.AnalysisIR == nil {
		return nil, nil, 0, 0
	}
	evidence := answerDocTypedEnrichmentEvidencePool(ctx, answerDocMaxEnrichmentCandidateFacts)
	// The strict diagram validator and finalizer authoring capsule must consume
	// one exact relation source. Explorer EvidenceItems can legitimately contain
	// definitions while the request-scoped typed provider separately carries an
	// implements/extends/overrides edge. Append only coverage-gate-eligible
	// provider rows here so the model receives the exact direction before it
	// authors or repairs a diagram. This supplies evidence; it neither requires
	// a diagram nor rewrites the model-owned answer.
	evidence = answerDocAppendExactTypedRelationEvidence(ctx, evidence)
	canonicalCallEdges := make(map[string]types.CallChainEvidenceEdge)
	for _, edge := range types.CanonicalCallChainEvidenceEdges(evidence) {
		if key := answerDocCanonicalCallEdgeKey(edge.EvidenceID, edge.Source, edge.LineStart); key != "" {
			canonicalCallEdges[key] = edge
		}
	}
	acceptedFacts := 0
	callsiteFacts := 0
	stagePrecedence := answerDocVerifiedReadModeStagePrecedenceForRequest(ctx)
	requestSpineComplete := answerDocVerifiedReadModeStagePrecedenceCoversRequestedScope(ctx)
	edges := make([]answerDocMechanismRelationEdge, 0, len(stagePrecedence)+8)
	seenEdges := map[string]bool{}
	for _, relation := range stagePrecedence {
		from := answerDocRequestedParticipantIdentityForStageRow(ctx.AnalysisIR.RequestModel, relation.From)
		to := answerDocRequestedParticipantIdentityForStageRow(ctx.AnalysisIR.RequestModel, relation.To)
		loc := fmt.Sprintf("%s:%d-%d", relation.SourceFile, relation.LineStart, relation.LineEnd)
		key := strings.ToLower(string(types.DiagramRelPrecedence) + "\x00" + from + "\x00" + to + "\x00" + loc)
		seenEdges[key] = true
		edges = append(edges, answerDocMechanismRelationEdge{
			from: from, to: to, relation: types.DiagramRelPrecedence, loc: loc,
			requestScoped: true,
			requestSpine:  requestSpineComplete,
		})
	}
	for _, item := range evidence {
		if !answerDocGroundedCurrentSourceMechanismFact(item) {
			continue
		}
		acceptedFacts++
		if item.AnchorKind == types.AnchorCall {
			callsiteFacts++
		}
		// Authoring recipes must carry exactly the same authority that the
		// diagram validator will consume. Recovered / location-less facts are
		// useful prose context, but publishing a copyable edge from them would
		// teach an anchor that the strict source gate must later reject.
		if !item.IsCitable() {
			continue
		}
		relation, fromRaw, toRaw := answerDocMechanismRelationProjection(item, ctx.AnalysisIR.RequestModel)
		if !relation.IsValid() {
			continue
		}
		from := answerDocMechanismEvidenceEndpoint(item, fromRaw)
		to := answerDocMechanismEvidenceEndpoint(item, toRaw)
		anchorFrom, anchorTo := "", ""
		if relation == types.DiagramRelCall {
			evidenceID := firstNonEmptyAnswerDocString(item.ID, item.EvidenceRef)
			if key := answerDocCanonicalCallEdgeKey(evidenceID, item.Source, item.LineStart); key != "" {
				if edge, ok := canonicalCallEdges[key]; ok {
					if !types.AnswerCodeIdentitySurfacesEquivalent(from, edge.From) {
						anchorFrom = from
					}
					if !types.AnswerCodeIdentitySurfacesEquivalent(to, edge.To) {
						anchorTo = to
					}
					from, to = edge.From, edge.To
				}
			}
			// A call-site may carry a reader-friendly module/type-qualified
			// callee while the same callable's body necessarily uses its short
			// parser owner. Reuse the shared fail-closed identity bridge before
			// topology/copy-ready compilation so the renderer and strict diagram
			// validator consume one typed endpoint projection.
			if qualified, ok := types.ResolveUniqueQualifiedCallEndpoint(evidence, from); ok {
				from = qualified
			}
			if qualified, ok := types.ResolveUniqueQualifiedCallEndpoint(evidence, to); ok {
				to = qualified
			}
		}
		if from == "" || to == "" || strings.EqualFold(from, to) {
			continue
		}
		key := strings.ToLower(string(relation) + "\x00" + from + "\x00" + to + "\x00" + item.DisplayLocation(true))
		if seenEdges[key] {
			continue
		}
		seenEdges[key] = true
		edges = append(edges, answerDocMechanismRelationEdge{
			from:       from,
			to:         to,
			anchorFrom: anchorFrom,
			anchorTo:   anchorTo,
			relation:   relation,
			loc:        item.DisplayLocation(true),
			sourceItem: item,
		})
	}
	acceptedFacts += len(stagePrecedence)
	edges = answerDocPrincipalTypedRelationBoundaryEdges(ctx, edges)
	return evidence, edges, acceptedFacts, callsiteFacts
}

// answerDocPrincipalTypedRelationBoundaryEdges keeps a principal relation
// diagram/table authoring carrier on the same exact membership ceiling already
// accepted by the completion layer. The full evidence pool remains unchanged,
// so excluded typed relations can still support prose or an explicitly bounded
// audit view; they simply cannot re-enter the principal graph through a broader
// source-scope candidate roster.
//
// Declared type relations have one reviewed direction across languages:
// implementing/sub/overriding member -> queried contract/supertype. Other
// relation families are untouched. No labels, request text, model prose, or
// Mermaid body are read, and no edge is authored or rewritten.
func answerDocPrincipalTypedRelationBoundaryEdges(ctx *types.AgentContext, edges []answerDocMechanismRelationEdge) []answerDocMechanismRelationEdge {
	if ctx == nil || ctx.AnalysisIR == nil || len(edges) == 0 {
		return edges
	}
	members := types.PrincipalTypedRelationMemberNamesForRequest(
		answerDocStableAggregateFacts(ctx), &ctx.AnalysisIR.RequestModel,
	)
	if len(members) == 0 {
		return edges
	}
	out := make([]answerDocMechanismRelationEdge, 0, len(edges))
	for _, edge := range edges {
		if edge.relation != types.DiagramRelTypeRelation ||
			types.PrincipalTypedRelationMemberMatches(edge.from, members) {
			out = append(out, edge)
		}
	}
	return out
}

func answerDocAppendExactTypedRelationEvidence(ctx *types.AgentContext, evidence []types.EvidenceItem) []types.EvidenceItem {
	if ctx == nil || ctx.AnalysisIR == nil || ctx.Mutable == nil {
		return evidence
	}
	exact := tool.ExactTypedRelationEvidenceForRequest(
		types.ToolBusContext(ctx, types.AgentFinalizer),
		ctx.AnalysisIR.RequestModel,
	)
	if len(exact) == 0 {
		return evidence
	}
	out := append([]types.EvidenceItem(nil), evidence...)
	seen := make(map[string]bool, len(out)+len(exact))
	for _, item := range out {
		if id := strings.TrimSpace(item.ID); id != "" {
			seen[id] = true
		}
	}
	for _, item := range exact {
		if item.ID == "" || seen[item.ID] {
			continue
		}
		seen[item.ID] = true
		out = append(out, item)
	}
	return out
}

func answerDocCanonicalCallEdgeKey(evidenceID, source string, line int) string {
	evidenceID = strings.TrimSpace(evidenceID)
	if evidenceID == "" {
		return ""
	}
	return strings.ToLower(evidenceID) + "\x00" +
		strings.ToLower(strings.TrimSpace(source)) + "\x00" + strconv.Itoa(line)
}

// answerDocMechanismRelationProjection projects one already-typed
// EvidenceItem onto the exact relation and endpoint direction consumed by the
// hard validator. For a typed source-flow request, an exact assignment is
// taught in execution direction (RHS value -> LHS receiver) as data_flow.
// Other request axes retain the binding view (receiver -> bound value) as
// assignment. This reads only the schema-valid predicate axis and exact source
// tuple; it never derives a relation from request/answer prose.
func answerDocMechanismRelationProjection(item types.EvidenceItem, rm types.RequestModel) (types.DiagramRelationKind, string, string) {
	if types.IsRepoMapTypeRelationEvidence(item) {
		return types.DiagramRelTypeRelation, item.Subject, item.Object
	}
	if types.ClaimFormOf(item) == types.ClaimAssignmentFact {
		receiver, value, ok := types.AssignmentEvidenceEndpoints(item)
		if !ok || !types.AssignmentEvidenceEndpointsMatch(item) {
			return types.DiagramRelUnknown, "", ""
		}
		if rm.PredicateAxis == types.AxisFlow {
			return types.DiagramRelDataFlow, value, receiver
		}
		return types.DiagramRelAssignment, receiver, value
	}
	return types.RelationForClaimForm(types.ClaimFormOf(item)), item.Subject, item.Object
}

func answerDocMechanismEvidenceEndpoint(item types.EvidenceItem, raw string) string {
	raw = strings.TrimSpace(raw)
	if projected, ok := types.DeterministicSourceQualifiedEvidenceSymbol(item, raw); ok {
		return projected
	}
	return raw
}

// answerDocMechanismUnaryAnnotations is a closed, typed projection for source
// facts that have one participant by definition. Guard conditions are the
// first supported member. Binary guards continue through the ordinary
// relation graph; unknown or future unary shapes fail closed until their
// visual semantics are explicitly reviewed.
func answerDocMechanismUnaryAnnotations(evidence []types.EvidenceItem) []answerDocMechanismUnaryAnnotation {
	const limit = 4
	out := make([]answerDocMechanismUnaryAnnotation, 0, limit)
	seen := make(map[string]bool)
	for _, item := range evidence {
		if len(out) >= limit || !item.IsCitable() || types.ClaimFormOf(item) != types.ClaimGuardCondition {
			continue
		}
		relation, _, object := answerDocMechanismRelationProjection(item, types.RequestModel{})
		if relation != types.DiagramRelGuard || strings.TrimSpace(object) != "" {
			continue
		}
		participant := firstNonEmptyAnswerDocString(item.Subject, item.OwnerIdentity, item.OwnerSymbol)
		participant = answerDocMechanismEvidenceEndpoint(item, participant)
		detail := strings.TrimSpace(item.Condition)
		if participant == "" || detail == "" || strings.ContainsAny(participant+detail, "\r\n") {
			continue
		}
		loc := item.DisplayLocation(true)
		key := strings.ToLower(string(relation) + "\x00" + participant + "\x00" + detail + "\x00" + loc)
		if seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, answerDocMechanismUnaryAnnotation{
			participant: participant,
			relation:    relation,
			detail:      detail,
			loc:         loc,
		})
	}
	return out
}

func renderAnswerDocMechanismRelationAuthoringCapsule(
	b *strings.Builder,
	edges []answerDocMechanismRelationEdge,
	unaryAnnotations []answerDocMechanismUnaryAnnotation,
	semanticHandoffs []answerDocRegisteredExportHandoff,
	limit int,
	copyReadyKind types.DiagramKind,
	requestedKind types.DiagramKind,
	requestScopedRelationComplete bool,
) answerDocMechanismAuthoringReceipts {
	if b == nil || len(edges)+len(unaryAnnotations) == 0 || limit <= 0 {
		return answerDocMechanismAuthoringReceipts{}
	}
	// Source authority and visual authority have different cardinalities. Two
	// grounded call sites may prove the same directed endpoint relation; they
	// remain distinct in the source-fact counters above, but a diagram has one
	// visible arrow for that exact (from, to, relation) tuple. Collapse those
	// duplicates before bounding so repeated call sites cannot consume the
	// compact view and hide unrelated typed relations.
	visualEdges := edges
	collapsedVisualDuplicates := 0
	if copyReadyKind != types.DiagramNone {
		visualEdges, collapsedVisualDuplicates = answerDocMechanismUniqueVisualEdges(edges)
	}
	aliases := make([]answerDocMechanismAliasRow, 0, limit*2)
	aliasFor := func(identity string) string {
		for _, row := range aliases {
			if row.identity == identity {
				return row.alias
			}
		}
		alias := fmt.Sprintf("n%d", len(aliases)+1)
		aliases = append(aliases, answerDocMechanismAliasRow{identity: identity, alias: alias})
		return alias
	}

	// Keep the exact invocation edges incident to a proved registered-export
	// handoff ahead of unrelated helper fan-out before applying the compact
	// authoring cap. Otherwise a broad callable body can fill the first N rows
	// and make the authority capsule claim that the native/export bridge is
	// disconnected even though the same typed evidence pool proves both sides.
	// This is stable typed-edge selection only: it neither creates an edge nor
	// changes its direction, relation, endpoint, or reader-facing wording.
	visualEdges = answerDocMechanismPrioritizeRegisteredExportEdges(visualEdges, semanticHandoffs)
	bounded := visualEdges
	if len(bounded) > limit {
		bounded = bounded[:limit]
	}
	recipes := make([]answerDocMechanismRecipeRow, 0, len(bounded))
	for _, edge := range bounded {
		fromAlias := aliasFor(edge.from)
		toAlias := aliasFor(edge.to)
		typedAnchor := types.DiagramEdgeAnchor{
			FromNode:     fromAlias,
			ToNode:       toAlias,
			FromIdentity: firstNonEmptyAnswerDocString(edge.anchorFrom, edge.from),
			ToIdentity:   firstNonEmptyAnswerDocString(edge.anchorTo, edge.to),
			RelationKind: edge.relation,
		}
		payload, err := json.Marshal(typedAnchor)
		if err != nil {
			continue
		}
		recipes = append(recipes, answerDocMechanismRecipeRow{
			edge:   edge,
			from:   fromAlias,
			to:     toAlias,
			anchor: string(payload),
			typed:  typedAnchor,
		})
	}
	if len(recipes) == 0 && len(unaryAnnotations) == 0 {
		return answerDocMechanismAuthoringReceipts{}
	}

	b.WriteString("\n### Typed relation authoring capsule (advisory)\n\n")
	handoffRows := answerDocMechanismSemanticHandoffRows(aliases, semanticHandoffs)
	handoffAnchors := answerDocMechanismSemanticHandoffAnchors(handoffRows)
	renderAnswerDocMechanismRelationComponentBoundary(
		b, aliases, recipes, handoffRows, requestScopedRelationComplete,
	)
	for i, anchor := range handoffAnchors {
		payload, err := json.Marshal(anchor)
		if err != nil {
			continue
		}
		fmt.Fprintf(b, "- semantic_handoff_relation[%d]=`%s -> %s`; relation_kind=`register`; edge_anchor_json=`%s`. If a model-authored principal list/table selects both endpoint identities, copy this row there with claim_form=registration_edge. If a model-authored Mermaid diagram selects both components, keep this exact direction as one visible, explicitly labelled binding edge with the same relation_kind=register anchor. It is not a call, callback, execution-order, return, or value-flow edge.\n",
			i+1, anchor.FromNode, anchor.ToNode, payload)
	}
	unaryRows := make([]answerDocMechanismUnaryAnnotationRow, 0, len(unaryAnnotations))
	for _, annotation := range unaryAnnotations {
		participantAlias := aliasFor(annotation.participant)
		unaryRows = append(unaryRows, answerDocMechanismUnaryAnnotationRow{
			annotation:  annotation,
			participant: participantAlias,
		})
	}
	if copyReadyKind == types.DiagramNone {
		b.WriteString("- Node aliases are local convenience identifiers, not new facts. In a Mermaid body declare the same alias as the node/participant ID; `from_node` and `to_node` must be these body identifiers. The identity below is endpoint authority, not mandatory primary display copy: author the visible label in the user's domain and keep the exact identity only as a secondary label when useful.\n")
		for _, row := range aliases {
			fmt.Fprintf(b, "- node_alias[%s]=`%s`\n", row.alias, row.identity)
		}
		for i, recipe := range recipes {
			fmt.Fprintf(b, "- edge_recipe[%d]=`%s -> %s`; relation_kind=`%s`; edge_anchor_json=`%s`",
				i+1, recipe.from, recipe.to, recipe.edge.relation, recipe.anchor)
			if recipe.edge.loc != "" {
				fmt.Fprintf(b, " @ %s", recipe.edge.loc)
			}
			b.WriteString("\n")
		}
		renderAnswerDocMechanismCopyReadyComponentFragments(b, aliases, recipes, handoffRows, requestedKind)
		for i, row := range unaryRows {
			fmt.Fprintf(b, "- unary_note_recipe[%d]=`%s`; participant=`%s`; relation_kind=`%s`; detail=`%s`",
				i+1, row.participant, row.annotation.participant, row.annotation.relation, row.annotation.detail)
			if row.annotation.loc != "" {
				fmt.Fprintf(b, " @ %s", row.annotation.loc)
			}
			b.WriteString("\n")
		}
		for i, row := range handoffRows {
			fmt.Fprintf(b, "- semantic_handoff_edge_recipe[%d]=`%s -> %s`; relation_kind=`register`; call_target=`%s`; registered_callable=`%s`; draw only when the model selects both components, use business wording, and do not describe it as an invocation or execution order.\n",
				i+1, row.from, row.to, answerDocCallChainInline(row.handoff.callTarget), answerDocCallChainInline(row.handoff.registeredCallable))
		}
	} else {
		b.WriteString("- A validator-aligned typed topology template and identity anchor array follow from the diagram-expressible, unambiguous subset of the typed recipe set. This is authoring input, not an acceptance-ready answer: every directed arrow carries the literal syntax-safe placeholder `AUTHOR_BUSINESS_ACTION`, and its anchor omits `visible_label`. Sequence diagrams keep non-message typed facts as unanchored Notes when possible; flow-family diagrams may keep reviewed unary facts as standalone unanchored fact nodes. Neither carrier is an edge or can satisfy call/callback authority. Relations that the selected family cannot carry remain valid sibling facts in the full capsule above. If you include the optional diagram, preserve its node IDs, exact edge topology, annotation carriers, and anchor identity fields; replace each placeholder with one concise business/domain action and copy it byte-identically into both the Mermaid message and matching anchor `visible_label`. Do not emit the template unchanged or compose a different story graph.\n")
		for i, row := range unaryRows {
			fmt.Fprintf(b, "- unary_note_recipe[%d]=`%s`; participant=`%s`; relation_kind=`%s`; detail=`%s`",
				i+1, row.participant, row.annotation.participant, row.annotation.relation, row.annotation.detail)
			if row.annotation.loc != "" {
				fmt.Fprintf(b, " @ %s", row.annotation.loc)
			}
			b.WriteString("\n")
		}
		renderAnswerDocMechanismCopyReadyDiagram(b, aliases, recipes, unaryRows, handoffRows, copyReadyKind)
	}
	if collapsedVisualDuplicates > 0 {
		fmt.Fprintf(b, "- source_relation_duplicates_collapsed_for_visual=%d; source facts remain counted above, while the diagram keeps one arrow per exact typed endpoint relation.\n", collapsedVisualDuplicates)
	}
	if len(visualEdges) > len(bounded) {
		fmt.Fprintf(b, "- (%d additional unique typed relation(s) omitted only from this compact authoring view)\n", len(visualEdges)-len(bounded))
	}
	anchors := make([]types.DiagramEdgeAnchor, 0, len(recipes))
	for _, recipe := range recipes {
		anchors = append(anchors, recipe.typed)
	}
	return answerDocMechanismAuthoringReceipts{
		relationAnchors:        anchors,
		semanticHandoffAnchors: handoffAnchors,
	}
}

func answerDocMechanismSemanticHandoffAnchors(rows []answerDocMechanismSemanticHandoffRow) []types.DiagramEdgeAnchor {
	out := make([]types.DiagramEdgeAnchor, 0, len(rows))
	for _, row := range rows {
		fromIdentity := strings.TrimSpace(row.handoff.callTarget)
		toIdentity := strings.TrimSpace(row.handoff.registeredCallable)
		if strings.TrimSpace(row.from) == "" || strings.TrimSpace(row.to) == "" ||
			fromIdentity == "" || toIdentity == "" {
			continue
		}
		out = append(out, types.DiagramEdgeAnchor{
			FromNode: row.from, ToNode: row.to,
			FromIdentity: fromIdentity, ToIdentity: toIdentity,
			RelationKind: types.DiagramRelRegister,
		})
	}
	return out
}

func answerDocMechanismPrioritizeRegisteredExportEdges(
	edges []answerDocMechanismRelationEdge,
	handoffs []answerDocRegisteredExportHandoff,
) []answerDocMechanismRelationEdge {
	if len(edges) < 2 || len(handoffs) == 0 {
		return edges
	}
	priority := func(edge answerDocMechanismRelationEdge) bool {
		for _, handoff := range handoffs {
			if edge.relation == types.DiagramRelCall &&
				(types.AnswerCodeIdentitySurfacesEquivalent(edge.to, handoff.callTarget) ||
					types.AnswerCodeIdentitySurfacesEquivalent(edge.from, handoff.registeredCallable)) {
				return true
			}
			if strings.TrimSpace(handoff.bindingEvidenceID) != "" &&
				(strings.TrimSpace(edge.sourceItem.ID) == strings.TrimSpace(handoff.bindingEvidenceID) ||
					strings.TrimSpace(edge.sourceItem.EvidenceRef) == strings.TrimSpace(handoff.bindingEvidenceID)) {
				return true
			}
		}
		return false
	}
	out := make([]answerDocMechanismRelationEdge, 0, len(edges))
	for _, edge := range edges {
		if priority(edge) {
			out = append(out, edge)
		}
	}
	for _, edge := range edges {
		if !priority(edge) {
			out = append(out, edge)
		}
	}
	return out
}

// renderAnswerDocMechanismCopyReadyComponentFragments gives a required flow
// question a directly reusable representation of each independently verified
// relation component when the typed evidence does not authorize one complete
// story graph. It reuses the already-bounded recipes and exact n# aliases; it
// never adds an edge, orders components, or connects them. The model remains
// responsible for selecting useful components, adding requested disconnected
// participants/boundaries, and authoring all visible business wording.
func renderAnswerDocMechanismCopyReadyComponentFragments(
	b *strings.Builder,
	aliases []answerDocMechanismAliasRow,
	recipes []answerDocMechanismRecipeRow,
	semanticHandoffs []answerDocMechanismSemanticHandoffRow,
	kind types.DiagramKind,
) {
	if b == nil || len(aliases) == 0 || len(recipes) == 0 {
		return
	}
	if kind != types.DiagramSequence && kind != types.DiagramFlow && kind != types.DiagramArchitecture && kind != types.DiagramCallDAG {
		return
	}
	components := answerDocMechanismRelationComponents(aliases, recipes)
	if len(components) == 0 {
		return
	}
	type fragment struct {
		aliases     []answerDocMechanismAliasRow
		recipes     []answerDocMechanismRecipeRow
		annotations []answerDocMechanismRecipeRow
		anchors     []types.DiagramEdgeAnchor
	}
	fragments := make([]fragment, 0, len(components))
	for _, component := range components {
		members := make(map[string]bool, len(component))
		for _, row := range component {
			members[row.alias] = true
		}
		componentRecipes := make([]answerDocMechanismRecipeRow, 0, len(recipes))
		for _, recipe := range recipes {
			if members[recipe.from] && members[recipe.to] {
				componentRecipes = append(componentRecipes, recipe)
			}
		}
		diagramRecipes, annotationRecipes, _ := answerDocMechanismCopyReadyRecipes(componentRecipes, kind)
		if len(diagramRecipes)+len(annotationRecipes) == 0 {
			continue
		}
		used := make(map[string]bool, (len(diagramRecipes)+len(annotationRecipes))*2)
		anchors := make([]types.DiagramEdgeAnchor, 0, len(diagramRecipes))
		for _, recipe := range diagramRecipes {
			used[recipe.from] = true
			used[recipe.to] = true
			anchors = append(anchors, recipe.typed)
		}
		for _, recipe := range annotationRecipes {
			used[recipe.from] = true
			used[recipe.to] = true
		}
		componentAliases := make([]answerDocMechanismAliasRow, 0, len(used))
		for _, row := range component {
			if used[row.alias] {
				componentAliases = append(componentAliases, row)
			}
		}
		fragments = append(fragments, fragment{
			aliases: componentAliases, recipes: diagramRecipes,
			annotations: annotationRecipes, anchors: anchors,
		})
	}
	if len(fragments) == 0 {
		return
	}
	b.WriteString("- Typed topology component templates follow. Each fence and its sibling anchor array are one self-consistent local topology carrier: copy node IDs, arrows, and anchors together, then replace every `AUTHOR_BUSINESS_ACTION` placeholder with a business/domain label in both the Mermaid message and matching anchor `visible_label`. Anchor arrays intentionally omit `visible_label`; do not emit a template unchanged. ")
	if len(semanticHandoffs) == 0 {
		b.WriteString("Fragments are mutually unordered and disconnected; selecting several never authorizes an inter-fragment edge or a complete-flow conclusion.\n")
	} else {
		b.WriteString("Source-level call arrows remain local to their fragments. Only the exact registered-export handoff recipes below may relate their named aliases as visibly labelled relation_kind=register binding edges; every other inter-fragment edge and all cross-component execution order remain unproven.\n")
	}
	for i, part := range fragments {
		fmt.Fprintf(b, "\n#### Verified component fragment %d (not a complete flow)\n\n", i+1)
		b.WriteString("```mermaid\n")
		if kind == types.DiagramSequence {
			b.WriteString("sequenceDiagram\n")
			for _, row := range part.aliases {
				fmt.Fprintf(b, "  participant %s as %s\n", row.alias, answerDocMechanismMermaidLabel(row.identity))
			}
			for _, recipe := range part.recipes {
				fmt.Fprintf(b, "  %s->>%s: %s\n", recipe.from, recipe.to, answerDocMechanismVisibleActionPlaceholder)
			}
			for _, recipe := range part.annotations {
				fmt.Fprintf(b, "  Note over %s,%s: %s\n", recipe.from, recipe.to,
					answerDocMechanismSequenceNotePlaceholder(recipe.edge.relation))
			}
		} else {
			b.WriteString("flowchart TD\n")
			for _, row := range part.aliases {
				fmt.Fprintf(b, "  %s[\"%s\"]\n", row.alias, answerDocMechanismMermaidLabel(row.identity))
			}
			for _, recipe := range part.recipes {
				fmt.Fprintf(b, "  %s -->|%s| %s\n", recipe.from, answerDocMechanismVisibleActionPlaceholder, recipe.to)
			}
		}
		b.WriteString("```\n")
		anchorJSON, err := json.Marshal(part.anchors)
		if err == nil {
			fmt.Fprintf(b, "- component_edge_anchors_json[%d]=`%s`\n", i+1, anchorJSON)
		}
	}
	for i, row := range semanticHandoffs {
		anchor := types.DiagramEdgeAnchor{FromNode: row.from, ToNode: row.to, FromIdentity: row.handoff.callTarget, ToIdentity: row.handoff.registeredCallable, RelationKind: types.DiagramRelRegister}
		payload, _ := json.Marshal(anchor)
		fmt.Fprintf(b, "- handoff_aware_composition_recipe[%d]=`%s -> %s`; if both source-edge fragments are selected in one diagram, preserve their existing aliases/arrows/anchors and add one visible binding edge with model-authored business wording plus exact `relation_kind=register` owner `edge_anchor_json=%s`. This binding is not a call, callback, value-flow, return, or execution-order claim.\n",
			i+1, row.from, row.to, payload)
	}
}

type answerDocMechanismSemanticHandoffRow struct {
	from    string
	to      string
	handoff answerDocRegisteredExportHandoff
}

// answerDocRegisteredExportHandoffsForContext reuses the same exact
// current-code-path join that powers the textual call-chain handoff. It adds
// presentation input only: no EvidenceItem, call edge, answer sentence, or
// conclusion is created here.
func answerDocRegisteredExportHandoffsForContext(ctx *types.AgentContext) []answerDocRegisteredExportHandoff {
	plan := answerSupportPlan(ctx)
	if plan == nil || plan.Family != types.QFCallChain {
		return nil
	}
	var entries []types.AnswerSupportEntry
	for _, lane := range plan.Lanes {
		if lane.Kind == types.SupportLaneCurrentCodePath {
			entries = append(entries, lane.Entries...)
		}
	}
	return answerDocRegisteredExportHandoffs(entries)
}

// answerDocMechanismSemanticHandoffRows maps an already-proved export binding
// onto existing diagram aliases. Both endpoints must resolve uniquely. The
// result is rendered only as a Note/non-edge fact, preserving the distinction
// between registration and source-level invocation.
func answerDocMechanismSemanticHandoffRows(
	aliases []answerDocMechanismAliasRow,
	handoffs []answerDocRegisteredExportHandoff,
) []answerDocMechanismSemanticHandoffRow {
	if len(aliases) == 0 || len(handoffs) == 0 {
		return nil
	}
	resolve := func(identity string) (string, bool) {
		match := ""
		for _, row := range aliases {
			if !types.AnswerCodeIdentitySurfacesEquivalent(row.identity, identity) {
				continue
			}
			if match != "" && match != row.alias {
				return "", false
			}
			match = row.alias
		}
		return match, match != ""
	}
	seen := make(map[string]bool)
	out := make([]answerDocMechanismSemanticHandoffRow, 0, len(handoffs))
	for _, handoff := range handoffs {
		from, fromOK := resolve(handoff.callTarget)
		to, toOK := resolve(handoff.registeredCallable)
		if !fromOK || !toOK || from == to {
			continue
		}
		key := from + "\x00" + to
		if seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, answerDocMechanismSemanticHandoffRow{from: from, to: to, handoff: handoff})
	}
	return out
}

func answerDocMechanismUniqueVisualEdges(edges []answerDocMechanismRelationEdge) ([]answerDocMechanismRelationEdge, int) {
	if len(edges) == 0 {
		return nil, 0
	}
	out := make([]answerDocMechanismRelationEdge, 0, len(edges))
	seen := make(map[string]bool, len(edges))
	duplicates := 0
	for _, edge := range edges {
		key := edge.from + "\x00" + edge.to + "\x00" + string(edge.relation)
		if seen[key] {
			duplicates++
			continue
		}
		seen[key] = true
		out = append(out, edge)
	}
	return out, duplicates
}

// answerDocMechanismSequenceDisplayOrder gives an already-grounded acyclic
// invocation graph a reader-facing order without changing its topology. The
// evidence pool is assembled from several producers, so its slice order can
// start at a terminal body call and end at the requested entrypoint. Copying
// that order into a sequenceDiagram makes a true graph read backwards.
//
// This normalization consumes only typed endpoints and source locations:
// roots precede their descendants, and sibling calls owned by the same caller
// keep grounded source-line order. It never creates, removes, reverses, or
// relabels an edge. Cycles fail open to the original order because a static
// cycle has no unique root-first sequence authority.
func answerDocMechanismSequenceDisplayOrder(
	aliases []answerDocMechanismAliasRow,
	recipes []answerDocMechanismRecipeRow,
) ([]answerDocMechanismAliasRow, []answerDocMechanismRecipeRow, bool) {
	if len(recipes) < 2 {
		return aliases, recipes, true
	}

	aliasOrder := make(map[string]int, len(aliases))
	for i, row := range aliases {
		aliasOrder[row.alias] = i
	}
	firstSeen := func(alias string) int {
		if order, ok := aliasOrder[alias]; ok {
			return order
		}
		return len(aliases) + len(recipes)
	}

	indegree := make(map[string]int, len(aliases))
	outgoing := make(map[string][]int, len(aliases))
	nodes := make(map[string]bool, len(aliases))
	for i, recipe := range recipes {
		nodes[recipe.from] = true
		nodes[recipe.to] = true
		outgoing[recipe.from] = append(outgoing[recipe.from], i)
		indegree[recipe.to]++
		if _, ok := indegree[recipe.from]; !ok {
			indegree[recipe.from] = 0
		}
	}

	ready := make([]string, 0, len(nodes))
	for node := range nodes {
		if indegree[node] == 0 {
			ready = append(ready, node)
		}
	}
	sort.SliceStable(ready, func(i, j int) bool { return firstSeen(ready[i]) < firstSeen(ready[j]) })
	if len(ready) == 0 {
		return aliases, recipes, false
	}

	ordered := make([]answerDocMechanismRecipeRow, 0, len(recipes))
	processedNode := make(map[string]bool, len(nodes))
	for len(ready) > 0 {
		current := ready[0]
		ready = ready[1:]
		if processedNode[current] {
			continue
		}
		processedNode[current] = true

		edgeIndexes := append([]int(nil), outgoing[current]...)
		sort.SliceStable(edgeIndexes, func(i, j int) bool {
			left := recipes[edgeIndexes[i]].edge.sourceItem
			right := recipes[edgeIndexes[j]].edge.sourceItem
			leftSource := strings.TrimSpace(left.Source)
			rightSource := strings.TrimSpace(right.Source)
			if leftSource != "" && leftSource == rightSource && left.LineStart > 0 && right.LineStart > 0 && left.LineStart != right.LineStart {
				return left.LineStart < right.LineStart
			}
			return edgeIndexes[i] < edgeIndexes[j]
		})
		newlyReady := make([]string, 0, len(edgeIndexes))
		for _, edgeIndex := range edgeIndexes {
			recipe := recipes[edgeIndex]
			ordered = append(ordered, recipe)
			indegree[recipe.to]--
			if indegree[recipe.to] == 0 {
				newlyReady = append(newlyReady, recipe.to)
			}
		}
		sort.SliceStable(newlyReady, func(i, j int) bool { return firstSeen(newlyReady[i]) < firstSeen(newlyReady[j]) })
		ready = append(ready, newlyReady...)
	}
	if len(ordered) != len(recipes) {
		return aliases, recipes, false
	}

	usedAliases := make(map[string]bool, len(aliases))
	orderedAliases := make([]answerDocMechanismAliasRow, 0, len(aliases))
	appendAlias := func(alias string) {
		if alias == "" || usedAliases[alias] {
			return
		}
		for _, row := range aliases {
			if row.alias == alias {
				usedAliases[alias] = true
				orderedAliases = append(orderedAliases, row)
				return
			}
		}
	}
	for _, recipe := range ordered {
		appendAlias(recipe.from)
		appendAlias(recipe.to)
	}
	for _, row := range aliases {
		appendAlias(row.alias)
	}
	return orderedAliases, ordered, true
}

func answerDocMechanismRelationGraphTopology(edges []answerDocMechanismRelationEdge) (answerDocMechanismRelationTopology, bool) {
	unique, _ := answerDocMechanismUniqueVisualEdges(edges)
	if len(unique) == 0 {
		return answerDocMechanismRelationTopology{}, false
	}
	nodes := make(map[string]bool, len(unique)*2)
	indegree := make(map[string]int, len(unique)*2)
	outdegree := make(map[string]int, len(unique)*2)
	adjacent := make(map[string]map[string]bool, len(unique)*2)
	for _, edge := range unique {
		nodes[edge.from] = true
		nodes[edge.to] = true
		outdegree[edge.from]++
		indegree[edge.to]++
		if adjacent[edge.from] == nil {
			adjacent[edge.from] = make(map[string]bool)
		}
		if adjacent[edge.to] == nil {
			adjacent[edge.to] = make(map[string]bool)
		}
		adjacent[edge.from][edge.to] = true
		adjacent[edge.to][edge.from] = true
	}
	topology := answerDocMechanismRelationTopology{
		uniqueEdges: len(unique),
		nodes:       len(nodes),
	}
	for node := range nodes {
		if outdegree[node] > topology.maxOutDegree {
			topology.maxOutDegree = outdegree[node]
		}
		if indegree[node] > topology.maxInDegree {
			topology.maxInDegree = indegree[node]
		}
	}
	topology.fanOutPresent = topology.maxOutDegree > 1
	topology.fanInPresent = topology.maxInDegree > 1
	visited := make(map[string]bool, len(nodes))
	for root := range nodes {
		if visited[root] {
			continue
		}
		topology.weakComponents++
		visited[root] = true
		queue := []string{root}
		for len(queue) > 0 {
			current := queue[0]
			queue = queue[1:]
			for next := range adjacent[current] {
				if visited[next] {
					continue
				}
				visited[next] = true
				queue = append(queue, next)
			}
		}
	}
	topology.disconnected = topology.weakComponents > 1
	if topology.weakComponents == 1 && len(unique) == len(nodes)-1 && !topology.fanOutPresent && !topology.fanInPresent {
		sources := 0
		sinks := 0
		valid := true
		for node := range nodes {
			switch {
			case indegree[node] == 0 && outdegree[node] == 1:
				sources++
			case indegree[node] == 1 && outdegree[node] == 0:
				sinks++
			case indegree[node] == 1 && outdegree[node] == 1:
			default:
				valid = false
			}
		}
		topology.singleLinearGraph = valid && sources == 1 && sinks == 1
	}
	return topology, true
}

func renderAnswerDocMechanismRelationComponentBoundary(
	b *strings.Builder,
	aliases []answerDocMechanismAliasRow,
	recipes []answerDocMechanismRecipeRow,
	semanticHandoffs []answerDocMechanismSemanticHandoffRow,
	requestScopedRelationComplete bool,
) {
	if b == nil || len(aliases) == 0 || len(recipes) == 0 {
		return
	}
	components := answerDocMechanismRelationComponents(aliases, recipes)
	if len(components) == 0 {
		return
	}
	componentForAlias := make(map[string]int, len(aliases))
	for i, component := range components {
		for _, row := range component {
			componentForAlias[row.alias] = i
		}
	}
	crossComponentHandoffs := make([]answerDocMechanismSemanticHandoffRow, 0, len(semanticHandoffs))
	for _, row := range semanticHandoffs {
		fromComponent, fromOK := componentForAlias[row.from]
		toComponent, toOK := componentForAlias[row.to]
		if fromOK && toOK && fromComponent != toComponent {
			crossComponentHandoffs = append(crossComponentHandoffs, row)
		}
	}
	bridgeStatus := "not_applicable_single_component"
	if len(components) > 1 {
		bridgeStatus = "unproven_between_components"
		if len(crossComponentHandoffs) > 0 {
			bridgeStatus = "registered_export_binding_between_components"
		} else if requestScopedRelationComplete {
			bridgeStatus = "typed_participant_carrier_join_available"
		}
	}
	requestSpineComponents := 0
	requestScopedRelations := 0
	for _, recipe := range recipes {
		if recipe.edge.requestScoped {
			requestScopedRelations++
		}
	}
	for _, component := range components {
		if answerDocMechanismComponentCarriesRequestSpine(component, recipes) {
			requestSpineComponents++
		}
	}
	fmt.Fprintf(b, "- verified_relation_component_count=%d; inter_component_bridge_status=`%s`.\n",
		len(components), bridgeStatus)
	for i, component := range components {
		members := make([]string, 0, len(component))
		for _, row := range component {
			members = append(members, fmt.Sprintf("%s:%s", row.alias, row.identity))
		}
		relationClass, internalEdges := answerDocMechanismComponentRelationClass(component, recipes)
		answerRole := "supporting_grounded_segment"
		if answerDocMechanismComponentCarriesRequestSpine(component, recipes) {
			answerRole = "requested_relation_spine"
		}
		fmt.Fprintf(b, "- verified_component[%d]=`%s`; relation_segment_class=`%s`; answer_role=`%s`; internal_typed_edge_count=%d\n",
			i+1, strings.Join(members, " | "), relationClass, answerRole, internalEdges)
	}
	if requestSpineComponents > 0 {
		fmt.Fprintf(b, "- requested_relation_spine_component_count=%d; this role comes only from a request-scoped typed authority provider and does not promote sibling facts or invent a bridge.\n", requestSpineComponents)
		renderAnswerDocMechanismPrincipalDiagramRecipe(b, aliases, recipes)
	} else if requestScopedRelationComplete {
		b.WriteString("- requested_relation_spine_status=`proved_through_typed_participant_carrier_join`. The exact typed endpoint rows form one complete requested-participant relation only when the model reuses each candidate-declared participant node on its declared endpoint side. Preserve the listed edge identities and directions; do not replace the bounded join with a direct synthetic edge, and do not emit requested_relation_scope=partial_unproven for this proved shape.\n")
		b.WriteString("- Multi-edge join guidance (soft): when two listed relations share one exact technical endpoint, keep that endpoint as one Mermaid node and attach each relation to its candidate-authorized requested participant node. The model still selects the useful rows and authors every visible label, node ID, layout, diagram, and conclusion; this authority creates or rewrites none of them.\n")
	} else if requestScopedRelations > 0 {
		fmt.Fprintf(b, "- requested_relation_spine_status=`unproven`; request_scoped_typed_relation_subset_count=%d. The verified subset does not cover every typed incident participant, so it remains supporting evidence and is not a complete answer to the requested relation.\n", requestScopedRelations)
		b.WriteString("- requested_relation_scope_recipe={requested_relation_scope:`partial_unproven`,placement:`exactly_one_requested_relation_diagram_block`}. Copy this typed model-authored field so the renderer can disclose the bounded whole-diagram scope in reader language. The field creates no edge and does not replace your conclusion; never copy the raw enum into visible prose or Mermaid labels.\n")
		b.WriteString("- Required-diagram boundary: preserve any useful verified subset, but do not call it the complete requested flow or let disconnected local operations stand in for missing carrier/participant relations. Investigate a typed bridge when available; otherwise keep the missing requested relation explicit with the existing participant boundary. You still author the diagram and conclusion; this authority adds no edge.\n")
		b.WriteString("- Principal-diagram display guidance (soft): prioritize the requested participant identities as visible nodes together with any proved request-scoped relation subset. Keep disconnected local implementation operations in prose or a separate bounded support visual unless they materially explain a requested participant relation. Use concise repository/domain/business wording for visible labels and keep exact implementation symbols in citations or typed anchors. Preserve uncovered requested participants as visible disconnected nodes with unproven participant boundaries. This is selection and language guidance only: the model still authors every visible label, node, edge, diagram, and conclusion; this authority adds or rewrites none of them.\n")
	}
	if len(components) > 1 {
		b.WriteString("- cross_component_execution_order_status=`unproven`; cross_component_value_handoff_status=`unproven`; component indices are stable identifiers, not execution/phase order.\n")
		if len(crossComponentHandoffs) > 0 {
			fmt.Fprintf(b, "- cross_component_registered_export_handoff_count=%d; each row is an exact non-call binding between the named aliases. It may join invocation fragments at the export/callable boundary, but does not create a source call, callback, value transfer, or execution order.\n", len(crossComponentHandoffs))
			for i, row := range crossComponentHandoffs {
				fmt.Fprintf(b, "- cross_component_registered_export_handoff[%d]=`%s,%s`; call_target=`%s`; registered_callable=`%s`.\n",
					i+1, row.from, row.to, answerDocCallChainInline(row.handoff.callTarget), answerDocCallChainInline(row.handoff.registeredCallable))
			}
		}
		b.WriteString("- Reader-facing language boundary: `verified_component`, component indices, `relation_segment_class`, `answer_role`, and bridge/status tokens in this authority block are internal validation metadata. Do not copy those tokens into Mermaid labels/Notes, titles, tables, or answer prose. Express each proved segment with the repository's domain participants and operations; if no useful domain annotation exists, omit the visible Note. This does not authorize a cross-component edge.\n")
		if len(crossComponentHandoffs) == 0 && !requestScopedRelationComplete {
			b.WriteString("- These are separate components in the bounded citable relation projection. This means the current typed carrier has no proved bridge between them; it does NOT prove the program can never connect them. Present them as independently proved segments in sibling sections/bullets, disclose the missing bridge, or investigate a citable bridge. Do not place the components as consecutive numbered hops. Do not narrate them as one continuous end-to-end path.\n")
		} else if len(crossComponentHandoffs) == 0 {
			b.WriteString("- The exact operation endpoints remain separate components only in this compact technical projection. The shared typed participant-carrier mapping proves a bounded model-authorable join through the listed rows; reuse those participant nodes and the shared technical endpoint instead of inventing a direct inter-component arrow.\n")
		} else {
			b.WriteString("- Source-level call components remain separate because a registered-export binding is not a source call edge. The exact handoff rows above are nevertheless proved semantic bridges between only their named aliases. When composing those invocation fragments, preserve each selected bridge as a visibly labelled relation_kind=register edge with its exact typed owner; keep every unlisted component pair disconnected, and do not turn the binding into execution order.\n")
		}
		if requestSpineComponents > 0 {
			b.WriteString("- Required-diagram selection: make the `requested_relation_spine` component the principal visual when it already covers the requested relation axis. A disconnected `supporting_grounded_segment` is additional evidence, not a missing hop and not a requirement to place both components in one diagram; keep it in prose or a separate clearly bounded visual when useful. Never add an inter-component arrow merely to make one picture. The model still authors the visible diagram and may select less only when it preserves every explicitly requested participant/dimension.\n")
		}
	}
}

// renderAnswerDocMechanismPrincipalDiagramRecipe projects the already-typed
// request spine into a compact repair-first recipe. It does not author a
// Mermaid body or infer an edge: every row is a strict subset of the same
// recipe set consumed by validation. Disconnected grounded siblings stay in
// the full capsule for prose or a separately bounded visual, so they cannot
// crowd a requested relation off the principal diagram during retries.
func renderAnswerDocMechanismPrincipalDiagramRecipe(
	b *strings.Builder,
	aliases []answerDocMechanismAliasRow,
	recipes []answerDocMechanismRecipeRow,
) {
	if b == nil || len(aliases) == 0 || len(recipes) == 0 {
		return
	}
	principal := make([]answerDocMechanismRecipeRow, 0, len(recipes))
	principalAliases := make(map[string]bool)
	for _, recipe := range recipes {
		if !recipe.edge.requestSpine {
			continue
		}
		principal = append(principal, recipe)
		principalAliases[recipe.from] = true
		principalAliases[recipe.to] = true
	}
	if len(principal) == 0 {
		return
	}
	fmt.Fprintf(b, "- principal_diagram_recipe_source=`request_scoped_typed_authority`; exact_edge_count=%d. For a required-diagram repair, preserve this compact edge set together before considering any supporting recipe. This is evidence input for the model, not a system-authored diagram or conclusion.\n", len(principal))
	for _, row := range aliases {
		if !principalAliases[row.alias] {
			continue
		}
		fmt.Fprintf(b, "- principal_node_alias[%s]=`%s`; visible wording remains model-authored in the user's domain.\n", row.alias, row.identity)
	}
	for i, recipe := range principal {
		fmt.Fprintf(b, "- principal_edge_recipe[%d]=`%s -> %s`; relation_kind=`%s`; edge_anchor_json=`%s`",
			i+1, recipe.from, recipe.to, recipe.edge.relation, recipe.anchor)
		if recipe.edge.loc != "" {
			fmt.Fprintf(b, " @ %s", recipe.edge.loc)
		}
		b.WriteString("\n")
	}
	b.WriteString("- supporting_recipe_policy=`optional_prose_or_separate_visual`; disconnected supporting recipes below must not replace, truncate, bridge, or be inserted as hops into this requested spine. Internal recipe tokens are not reader-facing labels.\n")
}

func answerDocMechanismComponentCarriesRequestSpine(
	component []answerDocMechanismAliasRow,
	recipes []answerDocMechanismRecipeRow,
) bool {
	if len(component) == 0 || len(recipes) == 0 {
		return false
	}
	members := make(map[string]bool, len(component))
	for _, row := range component {
		if row.alias != "" {
			members[row.alias] = true
		}
	}
	for _, recipe := range recipes {
		if recipe.edge.requestSpine && members[recipe.from] && members[recipe.to] {
			return true
		}
	}
	return false
}

func answerDocMechanismComponentRelationClass(
	component []answerDocMechanismAliasRow,
	recipes []answerDocMechanismRecipeRow,
) (string, int) {
	members := make(map[string]bool, len(component))
	for _, row := range component {
		if row.alias != "" {
			members[row.alias] = true
		}
	}
	classes := make(map[string]bool)
	edges := 0
	for _, recipe := range recipes {
		if !members[recipe.from] || !members[recipe.to] {
			continue
		}
		edges++
		class := "other_relation"
		switch recipe.edge.relation {
		case types.DiagramRelCall:
			class = "invocation"
		case types.DiagramRelCallback:
			class = "callback_handoff"
		case types.DiagramRelArgumentFlow:
			class = "value_flow"
		case types.DiagramRelRegister:
			class = "binding"
		case types.DiagramRelAssignment, types.DiagramRelDataFlow, types.DiagramRelReturn:
			class = "value_flow"
		case types.DiagramRelGuard, types.DiagramRelControlFlow, types.DiagramRelPrecedence:
			class = "control_or_order"
		case types.DiagramRelImport, types.DiagramRelContain, types.DiagramRelTypeRelation:
			class = "structural"
		case types.DiagramRelObserve:
			class = "observation"
		}
		classes[class] = true
	}
	if len(classes) != 1 {
		return "mixed_typed_relations", edges
	}
	for class := range classes {
		return class + "_segment", edges
	}
	return "unknown_relation_segment", edges
}

func answerDocMechanismRelationComponents(
	aliases []answerDocMechanismAliasRow,
	recipes []answerDocMechanismRecipeRow,
) [][]answerDocMechanismAliasRow {
	if len(aliases) == 0 || len(recipes) == 0 {
		return nil
	}
	known := make(map[string]answerDocMechanismAliasRow, len(aliases))
	order := make(map[string]int, len(aliases))
	adjacent := make(map[string]map[string]bool, len(aliases))
	for i, row := range aliases {
		if row.alias == "" {
			continue
		}
		known[row.alias] = row
		order[row.alias] = i
		adjacent[row.alias] = make(map[string]bool)
	}
	for _, recipe := range recipes {
		if _, ok := known[recipe.from]; !ok {
			continue
		}
		if _, ok := known[recipe.to]; !ok {
			continue
		}
		adjacent[recipe.from][recipe.to] = true
		adjacent[recipe.to][recipe.from] = true
	}
	visited := make(map[string]bool, len(known))
	components := make([][]answerDocMechanismAliasRow, 0)
	for _, root := range aliases {
		if root.alias == "" || visited[root.alias] {
			continue
		}
		visited[root.alias] = true
		queue := []string{root.alias}
		component := make([]answerDocMechanismAliasRow, 0)
		for len(queue) > 0 {
			current := queue[0]
			queue = queue[1:]
			component = append(component, known[current])
			neighbours := make([]string, 0, len(adjacent[current]))
			for candidate := range adjacent[current] {
				if !visited[candidate] {
					neighbours = append(neighbours, candidate)
				}
			}
			sort.Slice(neighbours, func(i, j int) bool { return order[neighbours[i]] < order[neighbours[j]] })
			for _, candidate := range neighbours {
				visited[candidate] = true
				queue = append(queue, candidate)
			}
		}
		sort.Slice(component, func(i, j int) bool { return order[component[i].alias] < order[component[j].alias] })
		components = append(components, component)
	}
	return components
}

const answerDocMechanismTypedTopologyTemplateHeading = "#### Typed topology authoring template"
const answerDocMechanismVisibleActionPlaceholder = "AUTHOR_BUSINESS_ACTION"

func renderAnswerDocMechanismCopyReadyDiagram(
	b *strings.Builder,
	aliases []answerDocMechanismAliasRow,
	recipes []answerDocMechanismRecipeRow,
	unaryAnnotations []answerDocMechanismUnaryAnnotationRow,
	semanticHandoffs []answerDocMechanismSemanticHandoffRow,
	kind types.DiagramKind,
) {
	if b == nil || len(aliases) == 0 || len(recipes)+len(unaryAnnotations) == 0 {
		return
	}
	for _, row := range aliases {
		if strings.ContainsAny(row.identity, "\r\n") {
			return
		}
	}
	diagramRecipes, annotationRecipes, omittedKinds := answerDocMechanismCopyReadyRecipes(recipes, kind)
	sequenceOrderGrounded := false
	if kind == types.DiagramSequence {
		var ordered bool
		aliases, diagramRecipes, ordered = answerDocMechanismSequenceDisplayOrder(aliases, diagramRecipes)
		sequenceOrderGrounded = ordered
	}
	if kind == types.DiagramSequence && len(semanticHandoffs) > 0 {
		// An exact owner/reference join gives the raw registration expression a
		// business-level export/callable interpretation. Prefer that semantic
		// Note and suppress only the duplicate low-level registration Note; the
		// underlying typed recipe and validator authority remain unchanged.
		consumedBindingEvidence := make(map[string]bool, len(semanticHandoffs))
		for _, row := range semanticHandoffs {
			consumedBindingEvidence[strings.TrimSpace(row.handoff.bindingEvidenceID)] = true
		}
		filtered := annotationRecipes[:0]
		for _, recipe := range annotationRecipes {
			evidenceID := strings.TrimSpace(firstNonEmptyAnswerDocString(recipe.edge.sourceItem.ID, recipe.edge.sourceItem.EvidenceRef))
			if recipe.edge.relation == types.DiagramRelRegister && evidenceID != "" && consumedBindingEvidence[evidenceID] {
				continue
			}
			filtered = append(filtered, recipe)
		}
		annotationRecipes = filtered
	}
	visualUnaryAnnotations := make([]answerDocMechanismUnaryAnnotationRow, 0, len(unaryAnnotations))
	for _, row := range unaryAnnotations {
		if answerDocMechanismUnaryAnnotationSafeForCopyReadyDiagram(kind, row.annotation.relation) {
			visualUnaryAnnotations = append(visualUnaryAnnotations, row)
		}
	}
	if len(diagramRecipes) == 0 && len(visualUnaryAnnotations) == 0 && len(semanticHandoffs) == 0 {
		b.WriteString("\n- No typed relation in this capsule can be represented unambiguously by the selected Mermaid family. Keep these facts in prose/notes or omit the optional diagram; do not coerce them into call arrows.\n")
		return
	}
	usedAliases := make(map[string]bool, len(diagramRecipes)*2)
	anchors := make([]types.DiagramEdgeAnchor, 0, len(diagramRecipes)+len(semanticHandoffs))
	for _, recipe := range diagramRecipes {
		usedAliases[recipe.from] = true
		usedAliases[recipe.to] = true
		anchors = append(anchors, recipe.typed)
	}
	for _, row := range semanticHandoffs {
		anchors = append(anchors, types.DiagramEdgeAnchor{
			FromNode: row.from, ToNode: row.to,
			FromIdentity: row.handoff.callTarget, ToIdentity: row.handoff.registeredCallable,
			RelationKind: types.DiagramRelRegister,
		})
		usedAliases[row.from] = true
		usedAliases[row.to] = true
	}
	for _, recipe := range annotationRecipes {
		usedAliases[recipe.from] = true
		usedAliases[recipe.to] = true
	}
	if kind == types.DiagramSequence {
		for _, row := range visualUnaryAnnotations {
			usedAliases[row.participant] = true
		}
	}
	anchorJSON, err := json.Marshal(anchors)
	if err != nil {
		return
	}

	b.WriteString("\n" + answerDocMechanismTypedTopologyTemplateHeading + "\n\n")
	b.WriteString("- This optional evidence template contains only relation kinds that the selected Mermaid family can represent without changing their typed meaning, and only one unambiguous relation per endpoint pair. Keep its node IDs, edge direction/topology, unanchored annotation carriers, and complete `edge_anchors_json` together, or omit the diagram. `from_identity` / `to_identity` are typed endpoint selectors, not visible copy and not relation evidence. Every directed template edge carries the literal syntax-safe placeholder `AUTHOR_BUSINESS_ACTION`, while every matching anchor intentionally omits `visible_label`: before emitting an answer, replace each placeholder with one concise business/domain action and copy that exact wording into both the Mermaid edge/message and its anchor `visible_label`. Do not emit this template unchanged. Notes and fact-node text are also authoring placeholders. Do not expose relation enums, exact endpoint selectors, or source locations as primary visible text. Non-edge annotations preserve already-typed facts but are not arrows and MUST NOT receive `edge_anchors` rows. ")
	if len(semanticHandoffs) == 0 {
		b.WriteString("Keep disconnected components disconnected; do not invent story/actor bridges.\n")
	} else {
		b.WriteString("An exact registered-export handoff may appear as a typed-topology edge carrying the same `AUTHOR_BUSINESS_ACTION` placeholder. Before emitting it, replace that placeholder with a concise business/domain binding action and copy that wording into both the Mermaid message and the matching relation_kind=register anchor `visible_label`. It is not a call, callback, value-flow, return, or execution-order claim. Keep every other disconnected component pair disconnected and do not invent story/actor bridges.\n")
	}
	if kind == types.DiagramSequence && sequenceOrderGrounded {
		b.WriteString("- Sequence display order is normalized only from the typed graph: zero-indegree entrypoints come first, then same-caller call sites use grounded source-line order. This improves reading order but does not prove that every branch executes, that siblings are concurrent, or that a static cycle has runtime order.\n")
	}
	renderedAnnotationKinds := make(map[string]bool)
	for _, recipe := range annotationRecipes {
		renderedAnnotationKinds[string(recipe.edge.relation)] = true
	}
	for _, row := range visualUnaryAnnotations {
		renderedAnnotationKinds[string(row.annotation.relation)] = true
	}
	if len(annotationRecipes)+len(visualUnaryAnnotations) > 0 {
		annotationKinds := make([]string, 0, len(renderedAnnotationKinds))
		for kindName := range renderedAnnotationKinds {
			annotationKinds = append(annotationKinds, kindName)
		}
		sort.Strings(annotationKinds)
		fmt.Fprintf(b, "- visual_annotation_relation_count=%d; annotation_relation_kinds=`%s`; these are preserved as unanchored non-edge annotations, not arrows.\n",
			len(annotationRecipes)+len(visualUnaryAnnotations), strings.Join(annotationKinds, ","))
	}
	omittedVisualKinds := make([]string, 0, len(omittedKinds))
	for _, kindName := range omittedKinds {
		if !renderedAnnotationKinds[kindName] {
			omittedVisualKinds = append(omittedVisualKinds, kindName)
		}
	}
	if len(omittedVisualKinds) > 0 {
		fmt.Fprintf(b, "- visual_omitted_relation_kinds=`%s`; these typed facts remain available in the sibling capsule/prose but are not rendered by this Mermaid-family skeleton.\n",
			strings.Join(omittedVisualKinds, ","))
	}
	b.WriteString("\n")
	b.WriteString("```mermaid\n")
	if kind == types.DiagramSequence {
		b.WriteString("sequenceDiagram\n")
		for _, row := range aliases {
			if !usedAliases[row.alias] {
				continue
			}
			fmt.Fprintf(b, "  participant %s as %s\n", row.alias, answerDocMechanismMermaidLabel(row.identity))
		}
		for _, recipe := range diagramRecipes {
			fmt.Fprintf(b, "  %s->>%s: %s\n", recipe.from, recipe.to, answerDocMechanismVisibleActionPlaceholder)
		}
		for _, recipe := range annotationRecipes {
			fmt.Fprintf(b, "  Note over %s,%s: %s\n", recipe.from, recipe.to,
				answerDocMechanismSequenceNotePlaceholder(recipe.edge.relation))
		}
		for _, row := range visualUnaryAnnotations {
			fmt.Fprintf(b, "  Note over %s: %s\n", row.participant,
				answerDocMechanismUnarySequenceNotePlaceholder(row.annotation))
		}
		for _, row := range semanticHandoffs {
			fmt.Fprintf(b, "  %s->>%s: %s\n", row.from, row.to, answerDocMechanismVisibleActionPlaceholder)
		}
	} else {
		b.WriteString("flowchart TD\n")
		for _, row := range aliases {
			if !usedAliases[row.alias] {
				continue
			}
			fmt.Fprintf(b, "  %s[\"%s\"]\n", row.alias, answerDocMechanismMermaidLabel(row.identity))
		}
		for _, recipe := range diagramRecipes {
			fmt.Fprintf(b, "  %s -->|%s| %s\n", recipe.from, answerDocMechanismVisibleActionPlaceholder, recipe.to)
		}
		for _, row := range semanticHandoffs {
			fmt.Fprintf(b, "  %s -->|%s| %s\n", row.from, answerDocMechanismVisibleActionPlaceholder, row.to)
		}
		for i, row := range visualUnaryAnnotations {
			fmt.Fprintf(b, "  u%d[\"%s\"]\n", i+1,
				answerDocMechanismUnaryFlowFactNodePlaceholder(row.annotation))
		}
	}
	b.WriteString("```\n")
	fmt.Fprintf(b, "- edge_anchors_json=`%s`\n", anchorJSON)
}

func answerDocMechanismUnaryAnnotationSafeForCopyReadyDiagram(kind types.DiagramKind, relation types.DiagramRelationKind) bool {
	if relation != types.DiagramRelGuard {
		return false
	}
	switch kind {
	case types.DiagramSequence, types.DiagramFlow, types.DiagramArchitecture, types.DiagramCallDAG:
		return true
	}
	return false
}

func answerDocMechanismUnarySequenceNotePlaceholder(annotation answerDocMechanismUnaryAnnotation) string {
	if annotation.relation != types.DiagramRelGuard || strings.TrimSpace(annotation.detail) == "" {
		return "A single-participant fact is verified; describe it without an arrow"
	}
	return fmt.Sprintf("Selection condition is verified (%s); describe the business condition",
		answerDocMechanismMermaidLabel(annotation.detail))
}

func answerDocMechanismUnaryFlowFactNodePlaceholder(annotation answerDocMechanismUnaryAnnotation) string {
	if annotation.relation != types.DiagramRelGuard || strings.TrimSpace(annotation.detail) == "" {
		return "A verified single-participant fact; describe it in business language"
	}
	return fmt.Sprintf("Selection condition for %s (%s); describe the business condition",
		answerDocMechanismMermaidLabel(annotation.participant),
		answerDocMechanismMermaidLabel(annotation.detail))
}

// answerDocMechanismCopyReadyRecipes narrows the full typed relation capsule
// to relations the system can safely render in the selected Mermaid family
// without choosing additional ordering/context on the model's behalf.
// Sequence messages are invocation/handoff carriers, not a generic
// drawing syntax for guards, assignments, factory returns, or type
// relationships. A registration is admitted only as an explicitly owned
// binding interaction, never as a call. Call DAGs are narrower still. A repeated endpoint pair
// with multiple relation kinds is omitted from a copy-ready body because the
// diagram parser cannot assign one visible arrow to several competing typed
// authorities. The full relation capsule remains available for prose/notes.
func answerDocMechanismCopyReadyRecipes(recipes []answerDocMechanismRecipeRow, kind types.DiagramKind) ([]answerDocMechanismRecipeRow, []answerDocMechanismRecipeRow, []string) {
	if len(recipes) == 0 {
		return nil, nil, nil
	}
	pairKinds := make(map[string]map[types.DiagramRelationKind]bool, len(recipes))
	for _, recipe := range recipes {
		key := recipe.from + "\x00" + recipe.to
		if pairKinds[key] == nil {
			pairKinds[key] = map[types.DiagramRelationKind]bool{}
		}
		pairKinds[key][recipe.edge.relation] = true
	}
	omitted := map[string]bool{}
	out := make([]answerDocMechanismRecipeRow, 0, len(recipes))
	annotations := make([]answerDocMechanismRecipeRow, 0, len(recipes))
	seenVisualRelation := make(map[string]bool, len(recipes))
	for _, recipe := range recipes {
		key := recipe.from + "\x00" + recipe.to
		representable := answerDocMechanismRelationSafeForCopyReadyDiagram(kind, recipe.edge.relation)
		if !representable || len(pairKinds[key]) != 1 {
			omitted[string(recipe.edge.relation)] = true
			if kind == types.DiagramSequence && recipe.edge.relation != types.DiagramRelUnknown {
				annotations = append(annotations, recipe)
			}
			continue
		}
		visualKey := key + "\x00" + string(recipe.edge.relation)
		if seenVisualRelation[visualKey] {
			continue
		}
		seenVisualRelation[visualKey] = true
		out = append(out, recipe)
	}
	omittedKinds := make([]string, 0, len(omitted))
	for relation := range omitted {
		omittedKinds = append(omittedKinds, relation)
	}
	sort.Strings(omittedKinds)
	return out, annotations, omittedKinds
}

// answerDocMechanismSequenceNotePlaceholder keeps copy-ready non-message
// carriers business-readable. It is an authoring placeholder derived from an
// already-typed relation; it does not mint authority. The model still owns the
// final wording and conclusion. Note rows are never included in edge_anchors,
// so a non-message fact cannot satisfy an invocation gate.
func answerDocMechanismSequenceNotePlaceholder(relation types.DiagramRelationKind) string {
	switch relation {
	case types.DiagramRelCall:
		return "Invocation is verified; describe it without adding an ambiguous arrow"
	case types.DiagramRelCallback:
		return "Callback handoff is verified; describe it without adding an ambiguous arrow"
	case types.DiagramRelArgumentFlow:
		return "Argument handoff is verified; describe the business value handoff"
	case types.DiagramRelGuard:
		return "Selection condition is verified; describe the business condition"
	case types.DiagramRelControlFlow:
		return "Branch effect is verified; describe the business decision and resulting action"
	case types.DiagramRelRegister:
		return "Runtime binding is verified; describe the selected implementation"
	case types.DiagramRelAssignment, types.DiagramRelDataFlow:
		return "Value handoff is verified; describe the business handoff"
	case types.DiagramRelReturn:
		return "Factory result is verified; describe the created implementation"
	case types.DiagramRelTypeRelation:
		return "Implementation contract is verified; describe the business role"
	case types.DiagramRelPrecedence:
		return "Execution order is verified; describe the business order"
	case types.DiagramRelImport:
		return "Source dependency is verified; describe the business dependency"
	case types.DiagramRelObserve:
		return "Observed attachment is verified; describe the business observation"
	case types.DiagramRelTemporal:
		return "Measured order is verified; do not claim causality"
	case types.DiagramRelContain:
		return "Ownership boundary is verified; describe the business grouping"
	default:
		return "A non-message fact is verified; describe it without an arrow"
	}
}

// answerDocMechanismRelationSafeForCopyReadyDiagram is the closed
// system-rendered copy-ready matrix for every semantic diagram family and
// typed relation. It is intentionally narrower than the parser/validator:
// models may place additional exact typed relations in a diagram when their
// evidence also establishes the diagram's ordering/context, while the system
// must not choose that ordering on their behalf.
// Keeping the matrix fail-closed matters in two directions:
//
//   - a new relation enum cannot silently become a generic flowchart arrow;
//   - a syntax family cannot visually recast a precise source fact as another
//     semantic (for example, a return as a sequence invocation).
//
// Containment is deliberately false for every edge family: architecture/flow
// diagrams represent it with Mermaid subgraph/grouping, not an arrow. Runtime
// temporal arrows are structurally expressible by flow/architecture syntax,
// while their independent runtime authority remains enforced by the trace
// capsule and validator. Sequence messages stay limited to invocation and
// callback handoff; a paired dashed reply is renderer structure, not an
// independently anchored return edge.
func answerDocMechanismRelationSafeForCopyReadyDiagram(kind types.DiagramKind, relation types.DiagramRelationKind) bool {
	switch kind {
	case types.DiagramSequence:
		return relation == types.DiagramRelCall || relation == types.DiagramRelCallback || relation == types.DiagramRelRegister
	case types.DiagramCallDAG:
		return relation == types.DiagramRelCall
	case types.DiagramFlow, types.DiagramArchitecture:
		switch relation {
		case types.DiagramRelCall,
			types.DiagramRelCallback,
			types.DiagramRelArgumentFlow,
			types.DiagramRelGuard,
			types.DiagramRelControlFlow,
			types.DiagramRelImport,
			types.DiagramRelPrecedence,
			types.DiagramRelTypeRelation,
			types.DiagramRelObserve,
			types.DiagramRelRegister,
			types.DiagramRelAssignment,
			types.DiagramRelDataFlow,
			types.DiagramRelReturn,
			types.DiagramRelTemporal:
			return true
		}
	}
	return false
}

func answerDocMechanismMermaidLabel(identity string) string {
	return strings.NewReplacer(
		"&", "&amp;",
		"\"", "&quot;",
		"<", "&lt;",
		">", "&gt;",
	).Replace(strings.TrimSpace(identity))
}

// The copy-ready example consumes the same final AnswerSemanticView that
// renders Required Answer Blocks. Reading the analyzer's earlier hint or raw
// contract here created two competing tutorials (for example, flowchart here
// while the effective call-chain contract taught sequenceDiagram).
func answerDocMechanismCopyReadyDiagramKind(
	ctx *types.AgentContext,
	edges []answerDocMechanismRelationEdge,
	semanticHandoffs []answerDocRegisteredExportHandoff,
) types.DiagramKind {
	view := types.BuildAnswerSemanticViewForAgentContext(ctx)
	// A typed flow answer asks the model to select the principal transfer
	// topology. A bounded arbitrary source relation (for example one helper
	// call inside Finalizer) is valid evidence but is not a replacement for
	// that requested flow. Keep per-edge recipes available as facts, while
	// withholding the system-authored whole-diagram capsule and its repair-time
	// copy command. This is driven only by the schema-valid axis.
	if view != nil && view.RelationAxis == types.AxisFlow {
		return types.DiagramNone
	}
	// A call-chain answer promises a relation path, not merely a bag of
	// individually valid local edges.  When the bounded typed graph has more
	// than one weak component and no request-scoped provider has identified a
	// complete principal spine, a whole copy-ready body would optimize per-edge
	// validity while silently losing the requested topology.  Withhold only the
	// system-provided whole skeleton in that shape.  The exact edge recipes and
	// per-component Mermaid fragments remain available, and the model may keep
	// them separate, investigate a typed bridge, or omit an optional diagram.
	//
	// This reads the normalized semantic family and typed graph metadata only;
	// it does not inspect request prose, model reasoning, draft/final text, or
	// Mermaid labels, and it never creates or removes a model-authored edge.
	if answerDocMechanismDisconnectedCallChainWithoutRequestSpine(view, edges, semanticHandoffs) {
		return types.DiagramNone
	}
	if view != nil && view.DiagramPlan != nil && view.DiagramPlan.Kind.IsValid() {
		if answerDocMechanismOptionalSequenceTopologyOnly(ctx, view, edges) {
			return types.DiagramNone
		}
		return view.DiagramPlan.Kind
	}
	return types.DiagramNone
}

func answerDocMechanismDisconnectedCallChainWithoutRequestSpine(
	view *types.AnswerSemanticView,
	edges []answerDocMechanismRelationEdge,
	semanticHandoffs []answerDocRegisteredExportHandoff,
) bool {
	if view == nil || view.Family != types.QFCallChain {
		return false
	}
	topology, ok := answerDocMechanismRelationGraphTopology(edges)
	if !ok || !topology.disconnected {
		return false
	}
	for _, edge := range edges {
		if edge.requestSpine {
			return false
		}
	}
	if answerDocMechanismSemanticHandoffsConnectAllComponents(edges, semanticHandoffs) {
		return false
	}
	return true
}

// answerDocMechanismSemanticHandoffsConnectAllComponents recognizes only the
// exact registered-export handoffs already produced by the typed owner/reference
// join. They remain non-call bindings even when the model renders a visible,
// explicitly owned edge, and may establish that otherwise separate invocation
// components belong to one evidenced cross-language topology. Ambiguous or
// partial joins fail closed.
func answerDocMechanismSemanticHandoffsConnectAllComponents(
	edges []answerDocMechanismRelationEdge,
	handoffs []answerDocRegisteredExportHandoff,
) bool {
	if len(edges) == 0 || len(handoffs) == 0 {
		return false
	}
	nodes := make([]string, 0, len(edges)*2)
	index := make(map[string]int, len(edges)*2)
	addNode := func(identity string) int {
		identity = strings.TrimSpace(identity)
		if identity == "" {
			return -1
		}
		if at, ok := index[identity]; ok {
			return at
		}
		at := len(nodes)
		nodes = append(nodes, identity)
		index[identity] = at
		return at
	}
	parent := make([]int, 0, len(edges)*2)
	ensureParent := func() {
		for len(parent) < len(nodes) {
			parent = append(parent, len(parent))
		}
	}
	var find func(int) int
	find = func(x int) int {
		if parent[x] != x {
			parent[x] = find(parent[x])
		}
		return parent[x]
	}
	union := func(a, b int) {
		if a < 0 || b < 0 {
			return
		}
		ra, rb := find(a), find(b)
		if ra != rb {
			parent[rb] = ra
		}
	}
	for _, edge := range edges {
		// A registered-export handoff is defined to join invocation fragments.
		// Registration, guard, type, and value evidence remain sibling support
		// components and must not make an otherwise complete invocation topology
		// look disconnected merely because they are not source call edges.
		if edge.relation != types.DiagramRelCall {
			continue
		}
		a, b := addNode(edge.from), addNode(edge.to)
		ensureParent()
		union(a, b)
	}
	if len(nodes) == 0 {
		return false
	}
	resolveUnique := func(identity string) (int, bool) {
		match := -1
		for i, node := range nodes {
			if !types.AnswerCodeIdentitySurfacesEquivalent(node, identity) {
				continue
			}
			if match >= 0 && match != i {
				return -1, false
			}
			match = i
		}
		return match, match >= 0
	}
	for _, handoff := range handoffs {
		from, fromOK := resolveUnique(handoff.callTarget)
		to, toOK := resolveUnique(handoff.registeredCallable)
		if fromOK && toOK && from != to {
			union(from, to)
		}
	}
	roots := make(map[int]bool)
	for i := range nodes {
		roots[find(i)] = true
	}
	return len(roots) == 1
}

func answerDocMechanismRequestedDiagramKind(ctx *types.AgentContext, edges []answerDocMechanismRelationEdge) types.DiagramKind {
	view := types.BuildAnswerSemanticViewForAgentContext(ctx)
	if view != nil && view.DiagramPlan != nil && view.DiagramPlan.Kind.IsValid() {
		if answerDocMechanismOptionalSequenceTopologyOnly(ctx, view, edges) {
			return types.DiagramNone
		}
		return view.DiagramPlan.Kind
	}
	return types.DiagramNone
}

// answerDocMechanismOptionalSequenceTopologyOnly prevents a system-authored
// copy-ready sequence body from adding a top-to-bottom time/order implication
// to a non-linear relation graph. An explicit required/preferred diagram
// contract remains available: it is typed presentation intent and the model
// must represent any unproved order honestly. Generic optional non-linear call
// evidence keeps its exact per-edge recipes, while the model may choose
// call-DAG/flow/prose.
// This predicate reads only the final typed diagram plan and relation graph;
// it never inspects request text, model prose, or a Mermaid body.
func answerDocMechanismOptionalSequenceTopologyOnly(ctx *types.AgentContext, view *types.AnswerSemanticView, edges []answerDocMechanismRelationEdge) bool {
	if view == nil || view.DiagramPlan == nil || view.DiagramPlan.Required || view.DiagramPlan.Kind != types.DiagramSequence {
		return false
	}
	// A concrete AnswerContract diagram is typed current-turn presentation
	// intent even when the diagram remains optional. Preserve its selected
	// family; this guard is only for the generic call-chain default that has no
	// explicit diagram contract at all.
	if ctx != nil && ctx.AnalysisIR != nil && ctx.AnalysisIR.AnswerContract.Diagram != nil {
		return false
	}
	topology, ok := answerDocMechanismRelationGraphTopology(edges)
	return ok && !topology.singleLinearGraph
}

const (
	answerDocMechanismOptionalRelationLimit = 8
	answerDocMechanismRequiredRelationLimit = 32
)

// Required diagrams need enough room for a broad but still bounded typed
// relation surface. This reads the final typed presentation contract, not the
// request text or answer prose. Optional diagrams retain the compact limit.
func answerDocMechanismCopyReadyRelationLimit(ctx *types.AgentContext) int {
	view := types.BuildAnswerSemanticViewForAgentContext(ctx)
	if view != nil && view.DiagramPlan != nil && view.DiagramPlan.Required {
		return answerDocMechanismRequiredRelationLimit
	}
	return answerDocMechanismOptionalRelationLimit
}

func answerDocMechanismRelationAuthorityApplies(rm types.RequestModel) bool {
	switch types.NormalizeRequirementKind(rm.AnalyzerHints.Kind) {
	case types.ReqMechanism, types.ReqCallChain:
		return true
	}
	profile := rm.CurrentSourceExplanationProfile
	if profile == nil || !profile.Active() {
		return false
	}
	for _, mode := range profile.Modes {
		switch mode {
		case types.CurrentSourceExplanationExplainCurrentMechanism,
			types.CurrentSourceExplanationTraceCurrentFlow:
			return true
		}
	}
	return false
}

func answerDocGroundedCurrentSourceMechanismFact(item types.EvidenceItem) bool {
	if strings.TrimSpace(item.Source) == "" ||
		types.RuntimeArtifactPathKind(item.Source) != "" ||
		(item.GroundingStatus != types.GroundingGrounded && item.GroundingStatus != types.GroundingRecovered) {
		return false
	}
	switch item.Origin {
	case types.ClaimOriginLog, types.ClaimOriginPerf:
		return false
	}
	switch item.AnchorKind {
	case types.AnchorDefinition, types.AnchorCall, types.AnchorCallback, types.AnchorArgument, types.AnchorCondition,
		types.AnchorReturn, types.AnchorAssignment, types.AnchorInitializer,
		types.AnchorImport, types.AnchorPrecedence, types.AnchorStringLiteral:
		return true
	default:
		return false
	}
}

func answerDocSupportedMechanismFlowPaths(findings []types.FlowFindingDigest) [][]string {
	return answerDocSupportedMechanismFlowPathsForScope(findings, nil, types.RequestModel{})
}

// answerDocSupportedMechanismFlowPathsForContext distinguishes a dataflow
// engine result that exists somewhere in the repository from an ordered path
// that is relevant to the current principal support surface.  The former is
// useful exploration background; only the latter may set
// ordered_path_authority=typed_flow_paths_present.
//
// The filter consumes typed request scope and Explorer-authored operation
// rows only. It never scans the user's request or model-authored prose. A
// compiled support plan still governs answer blocks and enrichment, but its
// deterministic repo-wide expansion cannot independently broaden principal
// ordered-path authority past the operations selected in this investigation.
func answerDocSupportedMechanismFlowPathsForContext(ctx *types.AgentContext) [][]string {
	if ctx == nil {
		return nil
	}
	rm := types.RequestModel{}
	if ctx.AnalysisIR != nil {
		rm = ctx.AnalysisIR.RequestModel
	}
	operations := types.ExplorerAuthoredFlowOperationEvidenceForRequest(
		answerDocTypedEnrichmentEvidencePool(ctx, answerDocMaxEnrichmentCandidateFacts),
		rm,
	)
	if len(operations) == 0 {
		return nil
	}
	operationScope := supportLaneScopeFromFlowOperations(operations)
	return answerDocSupportedMechanismFlowPathsForScopes(
		ctx.FlowFindings,
		rm,
		operationScope,
	)
}

func answerDocSupportedMechanismFlowPathsForScope(
	findings []types.FlowFindingDigest,
	supportScope *supportLaneScope,
	rm types.RequestModel,
) [][]string {
	return answerDocSupportedMechanismFlowPathsForScopes(findings, rm, supportScope)
}

func answerDocSupportedMechanismFlowPathsForScopes(
	findings []types.FlowFindingDigest,
	rm types.RequestModel,
	requiredScopes ...*supportLaneScope,
) [][]string {
	out := make([][]string, 0)
	for _, finding := range findings {
		if strings.TrimSpace(finding.UnsupportedReason) != "" {
			continue
		}
		if !answerDocFlowFindingWithinRequestedSourceScope(finding, rm) {
			continue
		}
		allowed := true
		for _, scope := range requiredScopes {
			if scope != nil && !scope.allowsOrderedFlowFinding(finding) {
				allowed = false
				break
			}
		}
		if !allowed {
			continue
		}
		path := finding.Path
		if len(path) < 2 {
			path = finding.Hops
		}
		if len(path) < 2 {
			continue
		}
		clean := make([]string, 0, len(path))
		for _, node := range path {
			if node = strings.TrimSpace(node); node != "" {
				clean = append(clean, node)
			}
		}
		if len(clean) >= 2 {
			out = append(out, clean)
		}
	}
	return out
}

// answerDocFlowFindingWithinRequestedSourceScope rejects only nodes that carry
// a deterministic repository path classified outside the analyzer's typed
// source scope. Symbol-only nodes remain eligible; absence of a file surface is
// not converted into proof or rejection.
func answerDocFlowFindingWithinRequestedSourceScope(finding types.FlowFindingDigest, rm types.RequestModel) bool {
	scope := types.SourceScopeProduction
	if rm.SourceScopeProfile != nil {
		if rm.SourceScopeProfile.RequestedScope != "" {
			scope = rm.SourceScopeProfile.RequestedScope
		}
		if rm.SourceScopeProfile.IncludeAuxiliaryAsPrincipal {
			scope = types.SourceScopeAll
		}
	}
	for _, group := range [][]string{finding.Path, finding.Hops, finding.Sources, finding.Sinks} {
		for _, raw := range group {
			file := supportLaneScopeFileKey(raw)
			if file == "" || !strings.Contains(file, "/") {
				continue
			}
			role := types.ClassifySourcePathRole(file)
			if role != types.SourcePathRoleUnknown && !types.SourceScopeAllowsPathRole(scope, role) {
				return false
			}
		}
	}
	return true
}

func answerDocShouldRenderRelationSurfaceHandoff(rm types.RequestModel, rows []answerDocRelationSurfaceRow, relationRefs []types.AnswerAggregateFactRef) bool {
	if len(rows) == 0 {
		return false
	}
	if len(relationRefs) > 0 ||
		types.ShouldSurfaceTypedRelationHints(rm) ||
		types.HasTypedRelationMemberSetShape(rm) ||
		rm.Predicates.IsRelationalLookup {
		return true
	}
	if answerDocRelationRequestShape(rm) {
		return true
	}
	// When the analyzer missed the relation shape, multiple already-structured
	// relation rows are still a useful advisory handoff. This remains soft:
	// it never creates a principal member set or a completion gate.
	return len(rows) >= 2
}

func answerDocRelationRequestShape(rm types.RequestModel) bool {
	switch rm.PredicateAxis {
	case types.AxisCall, types.AxisRegister, types.AxisImplement, types.AxisConfigure, types.AxisFlow:
		return true
	}
	switch types.NormalizeRequirementKind(rm.AnalyzerHints.Kind) {
	case types.ReqCallChain, types.ReqRegistration, types.ReqConfigMapping:
		return true
	default:
		return false
	}
}

func selectAnswerDocRelationSurfaceRows(ctx *types.AgentContext, limit int) []answerDocRelationSurfaceRow {
	if ctx == nil || limit <= 0 {
		return nil
	}
	evidence := answerDocTypedEnrichmentEvidencePool(ctx, answerDocMaxEnrichmentCandidateFacts)
	if len(evidence) == 0 {
		return nil
	}
	rows := make([]answerDocRelationSurfaceRow, 0, extractorMinInt(len(evidence), limit))
	seen := map[string]bool{}
	for i, item := range evidence {
		row, ok := answerDocRelationSurfaceRowForEvidence(ctx, item, i)
		if !ok {
			continue
		}
		key := answerDocRelationSurfaceRowKey(row)
		if key == "" || seen[key] {
			continue
		}
		seen[key] = true
		rows = append(rows, row)
	}
	if len(rows) == 0 {
		return nil
	}
	sort.SliceStable(rows, func(i, j int) bool {
		if rows[i].score != rows[j].score {
			return rows[i].score > rows[j].score
		}
		return rows[i].index < rows[j].index
	})
	if len(rows) > limit {
		rows = rows[:limit]
	}
	return rows
}

func answerDocRelationSurfaceRowForEvidence(ctx *types.AgentContext, item types.EvidenceItem, index int) (answerDocRelationSurfaceRow, bool) {
	includeBoundary := false
	if ctx != nil && ctx.AnalysisIR != nil {
		includeBoundary = answerDocRelationRequestShape(ctx.AnalysisIR.RequestModel) ||
			types.ShouldSurfaceTypedRelationHints(ctx.AnalysisIR.RequestModel) ||
			ctx.AnalysisIR.RequestModel.Predicates.IsRelationalLookup
	}
	if !answerDocEvidenceHasStructuredRelationSurface(item, includeBoundary) {
		return answerDocRelationSurfaceRow{}, false
	}
	label := answerDocRelationSurfaceLabel(item)
	if label == "" {
		return answerDocRelationSurfaceRow{}, false
	}
	surface := strings.TrimSpace(types.EvidenceAuthoritativeSurfaceText(item, false))
	if surface == "" {
		return answerDocRelationSurfaceRow{}, false
	}
	surface = truncateAnswerDocPromptText(surface, answerDocMaxEnrichmentSurfaceBytes)
	if ctx != nil && ctx.AnalysisIR != nil {
		surface = types.SanitizeSourceInventoryNoteForRequest(&ctx.AnalysisIR.RequestModel, surface)
	}
	return answerDocRelationSurfaceRow{
		role:              answerDocRelationSurfaceRole(item),
		label:             label,
		loc:               item.DisplayLocation(true),
		surface:           surface,
		authorityBoundary: types.EvidenceMechanismAuthorityBoundary(item),
		score:             answerDocRelationSurfaceScore(item),
		index:             index,
	}, true
}

func answerDocEvidenceHasStructuredRelationSurface(item types.EvidenceItem, includeBoundary bool) bool {
	if item.GroundingStatus == types.GroundingUngrounded {
		return false
	}
	hasEndpoint := strings.TrimSpace(item.Subject) != "" &&
		(strings.TrimSpace(item.Object) != "" || strings.TrimSpace(item.AnchorSymbol) != "")
	switch item.Kind {
	case types.EvidenceRelationship, types.EvidenceRegistration, types.EvidenceDataflowPath, types.EvidenceControlFlow:
		if item.Kind == types.EvidenceDataflowPath &&
			answerDocStructuredRelationChainProducer(item.Producer) &&
			(strings.TrimSpace(item.Subject) != "" || strings.TrimSpace(types.EvidenceAuthoritativeSurfaceText(item, false)) != "") {
			return true
		}
		return hasEndpoint || strings.TrimSpace(item.AnchorSymbol) != ""
	}
	if hasEndpoint {
		switch item.AnchorKind {
		case types.AnchorCall, types.AnchorImport, types.AnchorCondition:
			return true
		}
		if strings.TrimSpace(item.Predicate) != "" {
			return true
		}
	}
	if includeBoundary && strings.TrimSpace(item.Subject) != "" {
		switch item.Kind {
		case types.EvidenceDirect, types.EvidenceMechanism:
			return item.AnchorKind == types.AnchorDefinition ||
				item.ContextRole == types.EvidenceContextRoleDefining ||
				item.LoadBearingSummary ||
				item.SalienceLockedForScoring()
		}
	}
	return false
}

func answerDocRelationSurfaceLabel(item types.EvidenceItem) string {
	if types.ClaimFormOf(item) == types.ClaimGuardCondition {
		for _, raw := range []string{item.AnchorSymbol, item.OwnerSymbol, item.Subject} {
			if trimmed := strings.TrimSpace(raw); trimmed != "" {
				return trimmed
			}
		}
		return "guard"
	}
	left := strings.TrimSpace(item.Subject)
	right := strings.TrimSpace(item.Object)
	if right == "" {
		right = strings.TrimSpace(item.AnchorSymbol)
	}
	if left != "" && right != "" && !strings.EqualFold(left, right) {
		return left + " -> " + right
	}
	for _, raw := range []string{left, right, item.AnchorSymbol, item.OwnerSymbol} {
		if trimmed := strings.TrimSpace(raw); trimmed != "" {
			return trimmed
		}
	}
	return ""
}

func answerDocRelationSurfaceRole(item types.EvidenceItem) string {
	switch item.Producer {
	case "consumer_gate":
		return "qualifying_gate"
	case "bridge_literal":
		return "registry_identity_chain"
	}
	switch item.Kind {
	case types.EvidenceRegistration:
		return "registration_or_binding"
	case types.EvidenceDataflowPath:
		return "flow_or_handoff"
	case types.EvidenceControlFlow:
		return "branch_to_effect"
	case types.EvidenceDirect, types.EvidenceMechanism:
		if item.AnchorKind == types.AnchorDefinition {
			return "definition_or_boundary"
		}
		return "supporting_role_or_boundary"
	case types.EvidenceRelationship:
		switch item.AnchorKind {
		case types.AnchorCall:
			return "call_or_invocation"
		case types.AnchorCallback:
			return "callback_handoff"
		case types.AnchorArgument:
			return "argument_handoff"
		case types.AnchorImport:
			return "import_or_dependency"
		case types.AnchorCondition:
			return "guard_condition"
		default:
			return "relationship"
		}
	}
	switch item.AnchorKind {
	case types.AnchorCall:
		return "call_or_invocation"
	case types.AnchorCallback:
		return "callback_handoff"
	case types.AnchorArgument:
		return "argument_handoff"
	case types.AnchorImport:
		return "import_or_dependency"
	case types.AnchorCondition:
		return "guard_condition"
	default:
		return "relationship"
	}
}

func answerDocRelationSurfaceScore(item types.EvidenceItem) int {
	score := 0
	switch item.Kind {
	case types.EvidenceRegistration:
		score += 24
	case types.EvidenceRelationship:
		score += 20
	case types.EvidenceDataflowPath:
		score += 18
	case types.EvidenceControlFlow:
		score += 22
	case types.EvidenceDirect, types.EvidenceMechanism:
		score += 12
	default:
		score += 8
	}
	switch item.AnchorKind {
	case types.AnchorCall, types.AnchorCallback, types.AnchorArgument, types.AnchorImport, types.AnchorCondition:
		score += 8
	}
	if item.GroundingStatus == types.GroundingGrounded {
		score += 8
	} else if item.GroundingStatus == types.GroundingRecovered {
		score += 3
	}
	if item.SalienceLockedForScoring() {
		score += 10
	}
	switch item.Producer {
	case "consumer_gate":
		score += 18
	case "bridge_literal":
		score += 10
	}
	switch item.ContextRole {
	case types.EvidenceContextRoleDefining:
		score += 6
	case types.EvidenceContextRoleRelatedContext:
		score -= 4
	case types.EvidenceContextRoleIllustrativeOnly:
		score -= 8
	}
	if len(item.SurfaceTerms) > 0 {
		score += 3
	}
	return score
}

func answerDocStructuredRelationChainProducer(producer string) bool {
	switch strings.TrimSpace(producer) {
	case "consumer_gate", "bridge_literal":
		return true
	default:
		return false
	}
}

func answerDocRelationSurfaceRowKey(row answerDocRelationSurfaceRow) string {
	key := strings.TrimSpace(row.role) + "|" + strings.TrimSpace(row.label) + "|" + strings.TrimSpace(row.loc)
	key = strings.ToLower(key)
	if strings.Trim(key, "|") == "" {
		return ""
	}
	return key
}

func renderAnswerDocPrincipalMemberSetContractFromEnumerationRows(ctx *types.AgentContext, refs []types.AnswerAggregateFactRef, sets []types.EnumerationDisplaySet) string {
	if ctx == nil || ctx.AnalysisIR == nil || len(refs) == 0 || len(sets) == 0 {
		return ""
	}
	rm := ctx.AnalysisIR.RequestModel
	totalRows := 0
	for _, set := range sets {
		totalRows += len(set.Rows)
	}
	if totalRows == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Required Principal Member Set\n\n")
	b.WriteString("The authoritative principal member rows are rendered once in `Principal Enumeration Rows` above. ")
	sourceInventory := rm.SourceInventoryProfile != nil && rm.SourceInventoryProfile.Active()
	if sourceInventory {
		b.WriteString("Every typed row there MUST appear once as a structured item with its exact `source_inventory_row_id`. The visible first value may use the exact `display_label` or, for a parenthesized language-kind member such as `Index (struct)`, its exact base `Index`; keep the qualifier as same-row category/detail instead of inventing another member. Arrows, separators, and non-parenthesized identities remain exact. ")
	} else {
		b.WriteString("Every `row.member` there MUST appear verbatim in the visible answer, including decorators in parentheses, arrows, separators, and source-location text. ")
	}
	if types.RequiresExhaustiveEnumerationMemberSetHandoff(rm) || types.RequiresRelationMemberSetHandoff(rm) {
		if rm.Predicates.HasPerMemberTable {
			b.WriteString("Carry those rows exactly once as structured items in the required principal `table`; it is the sole principal member carrier. Optional sections may frame buckets in their title/text but must not repeat the rows in `items[]`. Prose-only mentions inside `summary` or block `text` do not satisfy the table carrier; ")
		} else {
			b.WriteString("Carry those rows as structured items in a principal `section`, `ordered_list`, `bullet_list`, or `table`; for `section`, use `items[]`. Prose-only mentions inside `summary` or block `text` do not satisfy the member carrier; ")
		}
		if sourceInventory {
			b.WriteString("do not drop, merge, or invent rows, and use only the exact display alternatives stated above.\n\n")
		} else {
			b.WriteString("do not paraphrase or abbreviate any row member.\n\n")
		}
	} else {
		b.WriteString("The pre-emit oracle checks the same row identities against `blocks[].items[].label/text/cells OR blocks[].text`; ")
		if sourceInventory {
			b.WriteString("do not drop, merge, or invent rows, and use only the exact display alternatives stated above.\n\n")
		} else {
			b.WriteString("do not paraphrase or abbreviate them.\n\n")
		}
	}
	if types.RequiresSourceOperationSiteMemberSetHandoff(rm) {
		b.WriteString("This request's member_set is a source operation-site set: render it as the principal write/call/registration/entry-point list or table before broad mechanism prose. Use member-specific support refs for the operation-site citation; constants, literal target paths, config keys, or registry names are row details and must not replace the citation for the function/call/write site itself.\n\n")
	}
	b.WriteString("This section intentionally does not duplicate the full member list. Use the row ids, locations, citation keys, and notes from `Principal Enumeration Rows` as the single rich member/citation contract.\n\n")
	for _, set := range sets {
		label := answerDocPrincipalEnumerationSetAuthorityLabel(set)
		if label == "" {
			label = "principal set"
		}
		if set.SelectionFamily != "" {
			fmt.Fprintf(&b, "- principal typed set selection_family=%q: %d row(s), source aggregate fact index=%d", label, len(set.Rows), set.FactIndex)
			if display := strings.TrimSpace(set.Label); display != "" && !strings.EqualFold(display, label) {
				fmt.Fprintf(&b, ", model display_group=%q (non-authoritative)", display)
			}
			b.WriteByte('\n')
			continue
		}
		fmt.Fprintf(&b, "- principal set %q: %d row(s), source aggregate fact index=%d\n", label, len(set.Rows), set.FactIndex)
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocAggregateFacts(ctx *types.AgentContext) string {
	plan := answerSurfacePlan(ctx)
	if plan == nil || len(plan.StableAggregateFacts) == 0 {
		return ""
	}
	rows := renderAnswerDocPrincipalEnumerationRows(ctx, plan)
	var b strings.Builder
	b.WriteString("## Structured Aggregate Facts\n\n")
	b.WriteString("- These aggregate facts were emitted by the investigator through `emit_investigation_complete.aggregate_facts` after exploration. They are model-authored structured handoff values, not system-synthesised answer text.\n")
	if runtimeObservationOnlyForAnswerDoc(ctx) {
		b.WriteString("- Observation-only runtime/log/trace answers: direct artifact observations are authoritative for error type, message, stack/span/timing, artifact-local line/order, and literal log content. Model-authored aggregate facts with `kind=behavior_outcome` or `kind=error_granularity_verdict` are supporting synthesis unless they carry explicit support refs or current-source proof; do not promote caller-owned values, variable provenance, or upstream data construction from those aggregate facts into a final root-cause fact.\n")
	}
	b.WriteString("- Preserve each `value` exactly when the corresponding fact answers the user's requested scalar, unique-set, group, bucket, exclusion, or exhaustive-member question. Use `members` for requested concrete lists such as enum/type names, file paths, or file:line locations.\n")
	b.WriteString("- Facts marked `role=principal_answer` and backed by a non-illustrative typed evidence origin are answer payloads. A fact marked `fact_authority=advisory_model_inference` is retained exploration synthesis: use it as a candidate, but do not treat it as a required roster or as proof of a relation/path merely because its model-authored role says principal.\n")
	if aggregateFactPromptOmitExcludedCandidates(ctx) {
		b.WriteString("- The active typed exclusion policy keeps concrete excluded candidates out of the answer surface. Excluded categories and counts may be used as scope boundaries; omitted `excluded[]` names are intentionally not part of the visible answer.\n")
	}
	b.WriteString("- `kind=negative_search` is the typed lane for a verified zero-result repository search. It has no citation line by design; use its repo/query-or-pattern/scope/searched_at dimensions to support no-hit conclusions, cross-repository boundaries, and caveats without inventing a file:line citation.\n")
	b.WriteString("- `kind=negative_observation` is the typed lane for a verified zero-result non-repo observation, such as git history/diff output, an attached log, a trace, command output, or repo-map/index output. Use its origin/target-or-query/scope/result_count/searched_at dimensions; do not rewrite it as repo search and do not invent file:line citations.\n")
	b.WriteString("- For evidence-authorized `member_set` rows, `role=principal_answer` marks the concrete principal slate. Pure `system_inference` sets remain advisory regardless of that model-authored role. `role=supporting_coverage` / `role=audit_ledger` rows are context or investigation bookkeeping and must not create duplicate principal rows.\n")
	b.WriteString("- Grounded definition evidence from read files and the requested source scope is the detail/citation authority for those principal members. Aggregate facts organize the slate/counts; they must not cause you to drop richer per-member summaries already present in the evidence pool or typed exploration enrichment rows.\n")
	b.WriteString("- `member_note_support_authority` is a positional ceiling derived from accepted evidence at each `support_refs` location. A `definition_fact{...definition_site_only...}` entry proves the member/entry exists but not the model-authored member note's function-body behavior; call/guard/assignment/return forms prove only their corresponding operation shape. Multiple support refs do not by themselves create order, a complete path, or branch equivalence.\n")
	b.WriteString("- `member_note_composite_support` groups accepted anchors for one exact typed owner in one source-definition incarnation. Use the grouped locations to cite the corresponding parts of a composite member description; the group does not prove execution order, branch equivalence, reachability, or any relation absent from its listed claim forms. Members without this field remain bounded by `member_note_support_authority`.\n")
	if rows != "" {
		b.WriteString("- Because principal enumeration rows are available, this prompt renders the rich member/citation list exactly once in `Principal Enumeration Rows`; aggregate metadata below keeps only non-conflicting audit dimensions. If a supporting aggregate is shadowed by authoritative principal rows, its concrete value/count/member fields are intentionally hidden and must not be reconstructed.\n")
	}
	if relationRefs := answerDocPrincipalRelationMemberSetRefs(ctx, plan.StableAggregateFacts); len(relationRefs) > 0 {
		b.WriteString("- Relation contract: principal relation `member_set` rows answer a qualifying-member lookup. Start from the qualifying member(s) in that typed set, then explain the relation evidence; do not substitute a mechanism-only architecture explanation for the direct member answer.\n")
		if answerDocHasMultiMemberAggregateRef(relationRefs) {
			b.WriteString("- For multi-member relation sets, render the qualifying members as list/table rows before any broader mechanism narrative.\n")
		}
	}
	if ctx != nil && ctx.AnalysisIR != nil && ctx.AnalysisIR.RequestModel.HasRequiredSourceLocationDimension() {
		b.WriteString("- Per-member source-location contract: for every principal member with an aligned `support_refs` source location, render that exact path or file:line in the same visible member row/cell. A citation proves the row but does not display the user-requested location.\n")
	}
	if ctx != nil && ctx.AnalysisIR != nil && types.RequiresSourceOperationSiteMemberSetHandoff(ctx.AnalysisIR.RequestModel) {
		b.WriteString("- Source operation-site contract: the principal `member_set` rows are the requested write/call/registration/entry points. Render every member identity as a visible list/table row and cite that member's function/call/file:line support ref. Treat `member_notes` as model-authored candidate descriptions: calibrate every behavior or effect in a note to that row's `member_note_support_authority` and accepted grounded operation evidence. A definition-only anchor proves existence only; when the grounded operation supports a narrower effect than the note, describe the exact observed operation or disclose the evidence boundary instead of preserving the stronger note. Do not borrow a nearby constant/path citation as the main citation for a function or call-site member.\n")
	}
	b.WriteString("- When a `members` entry is a source location such as `file.ext:line`, or a member-specific `support_refs` entry maps `Member @ file.ext:line`, `Member | file.ext:line`, or `Member (file.ext:line)`, use that row's exact projected row/evidence carrier; only a schema-permitted legacy lane should create or reuse a manual citation-pool index. Member labels with no citable source-location handoff should remain unsupported rather than borrowing an adjacent source.\n")
	b.WriteString("- Do not render internal provenance strings such as `source=emit_investigation_complete.aggregate_facts` in the user-visible answer text. Use provenance only to choose the correct member set and citations.\n")
	b.WriteString("- Do not recompute new aggregate values in finalization. If analyzer hints, unstructured prose, or raw tool snippets conflict with these facts, prefer evidence-authorized rows marked `role=principal_answer`. For `fact_authority=advisory_model_inference`, let grounded typed evidence and component/flow boundaries decide instead of preserving the proposed slate by force. If a same-member grounded definition evidence row provides richer detail, use that evidence to explain the member instead of deleting the detail.\n\n")
	if rows != "" {
		b.WriteString(rows)
		b.WriteString("## Aggregate Fact Metadata\n\n")
		b.WriteString("- Principal member-set bodies are compacted here to avoid a second dry copy of the same rows. Aggregate facts shadowed by an authoritative source-inventory principal row set are audit metadata only: do not use their hidden values, counts, member counts, or support-ref counts as answer payloads. Non-member aggregate values remain exact.\n\n")
	}
	b.WriteString(renderStructuredAggregateFactsForContext(ctx, plan.StableAggregateFacts))
	b.WriteString("\n")
	return b.String()
}

func answerDocPrincipalEnumerationSets(ctx *types.AgentContext, plan *types.AnswerSurfacePlan) []types.EnumerationDisplaySet {
	if ctx == nil || ctx.AnalysisIR == nil || plan == nil {
		return nil
	}
	sets := types.CompileEnumerationDisplaySets(&ctx.AnalysisIR.RequestModel, plan)
	out := sets[:0]
	for _, set := range sets {
		if set.FactIndex < 0 || set.FactIndex >= len(plan.StableAggregateFacts) {
			continue
		}
		if types.EnumerationDisplaySetAuthorizesPrincipalContract(&ctx.AnalysisIR.RequestModel, plan.StableAggregateFacts[set.FactIndex], set) {
			out = append(out, set)
		}
	}
	observation := answerDocSourceInventoryObservation(ctx)
	if !observation.IsActive() {
		return out
	}
	view := types.BuildSourceInventoryAnswerAuthorityView(answerDocSourceInventoryAuthoritySnapshot(ctx, observation))
	if !view.PrincipalAuthority || len(view.PrincipalRows) == 0 {
		return out
	}
	return answerDocCanonicalizeSourceInventoryPrincipalEnumerationSets(out, view.PrincipalRows)
}

// answerDocCanonicalizeSourceInventoryPrincipalEnumerationSets collapses
// overlapping model aggregate facts onto the exact typed declaration universe.
// A model may describe one declaration once by its bare symbol and again by a
// decorated display label such as "name (package)". Those facts receive
// different aggregate row IDs even though they point at the same typed
// declaration. The source-inventory principal row is the authority for that
// identity, so a unique family+location coordinate gets exactly one display
// row. Ambiguous coordinates fail open: no declaration is collapsed when the
// typed inventory itself contains multiple same-family declarations there.
// This projection reads typed rows only; it never scans request, reasoning, or
// answer prose.
func answerDocCanonicalizeSourceInventoryPrincipalEnumerationSets(
	sets []types.EnumerationDisplaySet,
	principalRows []types.SourceInventoryRow,
) []types.EnumerationDisplaySet {
	return types.CanonicalizeSourceInventoryPrincipalEnumerationSets(sets, principalRows)
}

func renderAnswerDocPrincipalEnumerationRows(ctx *types.AgentContext, plan *types.AnswerSurfacePlan) string {
	if ctx == nil || ctx.AnalysisIR == nil || plan == nil {
		return ""
	}
	sets := answerDocPrincipalEnumerationSets(ctx, plan)
	if len(sets) == 0 {
		return ""
	}
	stableFacts := answerDocStableAggregateFacts(ctx)
	var b strings.Builder
	b.WriteString("## Principal Enumeration Rows\n\n")
	b.WriteString("- These rows are compiled deterministically from accepted principal aggregate facts, member-specific support refs, and grounded evidence. Use them as the stable row/citation skeleton for enumeration tables or lists.\n")
	b.WriteString("- Preserve every `member` as the principal row identity. Use `display_label`, `location`, and `citation_key` to build clear table cells; use `note` to keep the answer explanatory instead of a dry symbol dump.\n")
	b.WriteString("- When any row has a non-empty `note`, render that note on the same row as a concise description/说明 column or equivalent item text. Do not collapse per-row notes only into a summary paragraph.\n")
	b.WriteString("- When a row has non-empty `attributes`, preserve those typed dimensions on that same row as table columns or equivalent item text; do not infer them from paths.\n")
	b.WriteString("- When a set exposes `selection_family`, that exact typed value is the membership boundary because every row independently carries it. A model-authored `display_group` is presentation only: it must not add exclusions, subtract rows, or change the typed row count. If the display wording conflicts, keep the typed roster and rewrite the display wording yourself.\n")
	b.WriteString("- When the required principal table carries `bucket_label`, preserve every row's `display_group`/set label as a separate visible category cell and matching column. Keep the exact member in item `label` (or cells[0] for a cells-only row); never put the bucket in `label`, and never drop the bucket while repairing member identity.\n")
	b.WriteString("- For EVERY structured source-inventory item, copy that row's exact `row_id` to `source_inventory_row_id` and copy its exact `member`/`display_label` to item `label`; only a cells-only row may put the member in `cells[0]`. If a visible Markdown table puts category before member, keep the exact member in the hidden item `label` and copy the complete visible row to `cells`; do not use the category as row identity. The system binds the row-local citation, so omit manual `citation_ref` arithmetic. This keeps member, family, location, and citation on one typed identity even when labels are unique, decorated for display, or repeated across files. When rows expose `surface_family`, use that exact row-local key for grouping. A principal block intentionally carrying exactly one family should copy it to block `source_inventory_family`; omit the field for a global/mixed-family block. Never infer family from a block title, path, language, or neighboring row.\n")
	if ctx.AnalysisIR.RequestModel.Predicates.HasPerMemberTable {
		b.WriteString("- Render these rows exactly once in the required per-member `table`; that table is the single structured principal-member carrier. Preserve each set/bucket in a visible category column. Optional bucket `section` blocks may keep headings and concise framing prose, but MUST NOT repeat the principal rows in `section.items[]` or another list/table. Copy each `source_inventory_row_id` only to its table row.\n")
	} else {
		b.WriteString("- Render these rows once as structured items in the answer's principal carrier: use a required bucket `section`'s `items[]` when the row belongs to that bucket, or use an `ordered_list`, `bullet_list`, or `table` when no such section is required. Prose-only mentions in block `text` do not carry row identity; do not add a second global list/table merely to repeat rows already carried by sections.\n")
	}
	b.WriteString("- A row without `citation_key` is a legitimate non-file aggregate member; do not invent a `repo:0` citation for it.\n\n")
	if guidance := renderAnswerDocSourceInventoryRowGuidance(ctx); guidance != "" {
		b.WriteString(guidance)
		b.WriteString("\n")
	}
	if counts, covered, total := answerDocPrincipalEnumerationSurfaceFamilyCounts(sets); counts != "" {
		fmt.Fprintf(&b, "- typed_surface_family_row_counts=[%s], family_coverage=%d/%d, complete=%t. These mutually exclusive counts are computed from the same single typed `surface_family` rendered on each principal row; copy them exactly when reporting top-level family counts and do not recount the row prose. Finer row-local modifiers remain item detail and do not create additional top-level members. These row counts are the only numeric family summary authorized by this carrier; omit derived per-family file counts or modifier totals unless another typed fact supplies them. The counts sum to `family_coverage`, not necessarily to all rows when some rows have no typed family.\n\n",
			counts, covered, total, covered == total)
	}
	for _, set := range sets {
		title := answerDocPrincipalEnumerationSetAuthorityLabel(set)
		if title == "" {
			title = "Principal enumeration"
		}
		if len(set.Rows) > 0 {
			fmt.Fprintf(&b, "### %s (%d row(s))\n\n", title, len(set.Rows))
		}
		if display := strings.TrimSpace(set.Label); set.SelectionFamily != "" && display != "" && !strings.EqualFold(display, set.SelectionFamily) {
			fmt.Fprintf(&b, "- model-authored display_group=`%s` (presentation only; `selection_family` remains the membership authority)\n", display)
		}
		for _, row := range set.Rows {
			member := sanitizeAggregateExcludedCandidatesForPrompt(ctx, row.Member, stableFacts)
			label := sanitizeAggregateExcludedCandidatesForPrompt(ctx, row.DisplayLabel, stableFacts)
			note := sanitizeAggregateExcludedCandidatesForPrompt(ctx, row.Note, stableFacts)
			fmt.Fprintf(&b, "- row_id=`%s`, member=`%s`", row.RowID, member)
			if label != "" && label != member {
				fmt.Fprintf(&b, ", display_label=`%s`", label)
			}
			if category := strings.TrimSpace(row.Category); category != "" {
				fmt.Fprintf(&b, ", category=%s", category)
			}
			if family := types.SourceInventorySurfaceFamilyKey(row.SurfaceTerms); family != "" {
				fmt.Fprintf(&b, ", surface_family=`%s`", family)
			}
			if location := strings.TrimSpace(row.Location); location != "" {
				fmt.Fprintf(&b, ", location=`%s`", location)
			}
			if citationKey := strings.TrimSpace(row.CitationKey); citationKey != "" {
				fmt.Fprintf(&b, ", citation_key=`%s`", citationKey)
			}
			if row.ClaimForm != types.ClaimUnknown {
				fmt.Fprintf(&b, ", claim_form=%s", row.ClaimForm)
			}
			if row.MemberSurface != types.PrincipalMemberSurfaceUnknown {
				fmt.Fprintf(&b, ", member_surface=%s", row.MemberSurface)
			}
			if equivalents := renderSupportEntryEquivalentLocations(row.EquivalentLocations); equivalents != "" {
				fmt.Fprintf(&b, ", equivalent_locations=%s", equivalents)
			}
			if attrs := renderEnumerationDisplayRowAttributes(row.Attributes); attrs != "" {
				fmt.Fprintf(&b, ", attributes=%s", attrs)
			}
			if note != "" {
				fmt.Fprintf(&b, " — note: %s", note)
			}
			b.WriteString("\n")
		}
		b.WriteString("\n")
	}
	return b.String()
}

// answerDocPrincipalEnumerationSurfaceFamilyCounts publishes exact canonical
// row-family cardinalities beside the authoritative principal rows. It uses
// the same single family selector as the row renderer; finer independent
// parser markers remain row-local detail rather than becoming overlapping
// top-level buckets. The finalizer should not have to recount a long
// Markdown-like list, and shadowed model aggregates must not regain numeric
// authority merely because their labels resemble one of these families. This
// projection consumes only typed row SurfaceTerms; it never reads the request,
// model reasoning, answer prose, or rendered output.
func answerDocPrincipalEnumerationSurfaceFamilyCounts(sets []types.EnumerationDisplaySet) (string, int, int) {
	counts := map[string]int{}
	covered := 0
	total := 0
	for _, set := range sets {
		for _, row := range set.Rows {
			total++
			family := types.SourceInventorySurfaceFamilyKey(row.SurfaceTerms)
			if family == "" {
				continue
			}
			covered++
			counts[family]++
		}
	}
	if len(counts) == 0 {
		return "", covered, total
	}
	families := make([]string, 0, len(counts))
	for family := range counts {
		families = append(families, family)
	}
	sort.Strings(families)
	parts := make([]string, 0, len(families))
	for _, family := range families {
		parts = append(parts, fmt.Sprintf("`%s`:%d", family, counts[family]))
	}
	return strings.Join(parts, ", "), covered, total
}

func answerDocPrincipalEnumerationSetAuthorityLabel(set types.EnumerationDisplaySet) string {
	if family := strings.TrimSpace(set.SelectionFamily); family != "" {
		return family
	}
	return strings.TrimSpace(set.Label)
}

func renderEnumerationDisplayRowAttributes(attrs []types.EnumerationDisplayRowAttribute) string {
	if len(attrs) == 0 {
		return ""
	}
	parts := make([]string, 0, len(attrs))
	seen := map[string]bool{}
	for _, attr := range attrs {
		name := strings.TrimSpace(attr.Name)
		if name == "" {
			continue
		}
		role := strings.TrimSpace(string(attr.Role))
		if role == "" {
			role = "attribute"
		}
		part := role + ":" + name
		key := strings.ToLower(part)
		if seen[key] {
			continue
		}
		seen[key] = true
		parts = append(parts, part)
	}
	if len(parts) == 0 {
		return ""
	}
	sort.Strings(parts)
	escaped := make([]string, 0, len(parts))
	for _, part := range parts {
		escaped = append(escaped, "`"+part+"`")
	}
	return "[" + strings.Join(escaped, ", ") + "]"
}

func renderAnswerDocSourceInventoryRowGuidance(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil || ctx.AnalysisIR.RequestModel.SourceInventoryProfile == nil ||
		!ctx.AnalysisIR.RequestModel.SourceInventoryProfile.Active() {
		return ""
	}
	profile := ctx.AnalysisIR.RequestModel.SourceInventoryProfile
	var fields []string
	for _, field := range profile.RequestedFields {
		fields = append(fields, string(field))
	}
	if len(fields) == 0 {
		fields = append(fields, "name", "location")
	}
	var b strings.Builder
	fmt.Fprintf(&b, "Source-inventory row contract: the requested answer fields are `%s`.\n", strings.Join(fields, "`, `"))
	if profile.RequestsField(types.SourceInventoryFieldLocation) {
		b.WriteString("- `location` is a user-visible row field: copy each row's exact `location` into that same item's text/cells (prefer a Location/文件路径 column for tables). A bound `citation_ref` proves the row but does not replace the requested visible file path.\n")
	}
	b.WriteString("- A typed source-inventory row proves that exact declaration/construct kind, location, and listed typed attributes only. It does not by itself prove inheritance, implementation, execution, ownership, or another behavioral relation. When `summary` was not requested, keep the row to the requested fields and do not invent such a relation.\n")
	if profile.RequiresConstSet {
		b.WriteString("- `requires_const_set=true` is a membership qualifier for enum-like types; it does not by itself mean the final answer should list every const/member value.\n")
	}
	if !profile.RequestsField(types.SourceInventoryFieldValues) {
		b.WriteString("- Do not surface literal enum/member values or variant lists in the principal table/list unless they are already part of the type name/location itself. Keep the principal surface aligned to the requested fields.\n")
	}
	return b.String()
}

func answerDocPrincipalRelationMemberSetRefs(ctx *types.AgentContext, facts []types.AnswerAggregateFact) []types.AnswerAggregateFactRef {
	var rm *types.RequestModel
	var refs []types.AnswerAggregateFactRef
	if ctx == nil || ctx.AnalysisIR == nil {
		refs = types.PrincipalRelationMemberSetFactRefs(facts)
	} else {
		rm = &ctx.AnalysisIR.RequestModel
		refs = types.PrincipalRelationMemberSetFactRefsForRequest(facts, rm)
	}
	out := refs[:0]
	for _, ref := range refs {
		if types.AnswerAggregateFactAuthorizesPrincipalContract(ref.Fact, rm) {
			out = append(out, ref)
		}
	}
	return out
}

func answerDocHasMultiMemberAggregateRef(refs []types.AnswerAggregateFactRef) bool {
	for _, ref := range refs {
		if len(ref.Fact.Members) > 1 {
			return true
		}
	}
	return false
}

const (
	answerDocDefaultEnrichmentFacts       = 14
	answerDocMaxEnrichmentFacts           = 28
	answerDocDefaultFlowEnrichmentFacts   = 3
	answerDocPreferredFlowEnrichmentFacts = 8
	answerDocMaxFlowEnrichmentFacts       = 12
	// Typed enrichment is prompt guidance, not an answer contract. Keep
	// its candidate scan bounded so large repositories cannot spend
	// minutes re-ranking optional context before the finalizer's first
	// LLM request.
	answerDocMaxEnrichmentCandidateFacts = 1024
	answerDocMaxFlowEnrichmentScan       = 2048
	answerDocMaxEnrichmentSurfaceBytes   = 640
)

type answerDocEnrichmentFact struct {
	item    types.EvidenceItem
	lane    string
	label   string
	surface string
	score   int
	index   int
}

type supportLaneScope struct {
	constrain             bool
	principalDiagramFloor bool
	evidenceIDs           map[string]bool
	locations             map[string]bool
	files                 map[string]bool
	fileLines             map[string][]int
	anchors               map[string]bool
	lanes                 map[types.AnswerSupportLaneKind]bool
	diagnosticLanes       bool
}

// supportLaneScopeFromFlowOperations is the no-support-plan authority bridge.
// It consumes only citable directed operation carriers already accepted in
// this investigation. The ordinary support-plan path remains stronger and is
// always preferred when present.
func supportLaneScopeFromFlowOperations(items []types.EvidenceItem) *supportLaneScope {
	scope := &supportLaneScope{
		constrain:   true,
		evidenceIDs: map[string]bool{},
		locations:   map[string]bool{},
		files:       map[string]bool{},
		fileLines:   map[string][]int{},
		anchors:     map[string]bool{},
		lanes:       map[types.AnswerSupportLaneKind]bool{},
	}
	for _, item := range items {
		for _, raw := range []string{item.ID, answerDocEvidenceIdentity(item)} {
			scope.addEvidenceID(raw)
		}
		scope.addLocation(item.Source, item.LineStart)
		for _, raw := range []string{
			item.Subject,
			item.Object,
			item.AnchorSymbol,
			item.OwnerSymbol,
		} {
			scope.addAnchor(raw)
		}
		for _, term := range item.SurfaceTerms {
			scope.addAnchor(term)
		}
	}
	return scope
}

func renderAnswerDocTypedExplorationEnrichment(ctx *types.AgentContext, supportRendered bool) string {
	if ctx == nil {
		return ""
	}
	evidence := answerDocTypedEnrichmentEvidencePool(ctx, answerDocMaxEnrichmentCandidateFacts)
	supportScope := supportLaneScopeForContext(ctx, supportRendered)
	facts := selectAnswerDocTypedEnrichmentFacts(ctx, evidence, supportRendered, supportScope)
	flowLines := selectAnswerDocFlowEnrichmentLines(ctx.FlowFindings, answerDocFlowEnrichmentLimit(ctx), supportScope)
	if len(facts) == 0 && len(flowLines) == 0 {
		return ""
	}

	var b strings.Builder
	b.WriteString("## Typed Exploration Enrichment Facts\n\n")
	b.WriteString("- This section is a typed replay of structured exploration handoff only: model-emitted `EvidenceItems`, deterministic evidence projections, and `FlowFindings`. It does not read raw thinking text, raw investigation notes, or unstructured closure prose.\n")
	b.WriteString("- Use these facts to enrich the same principal subject, block, facet, hop, scalar, or verdict that the current request asks for. They are not a member slate by themselves.\n")
	b.WriteString("- Do not promote an enrichment fact into a new principal ordered-list member, diagram node/edge, exact target, or countable bucket unless a typed support lane, exact-resolution contract, answer-symbol slate, structured aggregate fact, or cited source line independently makes it principal.\n")
	b.WriteString("- Rows marked `lane=principal_definition_fact` are grounded definition details from files read during exploration and within the requested source scope. They are the highest-priority detail/citation source for already-principal members; preserve their summaries when the answer asks for per-member explanations.\n")
	if supportRendered {
		b.WriteString("- Because typed support lanes are present, those lanes remain the principal boundary. Treat rows here as context, detail, exclusions, or same-item explanation only.\n")
	}
	b.WriteString("\n")

	if len(facts) > 0 {
		b.WriteString("### Evidence enrichment rows\n\n")
		stableFacts := answerDocStableAggregateFacts(ctx)
		for _, fact := range facts {
			loc := fact.item.DisplayLocation(true)
			fmt.Fprintf(&b, "- lane=%s", fact.lane)
			if fact.label != "" {
				label := sanitizeAggregateExcludedCandidatesForPrompt(ctx, fact.label, stableFacts)
				fmt.Fprintf(&b, " label=`%s`", label)
			}
			if loc != "" {
				fmt.Fprintf(&b, " @ %s", loc)
			}
			surface := sanitizeAggregateExcludedCandidatesForPrompt(ctx, fact.surface, stableFacts)
			if ctx != nil && ctx.AnalysisIR != nil {
				surface = types.SanitizeSourceInventoryNoteForRequest(&ctx.AnalysisIR.RequestModel, surface)
			}
			fmt.Fprintf(&b, ": %s", surface)
			if form := answerDocReturnExpressionForm(fact.item); form != "" {
				fmt.Fprintf(&b, " expression_form=`%s`", form)
			}
			if role := answerDocEvidenceRoleTag(fact.item); role != "" {
				fmt.Fprintf(&b, " (%s)", role)
			}
			b.WriteString("\n")
		}
		b.WriteString("\n")
	}
	if len(flowLines) > 0 {
		b.WriteString("### Flow/source-sink rows\n\n")
		for _, line := range flowLines {
			fmt.Fprintf(&b, "- %s\n", line)
		}
		b.WriteString("\n")
	}
	return b.String()
}

func answerDocStableAggregateFacts(ctx *types.AgentContext) []types.AnswerAggregateFact {
	plan := answerSurfacePlan(ctx)
	if plan == nil {
		return nil
	}
	return plan.StableAggregateFacts
}

func answerDocTypedEnrichmentEvidencePool(ctx *types.AgentContext, limit int) []types.EvidenceItem {
	if ctx == nil || limit <= 0 {
		return nil
	}
	// A later emit_evidence correction deliberately keeps the durable ID of
	// the row it amends.  The orchestrator truth set can therefore carry the
	// earlier carrier while Mutable's append-tail already has the corrected
	// call/guard/assignment shape under that same ID.  First-ID-wins loses the
	// correction and can make the finalizer report zero typed relations even
	// though Explorer just grounded one.  Reconcile same-ID rows through the
	// canonical coherent-carrier merger instead.  This only transports model-
	// authored evidence; it does not infer or synthesize a relation.
	seen := make(map[string]int, limit)
	out := make([]types.EvidenceItem, 0, extractorMinInt(len(ctx.EvidenceItems), limit))
	addGroup := func(items []types.EvidenceItem) {
		for _, item := range items {
			id := strings.TrimSpace(item.ID)
			if id == "" {
				id = types.StableEvidenceID(item)
				item.ID = id
			}
			if idx, ok := seen[id]; ok {
				out[idx] = types.MergeEvidenceItemByStableID(out[idx], item)
				continue
			}
			if len(out) >= limit {
				continue
			}
			seen[id] = len(out)
			out = append(out, item)
		}
	}
	// ctx.EvidenceItems is already the orchestrator's ranked,
	// deduplicated truth set. Prefer it over raw Mutable emissions; the
	// latter is only a backstop for unusual tests or partial contexts.
	addGroup(ctx.EvidenceItems)
	if ctx.Mutable != nil && len(out) < limit {
		if ta := ctx.Mutable.TurnAArtifacts(); ta != nil {
			addGroup(ta.EvidenceItems)
		}
	}
	if ctx.Mutable != nil && len(out) < limit {
		addGroup(ctx.Mutable.EmittedEvidence())
	}
	return out
}

func selectAnswerDocTypedEnrichmentFacts(
	ctx *types.AgentContext,
	evidence []types.EvidenceItem,
	supportRendered bool,
	supportScope *supportLaneScope,
) []answerDocEnrichmentFact {
	if len(evidence) == 0 {
		return nil
	}
	needles := extractorValueEvidenceNeedles(ctx, nil)
	profile := extractorValueEvidenceRankProfileFor(ctx)
	limit := answerDocEnrichmentDisplayLimit(ctx, profile, evidence)
	candidates := make([]answerDocEnrichmentFact, 0, len(evidence))
	hasRelevant := false
	for i, item := range evidence {
		// Explicitly rejected evidence may remain in the append-tailed audit
		// buffer so Explorer can repair it, but it has no factual authority in
		// the finalizer handoff.  In particular, selecting the lane from an
		// ungrounded assignment/initializer anchor would make a rejected field
		// declaration look like a value fact.  Preserve recovered evidence under
		// the existing policy; only the typed fail-closed verdict is excluded.
		if item.GroundingStatus == types.GroundingUngrounded {
			continue
		}
		if runtimeObservationOnlyForAnswerDoc(ctx) && answerDocEvidenceIsCurrentRepoOnly(item) {
			continue
		}
		if supportRendered && supportScope != nil && supportScope.hasEvidenceID(answerDocEvidenceIdentity(item)) {
			continue
		}
		if supportScope != nil && !supportScope.allowsEvidence(item) {
			continue
		}
		principalDefinition := answerDocEvidenceIsPrincipalDefinitionFact(ctx, item)
		lane := answerDocEnrichmentLaneForEvidence(item)
		if principalDefinition {
			lane = "principal_definition_fact"
		}
		if lane == "" {
			continue
		}
		surface := strings.TrimSpace(types.EvidenceAuthoritativeSurfaceText(item, false))
		if surface == "" {
			continue
		}
		if principalDefinition {
			surface = answerDocDefinitionSurfaceWithSummary(item, surface)
		}
		surface = truncateAnswerDocPromptText(surface, answerDocMaxEnrichmentSurfaceBytes)
		label := answerDocEnrichmentEvidenceLabel(item)
		score := answerDocEnrichmentEvidenceScore(item, label, surface, lane, needles, profile)
		if score > 0 {
			hasRelevant = true
		}
		candidates = append(candidates, answerDocEnrichmentFact{
			item:    item,
			lane:    lane,
			label:   label,
			surface: surface,
			score:   score,
			index:   i,
		})
	}
	if len(candidates) == 0 {
		return nil
	}
	if hasRelevant {
		filtered := candidates[:0]
		for _, candidate := range candidates {
			if candidate.score > 0 || candidate.item.SalienceLockedForScoring() {
				filtered = append(filtered, candidate)
			}
		}
		candidates = filtered
	}
	sort.SliceStable(candidates, func(i, j int) bool {
		if candidates[i].item.SalienceLockedForScoring() != candidates[j].item.SalienceLockedForScoring() {
			return candidates[i].item.SalienceLockedForScoring()
		}
		if candidates[i].score != candidates[j].score {
			return candidates[i].score > candidates[j].score
		}
		return candidates[i].index < candidates[j].index
	})
	if len(candidates) > limit {
		candidates = candidates[:limit]
	}
	return candidates
}

func answerDocEvidenceIsCurrentRepoOnly(item types.EvidenceItem) bool {
	switch item.Origin {
	case types.ClaimOriginLog, types.ClaimOriginPerf, types.ClaimOriginCrossSource:
		return false
	case types.ClaimOriginCurrentRepo:
		return true
	}
	source := strings.TrimSpace(item.Source)
	if source == "" {
		return false
	}
	source = strings.ReplaceAll(source, `\`, `/`)
	return strings.Contains(source, "/")
}

func answerDocEnrichmentDisplayLimit(ctx *types.AgentContext, profile extractorValueRankProfile, evidence []types.EvidenceItem) int {
	limit := answerDocDefaultEnrichmentFacts
	if ctx != nil && ctx.AnalysisIR != nil {
		rm := ctx.AnalysisIR.RequestModel
		if len(rm.SubTopics) >= 2 {
			limit += extractorMinInt(len(rm.SubTopics)*2, 6)
		}
		if buckets := rm.QuestionStructure().Buckets; len(buckets) >= 2 {
			limit += extractorMinInt(len(buckets)*2, 6)
		}
		if rm.Complexity == types.ComplexityComplex {
			limit += 4
		}
		if rm.Predicates.IsCrossComponent || rm.Predicates.IsRelationalLookup || rm.Predicates.IsCategoryEnumeration {
			limit += 4
		}
	}
	switch profile {
	case extractorValueRankTrace, extractorValueRankDiagnostic, extractorValueRankComparison, extractorValueRankEnumeration:
		limit += 4
	case extractorValueRankScalar:
		limit -= 2
	}
	limit = widenEvidenceLimitForSalience(limit, 8, answerDocMaxEnrichmentFacts, evidence, "answer_document")
	if limit < 8 {
		return 8
	}
	if limit > answerDocMaxEnrichmentFacts {
		return answerDocMaxEnrichmentFacts
	}
	return limit
}

func answerDocEnrichmentLaneForEvidence(item types.EvidenceItem) string {
	switch item.Kind {
	case types.EvidenceConcrete:
		return "value_fact"
	case types.EvidenceDataflowPath:
		return "flow_fact"
	case types.EvidenceControlFlow:
		return "flow_fact"
	case types.EvidenceAbsent, types.EvidenceConflict, types.EvidenceUnresolved, types.EvidenceTruncated:
		return "boundary_or_exclusion_fact"
	}
	switch item.ContextRole {
	case types.EvidenceContextRoleAbsenceSupport, types.EvidenceContextRoleIllustrativeOnly, types.EvidenceContextRoleRelatedContext:
		return "context_enrichment_fact"
	}
	switch item.AnchorKind {
	case types.AnchorAssignment, types.AnchorInitializer, types.AnchorReturn:
		return "value_fact"
	case types.AnchorCall, types.AnchorCallback, types.AnchorArgument, types.AnchorCondition, types.AnchorImport:
		return "chain_or_intermediate_fact"
	}
	if item.LoadBearingSummary || len(item.SurfaceTerms) > 0 {
		return "context_enrichment_fact"
	}
	if item.SalienceLockedForScoring() {
		return "context_enrichment_fact"
	}
	switch item.Authority {
	case types.AuthorityConditional, types.AuthorityHistorical, types.AuthorityIllustrative:
		return "boundary_or_exclusion_fact"
	}
	return ""
}

// answerDocReturnExpressionForm adds a small typed interpretation aid for a
// deterministic return row. It reads only the structured return Object and is
// prompt guidance, never an answer-side gate. The deliberately narrow
// classifier distinguishes an invocation result such as `cls()` / `new Foo()`
// / `Box::new()` from a bare class or function reference without claiming the
// runtime concrete type or replacing the model's conclusion.
func answerDocReturnExpressionForm(item types.EvidenceItem) string {
	if item.AnchorKind != types.AnchorReturn || strings.TrimSpace(item.Object) == "" {
		return ""
	}
	expression := strings.TrimSpace(item.Object)
	for {
		trimmed := expression
		for _, prefix := range []string{"await ", "try ", "try? ", "try! ", "new "} {
			if strings.HasPrefix(trimmed, prefix) {
				expression = strings.TrimSpace(strings.TrimPrefix(trimmed, prefix))
				break
			}
		}
		if expression == trimmed {
			break
		}
	}
	open := strings.IndexByte(expression, '(')
	close := strings.LastIndexByte(expression, ')')
	if open <= 0 || close <= open {
		return ""
	}
	callee := strings.TrimSpace(expression[:open])
	if callee == "" || strings.ContainsAny(callee, " \t\r\n=,+*/%&|!?:") {
		// `::` is a valid Rust/C++/Cangjie qualifier. Restore that case after
		// rejecting other conditional/operator-shaped expressions.
		if !strings.Contains(callee, "::") || strings.ContainsAny(strings.ReplaceAll(callee, "::", ""), " \t\r\n=,+*/%&|!?:") {
			return ""
		}
	}
	last := callee[len(callee)-1]
	if !((last >= 'a' && last <= 'z') || (last >= 'A' && last <= 'Z') ||
		(last >= '0' && last <= '9') || last == '_' || last == '$' || last == '>' || last == ']') {
		return ""
	}
	return "call_result"
}

func answerDocEnrichmentEvidenceLabel(item types.EvidenceItem) string {
	for _, raw := range []string{item.Subject, item.AnchorSymbol, item.OwnerSymbol, item.Object, item.Source} {
		if label := strings.TrimSpace(raw); label != "" {
			return label
		}
	}
	if item.AnchorKind != "" {
		return string(item.AnchorKind)
	}
	return string(item.Kind)
}

func answerDocEnrichmentEvidenceScore(
	item types.EvidenceItem,
	label string,
	surface string,
	lane string,
	needles map[string]bool,
	profile extractorValueRankProfile,
) int {
	score := extractorValueEvidenceScore(item, label, surface, needles, profile)
	switch lane {
	case "principal_definition_fact":
		score += 16
	case "value_fact":
		score += 8
	case "flow_fact":
		score += 10
	case "chain_or_intermediate_fact":
		switch profile {
		case extractorValueRankTrace, extractorValueRankDiagnostic, extractorValueRankComparison:
			score += 10
		default:
			score += 5
		}
	case "boundary_or_exclusion_fact":
		switch profile {
		case extractorValueRankDiagnostic, extractorValueRankComparison:
			score += 10
		default:
			score += 6
		}
	case "context_enrichment_fact":
		score += 4
	}
	if len(item.SurfaceTerms) > 0 {
		score += 4
	}
	switch item.ContextRole {
	case types.EvidenceContextRoleRelatedContext, types.EvidenceContextRoleAbsenceSupport:
		score += 2
	case types.EvidenceContextRoleIllustrativeOnly:
		score -= 2
	}
	if score == 0 && len(needles) == 0 {
		return 1
	}
	return score
}

func answerDocEvidenceIsPrincipalDefinitionFact(ctx *types.AgentContext, item types.EvidenceItem) bool {
	if ctx == nil || ctx.AnalysisIR == nil {
		return false
	}
	rm := ctx.AnalysisIR.RequestModel
	if !types.IsCategoryEnumerationAnswerShape(rm) && len(answerDocStableAggregateFacts(ctx)) == 0 {
		return false
	}
	if item.Kind != types.EvidenceDirect ||
		item.AnchorKind != types.AnchorDefinition ||
		item.GroundingStatus == types.GroundingUngrounded ||
		strings.TrimSpace(item.Source) == "" ||
		item.LineStart <= 0 {
		return false
	}
	scope := types.SourceScopeProduction
	if rm.SourceScopeProfile != nil && rm.SourceScopeProfile.RequestedScope != "" {
		scope = rm.SourceScopeProfile.RequestedScope
	}
	if !types.SourceScopeAllowsPathRole(scope, types.ClassifySourcePathRole(item.Source)) {
		return false
	}
	return answerDocEvidenceSourceWasRead(ctx, item.Source)
}

func answerDocEvidenceSourceWasRead(ctx *types.AgentContext, source string) bool {
	if ctx == nil || ctx.Mutable == nil {
		return true
	}
	ta := ctx.Mutable.TurnAArtifacts()
	if ta == nil || len(ta.ReadFiles) == 0 {
		return true
	}
	for _, readFile := range ta.ReadFiles {
		if answerDocPathMatches(readFile, source) {
			return true
		}
	}
	return false
}

func answerDocPathMatches(a, b string) bool {
	a = strings.ToLower(strings.Trim(strings.TrimSpace(strings.ReplaceAll(a, `\`, `/`)), "/"))
	b = strings.ToLower(strings.Trim(strings.TrimSpace(strings.ReplaceAll(b, `\`, `/`)), "/"))
	a = strings.TrimPrefix(a, "./")
	b = strings.TrimPrefix(b, "./")
	if a == "" || b == "" {
		return false
	}
	return a == b || strings.HasSuffix(a, "/"+b) || strings.HasSuffix(b, "/"+a)
}

func answerDocDefinitionSurfaceWithSummary(item types.EvidenceItem, surface string) string {
	if !item.LoadBearingSummary {
		return surface
	}
	summary := strings.TrimSpace(item.Summary)
	if summary == "" {
		return surface
	}
	if strings.Contains(surface, summary) {
		return surface
	}
	surface = strings.TrimSpace(surface)
	if surface == "" {
		return summary
	}
	return surface + " — " + summary
}

func answerDocEvidenceRoleTag(item types.EvidenceItem) string {
	var parts []string
	if item.Kind != "" {
		parts = append(parts, "kind="+string(item.Kind))
	}
	if form := types.ClaimFormOf(item); form != types.ClaimUnknown {
		parts = append(parts, "claim_form="+string(form))
	}
	if item.ContextRole != "" {
		parts = append(parts, "context_role="+string(item.ContextRole))
	}
	if item.Authority != "" {
		parts = append(parts, "authority="+string(item.Authority))
	}
	if boundary := types.EvidenceMechanismAuthorityBoundary(item); boundary != "" {
		parts = append(parts, boundary)
	}
	return strings.Join(parts, ", ")
}

func supportLaneScopeForContext(ctx *types.AgentContext, supportRendered bool) *supportLaneScope {
	if !supportRendered {
		return nil
	}
	plan := answerSupportPlan(ctx)
	return supportLaneScopeFromCompiledPlan(ctx, plan, supportRendered)
}

// supportLaneScopeFromCompiledPlan keeps every consumer of an already-built
// support plan on the same required-diagram boundary. Explorer StageReport
// rendering uses this entry point because its deterministic digest is built
// before the extractor/finalizer AgentContext exists; the full structured
// evidence and findings remain untouched for those later stages.
func supportLaneScopeFromCompiledPlan(
	ctx *types.AgentContext,
	plan *types.AnswerSupportPlan,
	supportRendered bool,
) *supportLaneScope {
	if !supportRendered {
		return nil
	}
	if plan == nil {
		return nil
	}
	// A required diagram already publishes one bounded principal support
	// floor. Optional lexical/flow enrichment must follow that same visible
	// floor instead of reopening every broad facet candidate in the full
	// support plan. Other answer families retain the full-plan behavior.
	if dc := answerDocDiagramContract(ctx); dc != nil && dc.Required {
		if diagramScope := supportLaneScopeFromDiagramPlan(
			plan,
			answerDocDiagramSupportSeedLimit,
			extractorValueEvidenceRankProfileFor(ctx),
		); diagramScope != nil && diagramScope.constrain {
			return diagramScope
		}
	}
	return supportLaneScopeFromPlan(plan, supportRendered, extractorValueEvidenceRankProfileFor(ctx))
}

func supportLaneScopeFromDiagramPlan(
	plan *types.AnswerSupportPlan,
	limit int,
	profile extractorValueRankProfile,
) *supportLaneScope {
	if plan == nil || limit <= 0 {
		return nil
	}
	filtered := &types.AnswerSupportPlan{Family: plan.Family}
	seen := make(map[string]bool)
	selected := 0
	for _, lane := range plan.Lanes {
		if !answerSupportLaneAllowsDiagram(lane) {
			continue
		}
		filteredLane := types.AnswerSupportLane{
			Kind:          lane.Kind,
			AllowedBlocks: append([]string(nil), lane.AllowedBlocks...),
		}
		for _, entry := range lane.Entries {
			display := diagramSupportEntrySurface(entry)
			if display == "" {
				continue
			}
			key := strings.ToLower(display) + "\x00" + strings.ToLower(strings.TrimSpace(entry.Location))
			if seen[key] {
				continue
			}
			seen[key] = true
			filteredLane.Entries = append(filteredLane.Entries, entry)
			selected++
			if selected >= limit {
				break
			}
		}
		if len(filteredLane.Entries) > 0 {
			filtered.Lanes = append(filtered.Lanes, filteredLane)
		}
		if selected >= limit {
			break
		}
	}
	if selected == 0 {
		return nil
	}
	scope := supportLaneScopeFromPlan(filtered, true, profile)
	if scope != nil {
		// The filtered plan is the visible principal diagram floor. Optional
		// relation context may replay an exact support evidence id or connect
		// two ordered principal endpoints; sharing just one endpoint is a
		// sibling coincidence, not support for the requested relationship.
		scope.principalDiagramFloor = true
	}
	return scope
}

func supportLaneScopeFromPlan(plan *types.AnswerSupportPlan, supportRendered bool, _ extractorValueRankProfile) *supportLaneScope {
	if plan == nil {
		return nil
	}
	scope := &supportLaneScope{
		evidenceIDs: map[string]bool{},
		locations:   map[string]bool{},
		files:       map[string]bool{},
		fileLines:   map[string][]int{},
		anchors:     map[string]bool{},
		lanes:       map[types.AnswerSupportLaneKind]bool{},
	}
	for _, lane := range plan.Lanes {
		scope.lanes[lane.Kind] = true
		for _, entry := range lane.Entries {
			for _, raw := range []string{
				entry.EvidenceID,
				answerDocEvidenceIdentity(types.EvidenceItem{
					ID:           entry.EvidenceID,
					Source:       entry.Source,
					LineStart:    entry.LineStart,
					AnchorKind:   entry.AnchorKind,
					Subject:      entry.Subject,
					Object:       entry.Object,
					AnchorSymbol: entry.AnchorSymbol,
					OwnerSymbol:  entry.OwnerSymbol,
				}),
			} {
				scope.addEvidenceID(raw)
			}
			scope.addLocation(entry.Source, entry.LineStart)
			scope.addLocationText(entry.Location)
			for _, loc := range entry.EquivalentLocations {
				scope.addLocationText(loc)
			}
			for _, raw := range []string{
				entry.Subject,
				entry.Object,
				entry.AnchorSymbol,
				entry.OwnerSymbol,
				string(entry.MemberSurface),
			} {
				scope.addAnchor(raw)
			}
			for _, term := range entry.SurfaceTerms {
				scope.addAnchor(term)
			}
		}
	}
	scope.diagnosticLanes =
		scope.lanes[types.SupportLaneObservedArtifact] ||
			scope.lanes[types.SupportLaneCurrentCodePath] ||
			scope.lanes[types.SupportLaneNearestMechanism] ||
			scope.lanes[types.SupportLaneUncertaintyBound] ||
			scope.lanes[types.SupportLaneCurrentVerdict]
	scope.constrain = supportRendered &&
		(len(scope.evidenceIDs) > 0 ||
			len(scope.locations) > 0 ||
			len(scope.files) > 0 ||
			len(scope.anchors) > 0)
	return scope
}

func (s *supportLaneScope) addEvidenceID(raw string) {
	if s == nil {
		return
	}
	key := strings.TrimSpace(raw)
	if key != "" {
		s.evidenceIDs[key] = true
	}
}

func (s *supportLaneScope) addLocation(source string, line int) {
	if s == nil {
		return
	}
	file := supportLaneScopeFileKey(source)
	if file == "" {
		return
	}
	s.files[file] = true
	if line <= 0 {
		return
	}
	loc := supportLaneScopeLocationKey(file, line)
	s.locations[loc] = true
	s.fileLines[file] = append(s.fileLines[file], line)
}

func (s *supportLaneScope) addLocationText(raw string) {
	if s == nil {
		return
	}
	file, line := supportLaneScopeParseLocation(raw)
	s.addLocation(file, line)
}

func (s *supportLaneScope) addAnchor(raw string) {
	if s == nil {
		return
	}
	key := supportLaneScopeAnchorKey(raw)
	if key == "" {
		return
	}
	s.anchors[key] = true
	if tail := types.NormalizedSurfaceSymbolTail(raw); tail != "" {
		s.anchors[tail] = true
	}
}

func (s *supportLaneScope) hasEvidenceID(raw string) bool {
	if s == nil {
		return false
	}
	return s.evidenceIDs[strings.TrimSpace(raw)]
}

func (s *supportLaneScope) allowsEvidence(item types.EvidenceItem) bool {
	if s == nil || !s.constrain {
		return true
	}
	if s.principalDiagramFloor {
		return s.allowsPrincipalDiagramEvidence(item)
	}
	if s.hasEvidenceID(answerDocEvidenceIdentity(item)) {
		return true
	}
	switch item.Origin {
	case types.ClaimOriginLog, types.ClaimOriginPerf:
		return s.lanes[types.SupportLaneObservedArtifact]
	}
	if s.hasLocation(item.Source, item.LineStart) {
		return true
	}
	if s.requiresExactLocationForConcreteSourceEvidence(item) {
		return false
	}
	for _, raw := range []string{
		item.Subject,
		item.Object,
		item.AnchorSymbol,
		item.OwnerSymbol,
		item.Predicate,
		item.Condition,
	} {
		if s.hasAnchor(raw) {
			return true
		}
	}
	for _, term := range item.SurfaceTerms {
		if s.hasAnchor(term) {
			return true
		}
	}
	return false
}

// allowsPrincipalDiagramEvidence is stricter than the ordinary advisory
// evidence scope. The visible principal path is already a bounded selection;
// a nearby line or a sibling fact from the same owner/file must not reopen the
// wider investigation in finalizer-facing digests. Exact support identity or
// exact source location remains authoritative. Location-less compatibility
// rows may still bind an exact typed endpoint.
func (s *supportLaneScope) allowsPrincipalDiagramEvidence(item types.EvidenceItem) bool {
	if s == nil || !s.constrain {
		return true
	}
	if s.hasEvidenceID(answerDocEvidenceIdentity(item)) {
		return true
	}
	switch item.Origin {
	case types.ClaimOriginLog, types.ClaimOriginPerf:
		return s.lanes[types.SupportLaneObservedArtifact]
	}
	if s.hasExactLocation(item.Source, item.LineStart) {
		return true
	}
	if strings.TrimSpace(item.Source) != "" && item.LineStart > 0 {
		return false
	}
	for _, raw := range []string{
		item.Subject,
		item.Object,
		item.AnchorSymbol,
		item.OwnerSymbol,
	} {
		if s.hasAnchor(raw) {
			return true
		}
	}
	return false
}

func (s *supportLaneScope) allowsLocalFact(owner string, item types.EvidenceItem) bool {
	if s == nil || !s.constrain {
		return true
	}
	if s.hasEvidenceID(answerDocEvidenceIdentity(item)) {
		return true
	}
	// Lexical order is an owner-local statement. A nearby line in the same
	// file may belong to a sibling helper and cannot connect that helper to
	// the principal support. When no typed owner/endpoint exists, fall back to
	// the ordinary location/file compatibility behavior.
	if len(s.anchors) > 0 {
		return s.hasAnchor(owner)
	}
	return s.allowsEvidence(item)
}

func (s *supportLaneScope) requiresExactLocationForConcreteSourceEvidence(item types.EvidenceItem) bool {
	if s == nil || len(s.locations) == 0 {
		return false
	}
	switch item.Origin {
	case types.ClaimOriginLog, types.ClaimOriginPerf:
		return false
	}
	source := strings.TrimSpace(item.Source)
	if source == "" || item.LineStart <= 0 {
		return false
	}
	return supportLaneScopeFileKey(source) != ""
}

func (s *supportLaneScope) allowsFlowFinding(ff types.FlowFindingDigest) bool {
	if s == nil || !s.constrain {
		return true
	}
	if s.principalDiagramFloor {
		return s.allowsOrderedFlowFinding(ff)
	}
	for _, id := range ff.EvidenceIDs {
		if s.hasEvidenceID(id) {
			return true
		}
	}
	fileMatch := false
	for _, group := range [][]string{ff.Path, ff.Hops, ff.Sources, ff.Sinks} {
		for _, raw := range group {
			if s.hasAnchor(raw) {
				return true
			}
			fileMatch = fileMatch || s.hasFile(raw)
		}
	}
	// A file-only scope is the compatibility lane for support entries that
	// genuinely have no typed endpoint identity. Once the support plan names
	// an endpoint, sharing a broad source file is only coincidence and cannot
	// pull an unrelated optional flow into the finalizer context.
	return len(s.anchors) == 0 && fileMatch
}

// allowsOrderedFlowFinding is deliberately stricter than allowsFlowFinding.
// One matching typed endpoint is sufficient to retain a row as optional
// exploration context, but it cannot authorize a principal ordered path. For
// that stronger claim the finding must either replay a support-lane EvidenceID
// or bind both ordered endpoints to the structured principal support surface.
func (s *supportLaneScope) allowsOrderedFlowFinding(ff types.FlowFindingDigest) bool {
	if s == nil || !s.constrain {
		return true
	}
	for _, id := range ff.EvidenceIDs {
		if s.hasEvidenceID(id) {
			return true
		}
	}
	path := ff.Path
	if len(path) < 2 {
		path = ff.Hops
	}
	if len(path) < 2 {
		return false
	}
	return s.matchesOrderedFlowEndpoint(path[0]) && s.matchesOrderedFlowEndpoint(path[len(path)-1])
}

func (s *supportLaneScope) matchesOrderedFlowEndpoint(raw string) bool {
	if s == nil {
		return false
	}
	if len(s.anchors) > 0 {
		if s.hasAnchor(raw) {
			return true
		}
		// FlowFinding endpoints commonly carry `repo/file.ext:symbol`.
		// The path prefix is typed location, not part of the callable
		// identity; strip only that unambiguous repository-path carrier and
		// retry exact anchor matching. This is syntax normalization, not a
		// file-only authority fallback.
		if file, symbol, ok := strings.Cut(strings.TrimSpace(raw), ":"); ok &&
			strings.ContainsAny(file, `/\`) {
			return s.hasAnchor(symbol)
		}
		return false
	}
	return s.hasFile(raw)
}

func (s *supportLaneScope) hasExactLocation(source string, line int) bool {
	if s == nil || line <= 0 {
		return false
	}
	file := supportLaneScopeFileKey(source)
	return file != "" && s.locations[supportLaneScopeLocationKey(file, line)]
}

func (s *supportLaneScope) hasLocation(source string, line int) bool {
	if s == nil {
		return false
	}
	file := supportLaneScopeFileKey(source)
	if file == "" {
		return false
	}
	if line > 0 && s.locations[supportLaneScopeLocationKey(file, line)] {
		return true
	}
	if line <= 0 {
		return false
	}
	for _, supportLine := range s.fileLines[file] {
		if supportLaneAbsInt(supportLine-line) <= 24 {
			return true
		}
	}
	return false
}

func (s *supportLaneScope) hasFile(raw string) bool {
	if s == nil {
		return false
	}
	file := supportLaneScopeFileKey(raw)
	return file != "" && s.files[file]
}

func (s *supportLaneScope) hasAnchor(raw string) bool {
	if s == nil {
		return false
	}
	key := supportLaneScopeAnchorKey(raw)
	if key != "" && s.anchors[key] {
		return true
	}
	if tail := types.NormalizedSurfaceSymbolTail(raw); tail != "" && s.anchors[tail] {
		return true
	}
	return false
}

func supportLaneScopeFileKey(raw string) string {
	raw = strings.TrimSpace(strings.ReplaceAll(raw, `\`, `/`))
	if raw == "" {
		return ""
	}
	if file, _, ok := strings.Cut(raw, ":"); ok && strings.IndexByte(file, '/') >= 0 {
		raw = file
	}
	return strings.ToLower(raw)
}

func supportLaneScopeLocationKey(file string, line int) string {
	if line <= 0 {
		return ""
	}
	return fmt.Sprintf("%s:%d", supportLaneScopeFileKey(file), line)
}

func supportLaneScopeParseLocation(raw string) (string, int) {
	raw = strings.TrimSpace(strings.ReplaceAll(raw, `\`, `/`))
	if raw == "" {
		return "", 0
	}
	idx := strings.LastIndex(raw, ":")
	if idx < 0 || idx == len(raw)-1 {
		return raw, 0
	}
	line, err := strconv.Atoi(strings.TrimSpace(raw[idx+1:]))
	if err != nil || line <= 0 {
		return raw, 0
	}
	return raw[:idx], line
}

func supportLaneScopeAnchorKey(raw string) string {
	return strings.ToLower(strings.TrimSpace(raw))
}

func supportLaneAbsInt(v int) int {
	if v < 0 {
		return -v
	}
	return v
}

func answerDocEvidenceIdentity(item types.EvidenceItem) string {
	if id := strings.TrimSpace(item.ID); id != "" {
		return id
	}
	return types.StableEvidenceID(item)
}

func selectAnswerDocFlowEnrichmentLines(findings []types.FlowFindingDigest, limit int, supportScope *supportLaneScope) []string {
	if len(findings) == 0 || limit <= 0 {
		return nil
	}
	out := make([]string, 0, extractorMinInt(len(findings), limit))
	scanned := 0
	for _, ff := range findings {
		scanned++
		if scanned > answerDocMaxFlowEnrichmentScan {
			break
		}
		if supportScope != nil && !supportScope.allowsFlowFinding(ff) {
			continue
		}
		parts := make([]string, 0, 5)
		if ff.ID != "" {
			parts = append(parts, "id="+ff.ID)
		}
		if len(ff.Path) > 0 {
			parts = append(parts, "path="+strings.Join(ff.Path, " -> "))
		}
		if len(ff.Sources) > 0 || len(ff.Sinks) > 0 {
			parts = append(parts, "source_sink="+strings.Join(ff.Sources, ", ")+" => "+strings.Join(ff.Sinks, ", "))
		}
		if len(ff.Hops) > 0 {
			parts = append(parts, "hops="+strings.Join(ff.Hops, " -> "))
		}
		if len(ff.Conditions) > 0 {
			parts = append(parts, "conditions="+strings.Join(ff.Conditions, "; "))
		}
		if ff.UnsupportedReason != "" {
			parts = append(parts, "boundary="+ff.UnsupportedReason)
		}
		if len(parts) == 0 {
			continue
		}
		out = append(out, strings.Join(parts, " | "))
		if len(out) >= limit {
			break
		}
	}
	return out
}

func answerDocFlowEnrichmentLimit(ctx *types.AgentContext) int {
	limit := answerDocDefaultFlowEnrichmentFacts
	if ctx != nil && ctx.AnalysisIR != nil {
		rm := ctx.AnalysisIR.RequestModel
		if rm.Intent == types.IntentTrace || types.ResolveQuestionFamily(rm) == types.QFRootCauseTrace {
			limit = answerDocMaxFlowEnrichmentFacts
		} else if rm.PredicateAxis == types.AxisCall || rm.Predicates.IsCrossComponent {
			limit = answerDocPreferredFlowEnrichmentFacts
		}
		if rm.Complexity == types.ComplexityComplex && limit < answerDocMaxFlowEnrichmentFacts {
			limit += 2
		}
	}
	if limit > answerDocMaxFlowEnrichmentFacts {
		return answerDocMaxFlowEnrichmentFacts
	}
	return limit
}

func truncateAnswerDocPromptText(s string, max int) string {
	s = strings.TrimSpace(s)
	if max <= 0 || len(s) <= max {
		return s
	}
	trimmed := s[:max]
	for len(trimmed) > 0 && !utf8.RuneStart(trimmed[len(trimmed)-1]) {
		trimmed = trimmed[:len(trimmed)-1]
	}
	return strings.TrimSpace(trimmed) + "…[truncated]"
}

// renderAnswerDocReferencedArtifactLines reminds the finalizer to keep
// the artifact-local coordinates the QUESTION referenced anchored in the
// visible answer. Soft guidance from a typed analyzer declaration; no
// hard gate reads it.
func renderAnswerDocReferencedArtifactLines(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil {
		return ""
	}
	refs := ctx.AnalysisIR.RequestModel.ReferencedArtifactLines
	if len(refs) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Referenced artifact lines\n\n")
	b.WriteString("The question references these attached-artifact line coordinates. Anchor the explanation to them explicitly (e.g. 「日志第 N 行」 / \"log line N\") so the user can map the answer back to their artifact; keep them artifact-local — they are NOT repository citations.\n")
	for _, r := range refs {
		if r.EndLine > r.StartLine {
			fmt.Fprintf(&b, "- %s lines %d-%d\n", r.Source, r.StartLine, r.EndLine)
		} else {
			fmt.Fprintf(&b, "- %s line %d\n", r.Source, r.StartLine)
		}
	}
	b.WriteString("\n")
	return b.String()
}

func renderAnswerDocRuntimeGroundingDisposition(ctx *types.AgentContext) string {
	plan := answerSurfacePlan(ctx)
	if plan == nil || !plan.RuntimeGroundingDisposition.IsActive() {
		return ""
	}
	d := plan.RuntimeGroundingDisposition
	var b strings.Builder
	b.WriteString("## Runtime Grounding Disposition\n\n")
	b.WriteString("A validated runtime artifact disposition says ordinary current-repo citation floors do not apply to the artifact's own observations.\n")
	fmt.Fprintf(&b, "- Source: `%s`\n", d.Source)
	fmt.Fprintf(&b, "- Reason: `%s`\n", d.Reason)
	fmt.Fprintf(&b, "- Rationale: %s\n", strings.TrimSpace(d.Rationale))
	b.WriteString("- Citation policy: claims whose source is the attached log / trace itself stay in the runtime/artifact provenance lane unless a cited current-repo line literally states the same claim.\n")
	b.WriteString("- Do not put attached-log / external-trace paths into `citations[]` just to quote artifact text. `citations[]` is for current-repo lines or bounded negative-scope proofs with `negative_pattern`; visible prose should say these facts come from the attached runtime artifact.\n")
	if runtimeObservationOnlyForAnswerDoc(ctx) {
		b.WriteString("- This dispatch is runtime-artifact scoped: current checkout/source evidence is not required. Leave current-repo files, helper symbols, and citations out of the answer unless a separate typed current-source anchor is present.\n")
		b.WriteString("- Do not emit `current_status_verdict`, and do not use visible `still_present` / `fixed` status wording or claim the current checkout lacks a fix. State the trace-observed cause/risk only, then name any current-code check as a possible follow-up if needed.\n\n")
		b.WriteString("Observation causality calibration:\n")
		b.WriteString(runtimeArtifactObservationCausalityCalibration())
		b.WriteString("\n")
	} else {
		b.WriteString("- Current repository citations may still be used for explicitly read current-code context, but do not present them as the source of the runtime observation or as proof that the current checkout produced the captured log / trace.\n")
		if !plan.CurrentStatusDiagnosticRequired {
			b.WriteString("- The current-status verdict lane is inactive for this dispatch. Do not emit `current_status_verdict`; answer the runtime-observed cause/risk and disclose any current-source boundary as prose if needed.\n")
		}
		b.WriteString("\n")
	}
	return b.String()
}

func runtimeObservationOnlyForAnswerDoc(ctx *types.AgentContext) bool {
	plan := answerSurfacePlan(ctx)
	if plan == nil || !plan.RuntimeGroundingDisposition.IsActive() {
		return false
	}
	authority := types.BuildRuntimeSourceAnswerAuthoritySnapshotForAgentContext(ctx, types.ObservationLedger{})
	if authority.Active && authority.CurrentSourceRequired {
		return false
	}
	return !plan.CurrentStatusDiagnosticRequired && !plan.CurrentSourceEvidenceOrigin
}

func renderAnswerDocCurrentStatusDiagnostic(ctx *types.AgentContext) string {
	if ctx == nil || ctx.AnalysisIR == nil || ctx.AnalysisIR.AnswerContract.CurrentStatusDiagnostic == nil {
		return ""
	}
	if plan := answerSurfacePlan(ctx); plan != nil && !plan.CurrentStatusDiagnosticRequired {
		return ""
	}
	contract := ctx.AnalysisIR.AnswerContract.CurrentStatusDiagnostic
	if !contract.Required {
		return ""
	}
	var b strings.Builder
	b.WriteString("## Current Status Diagnostic\n\n")
	b.WriteString("This answer must stay on two lanes and end with one bounded verdict.\n\n")
	b.WriteString("- Historical observation: state what the attached artifact, trace, or user-described prior symptom actually observed. Do not treat that historical fact as proof that the current checkout still behaves the same way.\n")
	b.WriteString("- Current code verification: cite the current code that was read and explain whether the same risk path is still present, blocked, removed, or not provable from the available evidence.\n")
	b.WriteString("- Verdict: emit a principal `decision` block with `current_status_verdict` set to exactly one of `still_present`, `fixed`, or `not_enough_evidence`, then explain the evidence boundary in the decision prose.\n\n")
	b.WriteString("Verdict semantics:\n")
	b.WriteString("- `still_present`: current cited code still contains the comparable risk path or missing guard. This is a current-checkout assessment, not proof that the historical artifact came from this revision.\n")
	b.WriteString("- `fixed`: current cited code removes, guards, or otherwise blocks the comparable risk path. Render it as a current-checkout risk assessment; unless a separate typed revision/transition witness exists, do not claim which change fixed the historical incident or that the captured build contains this fix.\n")
	b.WriteString("- `not_enough_evidence`: current cited code cannot decide between `still_present` and `fixed`; do not use it merely because the artifact line number drifted or the precise historical branch is uncertain.\n")
	b.WriteString("- Use `current_status_verdict` as the only canonical status token; the decision text is rationale and boundary explanation, not a second verdict channel.\n\n")
	if profile := ctx.AnalysisIR.RequestModel.ArtifactObservationProfile; profile != nil {
		b.WriteString("Typed artifact observations available for the historical lane:\n")
		if profile.SymptomSummary != "" {
			fmt.Fprintf(&b, "- Summary: %s\n", profile.SymptomSummary)
		}
		if len(profile.ObservationKinds) > 0 {
			fmt.Fprintf(&b, "- Observation kinds: %s\n", strings.Join(types.ObservationKindStrings(profile.ObservationKinds), ", "))
		}
		if profile.HasRetryLoop {
			b.WriteString("- Runtime/process observation includes a retry loop.\n")
		}
		if profile.HasLineMismatch {
			b.WriteString("- Runtime/process observation includes a line-mapping mismatch.\n")
		}
		if profile.HasCompletionRewrite {
			b.WriteString("- Runtime/process observation includes a completion rewrite / topical repair signal.\n")
		}
		limit := len(profile.EvidenceSnippets)
		if limit > 4 {
			limit = 4
		}
		for i := 0; i < limit; i++ {
			fmt.Fprintf(&b, "- Evidence snippet: %s\n", profile.EvidenceSnippets[i])
		}
		b.WriteString("\n")
	}
	return b.String()
}

func renderAnswerDocSupportPlan(ctx *types.AgentContext) string {
	plan := answerSupportPlan(ctx)
	if plan == nil || len(plan.Lanes) == 0 {
		return ""
	}
	enumerationCoverage := answerDocPrincipalEnumerationCoverage(ctx)
	var b strings.Builder
	b.WriteString("## Typed Answer Support Lanes\n\n")
	if supportPlanAllowsBlockKind(plan, string(types.BlockDecision)) {
		b.WriteString("- Build the principal answer blocks and any typed `decision` verdict only from the lanes below; use only block kinds each lane explicitly allows.\n")
	} else {
		b.WriteString("- Build the principal answer blocks only from the lanes below; use only block kinds each lane explicitly allows.\n")
	}
	b.WriteString("- Treat each lane's `Allowed block kinds` as a hard surface boundary. If a lane does not list `ordered_list`, do not turn its entries into principal hop items. If a lane does not list `diagram`, do not turn its entries into diagram edges or nodes.\n\n")
	b.WriteString("- In principal blocks, put inline backticks around code / file / config surfaces only when that exact surface is visible in a lane entry, a lane `typed_surface` / `surface_terms` value, a structured aggregate fact value/dimension, an exact target, or the cited source line. Names that appear only in `Evidence note`, retry diagnostics, raw tool output, search hints, or nearby context are background: use plain prose for them or omit them.\n")
	b.WriteString("- If the user's scalar / count question also asks for concrete members, files, paths, or line numbers, the scalar conclusion is not enough: add an `ordered_list` or `table` drawn from the principal lane entries. If the user asked only for the scalar value, do not invent a member list.\n\n")
	perMemberTable := ctx != nil && ctx.AnalysisIR != nil && ctx.AnalysisIR.RequestModel.Predicates.HasPerMemberTable
	if perMemberTable {
		b.WriteString("- For this dispatch, lane `Allowed block kinds` describe where the evidence is compatible; they do not authorize duplicate principal rosters. The required per-member `table` is the one structured principal-member carrier. Sections may use the same evidence only for headings or concise explanatory prose, without member `items[]`.\n\n")
	}
	if obligations := renderAnswerDocPrincipalMemberObligations(plan, enumerationCoverage, perMemberTable); obligations != "" {
		b.WriteString(obligations)
	}
	switch plan.Family {
	case types.QFRootCauseTrace:
		b.WriteString("- Keep observed runtime facts, current code path facts, nearest grounded mechanism facts, and uncertainty disclosures in their own lanes.\n")
		b.WriteString("- Do not promote an observation lane into caller-side provenance, old-build internals, or exact mechanism unless a current cited line explicitly proves that stronger claim.\n\n")
		b.WriteString("- Items rendered under the **Observed artifact facts** lane are runtime trace observations (the system tags them by typed source: panic / exception / traceback / perf bundle, regardless of language). They prove that the runtime hit the cited frame, but do NOT, by themselves, prove which source parameter was nil, which caller originated the value, or which exact downstream branch executed. Promotion to caller-side provenance / source-parameter mapping / exact mechanism requires a separately-cited current-code line.\n\n")
		b.WriteString("- For attached-artifact answers, keep the direct cause at the level literally observed by the artifact: error type/message, property or operation, frame/function, line/span, signal, and duration. If you infer a variable/parameter name, caller-side data construction, or ownership of the bad value without artifact text or current-source proof, label it as a possible upstream investigation direction rather than the root cause fact.\n\n")
		b.WriteString("- If a function, file, or hop appears elsewhere in the prompt but does NOT appear in the current code path / nearest mechanism / boundary lanes below, treat it as background only: do not turn it into a principal ordered-list hop, summary claim, or diagram node.\n\n")
		b.WriteString("- In drift-bounded root-cause answers, a current guard plus a later dereference proves the current code contains both sites; it does NOT by itself prove the runtime artifact actually passed the guard and reached the dereference path.\n\n")
		b.WriteString("- If the lanes below do NOT recover a grounded inner trigger statement, do NOT fill the gap with generic language-runtime guesses such as nil-map write, nil-slice index, field dereference, or similar builtin panic classes. State only that the exact internal trigger remains unrecovered in the current checkout.\n\n")
	case types.QFCallChain:
		b.WriteString("- Keep observed runtime facts, current grounded chain hops, and boundary disclosures in their own lanes.\n")
		b.WriteString("- Every current-chain entry below has an `entry_role` derived from typed ClaimForm/anchor fields. A `directed_hop` establishes exactly its own caller-to-callee edge; it becomes consecutive with another edge only when its callee is that edge's caller. `typed_step_backbone` preserves an already-compiled ordered step, while `callback_handoff` establishes a handoff but not execution; guard/assignment/return/literal/registration/definition/support facts explain a hop or live in a sibling support section.\n")
		b.WriteString("- Observation entries can explain where the trace came from, but they do not add caller/callee hops unless a `directed_hop` entry also establishes that hop. Do not turn adjacent non-hop facts into implicit bridges.\n")
		b.WriteString("- You may use an entry's `Evidence note` to enrich that SAME hop's explanation. Do not turn nouns from the note into additional hops, targets, diagram nodes, or countable list members unless they also appear as their own lane entry.\n")
		b.WriteString("- If a function, file, span, or prior-turn subject appears elsewhere in the prompt but not in the current grounded call-chain lane, treat it as background only for the principal path.\n\n")
		b.WriteString(renderAnswerDocCallChainDiagramSemanticsGuide())
		b.WriteString(renderAnswerDocCallChainRelationTopology(plan))
		b.WriteString(renderAnswerDocCallChainSemanticHandoffs(plan))
		b.WriteString(renderAnswerDocCallChainCitationAuthority(plan))
	default:
		b.WriteString("- Keep observed facts, current-code facts, and boundary disclosures in their own lanes.\n")
		b.WriteString("- If a function, file, symbol, trace span, or prior-turn subject appears elsewhere in the prompt but not in a lane that allows the block kind you are writing, treat it as background only.\n\n")
	}
	hasMechanismLane := false
	for _, lane := range plan.Lanes {
		if lane.Kind == types.SupportLaneNearestMechanism && len(lane.Entries) > 0 {
			hasMechanismLane = true
			break
		}
	}
	if plan.Family == types.QFRootCauseTrace && !hasMechanismLane {
		b.WriteString("- If the **Nearest grounded mechanism** lane is absent, do NOT invent a likely internal cause, specific nil-bearing variable, receiver field, or caller-side provenance from the current code path or boundary lanes alone. Keep the answer at the level of the observed frame, the grounded current path, and the explicit uncertainty boundary.\n\n")
	}
	for _, lane := range plan.Lanes {
		title := strings.TrimSpace(lane.Title)
		if title == "" {
			continue
		}
		fmt.Fprintf(&b, "### %s\n\n", title)
		if guidance := strings.TrimSpace(lane.Guidance); guidance != "" {
			b.WriteString(guidance)
			b.WriteString("\n\n")
		}
		if len(lane.AllowedBlocks) > 0 {
			fmt.Fprintf(&b, "Allowed block kinds: %s\n\n", strings.Join(lane.AllowedBlocks, ", "))
		}
		entries := lane.Entries
		if lane.Kind == types.SupportLanePrincipalEvidence && enumerationCoverage.Active() {
			rendered, remaining := answerDocSplitEntriesCoveredByPrincipalEnumerationRows(entries, enumerationCoverage)
			if rendered > 0 {
				fmt.Fprintf(&b, "Entries already rendered in `Principal Enumeration Rows`: %d. Keep this lane's allowed block kinds and guidance, but do not duplicate those member rows here.\n\n", rendered)
				entries = remaining
			}
		}
		for _, entry := range entries {
			text := strings.TrimSpace(entry.Text)
			if text == "" {
				continue
			}
			if ctx != nil && ctx.AnalysisIR != nil {
				text = types.SanitizeSourceInventoryNoteForRequest(&ctx.AnalysisIR.RequestModel, text)
			}
			if detail := strings.TrimSpace(entry.Detail); detail != "" {
				if ctx != nil && ctx.AnalysisIR != nil {
					detail = types.SanitizeSourceInventoryNoteForRequest(&ctx.AnalysisIR.RequestModel, detail)
				}
				text += " — Evidence note: " + detail
			}
			if plan.Family == types.QFCallChain && lane.Kind == types.SupportLaneCurrentCodePath {
				text = fmt.Sprintf("[entry_role=`%s`] %s", answerDocCallChainSupportEntryRole(entry), text)
			}
			if loc := strings.TrimSpace(entry.Location); loc != "" {
				if equivalents := renderSupportEntryEquivalentLocations(entry.EquivalentLocations); equivalents != "" {
					fmt.Fprintf(&b, "- %s (`%s`; equivalent typed anchors: %s)\n", text, loc, equivalents)
				} else {
					fmt.Fprintf(&b, "- %s (`%s`)\n", text, loc)
				}
			} else {
				fmt.Fprintf(&b, "- %s\n", text)
			}
		}
		b.WriteString("\n")
	}
	return b.String()
}

func answerDocCallChainSupportEntryRole(entry types.AnswerSupportEntry) string {
	switch entry.ClaimForm {
	case types.ClaimCallEdge:
		return "directed_hop"
	case types.ClaimCallbackHandoff:
		return "callback_handoff"
	case types.ClaimGuardCondition:
		return "guard_condition_fact"
	case types.ClaimBranchEffect:
		return "branch_effect_fact"
	case types.ClaimRegistrationEdge:
		return "registration_binding_fact"
	case types.ClaimAssignmentFact:
		return "assignment_state_or_binding_fact"
	case types.ClaimReturnFact:
		return "return_value_fact"
	case types.ClaimLiteralValueFact:
		return "literal_value_fact"
	case types.ClaimDefinitionFact:
		return "definition_fact"
	case types.ClaimExternalObservation:
		return "observation_fact"
	case types.ClaimImportEdge, types.ClaimPrecedenceRole:
		return "structural_or_order_fact"
	}
	if entry.ClaimForm == types.ClaimUnknown && entry.EvidenceID == "" && entry.Producer == "" {
		return "typed_step_backbone"
	}
	return "supporting_fact"
}

// renderAnswerDocCallChainDiagramSemanticsGuide is soft authoring guidance for
// the closed QFCallChain family. It helps the model preserve the operation and
// control-flow semantics already present in typed support lanes without
// deriving a hard decision from user/model prose or rewriting the answer.
// These rules are language-neutral: syntax differs, but an invocation, a
// guard, and a declarative relation remain distinct semantic edge classes.
func renderAnswerDocCallChainDiagramSemanticsGuide() string {
	return "### Cross-language call-diagram semantics\n\n" +
		"- For an invocation edge, prefer function/method-qualified participants. The message after `:` should name the exact callee operation carried by the current grounded call-edge entry; if you show arguments, literals, selectors, or operators, copy only what the cited call site establishes. Do not substitute the caller operation or an illustrative payload.\n" +
		"- One grounded invocation proves one direct caller-to-callee edge, not a complete path. Join two invocation edges into consecutive hops only when the first callee is the second caller under the typed identity rules. Calls with the same caller are sibling call sites; their source-line ordering is useful presentation order but does not by itself prove runtime co-execution, branch selection, value transfer, or a path through the callees.\n" +
		"- For a sequence view of several sibling calls inside one orchestration function, keep that function as the sender for each grounded message and place messages in cited source order. Describe this as source-ordered stages/call sites, with branch uncertainty where applicable; do not rename the fan-out as several independent paths converging on the last callee.\n" +
		"- A sequence diagram's top-to-bottom message order is itself an ordering claim. When the typed carrier proves only a non-linear call topology and supplies no separate precedence/control-flow authority for that order, prefer a call-DAG/flow view or omit the optional diagram; never label sibling calls as parallel/concurrent merely because they share a caller.\n" +
		"- A condition, capacity check, match arm, null guard, loop predicate, or other control decision that does not invoke a second symbol is not a call edge. In a sequence diagram render it as `Note`, `alt`/`else`, or `opt`; in a flow diagram render it as a branch. Do not manufacture a self-call to make the condition visible.\n" +
		"- A language/runtime binding boundary (FFI, JNI, PyO3, native-module registration, generated RPC binding) is not a source-level invocation unless a grounded call row proves that exact edge. A matching `registration_binding_fact` proves that a public/exported surface is bound to a callable; therefore describe a caller targeting that exact export as going through the registered binding, never as bypassing it. It still does not prove execution of the registered callable or its downstream core call unless those calls have their own `directed_hop` rows. In a sequence diagram show an unproved binding transition as a `Note over` the two grounded endpoints, not an arrow; use the same note shape for an unproved execution transition after a proved binding. In a call-DAG/architecture diagram, use only the matching typed non-call relation carried by evidence. Keep independently grounded calls on both sides visible and qualified.\n" +
		"- A compound condition can still contain a real invocation. Preserve the grounded caller-to-callee edge for that operation, then annotate the comparison/branch separately; never replace the callee with an abstract guard node, and never make the guard node the caller of the post-guard operation.\n" +
		"- Preserve the source language's resolved identity: package/type/receiver qualification when known; exact receiver/member surface with an uncertainty disclosure when dynamic dispatch is unresolved. Never guess an owner merely to make the graph look uniform.\n" +
		"- This guidance applies uniformly to Go, Java, Kotlin, JavaScript/TypeScript/ArkTS, C/C++, Rust, Python, Ruby, Swift, Lua, Cangjie, and every other supported executable language. Declarative imports, inheritance/implements edges, annotations, and Proto/RPC declarations use their typed relation class; they are not executable calls unless a separately grounded invocation proves that edge.\n" +
		"- In the visible answer and diagram, prefer repository and business vocabulary. Authoring terms such as typed lane, entry_role, evidence capsule, shared frontier, and validator are internal context unless the user explicitly asks about Codrax internals.\n" +
		"These are presentation instructions, not conclusion authority: keep the model's explanation and judgment, and omit the diagram when it would add no useful structure.\n\n"
}

// renderAnswerDocCallChainRelationTopology gives the finalizer a bounded,
// typed description of how the accepted call rows relate to one another.
// Each EvidenceItem already proves one direct edge. This helper only compares
// their structured Subject/Object identities and source locations: it never
// parses request prose, model prose, or Mermaid text, never rejects an answer,
// and never writes the conclusion or diagram for the model.
func renderAnswerDocCallChainRelationTopology(plan *types.AnswerSupportPlan) string {
	entries := answerDocCurrentCodePathEntries(plan)
	var calls []types.AnswerSupportEntry
	for _, entry := range entries {
		if entry.ClaimForm == types.ClaimCallEdge && strings.TrimSpace(entry.Subject) != "" && strings.TrimSpace(entry.Object) != "" {
			calls = append(calls, entry)
		}
	}
	if len(calls) == 0 {
		return ""
	}

	type siblingGroup struct {
		caller string
		calls  []types.AnswerSupportEntry
	}
	var groups []siblingGroup
	for _, call := range calls {
		callSource := strings.TrimSpace(strings.ReplaceAll(call.Source, `\`, "/"))
		if callSource == "" {
			continue
		}
		idx := -1
		for i := range groups {
			groupSource := strings.TrimSpace(strings.ReplaceAll(groups[i].calls[0].Source, `\`, "/"))
			if strings.EqualFold(groupSource, callSource) && answerDocCallChainTopologyIdentityEquivalent(groups[i].caller, call.Subject) {
				idx = i
				break
			}
		}
		if idx < 0 {
			groups = append(groups, siblingGroup{caller: call.Subject})
			idx = len(groups) - 1
		}
		groups[idx].calls = append(groups[idx].calls, call)
	}

	connected := 0
	for i := range calls {
		for j := range calls {
			if i == j {
				continue
			}
			if answerDocCallChainTopologyIdentityEquivalent(calls[i].Object, calls[j].Subject) {
				connected++
			}
		}
	}

	var b strings.Builder
	b.WriteString("### Typed relation topology (advisory)\n\n")
	b.WriteString("- relation_authority=`each row proves exactly one direct caller_to_callee edge`\n")
	fmt.Fprintf(&b, "- grounded_direct_edge_count=`%d`; connected_edge_transition_count=`%d`\n", len(calls), connected)
	if connected == 0 && len(calls) > 1 {
		b.WriteString("- connected_path_status=`no callee_to_next_caller transition is present in this bounded lane`; keep separate edges or sibling stages rather than declaring one end-to-end path.\n")
	}
	for _, group := range groups {
		if len(group.calls) < 2 {
			continue
		}
		sort.SliceStable(group.calls, func(i, j int) bool {
			if group.calls[i].Source == group.calls[j].Source {
				return group.calls[i].LineStart < group.calls[j].LineStart
			}
			return group.calls[i].Source < group.calls[j].Source
		})
		parts := make([]string, 0, len(group.calls))
		for _, call := range group.calls {
			location := strings.TrimSpace(call.Location)
			if location == "" {
				location = "location unavailable"
			}
			parts = append(parts, fmt.Sprintf("%s @ %s", strings.TrimSpace(call.Object), location))
		}
		fmt.Fprintf(&b, "- sibling_callsite_group: caller=`%s`; source_order=`%s`; semantics=`same caller fan-out; source order is not callee chaining or proof that all branches executed`\n",
			answerDocCallChainInline(group.caller), answerDocCallChainInline(strings.Join(parts, " | ")))
	}
	b.WriteString("- The model owns the explanation and visible diagram; this section supplies relation boundaries only.\n\n")
	return b.String()
}

func answerDocCallChainTopologyIdentityEquivalent(left, right string) bool {
	left = strings.TrimSpace(left)
	right = strings.TrimSpace(right)
	return left != "" && right != "" &&
		(strings.EqualFold(left, right) || types.AnswerCodeIdentitySurfacesEquivalent(left, right))
}

type answerDocPrincipalEnumerationRowCoverage struct {
	byEvidenceID map[string]bool
	byRowKey     map[string]bool
	rows         []types.EnumerationDisplayRow
	rowCount     int
}

func answerDocPrincipalEnumerationCoverage(ctx *types.AgentContext) answerDocPrincipalEnumerationRowCoverage {
	plan := answerSurfacePlan(ctx)
	sets := answerDocPrincipalEnumerationSets(ctx, plan)
	coverage := answerDocPrincipalEnumerationRowCoverage{
		byEvidenceID: map[string]bool{},
		byRowKey:     map[string]bool{},
	}
	for _, set := range sets {
		for _, row := range set.Rows {
			coverage.rowCount++
			coverage.rows = append(coverage.rows, row)
			if id := strings.TrimSpace(row.EvidenceID); id != "" {
				coverage.byEvidenceID[id] = true
			}
			for _, key := range answerDocPrincipalEnumerationRowKeys(row) {
				coverage.byRowKey[key] = true
			}
		}
	}
	return coverage
}

func (c answerDocPrincipalEnumerationRowCoverage) Active() bool {
	return c.rowCount > 0 && (len(c.byEvidenceID) > 0 || len(c.byRowKey) > 0)
}

func (c answerDocPrincipalEnumerationRowCoverage) CoversEvidenceID(id string) bool {
	id = strings.TrimSpace(id)
	return id != "" && c.byEvidenceID[id]
}

func (c answerDocPrincipalEnumerationRowCoverage) CoversSupportEntry(entry types.AnswerSupportEntry) bool {
	if !c.Active() {
		return false
	}
	if c.CoversEvidenceID(entry.EvidenceID) {
		return true
	}
	return c.coversAnyRowKey(answerDocPrincipalEnumerationSupportEntryKeys(entry))
}

func (c answerDocPrincipalEnumerationRowCoverage) CoversObligation(ob types.AnswerSupportMemberObligation) bool {
	if !c.Active() {
		return false
	}
	if c.CoversEvidenceID(ob.EvidenceID) {
		return true
	}
	return c.coversAnyRowKey(answerDocPrincipalEnumerationObligationKeys(ob))
}

func (c answerDocPrincipalEnumerationRowCoverage) coversAnyRowKey(keys []string) bool {
	if len(keys) == 0 || len(c.byRowKey) == 0 {
		return false
	}
	for _, key := range keys {
		if c.byRowKey[key] {
			return true
		}
	}
	return false
}

func answerDocSplitEntriesCoveredByPrincipalEnumerationRows(entries []types.AnswerSupportEntry, coverage answerDocPrincipalEnumerationRowCoverage) (int, []types.AnswerSupportEntry) {
	if !coverage.Active() || len(entries) == 0 {
		return 0, entries
	}
	remaining := make([]types.AnswerSupportEntry, 0, len(entries))
	rendered := 0
	for _, entry := range entries {
		if coverage.CoversSupportEntry(entry) {
			rendered++
			continue
		}
		remaining = append(remaining, entry)
	}
	return rendered, remaining
}

func renderAnswerDocPrincipalMemberObligations(plan *types.AnswerSupportPlan, coverage answerDocPrincipalEnumerationRowCoverage, perMemberTable bool) string {
	obligations := types.PrincipalSupportMemberObligations(plan)
	if len(obligations) == 0 {
		return ""
	}
	coveredCount := 0
	if coverage.Active() {
		filtered := obligations[:0]
		for _, ob := range obligations {
			if coverage.CoversObligation(ob) {
				coveredCount++
				continue
			}
			filtered = append(filtered, ob)
		}
		obligations = filtered
	}
	var b strings.Builder
	b.WriteString("### Principal Member Obligations\n\n")
	totalObligations := len(obligations) + coveredCount
	if coveredCount > 0 {
		fmt.Fprintf(&b, "%d answer-grade member obligation(s) are already rendered once in `Principal Enumeration Rows` above. Use those rows as the stable member-to-citation map instead of duplicating them here.\n", coveredCount)
		if equivalents := answerDocCoveredEquivalentAnchorLines(coverage); equivalents != "" {
			b.WriteString(equivalents)
		}
		b.WriteString("When one member has both a definition/declaration anchor and an implementation/proof anchor, keep it as one principal member. Anchors are equivalent only for the visible claims they both actually prove: if the row also displays a related attribute, condition, owner, route, default, or selection rule, prefer one grounded proof anchor that carries both the member endpoint and that visible second axis; a definition-only line is not equivalent for that two-axis row. Do not churn the selected stable row/evidence carrier between anchors that prove the same visible claims; mention the other only as same-row enrichment when it helps the user.\n")
	}
	if len(obligations) == 0 {
		if perMemberTable {
			fmt.Fprintf(&b, "The typed principal lane contains %d answer-grade member(s). Render each member from `Principal Enumeration Rows` once as a structured row in the required principal `table`, with a citation to the listed location or one of its equivalent typed anchors. Do not duplicate those members in section/list items; prose-only mentions do not satisfy the table carrier.\n\n", totalObligations)
		} else {
			fmt.Fprintf(&b, "The typed principal lane contains %d answer-grade member(s). Render each member from `Principal Enumeration Rows` once as a structured item in a principal `section`, `ordered_list`, `bullet_list`, or `table`, with a citation to the listed location or one of its equivalent typed anchors. For `section`, use `items[]`; prose-only mentions in block `text` do not satisfy the member carrier.\n\n", totalObligations)
		}
		return b.String()
	}
	if perMemberTable {
		fmt.Fprintf(&b, "The typed principal lane contains %d answer-grade member(s); %d still need explicit obligation rows below. Render each listed member once as a structured row in the required principal `table`, with a citation to the listed location or one of its equivalent typed anchors. Do not duplicate those members in section/list items. These rows are a stable member-to-citation map; do not satisfy them by prose-only mentions in block `text`.\n", totalObligations, len(obligations))
	} else {
		fmt.Fprintf(&b, "The typed principal lane contains %d answer-grade member(s); %d still need explicit obligation rows below. Render each listed member once as a structured item in a principal `section`, `ordered_list`, `bullet_list`, or `table`, with a citation to the listed location or one of its equivalent typed anchors. For `section`, use `items[]`. These rows are a stable member-to-citation map; do not satisfy them by prose-only mentions in block `text`.\n", totalObligations, len(obligations))
	}
	b.WriteString("Use the shown `item_id` for the row id when possible. When the projected schema exposes stable evidence or principal-row identities, copy that exact selector and omit citation-pool arithmetic. Only in a schema-permitted legacy lane should `citation_key` be used to build `citations[]` and locate the matching zero-based item reference; never count indexes from memory.\n")
	b.WriteString("When one member has both a definition/declaration anchor and an implementation/proof anchor, keep it as one principal member. Anchors are equivalent only for the visible claims they both actually prove: if the row also displays a related attribute, condition, owner, route, default, or selection rule, prefer one grounded proof anchor that carries both the member endpoint and that visible second axis; a definition-only line is not equivalent for that two-axis row. Do not churn the selected stable row/evidence carrier between anchors that prove the same visible claims; mention the other only as same-row enrichment when it helps the user.\n")
	if plan != nil && plan.ChangeImpactProfile != nil && plan.ChangeImpactProfile.Active() &&
		plan.ChangeImpactProfile.RequestedOutput == types.ImpactOutputFiles {
		fmt.Fprintf(&b, "This is a change-impact file enumeration: the %d member(s) below are the file set. Use each file path as the item label; keep file:line anchors only in item text/citations. Do not copy numeric file counts from unstructured closure prose when they disagree with this typed member set.\n", len(obligations))
	}
	b.WriteString("For large repairs that change many member citations, re-emit a full `emit_answer_document` with a fresh `citations[]` pool instead of patching stale citation indexes.\n\n")
	for _, ob := range obligations {
		label := strings.TrimSpace(ob.Label)
		if label == "" {
			label = strings.TrimSpace(ob.Location)
		}
		loc := strings.TrimSpace(ob.LocationHint())
		if loc == "" {
			loc = strings.TrimSpace(ob.Location)
		}
		form := strings.TrimSpace(string(ob.ClaimForm))
		if form == "" {
			form = "principal_evidence"
		}
		itemID := strings.TrimSpace(ob.StableItemID())
		citationKey := strings.TrimSpace(ob.StableCitationKey())
		if id := strings.TrimSpace(ob.EvidenceID); id != "" {
			fmt.Fprintf(&b, "- item_id=%s — label=%s — citation_key=%s — %s — evidence_id=%s\n", itemID, label, citationKey, form, id)
		} else {
			fmt.Fprintf(&b, "- item_id=%s — label=%s — citation_key=%s — %s\n", itemID, label, citationKey, form)
		}
		if loc != "" && loc != citationKey {
			fmt.Fprintf(&b, "  accepted_locations=%s\n", loc)
		}
	}
	b.WriteString("\n")
	return b.String()
}

func answerDocPrincipalEnumerationRowKeys(row types.EnumerationDisplayRow) []string {
	locations := []string{
		row.Location,
		row.CitationKey,
		answerDocPrincipalEnumerationSourceLine(row.Source, row.LineStart),
	}
	locations = append(locations, row.EquivalentLocations...)
	labels := []string{
		row.Member,
		row.DisplayLabel,
		row.Subject,
		row.Object,
		row.AnchorSymbol,
		row.OwnerSymbol,
	}
	labels = append(labels, row.SurfaceTerms...)
	return answerDocPrincipalEnumerationKeys(locations, labels)
}

